    ["{{先生|女士}}，赏我杯酒吧，就一杯！"] = "{{Сэр | Мадам}}, дайте мне выпить, хотя бы одну!",
    ["{{尊敬的先生|美丽的女士}}，这支花送您！"] = "{{ Respected Sir | Beautiful Lady } }, этот цветок для тебя!",
