    ["ω除以___等于2，第二个空位填写？"] = "ω, разделенное на ___, равно 2, что следует заполнить во втором пропуске?",
    ["“不灭之心”、“圣者之石”和“永生之水”之类的，各种各样的名字"] = "«Сердце бессмертия», «Философский камень», «Вода вечной жизни» и всякие другие названия",
    ["“书籍是人类进步的阶梯”……我考考你，这句话是谁说的？"] = "«Книги — это лестница человеческого прогресса»... Позвольте мне вас проверить, кто это сказал?",
    ["“他”的帮助？"] = "«Его» помощь?",
    ["“佛尔思亲笔签名典藏版小说”……这些是采买清单里该出现的东西吗？"] = "«Коллекционное издание романа Форса с автографом»… Это вещи, которые должны появиться в списке покупок?",
    ["“你最近有做桃色之梦吗？你桃色之梦的主角都有谁？”"] = "«Были ли у вас в последнее время эротические сны? Кто главные герои ваших эротических снов?»",
    ["“太阳”先生是个很单纯的人，温暖，善良……很难想象经历过这个世界黑暗面的人还能保持这份真诚。"] = "Мистер Солнце — человек удивительно чистый, теплый, добрый... Трудно представить, что тот, кто познал темную сторону этого мира, все еще способен сохранять такую искренность.",
    ["“太阳”先生说，把学派当成家，那是什么？那群人嘴里念叨的故乡吗？"] = "Г-н Сан советует относиться к Клубу Таро как к дому, что это такое? Это тот родной город, о котором постоянно бормочет группа людей?",
    ["“惩戒天使”，祂是主的雷霆，主的怒火，主的手掌，是所有堕落者和不洁者的审判官及处刑人。"] = "«Ангел наказания», Он — гром Господень, гнев Господень, ладонь Господня, судья и палач всех падших и нечистых.",
    ["“愚者”先生仁慈而怜悯，是这个世界的救主，却让我们以“他”而非“祂”来称呼。"] = "Мистер Шут добр и милосерден, спаситель этого мира, но позволяет нам называть его «он», а не «Он».",
    ["“愚者”先生是得到所有教会认可的正神，塔罗学派的成功修建也是得益于他的帮助。"] = "Господин Шут — истинный Бог, признанный всеми церквями, и успешное строительство Клуба Таро также произошло благодаря его помощи.",
    ["“指证”。当你构建出完整的逻辑链条，就必须以坚定的意志和灵性，将你的推论“呈现”出来。"] = "«Свидетельство». Когда вы строите полную логическую цепочку, вы должны использовать твердую волю и духовность, чтобы «представить» свой вывод.",
    ["“时之天使”，祂是古老年代里的天使，最终臣服于我主，为祂敲击天国之钟。"] = "«Ангел Времени». Это ангел из древних времен, который в конце концов подчинился моему Господу, ударив для Него в колокол Царства Небесного.",
    ["“歌剧魅影”是贝克兰德最负盛名的时装盛典。"] = "«Призрак оперы» — самый престижный модный гала-концерт Баклунда.",
    ["“歌剧魅影”曾是一位神秘魔女的私人舞台，她在此处举行过无数场精彩动人的表演。如今舞台向各大俱乐部敞开大门，是展示俱乐部风华的最佳场所。胜者不仅能赢得万众瞩目的荣耀，更会得到神秘「魅影」的馈赠。"] = "«Призрак Оперы» когда-то был частной сценой таинственной Ведьмы, где она давала бесчисленные блестящие и трогательные представления. Сегодня сцена открыта для всех крупных клубов и является лучшим местом, чтобы продемонстрировать клубную элегантность. Победитель не только заслужит славу быть в центре внимания, но и получит подарок от загадочного «Фантома».",
    ["“正义”女士勇敢坚定，美丽优雅，她关心着学派的每个人，无论遇到任何困难，和她聊聊好像都能轻松解决。"] = "Мисс Джастис храбрая, твердая, красивая и элегантная. Она заботится обо всех в клубе, и какие бы трудности ни возникали, общение с ней, кажется, легко их разрешает.",
    ["“正义”女士，要不要尝试一下我们培育出来的高歌蘑菇？"] = "Госпожа Джастис, не хотите ли попробовать поющие грибы, которые мы выращиваем?",
    ["“毛毛草”…… 什么时候我也能有自己的新名字呢？"] = "«Нечеткая трава»… Когда у меня появится новое имя?",
    ["“水银天使”是命运的化身，是我主最宠爱的天使；“死亡天使”是跟随我主最久的存在，是冥界的执政官；“救赎天使”是我主的号角，是祂神谕的传达者；“生命天使”是智慧的结晶，是每个人体内永不磨灭的灵性。"] = "«Ангел Ртути» — воплощение судьбы, любимейший ангел моего Господа; «Ангел Смерти» — дольше всех следовавший за моим Господом архонт подземного мира; «Ангел Искупления» — глас моего Господа, вестник Его божественной воли; «Ангел Жизни» — средоточие мудрости, неугасимая духовность внутри каждого человека.",
    ["“爱情总是伴随着谎言”，不过谁又知道，这句话本身是不是一种欺诈？"] = "«Любовь всегда сопряжена с ложью»... Но кто знает, быть может, эти слова и сами по себе — обман?",
    ["“给人一种回家的感觉。”"] = "«Дает ощущение дома».",
    ["“贝克兰德夜总会香花女士的印有她唇印的丝巾，顺便问问她，还记得当时那个美妙的午夜吗？”"] = "«Шелковый шарф с отпечатком помады мисс Фрагрант из ночного клуба Бэкланд, и, кстати, спроси ее, помнит ли она еще ту чудесную полночь?»",
    ["“鞋子破了要换双新的，必须是廷根水仙花街13号……”呃，这个也算他正常吧。"] = "«Если у тебя сломались туфли, тебе нужно переодеться в новую пару, это, должно быть, улица Даффодил, 13, Тинген…» Э-э, я думаю, для него это нормально.",
    ["“项圈”……"] = "\"Воротник\"…",
    ["“顾问”……我知道了，是老崔让你来的。"] = "«Консультант»… Я вижу, тебя послал Старый Цюй.",
    ["……"] = false,
    ["…………"] = false,
    ["………………"] = false,
    ["……不过也糟糕不到哪里去。"] = "…Но хуже быть не могло.",
    ["……人有时候应该保守点，不能对所有新事物都太好奇。"] = "...Иногда человеку стоит быть консервативнее и не проявлять излишнее любопытство ко всему новому.",
    ["……仔细一看只是前主人吃番茄酱时留下的痕迹。"] = "…Если присмотреться, то это всего лишь пятно, оставленное предыдущим хозяином, когда они ели кетчуп.",
    ["……他又迟到了。<P_Heart>  (苦笑)</> 不对，是我又忘了，他已经不会来了。 "] = "…Он снова опаздывает. <P_Heart> (горькая улыбка) </> Нет, я опять забыл, он больше не придет.",
    ["……他睡着了。"] = "…Он уснул.",
    ["……伟大的圣者来到这片充满纷争的土地，用怜悯炼成金黄的树叶，以慈爱抚慰疮痍的大地。"] = "…Великий Святой пришел в эту землю, полную раздора, с состраданием очищая золотые листья и добротой успокаивая израненную землю.",
    ["……你就失踪在这片水里，三十年了，我每天给你送东西，你也不愿意回来见见我……"] = "...Ты пропал в этой воде... Тридцать лет прошло, я каждый день приношу тебе гостинцы, а ты даже повидаться со мной не хочешь...",
    ["……你投到过吗？"] = "...Вы когда-нибудь его кастовали?",
    ["……你替八个人祈祷？"] = "…Вы молитесь за восемь человек?",
    ["……你能陪我喝到第几杯？"] = "…Сколько выпивок ты сможешь угнаться за мной?",
    ["……你说呢？"] = "…Что вы думаете?",
    ["……刚才的状态很奇怪，也许它的精神影响还没散去。我必须再次向你的提醒表示感谢。"] = "…Только что было очень странное состояние, возможно, его ментальное влияние еще не рассеялось. Должен еще раз поблагодарить тебя за предупреждение.",
    ["……别那样看着我，我可没有斯普林那种特殊癖好。我申请看守这里，是因为我的朋友们都在。"] = "…Не смотри на меня так, у меня нет такого особенного хобби, как Весна. Я подал заявку на охрану этого места, потому что здесь все мои друзья.",
    ["……原本它已经被封印了，妥善保管的情况下不会造成新的损害，但，我和同伴受到了它们的蛊惑……"] = "...Изначально он уже был запечатан, и при должном хранении от него не было бы никакого вреда, но... мы с товарищами поддались их соблазну...",
    ["……听起来，你这份工作干得很辛苦。"] = "...Судя по всему, эта работа дается тебе нелегко.",
    ["……呃，手持……<P_Heart> （翻找）</>……奇怪……放哪去了……"] = "...Э-э, в руке... <P_Heart>（роется в вещах）</>... Странно... куда же оно запропастилось...",
