    ["一个人挺好的。不用说话，不用笑，不用想待会儿要说什么。"] = "Быть одному очень приятно. Не нужно говорить, не нужно улыбаться, не нужно думать, что сказать дальше.",
    ["一个人？不算。周围都是人，只是……不怎么投机。"] = "Один? Не совсем. Кругом люди, просто... мы особо не сходимся.",
    ["一个对开膛手来说，是个容易做噩梦的地方。"] = "Для Потрошителя это место, где легко снятся кошмары.",
    ["一个是凶狠的开膛手，一个是善良无辜的年轻姑娘。"] = "Один — злобный Потрошитель, другой — добрая и невинная молодая девушка.",
    ["一个贪心又油腻腻的家伙，总想把镇上卖鱼的生意全部吃下来。"] = "Жадный и жирный парень, который всегда хочет взять на себя весь бизнес по продаже рыбы в городе.",
    ["一会进去之后，注意观察狂信徒身上<P_Yellow>特殊的红色部位</>，那是他们的<P_Yellow>弱点</>。"] = "Зайдя позже, обратите внимание на специальные красные детали <P_Yellow></> на фанатиках; это их слабые стороны <P_Yellow></>.",
    ["一位老同事帮了我，我逃到廷根躲了两年，又安身在贝克兰德。"] = "Мне помог старый коллега, и я сбежал в Тинген, чтобы скрываться два года, а затем поселился в Баклунде.",
    ["一只及至肘部的黑色薄纱长手套，仿佛出于皇室，自有种尊贵典雅的气质。"] = "Черная прозрачная длинная перчатка до локтя, словно из королевской семьи, обладающая благородным и элегантным темпераментом.",
    ["一只裹着奇怪纤维皮毛的……白色猿猴？"] = "Белая обезьяна, завернутая в странный волокнистый мех?",
    ["一同等待戈多。"] = "Вместе в ожидании Годо.",
    ["一场“意外”被安排在我身上，曾经的我，索罗·布莱克就这样“死”在任务里。"] = "Мне устроили «несчастный случай», и бывший я, Соло Блэк, таким образом «погиб» в миссии.",
    ["一场战斗测试。放心，这一切都发生在梦境中。"] = "Боевое испытание. Не волнуйтесь, все это происходит во сне.",
    ["一场特别的际遇，您明白的，命运的齿轮开始转动了。"] = "Особая встреча, понимаете, шестеренки судьбы начали вращаться.",
    ["一块三分熟的牛排和一块五分熟的牛排相遇了，他们为什么不打招呼？"] = "Стейк средней прожарки и стейк средней прожарки встретились, почему они не поздоровались?",
    ["一块鱼派卖1金镑！还是卖给贝克兰德人吧！"] = "Рыбный пирог продается за 1 фунт! С тем же успехом можно продать его жителям Баклунда!",
    ["一定是吧？不然怎么会有人一身双排扣礼服出现在雪山上，嘴里说着……"] = "Наверняка ведь? Иначе с чего бы кому-то появляться на заснеженной горе в двубортном сюртуке и твердить...",
    ["一对红色的拳套。"] = "Пара красных боксерских перчаток.",
    ["一旦进去，就没有回头路了，你得考虑清楚。"] = "Once you go in, there is no turning back. You need to think this through carefully.",
    ["一本……会说话的剧本？"] = "Говорящий сценарий?",
    ["一本笔记？封面写着……《睡莲镇漫游指南》？"] = "Тетрадь? На обложке написано... «Путеводитель по городку Водяных Лилий»?",
    ["一本被翻烂的教材，扉页上潦草地写着“老师没教被附身怎么办”，内页插图中疑似有蠕动的血迹。"] = "Потертый учебник с надписью «Что делать, если он одержим, а не преподан учителем» на титульном листе и подозрительно извивающимися пятнами крови на иллюстрациях.",
    ["一杯 “安慰剂” 正是你需要的，闻起来是花香味的主调，但入口又会有偏酸涩的口感。"] = "«Плацебо» — это именно то, что вам нужно. Он пахнет в основном цветами, но при питье имеет кисловатый и вяжущий вкус.",
    ["一直是满的？听起来老板是个很勤快的人。"] = "Всегда полный? Судя по всему, начальник очень старательный человек.",
    ["七重试炼将铸就你的锋芒。试问！你，准备好了吗？"] = "Семь испытаний укрепят ваше преимущество. Я спрашиваю! Вы готовы?",
    ["上一秒我们还在正常交谈，下一秒他就用警惕陌生的眼神看我……没有一种医学术语能形容他的状态。"] = "В одну секунду мы нормально разговаривали, в следующую он смотрел на меня настороженными, незнакомыми глазами... Ни один медицинский термин не может описать его состояние.",
    ["上去吧。下面的只是前戏……上面才是正片。"] = "Идите вверх. То, что внизу, - это всего лишь прелюдия... настоящее шоу - наверху.",
    ["上班时间也能这样呼呼大睡吗？真羡慕啊！"] = "Неужели можно так крепко спать в рабочее время? Я так завидую!",
    ["上面？你是说二层贵宾区吧。"] = "Наверху? Вы имеете в виду вип-зону на втором этаже.",
    ["下午<P_Yellow>三点前</>。当时我们吵了一架，我劝他把那件古董处理掉，可他根本不听。"] = "До <P_Yellow> три часа </> дня. Мы тогда поссорились, и я посоветовал ему избавиться от этого антиквариата, но он вообще не послушался.",
    ["下把我不会输了！这次赌……帮妈妈跑腿！"] = "В следующий раз я не проиграю! На этот раз спорим на... поход по маминым поручениям!",
    ["下次路过，要是听说了什么稀奇古怪的石头或者画儿的故事，一定记得跟我讲讲呀！我这别的没有，故事和酒管够。"] = "В следующий раз, когда будешь проходить мимо, если услышишь какие-нибудь диковинные истории о странных камнях или картинах, обязательно расскажи мне! Чего-чего, а уж историй и выпивки у меня вдоволь!",
    ["下水？你是外地来的吧！"] = "Зайти в воду? Вы, должно быть, из другого города!",
    ["下设神奇动物、神奇植物、灵界生物三大分会，再往下还有一些特殊的兴趣小组。"] = "В нем есть три подассоциации: «Волшебные животные», «Волшебные растения» и «Существа духовного мира», а далее есть несколько групп с особыми интересами.",
    ["不……你听我说……山里有东西……我不该接这份活……这是对山脉的不敬……"] = "Нет... послушай меня... в горах что-то есть... Зря я брал эту работу... это неуважение к горам...",
    ["不不不，直走那条路不是我们的营地。"] = "Нет-нет-нет, если идти прямо по той дороге — там не наш лагерь.",
    ["不仅如此，箱子还在动！你可能看不出来，虽然很缓慢，但它在移动，我已经观察它很久了。"] = "Мало того, коробка движется! Возможно, вы не сможете этого сказать, но, хотя он и очень медленный, он движется. Я наблюдаю за этим уже давно.",
    ["不仅是偷东西！被偷走的东西还会被埋在野外，旁边还立了块墓碑！"] = "Это не просто воровство! Украденные вещи закопаны в дикой природе, а рядом с ними даже установлено надгробие!",
    ["不可能跑远……"] = "Он не мог далеко убежать...",
    ["不告诉你喵，你是来抓主人的喵。"] = "Не скажу тебе, мяу. Ты здесь, чтобы поймать хозяина, мяу.",
    ["不好意思，不……不能道歉，能不能骂我两句？"] = "Извини, нет... Я не могу извиняться, можешь меня дважды отругать?",
    ["不客气！我们只想请您帮个小忙，可以吗？"] = "Пожалуйста! Мы просто хотели попросить тебя о небольшой услуге, ты согласен?",
    ["不对不对，骑士劈开的是恶龙吐出的乌云，阳光照进来，才赶走了恶龙！"] = "Нет-нет, рыцарь расколол темные тучи, извергнутые злым драконом, и солнечный свет засиял, прогнав «Злой Дракон»!",
    ["不对啊！我得到的启示是太阳升起时对着城堡鞠躬十次，丢失的物品就会自动回来。"] = "Это неправильно! Откровение, которое я получил, заключалось в том, чтобы поклониться замку десять раз, когда взойдет солнце, и потерянные предметы автоматически вернутся.",
    ["不对！我听的版本是戴着礼帽的灰兔。"] = "Неправильный! Версия, которую я слышал, была серым кроликом в цилиндре.",
    ["不对，是你先提的……对，咳咳，你说这话的目的是什么？动机是什么？谁指使你的？你是不是被某些危险存在蛊惑了？跟我走一趟！"] = "Нет, ты сам первый это начал... Так, кхм-кхм, с какой целью ты это говоришь? Каковы твои мотивы? Кто тебя подослал? Не околдовала ли тебя какая-то опасная сущность? А ну пройдем со мной!",
    ["不打扰，不打扰！有问题随时来找我！"] = "Не беспокойтесь, не беспокойтесь! Если у вас есть вопросы, приходите ко мне в любое время!",
    ["不敢说全部，但几乎都是。毕竟每朵花都像孩子，得知道它们的脾气。"] = "Я бы не сказал все, но почти все. Ведь каждый цветок подобен ребенку, надо знать его темперамент.",
    ["不明白……但他的姿势，似乎是坠楼而亡……"] = "I don't understand... but his posture seems to suggest he died from a fall...",
    ["不是要看小说吗？ "] = "Разве это не тот роман, который вы хотите прочитать?",
    ["不是！<P_Heart>（小声）</>那份“手稿”……你看完了吗？"] = "Нет! <P_Heart>(шепотом)</> Эта «рукопись»… ты дочитал ее?",
    ["不是，因为我有，有点结，结巴。"] = "Нет, потому что я немного заикаюсь.",
    ["不清楚。我给你父亲的贴身男仆塞了钱，他才肯告诉我这个消息。"] = "Не уверен. Я подкупил личного камердинера твоего отца, и именно он сообщил мне эту новость.",
    ["不用练习，可以多休息一会儿，或许也是一种幸运呢？"] = "Не нужно тренироваться, можно больше отдохнуть. Возможно, это удача?",
    ["不着急，在舞台的帷幕升起前，你有充足的时间准备。"] = "Не торопитесь, у вас есть достаточно времени, чтобы подготовиться до того, как поднимется занавес.",
    ["不知怎么，总感觉有些眼熟……您家里有兄弟吗？"] = "Не знаю почему, но ты выглядишь знакомо... у тебя есть братья?",
    ["不知道哪里传出的消息，说背对净化之泉，右手拿硬币从左肩上方向后投入水中，能够实现自己的愿望。"] = "Неведомо откуда пошел слух: если встать спиной к Источнику Очищения, взять правой рукой монетку и бросить ее через левое плечо в воду, то загаданное желание непременно сбудется.",
    ["不知道园丁先生的名字是什么。"] = "Я не знаю, как зовут мистера Гарденера.",
    ["不知道是哪个混蛋这么诅咒我们！"] = "Я не знаю, какой ублюдок нас так ругает!",
    ["不知道还敢来？滚回去写你的作业吧！"] = "Ты не знаешь и осмелишься прийти сюда? Вернитесь и сделайте домашнее задание!",
    ["不管怎样，先让我眯一会儿吧！"] = "В любом случае, дай мне сначала немного вздремнуть!",
