    ["不管是哪种，今晚我不太想讲故事。酒你随便喝，故事……留到下次吧。"] = "Как бы то ни было, сегодня мне не до историй. Пей сколько влезет, а истории... оставим на следующий раз.",
    ["不管是真是假，有些谜底，不知道比知道要好。"] = "Правда это или ложь, но о некоторых тайнах куда лучше не знать вовсе.",
    ["不能，我们哪也不去。 "] = "Нет, мы никуда не пойдем.",
    ["不行，伊迪丝，这种力量很神奇，但也很危险。知道得太多对你不是好事，有我来保护你就足够了。"] = "Нет, Эдит, эта сила волшебна, но и опасна. Знать слишком много вредно для тебя; того, что я защищаю тебя, достаточно.",
    ["不行，我真的不知道，再见。"] = "Нет, я правда не знаю, до свидания.",
    ["不要一脸不在乎啊！危机感，要有危机感啊！"] = "Не делай такое равнодушное лицо! Опасность — ты должен чувствовать опасность!",
    ["不要叹气，卡莱斯，你知道他们化作石像时是快乐的。"] = "Не вздыхай, Карлес, ты же знаешь, они были счастливы, когда превратились в каменные статуи.",
    ["不要听信谣言啊……怎么还越传越广了。"] = "Не слушайте слухи... как они распространяются еще дальше.",
    ["不要小瞧比你序列低的人，序列八也可以打败序列五……"] = "Не стоит недооценивать тех, чья Последовательность ниже твоей, Последовательность 8 тоже может победить Последовательность 5...",
    ["不要看我！我知道自己的舞步很滑稽。哎，这都是为了我的小鸟，你知道的，它从小就离开了妈妈……"] = "Не смотри на меня! Я знаю, что мои танцевальные движения забавны. Эй, это все для моей птички, ты знаешь, она оставила свою мать, когда была ребенком...",
    ["不要紧张，我们塔罗学派是一个友爱的大家庭，遇到困难可以咨询伟大的阿罗德斯大人，祂会给出答案的……"] = "Не волнуйтесь, наша Школа Таро — это дружная семья. Если столкнетесь с трудностями, обратитесь к великому владыке Ародосу, Он непременно даст ответ...",
    ["不要进入……雾气……"] = "Не входи... туман...",
    ["不论他留下的巨额遗产会留给他四个儿子中的哪一个，都让我们缅怀他，令他在女神的神国得以安息。"] = "Независимо от того, кому из четырех его сыновей достанется его огромное наследство, давайте вспомним его и позволим ему покоиться с миром в царстве Богини.",
    ["不说了，我赶着去接下一个委托了。"] = "Хватит болтать, я спешу за следующим заказом.",
    ["不过……在这期间，我看到夫人、约翰先生，还有仆人都去过卧室。"] = "Однако... в это время я увидел, как дама, мистер Джон и слуга вошли в спальню.",
    ["不过下次——衷心建议你别在我们的封锁线里“改主意”太频繁。"] = "Но в следующий раз я искренне советую вам не «передумать» слишком часто в условиях нашей блокады.",
    ["不过凡事都有代价。万一您不幸失败了，那就只能委屈您也变成木偶了……很划算的交易吧？"] = "Однако у всего есть цена. Если вы, к сожалению, потерпите неудачу, я могу только обидеть вас, превратив и вас в марионетку... Очень выгодная сделка, не так ли?",
    ["不过变故很快发生了。"] = "Но вскоре произошла перемена.",
    ["不过我听说，内维尔那家伙好像从山上带了什么东西下来。"] = "Но я слышал, что парень Невилл, кажется, принес что-то с горы.",
    ["不过无所谓，来这里的人都有自己的理由。"] = "Но это не важно, у каждого, кто сюда приходит, свои причины.",
    ["不过要等我把这该死的小偷抓到先！"] = "Но сначала мне придется подождать, пока я не поймаю этого проклятого вора!",
    ["不过这个地方，好像是有点凉飕飕的……"] = "Но в этом месте немного прохладно...",
    ["不过都已经这么久了，他怎么还不找过来呢？唔，那个爱哭鬼，不会是又哭鼻子了吧……"] = "Но прошло так много времени, почему он до сих пор не нашел дорогу сюда? Ох, этот плакса, он же не будет больше плакать, не так ли...",
    ["不过预言中的灾难似乎并没有发生……喔，难道是有“大人物”保护了金秋湖？"] = "Но катастрофы в пророчестве, похоже, не произошло... О, неужели «большая шишка» защитила озеро Золотой Осени?",
    ["不过，医生啊，你总一个人住在诊所楼上不是办法。我远房表亲的朋友的姑妈的女儿的同学在图书馆做事，和你一样爱看书。"] = "Однако, Доктор, для вас не выход всегда жить одному над клиникой. Одноклассница дочери тети подруги моего дальнего родственника работает в библиотеке и любит читать так же, как и вы.",
    ["不过，在我们的世界里，这些都是童话传说，没有它们是真实存在的证据。我更倾向是这个世界的神秘学知识扰乱时空传到我们的世界。"] = "Впрочем, в нашем мире все это лишь сказки и предания, нет никаких доказательств их реального существования. Я скорее склонен думать, что мистические знания этого мира исказили пространство и время, проникнув в наш мир.",
    ["不过，在潜入调查前，我需要对你进行一项小小的考验。"] = "Однако, прежде чем мы углубимся в расследование, мне нужно подвергнуть вас небольшому тесту.",
    ["不过，我现在过得很好。我维护这里的交易公平，我相信这是神真正想要的。"] = "Однако сейчас у меня дела идут очень хорошо. Я поддерживаю здесь справедливость сделок и верю, что именно этого хочет Бог.",
    ["不过，现在我要向女神祷告，希望女神能庇佑我妈妈的病快点好起来。"] = "Но сейчас мне нужно помолиться Богине. Надеюсь, Богиня защитит мою маму, и та скорее поправится.",
    ["不过，躲在这里果然还是太吓人了……我还是回去找比利吧，下次再换个地方藏。"] = "Однако прятаться здесь действительно слишком страшно... Мне лучше вернуться и найти Билли, а в следующий раз спрятаться где-нибудь в другом месте.",
    ["不过，还是要好心提醒你一下——这可不是一个轻松的任务，但足够有趣，好好享受吧。"] = "Однако должен вам напомнить — квест это не простой, но достаточно интересный. Наслаждайся этим.",
    ["不过，还需要更多的资料去验证。"] = "Однако для подтверждения этого необходимо больше данных.",
    ["不错……这里……很温暖……"] = "Неплохо... здесь... очень тепло...",
    ["不！不是我！怎么可能是我！我没有理由杀害老爷啊！"] = "Нет! Это не я! Как это мог быть я?! У меня не было никаких причин убивать господина!",
    ["不！爷爷！爷爷还在下面！本杰明哥哥……"] = "Нет! Дедушка! Дедушка все еще внизу! Брат Бенджамин...",
    ["不，不太能……"] = "Нет, не совсем...",
    ["不，不，女士，高歌是指这种蘑菇从离开盆栽开始就会高声唱歌，哪怕是被臼齿咀嚼、被咽进胃袋，也绝对不会停止！"] = "Нет-нет, сударыня, под «Пением» имеется в виду то, что этот гриб будет громко петь с того момента, как покинет горшок, и даже если его разжевать коренными зубами или проглотить в желудок, он совершенно не перестанет!",
    ["不，不，那危险的东西就在城堡的废墟里，等待人放松警惕，等我们以为安全了，然后就会……杀了所有人！"] = "Нет-нет, эта опасная тварь находится в руинах замка и ждет, пока люди ослабят бдительность. Как только мы подумаем, что мы в безопасности, оно... всех убьет!",
    ["不，只是对你这位眉头紧皱小姐如此。现在眉头松开了，也更好看了。"] = "Нет, только такой даме с нахмуренными бровями, как ты. Теперь, когда ваши брови расслабились, вы выглядите еще лучше.",
    ["不，您肯定知道，我看见您从那边走过！伊迪斯，快！"] = "Нет, ты должен знать, я видел, как ты шел туда! Эдит, быстрее!",
    ["不，最后木马骑士倒下了，他的盔甲周围开出了白色的小花。"] = "Нет, в конце концов Деревянный Конь-Рыцарь пал, а вокруг его доспехов расцвели маленькие белые цветы.",
    ["不，说抱歉的应该是我才对。这不是什么听了会让人微笑的故事。"] = "Нет, это я должен извиниться. Это не история, которая заставляет людей улыбаться.",
    ["不，还需要灵性……我有了新的思路！"] = "Нет, нужна еще духовность... У меня появилась новая мысль!",
    ["不，这是个好结局。"] = "Нет, это хороший конец.",
    ["世界不是本来就这样？她却神叨叨的，还写了很多笔记。"] = "Разве мир не такой? Она вела себя загадочно и писала много заметок.",
    ["世界的本色是无序，何不随心所欲？"] = "Истинная природа мира — беспорядок, так почему бы не поступать как заблагорассудится?",
    ["世界的本色是秩序，回归原状是必然。"] = "Истинная природа мира — порядок, и возвращение к исходному состоянию неизбежно.",
    ["丝巾……我怀念的……你何时能来到我身边。"] = "Шелковый шарф... тот, по которому я скучаю... когда ты будешь рядом со мной?",
    ["两位真幸福啊，祝你们新婚快乐！"] = "Какая вы счастливая пара, совет да любовь!",
    ["丰收后就会迎来的荒芜期吗……枯萎的枝藤会是不错的装饰。"] = "Бесплодный период, который наступает после сбора урожая... увядшие лозы могли бы стать хорошим украшением.",
    ["为什么呢？"] = "Почему?",
    ["为什么在地上睡觉？休息室有更舒服的空间。"] = "Зачем спать на полу? В гостиной есть более удобные места.",
    ["为什么？"] = "Почему?",
    ["为什么？你看上去挺友善的。"] = "Почему? Ты выглядишь вполне дружелюбно.",
    ["为什么？女神不喜欢吵闹的孩子吗？"] = "Почему? Богиня не любит шумных детей?",
    ["为什么？我……我不想别人也变成这样。自从那天我见到了那副场景，一切都变了。可怕，太可怕了……"] = "Почему? Я... я не хочу, чтобы другие закончили так же. С тех пор, как я увидел эту сцену в тот день, все изменилось. Это ужасно, слишком страшно...",
    ["主人又在研究新的怪茶咪。"] = "Мастер снова исследует новые странные чаи, мяу.",
    ["主人是位魔药天才！能为她工作真是幸福啊！"] = "Мастер — гений зелий! Это настоящее счастье работать у нее!",
    ["主教大人，我向您忏悔，我们一家前阵子一直在供奉那个“神兔”。我们违背了对女神的忠诚……"] = "Ваше Преосвященство, я исповедуюсь вам: наша семья некоторое время назад поклонялась тому «Божественному кролику». Мы предали свою преданность Богине...",
    ["之前他们小队一起出任务，只有他回来了，从那之后他就像变了一个人。"] = "Раньше их команда вместе отправлялась на квест, и вернулся только он. С тех пор он стал другим человеком.",
    ["之前有人骑着脚踏车挂在了生命之脉上，那辆肇事脚踏车还在工匠房放着呢。"] = "Раньше кто-то катался на велосипеде и повесил его на «Пульс жизни»; этот оскорбительный велосипед все еще находится в комнате мастера.",
    ["乐意为你效劳。"] = "Рад быть полезным.",
    ["乖，摸摸头，不是你的错，盔甲之神会原谅你。"] = "Там, там, позволь мне погладить тебя по голове. Это не ваша вина; Бог Доспехов простит тебя.",
    ["也没什么，新人总是对这里充满好奇，然后向阿罗德斯大人发问。"] = "Ничего особенного, новички всегда проявляют любопытство к этому месту, а потом задают вопросы лорду Арродесу.",
    ["也许他已经去别的地方了呢？你要不要换个地方找找？"] = "Возможно, он ушел куда-то еще? Хотите попробовать поискать где-нибудь еще?",
    ["也许你能给我点启发？金秋湖让你想到什么？"] = "Возможно, вы дадите мне немного вдохновения? О чем заставляет вас думать озеро Золотая осень?",
    ["也许吧。"] = "Возможно.",
    ["也许吧，昨天，今天，明天，我没有留意。"] = "Может быть. Вчера, сегодня, завтра я не обращал внимания.",
    ["也许它迷路了？妈妈说，有的人害怕的时候会乱发脾气。"] = "Может, он заблудился? Мама говорит, что некоторые люди, когда пугаются, начинают злиться и капризничать.",
    ["也许是哪家的千金。"] = "Возможно, она дочь какой-то семьи.",
    ["也许骑士是在帮助他的龙朋友冷静下来？"] = "Может быть, рыцарь помогал своему другу-дракону успокоиться?",
    ["也许，会让您能轻松回想起一些重要的事情。"] = "Возможно, это позволит вам легко вспомнить какие-то важные вещи.",
    ["也许，这个药剂做出来它就会出现？"] = "Может быть, если это зелье приготовить, оно появится?",
    ["书会说话？！"] = "The book can talk?!",
    ["买书的人越来越少了，如果康修娜没失踪，她肯定知道该怎么做。"] = "Все меньше и меньше людей покупают книги. Если бы Консуна не пропала, она бы точно знала, что делать.",
    ["乱斗的战场十分特别，你召唤的是一段段俱乐部成员的历史投影。\n作为召唤者，你既是观战者，又是参与者——多么刺激有趣的乱斗！\n真的不来一局吗？"] = "Поле потасовки поистине уникально: вы призываете исторические проекции членов клуба.\nКак призыватель, вы одновременно и зритель, и участник битвы. Какая захватывающая потасовка!\nНеужели не хотите сыграть раунд?",
    ["事不宜迟，我们需要立刻行动。"] = "Нельзя терять времени; нам нужно действовать немедленно.",
    ["事已至此，先吃葡萄吧。"] = "Что сделано, то сделано, давайте сначала съедим виноград.",
    ["二十分钟？怀表才走这么一点点呢！"] = "Двадцать минут? Карманные часы работают только до сих пор!",
    ["于是相聚在这里。"] = "И вот мы собрались здесь.",
    ["五个苏勒，带你上城堡里走一遭。淘到的东西都归你，怎么样？"] = "Five Soles отправит вас в путешествие по замку. Все, что вы найдете, принадлежит вам, как насчет этого?",
    ["五海啊！你们的阴霾，终将归来！"] = "О, Пять Морей! Твоя дымка вернется!",
    ["亲戚们都说我最稳重，但只有我知道，我父亲有多偏心。"] = "Все родственники говорят, что я самый устойчивый, но только я знаю, насколько предвзятым был мой отец.",
    ["亲爱的，你想喝点什么？"] = "Дорогая, чего бы ты хотела выпить?",
    ["亲爱的，你看着面生得很呢，从哪儿来的？快进来坐坐，喝点热酒。"] = "Дорогой, ты выглядишь очень незнакомо. Откуда ты? Зайди, посиди немного, выпей горячего вина.",
    ["人交给我们就好。他会被送进那座‘永恒监狱’——你们听说过吧？就是那座邪门的监狱。"] = "Просто оставьте этого человека нам. Его отправят в эту «Вечную тюрьму» — вы о ней слышали, да? Эта жуткая тюрьма.",
    ["人力物力劳动力，路费车费误工费……嗯，还得再算算……"] = "Рабочая сила, материальные ресурсы, затраты на рабочую силу, командировочные расходы, потерянная зарплата... хм, надо еще раз посчитать...",
    ["人和牛杂交除了让人长出犄角和尾巴、变得强壮又耐劳、可以哞哞叫……<P_Heart>（逐渐心虚）</>以外，还有什么好处吗？"] = "Помимо того, что у людей отрастают рога и хвосты, они становятся сильнее и терпимее, умеют мычать... <P_Heart> (Постепенно чувствуя вину) </> Есть ли еще какая-то польза от скрещивания человека и скота?",
    ["人类想要成为非凡者，并在非凡之路上持续走下去，只能依靠魔药。"] = "Люди, желающие стать Потусторонними и продолжать идти по пути сверхъестественного, могут полагаться только на зелья.",
    ["什么“杰克爱吃这个”，“杰克上次说那个”……"] = "Такие вещи, как «Джек любит это есть», «Джек сказал это в прошлый раз»…",
    ["什么宝藏？"] = "Какое сокровище?",
    ["什么想法？"] = "Какая идея?",
    ["什么意思？"] = "Что это значит?",
    ["什么祈祷？我不知道啊。他们四个都在跳舞，我也要跳！"] = "Какая еще молитва? Я ничего не знаю. Они вчетвером танцуют, и я тоже хочу танцевать!",
    ["什么西红柿！那是深眠花！"] = "Какие помидоры! Это цветы глубокого сна!",
    ["什么都没找到。"] = "Ничего не найдено.",
    ["什么？"] = "Что?",
    ["什么？你不知道？你的东西没有被偷吗！"] = "Что? Вы не знаете? Не украли ли твои вещи!",
    ["什么？你在说什么呢？"] = "Что? О чем ты говоришь?",
    ["什么？可我不是……"] = "Что? Но я же не...",
    ["什么？报亭自己说话了！"] = "Что? Газетный киоск говорил сам за себя!",
    ["什，什么？他要用那些葡萄做成酒。呃，好吧，听上去是很不错……我喜欢喝酒！"] = "Ч-что? Он собирается сделать вино из этого винограда. Э-э, ну, это звучит неплохо... Я люблю выпить!",
    ["仅仅是魔药配方这一项，就能将人推向不可预知的漩涡。"] = "Один лишь рецепт зелья способен ввергнуть человека в непредсказуемый водоворот.",
    ["仆人们说的那些幽灵传说……倒是有点意思。说不定有机会能亲眼见识见识。"] = "Байки о призраках, что рассказывают слуги... довольно любопытны. Быть может, мне еще доведется увидеть все своими глазами.",
    ["今天会捞出什么呢？"] = "Что же мы выловим сегодня?",
    ["今天天气真好，亲爱的{{先生|小姐}}，来串葡萄尝尝，这没准是金秋湖最好吃的葡萄呢！"] = "Погода сегодня такая хорошая, дорогой {{Mr.|Ms.}}. Возьмите немного винограда; возможно, это лучший виноград на озере Золотой Осени!",
    ["今天开始，我，新的，“至尊霹雳舞王”！"] = "С сегодняшнего дня я — новый «Верховный король брейкданса»!",
    ["今天由我帮父亲照看报亭，这是你要的日报，没什么事就赶快走吧！"] = "Сегодня я помогаю отцу присматривать за газетным киоском. Вот ежедневная газета, которую вы хотели, поторопитесь, если больше ничего нет!",
    ["今天的南瓜怎么这么轻……像是空心的？"] = "Почему сегодняшняя тыква такая легкая... как будто полая?",
    ["今天说要和你去看日出，明天又想去森林里漫步。"] = "Сегодня они зовут встретить с ними рассвет, а завтра уже хотят прогуляться по лесу.",
    ["今天还得完成巴纳比队长交代的事。"] = "Сегодня нам предстоит выполнить задания, поставленные капитаном Барнаби.",
    ["今天，她就要被别人求婚了。而我？我连一句确定的承诺都不敢说出口！"] = "Сегодня другой мужчина сделает ей предложение. А я? Я даже не посмел дать ни единого твердого обещания!",
    ["今天，我们之所以相聚在这里，是为了祭奠我们的老朋友，霍普先生。"] = "Сегодня мы собрались здесь, чтобы выразить свое почтение нашему старому другу мистеру Хоупу.",
    ["今日有三种特调可供您选择。分别是“记忆之水”、“酣眠”和“月下漫步”。"] = "Сегодня на ваш выбор три особенных напитка. Это «Вода памяти», «Глубокий сон» и «Прогулка под луной».",
    ["今晚……去谁家呢……"] = "Сегодня вечером... в чей дом мне пойти...",
    ["今晚吃什么呢……"] = "Что съесть сегодня вечером...",
    ["今晚我得去查查，是不是真的有只兔子在跟我们抢信徒。"] = "Мне нужно сегодня вечером пойти проверить, действительно ли кролик конкурирует с нами за верующих.",
    ["从克莱拉那里拿来的钱，我都用在我们的孩子身上了，绝对不藏私！"] = "Все деньги, полученные от Клары, я потратил на наших детей; Я точно ничего не скрываю!",
    ["从前我们常常一起躺在这片花丛里看星星。"] = "Мы вместе лежали на этом участке цветов и смотрели на звезды.",
    ["从前有座山，山上有许多古代遗迹，几乎可以确定曾经存在一个古老的国度……"] = "Когда-то стояла гора, а на ней — множество древних руин; можно с уверенностью сказать, что здесь когда-то процветало древнее царство...",
    ["从前的我老实本分，是巴伐特银行里最不起眼的一个记账员。"] = "Раньше я был честным и надежным, самым незаметным бухгалтером в Бават Банке.",
    ["从头到尾，都只有你在这里，欣赏这场闹剧。"] = "От начала и до конца здесь был только ты, наслаждаясь этим фарсом.",
    ["从旁边的隔间走！那里有通往二楼的传送仪式！"] = "Go through the compartment next to us! There is a Teleport ritual there that leads to the second floor!",
    ["他……是您什么人？"] = "Что... он для тебя?",
    ["他一定是有事耽搁了。"] = "Должно быть, его что-то задержало.",
    ["他一直以为父亲放养他是因为他是养子，不重视他！结果染上了小偷小摸的毛病！哎！"] = "Он всегда думал, что отец позволил ему разгуляться, потому что он был приемным сыном и не ценил его! В результате он приобрел привычку к мелкому воровству! Вздох!",
    ["他七岁那年发高烧，是我守了他三天三夜。从那时起，我就一直替他保管药品。"] = "Когда ему было семь лет, у него была высокая температура, и я наблюдал за ним три дня и три ночи. С тех пор я храню для него лекарства.",
    ["他不喜欢别人碰他的东西……只有我例外。"] = "Он не любит, когда трогают его вещи... исключение только я.",
    ["他为什么暴躁？"] = "Почему он такой раздражительный?",
    ["他也在这里吗？也跟你一样在练习？"] = "Он тоже здесь? Вы тренируетесь так же, как и вы?",
    ["他以前是个不错的木匠，就是那之后疯的。我猜他那天可能正好在附近，看见了什么不该看的东西。"] = "Раньше он был хорошим плотником, а сошел с ума как раз после тех событий. Подозреваю, в тот день он случайно оказался поблизости и увидел то, чего видеть не следовало.",
    ["他们一直在等你。"] = "Они ждали вас.",
    ["他们不和你玩吗？"] = "Они с тобой не играют?",
    ["他们以前也和您一样，都是……贵客。"] = "Они раньше были такими же, как вы, все сплошь... почтенные гости.",
    ["他们似乎在谈论什么了不得的事。"] = "Кажется, они говорят о чем-то невероятном.",
    ["他们发生了一些……不好的变化。你看起来也是……嗯？想必你一定能懂。"] = "С ними произошли кое-какие... нехорошие перемены. Кажется, с вами тоже... м-м? Уверен, вы меня понимаете.",
    ["他们围住我，凑近我……就像现在您和我的距离……"] = "Они окружили меня, прижались ко мне... так же, как расстояние между нами сейчас...",
    ["他们整队人就那么进到城堡里面去，然后……光，还有声音！所有人像睡着了似的，那场面太诡异了……"] = "Весь их отряд вошел в замок, а затем... свет и звуки! Все будто уснули разом, это было жуткое зрелище...",
    ["他们的行头十分引人注目，又到处询问情况。我猜，他们是某些特别的官方机构。"] = "Их одежда была очень привлекательной, и они повсюду расспрашивали о ситуации. Я подозреваю, что они были из какой-то особой официальной организации.",
    ["他们走后，两件事变了。一是城堡，那种奇怪的感觉消失了；二是老杰克——哦，就是现在守在铁轨那边的疯子。"] = "После их ухода изменились две вещи. Одним из них был замок; это странное чувство исчезло. Вторым был Старый Джек — ох, это тот сумасшедший, который сейчас охраняет железнодорожные пути.",
    ["他们都不想玩了。陪我来一把吗，我不缺钱，只是……"] = "Никто из них больше не хочет играть. Вы присоединитесь ко мне на раунд? У меня нет недостатка в деньгах, просто...",
    ["他会怎么选呢，"] = "Как бы он выбрал?",
    ["他关爱着每位生灵，哪怕你没有信仰“愚者”，依然可以享受塔罗学派的一切。"] = "Он заботится о каждом живом существе; даже если ты не веришь в «Шута», ты всё равно можешь пользоваться всем, что предлагает Клуб Таро.",
    ["他出生的时候，我就在这里。他第一次骑马，第一次打猎……我全都记得。"] = "Я был здесь, когда он родился. Его первая поездка на лошади, его первая охота... Я все это помню.",
    ["他利用我召唤出许多历史投影，那些投影却用靠垫闷死了他，还把他推下了楼！"] = "He used me to summon many historical projections, but those projections smothered him with cushions and pushed him downstairs!",
    ["他只是被鸟啄了脑袋，可鸟却要被他谩骂一整天。"] = "Его только что клюнула птица в голову, а он весь день проклинал птиц.",
    ["他叫约翰尼，一头金发，还很年轻，是个体面的医生……他带着狮子纹章的戒指，那是我们家的徽记。"] = "Его зовут Джонни, светлые волосы, еще очень молодой, приличный врач... он носит кольцо с гербом льва, это наша семейная эмблема.",
    ["他呀？是我这店里最不懂规矩的长期客人……开玩笑的！他是我的未婚夫。"] = "Ему? Он самый неуправляемый постоянный гость в моем магазине... Шучу! Он мой жених.",
    ["他大概是想换掉某个愚蠢的演员。"] = "Вероятно, он хочет заменить какого-нибудь глупого актера.",
    ["他就倒在一间反锁的卧室里，是管家叫人撞开的门。目前现场还保持着原来的样子，我没有让人动过任何地方。"] = "Он потерял сознание в запертой спальне; это дворецкий приказал людям выломать дверь. Сцена все та же, что и была; Я никому не позволял ничего трогать.",
    ["他常年在外完成“愚者”先生布置的任务，好像在海上寻找什么，偶尔才会回到学派。"] = "Он проводит время, выполняя квесты, заданные Мистеромом, по-видимому, ища что-то в море, и лишь изредка возвращается в школу.",
    ["他干了什么？"] = "Что он сделал?",
    ["他当时的情况很微妙，像是体内凭空多出了另一个人格。他的眼神、措辞、甚至坐姿，都会在某一瞬间发生变化。"] = "Его состояние в тот момент было очень тонким, как будто в его теле из воздуха появилась другая личность. Его глаза, слова и даже его сидячая поза мгновенно изменились.",
    ["他总是努力到令我担心……如果你遇见波特，记得转告他有空多来休息室放松一下，别给自己太大压力。"] = "Он всегда так усердно работает, что меня это беспокоит... Если ты встретишь Поттера, не забудь сказать ему, чтобы он приходил в гостиную отдохнуть, когда у него есть время, не дави на себя слишком сильно.",
    ["他总是执着于种出最香甜的南瓜，哈哈，不过，他的南瓜的确非常美味！"] = "Он прямо одержим идеей вырастить самую сладкую и ароматную тыкву! Ха-ха, но надо признать, тыквы у него и впрямь отменные!",
    ["他总爱背个旧皮包，说是要画遍各地的怪石头。"] = "Он вечно таскает старую кожаную сумку, повторяя, что хочет зарисовать причудливые камни во всех уголках земли.",
    ["他总说标点要像婚约般严谨。"] = "Он всегда говорил, что пунктуация должна быть столь же строгой, как брачный контракт.",
    ["他打败了恶龙？"] = "Победил ли он «Злой Дракон»?",
    ["他推开了死亡国度的大门，看到他的姐姐正在那里煮蒲公英茶，桌上永远摆着两人份的蜂蜜松饼……"] = "Он распахнул врата царства смерти и увидел там свою сестру: она заваривала чай из одуванчиков, а на столе всегда стояли медовые оладьи на двоих...",
    ["他救过我，我在……守护他。"] = "Он спас меня, я... охраняю его.",
    ["他是一位旅人，和我们一样年轻。"] = "Он путешественник, такой же молодой, как и мы.",
    ["他是一只灰色花猫，喜欢睡在丝瓜筐里。"] = "Это серый полосатый кот, который любит спать в корзинке из люфы.",
    ["他是我最佩服的小众诗人。他的作品平实而感人，可惜能欣赏的人太少了……这个浮躁的世界！"] = "Он нишевый поэт, которым я восхищаюсь больше всего. Его работы просты и трогательны, но, к сожалению, их мало кто может оценить... в этом беспокойном мире!",
    ["他死后，召唤我的仪式魔法还没有停止！如果不能净化邪神污染，我们恐怕都会死在这里！"] = "After he died, the Ritual Magic that summoned me didn't stop! If we can't perform Purification on the corruption of the evil God, we will likely all die here!",
    ["他现在缺少猎物信息，正抓耳挠腮呢。"] = "В настоящее время ему не хватает информации о своей жертве, и он в тревоге чешет затылок.",
    ["他的声音听起来有点奇怪……但我不敢违抗命令，就把<P_Yellow>托盘放在门口</>，先离开了。"] = "Его голос звучал немного странно... но я не посмел ослушаться приказа, поэтому я, <P_Yellow>, оставил поднос у двери </> и ушел первым.",
    ["他的状态很不好……浑浑噩噩的，又喜怒无常，我劝他别去，但他说这种材料只有这山脉有。"] = "Он был сам не свой... затуманенный рассудок, перепады настроения. Я уговаривал его не ходить, но он твердил, что этот материал можно найти только в этих горах.",
    ["他的眼神偶尔扫向某个方向——不是看人，像在确认什么。"] = "Его взгляд изредка устремляется в определенную сторону — ни на кого не глядя, словно что-то подтверждая.",
    ["他虽杀人无数，但从未被警方逮捕过。"] = "Хотя он убил бесчисленное количество людей, он ни разу не был арестован полицией.",
    ["他说丰饶之树能复活他的宠物鸟！……我可怜的孩子。"] = "Он сказал, что Дерево изобилия может воскресить его домашнюю птицу!...Мой бедный ребенок.",
    ["他说外面的世界很大。"] = "Он говорил, что внешний мир огромен.",
    ["他说廷根有个大学城，坐飞艇能飞到云上。 "] = "Он сказал, что в Тингене есть университетский округ, и над облаками можно летать на дирижабле.",
    ["他说贝克兰德的火车很长，一路能到雪山。"] = "Он сказал, что поезд в Баклунде очень длинный и может дойти до заснеженных гор.",
    ["他说，只有非凡者可以发挥它“保护”的力量。"] = "Он сказал, что только Потусторонний может раскрыть его силу «защиты».",
    ["他还在埋东西的地方立了墓碑！诅咒我们已经死了！"] = "Он даже установил надгробие, где закопал свои вещи! Проклиная нас, как будто мы уже умерли!",
    ["以及，必须遵守规则，否则我们的人会随时请你离开。"] = "И еще: вы обязаны соблюдать правила, иначе наши люди в любой момент попросят вас на выход.",
    ["以它为圆心，十米范围内将充斥纯净温暖的力量，正常人无法察觉，但死灵类怪物将不断受到伤害，它们会如同炽热火球下的水池，飞快地“蒸发”着，哪怕怨魂和幽影，也同样如此，只是会支撑得更久一点。"] = "С его центром десятиметровый радиус наполнится чистой и теплой силой. Обычные люди не могут этого воспринять, но монстрам-нежити будет постоянно наноситься урон. Они будут «испаряться» быстро, как лужа под палящим огненным шаром, даже Призраки и Тени, хотя и продержатся немного дольше.",
    ["仪式材料？这不是个菜摊吗？"] = "Ритуальные материалы? Но разве это не овощная лавка?",
    ["仰望星空派吗，听起来不错，我看看价格……啊！"] = "Пирог «Вглядываясь в звёзды»? Звучит заманчиво, посмотрю-ка я цену... Ох!",
    ["仰望星空派！名字取自鱼群跃出海面，仰望繁星的意象。采用间海郡新鲜河鱼佐以贝克兰德上等黄油与凛冬郡面粉……"] = "Пирог, смотрящий на звезды! Название взято из изображения рыб, выпрыгивающих из моря, чтобы посмотреть на звезды. В нем используется свежая речная рыба из графства Мидсишир, приправленная высококачественным сливочным маслом из округа Уинтер и мукой из Баклунда...",
    ["伊恩——伊恩到底什么时候来，我要看佛尔思的新作！"] = "Йен, когда именно приедет Йен? Хочу увидеть новую работу Форса!",
    ["伊迪丝，你总是这么胆小。放心吧，就算真有什么东西，它们也不敢靠近这里。"] = "Эдит, ты всегда такая робкая. Не волнуйтесь, даже если там действительно что-то есть, они не посмеют подойти сюда.",
    ["休息，我要休息……"] = "Отдыхай, мне нужно отдохнуть...",
    ["伙计，你对工作太热心了，我害怕，不就是帮她分分材料吗？"] = "Приятель, ты слишком увлечен работой. Я боюсь. Разве это не просто помощь ей ​​в сортировке материалов?",
    ["会长的衣服让人感觉亲切，又非常贴合时代环境，而且很少有人穿着相同风格的衣服，再也不怕撞衫啦！"] = "Одежда президента заставляет людей чувствовать себя доступными и очень соответствует обстановке той эпохи, и очень немногие люди носят одежду такого же стиля, поэтому я больше не боюсь носить то же, что и другие!",
    ["伟大的阿罗德斯大人，哥德巴赫猜想是可以被验证的吗？"] = "Великий Лорд Арродес, можно ли проверить гипотезу Гольдбаха?",
    ["伟大的阿罗德斯大人，请问考试的题目是什么？"] = "Великий господин Арродес, позвольте спросить, каков вопрос экзамена?",
    ["传说中的睡莲仙女呀……"] = "Легендарная фея водяных лилий...",
    ["传闻金秋湖受到了大地的恩赐，所以常年处于丰收季 。不过——"] = "Ходят слухи, что озеро Золотая Осень получила дар Земли, поэтому сезон сбора урожая здесь круглый год. Однако-",
    ["伸手试探，宝箱纹丝不动——它被锁住了。"] = "Когда я протягиваю руку, чтобы проверить его, сундук с сокровищами не сдвигается с места — он заперт.",
    ["似乎只是一具普通的尸体。"] = "Кажется, это обычный труп.",
    ["但……但他看起来那么严肃，我根本不敢靠近他。"] = "Но... но он выглядит настолько серьезным, что я вообще не смею к нему подойти.",
    ["但……你现在的眼神，和这里的人一样了。"] = "Но... твои глаза теперь такие же, как и у людей здесь.",
    ["但一想到有许多同伴陪着我，我就一点也不害怕了。"] = "Но как только я подумал о том, что со мной будет много товарищей, я совсем не боялся.",
    ["但也要随时保持警惕，有些学员很喜欢恶作剧，一定要谨慎对待入口的药剂。"] = "Но всегда оставайтесь настороже: некоторые ученики обожают шутить, так что будьте предельно осторожны с зельями, которые принимаете внутрь.",
    ["但从来没听说哪个邪教信仰兔子，祈祷仪式听上去也并不邪恶……"] = "Но я никогда не слышал ни о каком культе поклонения кролику, да и молитвенный ритуал не звучит злобно...",
    ["但他最近……忽然变得很冷淡。"] = "Но недавно... ему вдруг стало очень холодно.",
    ["但他最近老往外跑，你看，这会儿又不知道去哪了。"] = "Но в последнее время он сильно иссяк. Смотри, он снова не знает, куда пошел.",
    ["但他没有……一直没有……"] = "Но он этого не сделал... он никогда этого не делал...",
    ["但你看起来并不太好。"] = "Но ты выглядишь не слишком хорошо.",
    ["但凡你也被鱼刺卡过喉咙，你也会认同我的话。"] = "Если бы вас когда-нибудь подавили рыбной костью, вы бы тоже со мной согласились.",
    ["但在正式开始之前，你需要了解最基础的知识。"] = "Но прежде чем мы официально начнем, вам необходимо понять основы.",
    ["但如果你想要不一样的结局，或许可以换一个地方，"] = "Но если вам нужен другой финал, возможно, вам стоит попробовать другое место.",
    ["但实际上什么都没发生，不是吗？"] = "Но на самом деле ничего не произошло, не так ли?",
    ["但愿你说的是真的……"] = "Надеюсь, ты говоришь правду...",
    ["但我也不是什么消息都“灵通”，八卦的话瑞克了解的更多些。"] = "Но я не «хорошо информирован» обо всем, а когда дело доходит до сплетен, Рик знает лучше.",
    ["但我没有动手！一定是那件东西害了他！一定！"] = "Но я этого не сделал! Должно быть, именно эта штука причинила ему вред! Должно быть!",
    ["但是……污染扭曲了现实，普通的方法无法进入。"] = "Но... Искажение исказила реальность, и обычными методами туда проникнуть невозможно.",
    ["但是……没有挂饵？"] = "Но... на крючке нет наживки?",
    ["但是根据对等原则，阿罗德斯也会要求对方回答一个问题，或者接受雷击的惩罚。"] = "Но согласно принципу эквивалентности, Арродес также потребует от другой стороны ответить на вопрос или принять наказание в виде Удара Молнии.",
    ["但是这里很危险。"] = "Но здесь опасно.",
    ["但有人愿意帮我解决这桩麻烦事，我当然十分欢迎，廷根的戏码我早就看腻了，让那个疯狂戏剧节滚蛋吧！"] = "Но если кто-то готов помочь мне решить эту проблему, я, конечно, буду очень рад. Я давно устал от драм в Тингене; пусть этот сумасшедший драматический фестиваль затеряется!",
    ["但这杯我想自己喝完。你去别的地方看看吧。"] = "Но я бы хотел допить этот напиток один. Почему бы тебе не пойти поискать где-нибудь еще?",
    ["位于俱乐部场景中时，玩家将获得【结社之辉】增益：基于魅力、直觉的检定投骰结果+1。"] = "Находясь на сцене клуба, игроки получат положительный эффект [Сияние организации]: +1 к результатам кубиков для проверок Харизмы и Интуиции.",
    ["作为「召唤者」，可选取合适的幻象投影报名参战。每个幻象投影只能出战一次，请谨慎抉择。可提前报名后续场次，无需时刻在线。"] = "В качестве «Призывателя» вы можете выбрать подходящие призрачные проекции для записи на битву. Каждая проекция может сразиться лишь раз, выбирайте осмотрительно. Можно заранее записаться на следующие матчи, постоянный онлайн не требуется.",
    ["作为他的朋友，我可真有点失职。你瞧，现在又找不着他了。"] = "Как его друг, я действительно был весьма небрежен. Слушай, я больше не могу его найти.",
    ["你——"] = "Ты-",
    ["你……嗯你别难过！酒总是会卖光的！"] = "Ты... эм, не грусти! Вино всегда кончится!",
    ["你……您能把那东西赶出去？太好了！走走，快跟我来！"] = "Ты... Вы можете прогнать эту тварь? Замечательно! Пойдемте, скорее за мной!",
    ["你、你在这里站很久了吧。"] = "Ты, ты стоишь здесь уже долгое время, не так ли?",
    ["你一定喜欢！"] = "Они вам обязательно понравятся!",
    ["你一定要坚持错误的答案，我无话可说，只希望法庭上出示证据时，您也可以如此自信。"] = "Если вы настаиваете на неправильном ответе, мне нечего сказать. Я просто надеюсь, что вы сможете быть настолько уверены в себе, когда доказательства будут представлены в суде.",
    ["你一直面朝路口，在等人吗？"] = "Вы все время смотрели на перекрёсток. Вы кого-то ждете?",
    ["你一路上一定没少遇见想要卖你古董的家伙，还有带你进去探险的——现在的人，对历史一点敬畏都没有！"] = "По пути вы, должно быть, встретили множество парней, пытающихся продать вам антиквариат, и тех, кто предлагает взять вас с собой на прогулку — люди в наши дни вообще не уважают историю!",
    ["你不也是？"] = "Разве ты не делаешь то же самое?",
    ["你不信我？那我今晚就带你去看！要是真瞧见了，你得让我玩玩你的怀表；要是没有，我那辆脚踏车就借你骑两天！"] = "Ты мне не веришь? Тогда я возьму тебя посмотреть на это сегодня вечером! Если ты действительно это видишь, ты должен позволить мне поиграть с твоими карманными часами; если нет, я одолжу тебе свой велосипед на два дня!",
    ["你不感觉时间很紧迫吗？消化魔药，战斗训练，任务实践……"] = "Разве вы не чувствуете, что время очень поджимает? Переваривание зелий, боевая подготовка, практика выполнения заданий...",
    ["你不是说自己刚见过他？"] = "Didn't you say you just saw him?",
    ["你不知道沼泽女巫的传说吗？接触到这片池塘的人都会连做好几天噩梦！"] = "Разве вы не знаете легенду о Болотной Ведьме? Каждому, кто прикоснется к этому пруду, несколько дней будут сниться кошмары!",
    ["你不觉得很过分吗？"] = "Вам не кажется, что это слишком много?",
    ["你为什么要朝一个水池许愿呢？"] = "Почему ты загадываешь желание бассейну?",
    ["你为什么躲在这里？"] = "Почему ты прячешься здесь?",
    ["你为什么还是躲在这里练习？"] = "Почему ты все еще прячешься здесь, чтобы практиковаться?",
    ["你也一样。戴着面具，说什么话，其实都没差别。"] = "Ты такой же. В маске не имеет значения, что вы говорите.",
    ["你也想起舞吗？可以在那边的看板上报名！"] = "Тоже хотите станцевать? Записаться можно на доске объявлений вон там!",
    ["你也是被选中的人吧，这个世界上总有些人是特殊的，不是吗？"] = "Ты тоже избранный, верно? В этом мире всегда есть особенные люди, не так ли?",
    ["你也渴了吧，我为你点了一杯喝的。"] = "Вы, должно быть, тоже хотите пить; Я заказал для тебя выпить.",
    ["你也要来帮忙吗？你真是个好人！"] = "Ты тоже хочешь помочь? Ты действительно хороший человек!",
    ["你从没说过你失忆了啊……"] = "You never said you had amnesia...",
    ["你仔细看碑文了吗？我越来越觉得……这根本不是普通的恶作剧。"] = "Вы внимательно смотрели на надписи? Я все больше чувствую... это не просто шалость.",
    ["你们到底是从哪里听说这些的？"] = "Где вы все это слышали?",
    ["你们在向什么神祈祷？"] = "Какому богу ты молишься?",
    ["你们在聊什么？"] = "О чем вы, ребята, говорите?",
    ["你们在讨论什么？"] = "Что вы обсуждаете?",
    ["你们在说什么？"] = "О чем вы говорите?",
    ["你们在说谁？"] = "О ком ты говоришь?",
    ["你们在这个营地呆了多久？"] = "Как долго вы находитесь в этом лагере?",
    ["你们在这里做什么？"] = "Что ты здесь делаешь?",
    ["你们太过分了！都不理我！"] = "Вы переходите все границы! Никто на меня даже внимания не обращает!",
    ["你们是考古学家？"] = "Вы археологи?",
    ["你们看不见……他们看不见……只有我看见了！"] = "Ты не видишь... они не видят... только я это вижу!",
    ["你们知道我爬上来观赏瀑布有多不容易吗！"] = "Вы хоть представляете, как мне было тяжело подняться сюда, чтобы увидеть водопад!",
    ["你们说的杰瑞米是？"] = "Кто тот Джереми, о котором ты говорил?",
    ["你们这是什么营地？"] = "Что это у вас за лагерь?",
    ["你们这群鸟，竟敢啄我的脑袋！"] = "Стая птиц, как вы смеете клевать мою голову!",
    ["你儿子长什么样？"] = "Как выглядит ваш сын?",
    ["你再看看我是谁！"] = "Ты повнимательнее посмотри, кто я такой!",
    ["你到底去哪了，我亲爱的奥罗拉……我一定会找到你……"] = "Куда ты пошла, моя дорогая Аврора... Я тебя обязательно найду...",
    ["你向教会揭发了那位主教？"] = "Вы выдали этого епископа церкви?",
    ["你听她提起过我？那一定不是什么好话。"] = "Ты слышал, как она говорила обо мне? Тогда наверняка ничего хорошего.",
    ["你听起来很会说话，但这里，光会说话可不够。"] = "Язык у тебя подвешен хорошо, но здесь одних лишь слов недостаточно.",
    ["你告诉我，你是不是和克莱拉好上了！"] = "Скажи мне, ты встречался с Кларой?",
    ["你呢？看起来也不像是来寻欢作乐的。"] = "А вы? Похоже, ты тоже здесь не для того, чтобы искать удовольствия.",
    ["你和内维尔、马丁之间有矛盾？"] = "У вас конфликт с Невиллом и Мартином?",
    ["你在做什么？"] = "Что ты делаешь?",
    ["你在我这永远是最好看的！"] = "Ты всегда будешь для меня самой красивой!",
    ["你在找什么？"] = "Что Вы ищете?",
    ["你在找我？"] = "Ты ищешь меня?",
    ["你在用学徒的技能跑腿？"] = "Используете ли вы свои навыки ученика для выполнения поручений?",
    ["你在画什么？"] = "Что ты рисуешь?",
    ["你在这里住的怎么样？"] = "Как ты здесь живешь?",
    ["你在这里做什么？"] = "Что ты здесь делаешь?",
    ["你复习得怎么样了？"] = "Как успехи с подготовкой?",
    ["你好像很痛苦？"] = "Кажется, тебе больно?",
    ["你好啊，陌生人，你也是到屋顶来享受片刻安宁的吗？"] = "Привет, незнакомец. Вы тоже здесь, на крыше, чтобы насладиться моментом покоя?",
    ["你好！欢迎来到拉姆德小镇！我是亚伦上士，是小镇的巡逻员！"] = "Привет! Добро пожаловать в Ламуд Таун! Я сержант Аарон, городской патрульный!",
    ["你好，不，你不好，不对……"] = "Привет, нет, ты нехороший, нет...",
    ["你好，俱乐部的伙伴。“歌剧魅影”即将开启，要了解一下吗？"] = "Приветствую, соратник по клубу. «Призрак оперы» вот-вот начнется, хотите узнать подробности?",
    ["你好，尊敬的贵客。需要出售物产吗？"] = "Здравствуйте, уважаемый гость. Вам нужно продать продукцию?",
    ["你好，屋顶上有什么特别的吗？"] = "Здравствуйте, есть ли что-то особенное в крыше?",
    ["你好，愿女神庇佑你。"] = "Здравствуйте, пусть Богиня защитит вас.",
    ["你好，我是因蒂斯军事学院的。正在做实地考察。"] = "Здравствуйте, я из Военной академии Интис. Я провожу полевые исследования.",
    ["你好，是要擦皮鞋吗？很抱歉现在不行，我们得离开教堂。"] = "Здравствуйте, вам нужна чистка обуви? Извините, не сейчас, нам нужно покинуть церковь.",
    ["你好，请问你有没有看见过我的朋友？"] = "Привет, ты видел моего друга?",
    ["你好，请问有什么需要帮助的吗？"] = "Здравствуйте, могу ли я вам чем-нибудь помочь?",
    ["你好，这位{{先生|女士}}，欢迎来到廷根，请允许我向您推荐我社的观光马车游览服务。"] = "Привет, этот {{Mr.|Ms.}}, добро пожаловать в Тинген. Разрешите порекомендовать услугу экскурсионного тура нашего агентства.",
    ["你好，这是我的门票。"] = "Здравствуйте, это мой билет.",
    ["你对金属制品有兴趣？还是……只是找话题？"] = "Интересуетесь металлообработкой? Или... просто ищете повод для разговора?",
    ["你就不能像杰瑞米学学？你儿子每天在外面玩得多开心啊！"] = "Разве ты не можешь поучиться у Джереми? Ваш сын так счастливо играет на улице каждый день!",
    ["你就是那个刚加入黑荆棘的新人？"] = "Вы новичок, который только что присоединился к Чёрный Чертополох?",
    ["你很烦恼？"] = "Вы очень обеспокоены?",
    ["你怎么一个人在这睡觉？你的爸爸妈妈呢？"] = "Почему ты спишь здесь один? Где твои мама и папа?",
    ["你怎么变成了这样？你的手臂全都是木纹…… "] = "Во что ты превратился? Твои руки сплошь покрыты древесным узором...",
    ["你怎么哭啦？不是你弟弟是什么意思？"] = "Почему ты плачешь? Что значит, он не твой брат?",
    ["你总算爬过来了。听好，没时间废话。"] = "Наконец-то ты дополз. Слушай, нет времени на глупости.",
    ["你想买什么？我现在手上有“安格尔威德之梦”、“夜访魔女”，以及“浴火的吞尾蛇”。"] = "Что вы хотите купить? Сейчас у меня есть «Сон Анкевельта», «Ночной визит Ведьмы» и «Омытый пламенем Уроборос».",
    ["你想使用那个炉子？"] = "Хотите воспользоваться этой плитой?",
    ["你成了一个小偷？"] = "Ты стал вором?",
    ["你才不务正业，我在认真生活，欣赏这宏伟的屏障，美丽的窗景。"] = "Сам ты бездельник! Я живу полной жизнью, любуясь этим величественным Барьером и прекрасным видом из окна.",
    ["你打得过柯莱特吗？"] = "Сможете ли вы победить Камелот?",
    ["你把自己的未婚妻叫做女巫？"] = "Ты называешь свою невесту ведьмой?",
    ["你指的是什么？"] = "Что вы имеете в виду?",
    ["你是什么途径？"] = "Каков ваш Путь?",
    ["你是否听说过特伦索斯特黄铜书？"] = "Слышали ли вы о Латунной книге Трунсоэста?",
    ["你是在和我说话？"] = "Ты говоришь со мной?",
    ["你是寄信的伊洛？"] = "Are you Ilo, the one who sent the letter?",
    ["你是想直接将人送去黑夜女神的神国吗？"] = "Вы пытаетесь отправить кого-то прямо в божественное царство Богини Вечной Ночи?",
    ["你是说……"] = "Ты имеешь в виду...",
    ["你是说亚特先生？他似乎在忙着把葡萄发酵成酒。"] = "Вы имеете в виду мистера Йейта? Кажется, он занят ферментацией винограда в вино.",
    ["你是说，崔佛让你用“共感手铐”来压制非凡者失控吗！？"] = "Вы хотите сказать, что Тревор просил вас использовать «Наручники Эмпатии», чтобы подавить потерю контроля Потусторонним!?",
    ["你有没有考虑过！我们要是放过他，我们可就没命了！"] = "Вы подумали! Если мы отпустим его, мы погибнем!",
    ["你有没有闻到？周围有一阵酒香。"] = "Вы почувствовали запах? Вокруг пахнет вином.",
    ["你有空的话，可以进去给夏尔夫先生帮忙。"] = "Если у вас есть время, можете зайти и помочь господину Шарфу.",
    ["你来了，看这起报道：“凌晨码头区一家制铅工厂发生爆炸。”我们怀疑这就是廷根市隐藏的黑市交易地点。"] = "Ты здесь. Посмотрите на этот отчет: «Сегодня рано утром на свинцовом заводе в районе Дока произошел взрыв». Мы подозреваем, что это скрытое торговое место на черном рынке в Тингене.",
    ["你来了，要开始拍照吗？"] = "Вы пришли! Начнем съемку?",
    ["你来了，议院治安队那群骗子又要通过演讲来欺骗市民获得支持了，我希望可以借机刺杀掉演讲的骗子。"] = "Вы пришли; эти лжецы из службы безопасности Совета собираются использовать речи, чтобы обмануть граждан и снова получить поддержку. Я надеюсь воспользоваться этой возможностью, чтобы убить лжеца, произносящего речь.",
    ["你来了，雷电灵性将在此地降落，我们需要你的帮助。"] = "Ты пришел. Духовность молнии вот-вот снизойдет сюда, нам нужна твоя помощь.",
    ["你爱的是他的灵魂，不要在意这些细节。"] = "Вы любите его душу; не беспокойтесь об этих деталях.",
    ["你的到来让周围的景色都黯然失色！"] = "С твоим появлением меркнут все окрестные пейзажи!",
    ["你的品质令人钦佩，顾问{{先生|女士}}。"] = "Ваш характер достоин восхищения, консультант {{Mr.|Ms.}}.",
    ["你的朋友失踪了？"] = "Ваш друг пропал?",
    ["你的朋友是谁？长什么样？"] = "Кто твой друг? Как они выглядят?",
    ["你的灵体在被撕裂，装载了太多疯狂的碎片。"] = "Ваше духовное тело разрывается на части, нагруженное слишком большим количеством фрагментов безумия.",
    ["你的灵性真敏锐，竟然能找出藏着的我。\n不如来玩一场捉迷藏吧，把附近的宝箱都找出来，就能开启我的宝藏。"] = "Какая острая у тебя духовность — надо же, сумел отыскать моё убежище!\nА давай сыграем в прятки? Отыщи все сундуки поблизости, и тогда сможешь открыть мою сокровищницу.",
    ["你相信吗？只要我轻轻拍两下手背，一切的幽灵都会在我眼前显形，然后……全部消失。"] = "Вы верите в это? Пока я нежно хлопаю в ладоши тыльной стороной ладони, все призраки будут проявляться перед моими глазами, а затем... все они исчезнут.",
    ["你看上去很难过，还好吗？"] = "Ты выглядишь очень грустно, с тобой все в порядке?",
    ["你看上去有些苦恼？"] = "Ты выглядишь немного обеспокоенным?",
    ["你看人的方式挺烦的。"] = "Раздражает то, как ты пялишься на людей.",
    ["你看我的墓碑，就在你旁边。"] = "Посмотрите на мое надгробие, рядом с вашим.",
    ["你看我，柔弱无法自理，如果得不到遗产，我恐怕就会死……"] = "Посмотри на меня, слабого и неспособного позаботиться о себе. Если я не получу наследство, боюсь, я умру...",
    ["你看着不像本地人，也是被宝藏传说骗来的？"] = "Вы не похожи на местного. Вас тоже заманили сюда россказнями о сокровищах?",
    ["你看见他往哪里走了吗？"] = "Вы видели, куда он пошел?",
    ["你看起来也有想忘记的东西。要不然……你不会在这里。"] = "Ты выглядишь так, будто у тебя тоже есть вещи, которые ты хочешь забыть. Иначе... тебя бы здесь не было.",
    ["你看起来很疲惫。"] = "Ты выглядишь очень усталым.",
    ["你看这日光。昨天，今天，明天，永恒的太阳高悬！"] = "Взгляни на этот солнечный свет. Вчера, сегодня, завтра — Вечное Солнце сияет в вышине!",
    ["你看，前面这些还挺正常——“帮忙到邮局领取家人寄的书信”……"] = "Посмотрите, те, что в начале, вполне обычные — «Помоги забрать на почте письма, отправленные семьей»…",
    ["你知道“扮演法”吧？“扮演法”通过解读魔药名称，获得其核心象征和具体意象，并在日常生活中与其贴合，总结出扮演守则。"] = "Ты ведь знаешь о «методе лицедейства»? Метод лицедейства заключается в толковании названия зелья, постижении его сокровенного символизма и конкретных образов, следовании им в повседневной жизни и формулировании правил лицедейства.",
    ["你知道一块三分熟的牛排和一块五分熟的牛排相遇，他们为什么不打招呼吗？"] = "Знаешь, почему стейк слабой прожарки и стейк средней прожарки при встрече не здороваются?",
    ["你知道开膛手杰克吗？"] = "Вы знаете Джека Потрошителя?",
    ["你知道白天公园有场演出吗？"] = "Знаете ли вы, что днем ​​в парке идет представление?",
    ["你知道的，那些该死的非凡材料实在是太贵了！"] = "Ты же знаешь, эти проклятые потусторонние ингредиенты стоят целое состояние!",
    ["你终于来了！"] = "Наконец-то ты здесь!",
    ["你终于来了，最近的非凡案件数量越来越多，我们也需要更多的人手，辛苦你了！"] = "Ты наконец здесь. В последнее время количество случаев Потустороннего растет, и нам нужно больше рабочей силы. Спасибо за ваш тяжелый труд!",
    ["你肯定想不到那个幽灵有多威风！他就在古堡门口，穿着一身制服，走起路来皮靴啪嗒啪嗒的，就像……就像个刚打完胜仗的锡兵！"] = "Вы не поверите, насколько величественно это привидение! Он стоит прямо у входа в древний замок, в униформе, его ботинки цокают при ходьбе, совсем как… совсем как оловянный солдатик, только что выигравший битву!",
    ["你能理解我的感受吗？"] = "Ты понимаешь, что я чувствую?",
    ["你要再苦着个脸，我就往你晚饭里加苦艾草！"] = "Если будешь сохранять такое кислое лицо, я добавлю к твоему обеду полыни!",
    ["你要去廷根，就帮我顺路捎给他，怎么样？"] = "Если ты собираешься в Тинген, почему бы тебе не отвезти их ему по дороге?",
    ["你要是想上去的话，那你找错人了。我不负责带路，也不负责引荐。"] = "Если вы хотите подняться туда, вы обратились не к тому человеку. Я не отвечаю за руководство или знакомство.",
    ["你见到他的话，就让他快回家吧，再贪玩就会被妈妈揍了。"] = "Если вы его увидите, скажите ему, чтобы он поторопился домой, иначе мама отшлепает его за то, что он слишком много играет.",
    ["你觉得怎么样？"] = "Что вы думаете?",
    ["你觉得这只是恶作剧？那混蛋把我心爱的钓竿偷了，还毁掉了！"] = "Вы думаете, это просто розыгрыш? Этот ублюдок украл мою любимую удочку и уничтожил ее!",
    ["你说什么呢？猫本来就是睡在鸟巢里的呀？"] = "О чем ты говоришь? Кошки должны спать в птичьих гнездах, не так ли?",
    ["你说得……也有道理。"] = "То, что ты сказал... тоже имеет смысл.",
    ["你说我老爹把遗嘱藏在这里面了？真的假的？能不能拿到遗产，就靠这玩意了。"] = "Ты хочешь сказать, что мой старик спрятал завещание здесь? Это правда? От этого зависит, смогу ли я получить наследство.",
    ["你说的奥罗拉是谁？"] = "Кто эта Аврора, о которой ты говоришь?",
    ["你说的山，难道就是……"] = "Гора, о которой ты говоришь, может быть...",
    ["你说的沼泽女巫是什么？"] = "Что это за Болотная Ведьма, о которой ты говоришь?",
    ["你说的闹鬼祖宅是怎么回事？"] = "Что там насчет родового дома с привидениями, о котором ты упомянул?",
    ["你说老大到底看上那小子什么了？"] = "Как вы думаете, что босс видит в этом ребенке?",
    ["你说这是第几起了？"] = "Какой это уже случай по счету, как думаешь?",
    ["你负责男爵的药物。趁着送药毒杀了男爵，伪装出男爵还活着的假象，甚至伪造案发现场，嫁祸仆人。"] = "Вы отвечаете за Лекарство Барона. Вы отравили барона, когда доставляли лекарство, имитировали иллюзию, что он все еще жив, и даже подделали место преступления, чтобы подставить слуг.",
    ["你身上有坏人的味道咪。"] = "От тебя пахнет плохим человеком, мяу.",
    ["你躺在地上做什么？"] = "Что ты делаешь, лежа на земле?",
    ["你还好吗？"] = "Ты в порядке?",
    ["你还真是不委屈自己。"] = "Ты действительно не сдерживаешься, не так ли?",
    ["你还记得你的朋友吗？是一只橘猫，他在集市那边的车筐里等你呢！"] = "Ты еще помнишь своего друга? Это рыжий кот, он ждет тебя в корзине возле рынка!",
    ["你还需要寻找其他狱友合作，救赎之路，从此开始。"] = "Вам все еще нужно найти других заключенных, с которыми можно сотрудничать; путь к искуплению начинается здесь.",
    ["你这么一说，我好像是有点印象……"] = "Теперь, когда вы упомянули об этом, у меня, кажется, сложилось некоторое впечатление...",
    ["你这么偷偷摸摸的，不会在做坏事吧？"] = "Ты такой хитрый, ничего плохого не делаешь, да?",
    ["你这是在干什么呢？摘睡莲吗？"] = "Что ты делаешь? Собираете кувшинки?",
    ["你这是怎么了？"] = "Что с тобой не так?",
    ["你这猫太庸俗！不和你说！"] = "Кот, ты слишком вульгарен! Я не буду с тобой разговаривать!",
    ["你这里不卖睡莲吗？"] = "Разве вы не продаете здесь кувшинки?",
    ["你问问题的角度很刁钻，你这个人很不会聊天。"] = "Ты задаёшь очень каверзные вопросы. Собеседник из тебя так себе.",
    ["你面对枪口时的冷静眼神，有格尔曼·斯帕罗的气质。"] = "Ваши спокойные глаза, когда вы смотрите на дуло пистолета, имеют темперамент Германа Воробья.",
    ["你！"] = "Ты!",
    ["你！你有没有看到我的小杰克？"] = "Ты! Ты видел моего маленького Джека?",
    ["你，你怎么会知道？这可是近十年来，我最拿手的笑话了……难不成，你才是笑话之王？"] = "Ты, откуда ты мог знать? Это была моя лучшая шутка за последние десять лет... Может быть, вы Король шуток?",
    ["你，哪里来的，这里，“至尊霹雳舞王”的地盘，呜嘎。"] = "Ты откуда, отсюда, с территории «Верховного короля брейкданса», ога.",
    ["你，拿到了徽章。"] = "Ты, ты получил значок.",
    ["你，舞王？我才是，“至尊霹雳舞王”。"] = "Ты, Король Танца? Я «Верховный король брейк-данса».",
    ["佩姬，佐治，我后悔了。"] = "Пегги, Джордж, я сожалею об этом.",
    ["使用叹息之种·潮汐，完成你的第一次猩红狩猎。"] = "Используйте Семя вздохов: Прилив, чтобы завершить свою первую алую охоту.",
    ["侦探{{先生|女士}}，关于案件的具体情况，我不便多言，还请与夫人详谈。"] = "Детектив {{sir|madam}}, я не могу много говорить о конкретных обстоятельствах дела; пожалуйста, обсудите это с мадам.",
    ["侦探{{先生|女士}}，如果还有疑问，不如先在房间调查看看。"] = "Детектив {{мистер|мисс}}, если у вас все еще есть вопросы, почему бы сначала не осмотреть комнату?",
    ["侦探{{先生|女士}}，您的调查有结果了吗？"] = "Детектив {{ Mr. | Ms. }}, есть ли у вас результаты вашего расследования?",
    ["保菈，我的嗓子，我的嗓子怎么成这样了？"] = "Паула, мое горло, что случилось с моим горлом?",
    ["保险起见，你也拿上火枪，协助XX进行刺杀，如果事不可为，优先保护自身安全。"] = "На всякий случай вам также следует взять мушкет и помочь ХХ в убийстве. Если ситуация невозможна, поставьте на первое место собственную безопасность.",
    ["信仰不灭，金狼不死。除掉所有的狂信徒，金狼就和普通人没多大区别。"] = "Пока сохраняется вера, Золотой Волк не умрет. Устраните всех фанатиков, и Золотой Волк ничем не будет отличаться от обычного человека.",
    ["倒是你……看起来很想找人说话。"] = "Но ты... ты выглядишь так, будто тебе очень хочется с кем-нибудь поговорить.",
    ["假装一下。"] = "Притворитесь на мгновение.",
    ["做了他们的夫人，就不用再为别人洗衣服了。来这里也不用攒上三个月的钱……"] = "Стань я их госпожой, мне бы больше не пришлось стирать чужое белье. И чтобы прийти сюда, не нужно было бы копить деньги три месяца...",
    ["做得好，现在强化你的技能吧。"] = "Молодцы, теперь укрепляйте свои навыки.",
    ["停！你有没有感觉到一阵阴风？好冷啊……"] = "Останавливаться! Вы чувствуете холодный ветерок? Это так холодно...",
    ["偶尔我能在睡梦中闻到他身上佛手柑和迷迭香的味道……但出声的话肯定会把他吓跑吧？"] = "Иногда во сне я слышу от него запах бергамота и розмарина... но если бы я заговорила, я бы точно его отпугнула, верно?",
    ["傻瓜，我支持你是因为相信你的才华，不是因为你是什么教授。"] = "Дурак, я поддерживаю тебя, потому что верю в твой талант, а не из-за того, какой ты профессор.",
    ["像是一顿吃撑了，麻秆一样的身体，顶着一个圆滚滚的肚子。"] = "Словно объелись до отвала: худющие, как былинки, тела венчали круглые раздутые животы.",
    ["像是民间的探险队……或者是登山团队临时驻扎的？"] = "Типа гражданских экспедиционных групп... или временных лагерей, организованных альпинистскими группами?",
    ["像阳光照进玻璃窗，让人忘记烦恼，专注于当下的愉悦。"] = "Подобно солнечному свету, сияющему через стеклянное окно, он заставляет людей забыть о своих заботах и ​​сосредоточиться на удовольствиях настоящего.",
    ["兄弟……你是非凡者，是我们中能力最强的人了。"] = "Брат... ты Потусторонний, самый способный человек среди нас.",
    ["兄弟？我母亲说我是她唯一的孩子呢。"] = "Братья? Моя мать сказала, что я ее единственный ребенок.",
    ["先别管箱子了！你的命更要紧！"] = "Забудьте о ящике! Ваша жизнь важнее!",
    ["先生，你是在找谁吗？"] = "Сэр, вы кого-то ищете?",
    ["先生，女神的仁慈不会以金钱与利益来度量，所有的信徒都是祂的孩子，只要内心足够真诚。"] = "Сэр, милость Богини не измеряется деньгами и прибылью. Все верующие являются Ее детьми, пока их сердца достаточно искренни.",
    ["先生，您昨晚在河边，有注意到什么吗？"] = "Сэр, вы были вчера вечером у реки? Вы что-нибудь заметили?",
    ["先生，您看见了什么？"] = "Сэр, что вы видели?",
    ["先生，案件发生前你在干什么？"] = "Сэр, чем вы занимались до того, как произошло это дело?",
    ["先生，请问你有没有见过一个叫戈多的人？"] = "Сэр, вы видели человека по имени Годо?",
    ["光明在愚者雕像周围缓缓旋转，最多十道，实时流转。"] = "Свет медленно вращается вокруг Стату Шута, излучая до десяти лучей в реальном времени.",
    ["克罗伊，你看，禁止在学派骑脚踏车，哈哈哈哈好离谱的院规啊……你怎么不笑？"] = "Хлоя, послушай, в школе запрещено кататься на велосипеде, хахахаха, какое абсурдное школьное правило... почему ты не смеешься?",
    ["公主？公主是谁？我为什么要救？"] = "Принцесса? Кто такая принцесса? Почему я должен экономить?",
    ["兰伊，一定是有人故意害你！我去和吉姆先生说！"] = "Ланьи, тебя точно кто-то подставил нарочно! Я пойду и поговорю с мистером Джимом!",
    ["关于拉姆德家族为何衰败、古堡为何废弃，正史没有记载。流传下来的只有些模糊的民间传说。"] = "О том, почему семья Ламуд пришла в упадок и почему замок был заброшен, официальная история не упоминает. До нас дошел только смутный фольклор.",
    ["关于这本书的算式都已经解开了，终于可以完成封印了。"] = "Все уравнения для этой книги решены; Наконец-то я могу завершить запечатывание.",
    ["关键应该是长着银色毛发的神兔，据说就在附近的森林里。"] = "Ключом должен быть Кролик-Бог с серебристым мехом, который, как говорят, находится в ближайшем лесу.",
    ["兴趣小组？"] = "Группы по интересам?",
    ["其一，祈愿织线——通过冥冥之中的眷顾，为你寻找命运织线上的另一端——那个与你灵魂共鸣的人。 "] = "Во-первых, Молитвенное Плетение – благодаря милости неизвестного Я найду для тебя другой конец нити судьбы – человека, душа которого резонирует с твоей.",
    ["其三，永恒之契——当你们确定了彼此真心后，我会为你们主持永恒之契——那是用誓言与火漆签下的庄重约定。 "] = "В-третьих, Вечный Завет: когда вы убедитесь в искренности друг друга, я проведу для вас обряд Вечного Завета — торжественную клятву, скреплённую обетами и сургучной печатью.",
    ["其二，七夜邂逅——每月的七夜邂逅，是命运赐予的相识之礼。在七日内，陌生人将成为旅伴，或许也会成为更多。 "] = "Во-вторых, Встреча на семь ночей. Встреча на семь ночей каждый месяц — это дар знакомства, дарованный судьбой. В течение семи дней незнакомец станет попутчиком, а возможно, и больше.",
    ["其他人都藏在哪里？"] = "Где прячутся остальные?",
    ["其实是在开小差。"] = "На самом деле, ты расслабляешься.",
    ["其实根本就没有什么守护灵吧？"] = "На самом деле никакого духа-хранителя вообще нет, не так ли?",
    ["其实父亲是觉得亏欠他太多。至于我么，呵，看似被重视，其实只是当做工具而已！我才不关心遗产！"] = "На самом деле отец чувствовал, что он ему слишком много обязан. Что касается меня, хех, меня вроде бы ценят, но на самом деле со мной обращаются просто как с инструментом! Меня вообще не волнует наследство!",
    ["其实，“倒吊人”先生是一位很好的导师。"] = "На самом деле, мистер «Повешенный» очень хороший инструктор.",
    ["其核心只有三步："] = "Вся суть сводится к трем шагам:",
    ["内维尔、马丁……"] = "Невилл, Мартин...",
    ["再不回家吃饭，妈妈肯定要骂我了。但、但是……"] = "Если я не пойду домой ужинать, мама меня обязательно отругает. Но, но...",
    ["再坚持一下，马上就到营地了……"] = "Потерпи ещё немного, мы почти дошли до лагеря...",
    ["再次翻开我吧，我能帮您控制激光的激活顺序！"] = "Open me again; I can help you control the activation sequence of the lasers!",
    ["再过四十八小时，你就会变成玫瑰天堂的又一只提线木偶——没有自我意识，只会戴着面具跳舞的傀儡。"] = "Еще через сорок восемь часов ты превратишься в очередную марионетку Розового Рая — куклу без собственного сознания, способную лишь танцевать в маске.",
    ["再这样耽误进度，酬金别想拿全！"] = "Если вы снова задержите прогресс, не ждите, что вам заплатят в полном объеме!",
    ["冒昧地问一句，我是不是在哪见过您？"] = "Прошу прощения за бестактность, но мы с вами раньше нигде не встречались?",
    ["冒险！冒险！我要当《大冒险家》！"] = "Приключение! Приключение! Я хочу быть «Великим авантюристом»!",
    ["冰化了就是水，是水就能钓。"] = "Лед тает, превращаясь в воду, и если есть вода, можно ловить рыбу.",
    ["冰湖！你又宽又广！你又冷又亮！"] = "Ледяное озеро! Ты широк и необъятен! Ты холоден и светел!",
    ["冰面上？"] = "На льду?",
    ["况且，因为您的到来，城堡最艰难的时期已经度过了。一定会有更为繁荣的未来。"] = "Более того, с вашим приездом самый трудный период для замка прошел. Будущее определенно будет более процветающим.",
    ["冷了加火，热了加冰，就是这么简单……不过，时机，时机非常重要。"] = "Добавляй огонь, когда холодно, добавляй лед, когда горячо; это так просто... Однако время, время очень важно.",
    ["准备好了吗？"] = "Вы готовы?",
    ["准备好后，拿起桌上的枪。挑战会立即开始。"] = "When you are ready, pick up the gun on the table. The challenge will begin immediately.",
    ["准确来说，杀害男爵的凶手是你，但造成这一切的真凶另有其人。"] = "Если быть точным, то вы — убийца, убивший Барона, но настоящий виновник всего этого — кто-то другой.",
    ["几天前，他因病去世在别墅里，不久后，将有律师宣读他的遗嘱。"] = "Несколько дней назад он скончался из-за болезни на своей вилле. Вскоре адвокат зачитает его завещание.",
    ["几天前，我跟着朋友去古堡寻宝时，和一具盔甲对视了！回来后竟然发现恋人是我失散多年的亲哥哥！"] = "Несколько дней назад я отправилась с другом на поиски сокровищ в старинный замок и столкнулась взглядом с доспехом! А вернувшись, внезапно выяснила, что мой возлюбленный — мой давно потерянный родной брат!",
    ["几年前在边境，我误入过一个叫“新芽”的村子。"] = "Несколько лет назад на границе я случайно забрел в деревушку под названием «Новый росток».",
    ["凶手是你！你冷眼旁观每一个人进出，却什么都没做。只有你，从来没有真正关心过男爵的死亡。"] = "Убийца — ты! Ты безучастно смотрел, как все входят и выходят, но ничего не предпринял. Только тебе не было никакого дела до гибели барона!",
    ["凶手是你！你原本就对霍克斯男爵心有不满。下午，你再次因为那件古董，和他大吵一架，冲动之下，选择了结束霍克斯男爵的生命！"] = "Убийца - это ты! Вы уже были недовольны бароном Хоуксом. Сегодня днем ​​у вас с ним был еще один серьезный спор из-за этого антиквариата, и в порыве порыва вы решили покончить с жизнью барона Хоукса!",
    ["凶手是你！霍克斯男爵在你敲门前就已经死亡，你不可能听到他的声音。你撒谎是因为你杀了霍克斯男爵，想用谎言掩盖真相！"] = "Убийца - это ты! Барон Хоукс был уже мертв, когда вы постучали в дверь; вы не могли слышать его голос. Вы солгали, потому что убили барона Хоукса и хотели скрыть правду ложью!",
    ["出示徽章。否则，回去喝你的酒，做你的梦。"] = "Покажите свой значок. В противном случае вернитесь к тому, чтобы пить вино и мечтать о своих мечтах.",
    ["刚才那是，“愚者”先生的一段历史？"] = "Было ли это только что частью истории Мистераа?",
    ["别人家的猪也总往我们的后花园跑！唉！弄得一团糟！"] = "Чужие свиньи тоже продолжают забегать к нам во двор! Вздох! Это беспорядок!",
    ["别再待在鸟巢里啦！你下来我给你好吃的！"] = "Хватит оставаться в птичьем гнезде! Сходи, я дам тебе что-нибудь вкусненькое!",
    ["别动！骨头可能断了，乱动会更严重！"] = "Не двигайся! Ваша кость может быть сломана; переезд сделает еще хуже!",
    ["别只在岸边看啦，湖上的风刚刚好，跟我一起去冲浪怎么样？"] = "Не просто наблюдайте с берега; ветер на озере хороший, как насчет того, чтобы заняться со мной серфингом?",
    ["别哭别哭，我帮你找找弟弟吧。"] = "Не плачь, не плачь, давай я помогу тебе отыскать братика.",
    ["别害怕，只是一个恐怖故事而已。"] = "Не бойтесь, это просто страшилка.",
    ["别害羞，也别太清醒。二楼的规矩是——看得越投入，走得越深入。如果你只是站着发呆……当心被吃掉。"] = "Не стесняйтесь и не будьте слишком трезвыми. На втором этаже действует правило: чем больше ты погружаешься, тем глубже ты погружаешься. Если ты просто стоишь там ошеломленный... берегись, чтобы тебя не съели.",
    ["别想把主人抓去研究她不喜欢的药剂喵，我们会保护主人喵。"] = "Не думай застать мастера за изучением зелий, которые ей не нравятся, мяу. Мы защитим хозяина, мяу.",
    ["别担心，我会把你交给教会处理，先净化污染吧。"] = "Don't worry, I will hand you over to the Church to deal with; let's purify the corruption first.",
    ["别狡辩了，向亚特先生传个话，今年我会种出最大最甜的南瓜，比他的葡萄还要甜呢！"] = "Перестаньте оправдываться. Передайте господину Арте сообщение: в этом году я вырасту самые большие и сладкие тыквы, даже слаще его винограда!",
    ["别生气……我听说，投硬币会增加好运，运气爆棚的人能在净化之泉里获得非凡奖励！"] = "Не сердись... Я слышал, что подбрасывание монеты увеличивает удачу. Обладатели взрывной удачи могут получить необыкновенные награды в Фонтане Очищения!",
    ["别白费力气了，{{先生|小姐}}，我已经在这里等了一个小时，一个卖报的都没看见！"] = "Не теряй дыхания, {{Mr.|Ms.}}, я жду здесь уже час и не увидел ни одного продавца газет!",
    ["别看黑兹那样，他曾经是个很好的队长。"] = "Не смотри, что Хейз сейчас такой, когда-то он был отличным капитаном.",
    ["别紧张，您是为了那张求救门票来的吧？请把我放进面前的机关里，我来帮助您救他们。"] = "Не нервничайте. Вы здесь ради билета с просьбой о помощи, верно? Пожалуйста, поместите меня в механизм перед вами, и я помогу вам спасти их.",
    ["别误会！我在调查最近出现在学派的神秘歌声……"] = "Не поймите неправильно! Я расследую загадочное пение, появившееся недавно в школе...",
    ["别说了。说得我冒汗了。"] = "Прекрати это. Ты заставляешь меня потеть.",
    ["别说了咪，主人就是讨厌那些打架用的茶，才离开家人的咪。"] = "Перестань говорить, мяу. Мастер просто ненавидит те чаи, которые используют для борьбы, поэтому и ушла из семьи, мяу.",
    ["别说了，听了那些故事，我一整晚都没睡好。 "] = "Хватит болтать, я плохо спал всю ночь после того, как услышал эти истории.",
    ["别过来！这里不安全！"] = "Не подходи! Здесь небезопасно!",
    ["到小镇上玩，有什么要注意的吗？"] = "Есть ли на что обратить внимание при посещении города?",
    ["前往隐藏关，触发一场艰难的战斗。"] = "Отправляйтесь на скрытый уровень и начните сложную битву.",
    ["前方……雾气……不要进入……"] = "Впереди... туман... не входи...",
    ["前辈，你终于来了！我们小队发现了一名在失控边缘的魔女，需要你来护送她给交接的值夜者。"] = "Старший, ты наконец здесь! Наш отряд обнаружил ведьму, которая находится на грани потери контроля, и просит вас сопроводить ее к «Ночным ястребам» для передачи.",
    ["前面那个山洞让我有不好的感觉。"] = "Эта пещера впереди вызывает у меня плохое предчувствие.",
    ["剩下的怪物，就交给我来处理。"] = "Оставшихся монстров оставь мне.",
    ["动手吗？"] = "Должны ли мы сделать шаг?",
    ["动手！"] = "Сделайте это!",
    ["努力拼搏，放下结果，对不对？"] = "Старайтесь изо всех сил, отпустите результаты, верно?",
    ["医生说我咳血是照顾父亲染上的肺病……可律师说没有遗嘱只能平分遗产！"] = "Врач сказал, что мой кашель с кровью - это болезнь легких, которую я подхватил, ухаживая за отцом... но адвокат сказал, что без завещания наследство должно быть разделено поровну!",
    ["千万别！"] = "Только не это!",
    ["午睡的时候他会站起来，从关着的窗户飘出去……呜呜。"] = "Во время сна он вставал и выплывал через закрытое окно... ууууу.",
    ["半月前，湖面上传来了叹息声，可怜的女人失去了她的孩子。"] = "Полмесяца назад с озера раздался вздох, и бедная женщина потеряла ребенка.",
    ["卖鱼的生意不好吗？"] = "Бизнес по продаже рыбы идет не очень хорошо?",
    ["南瓜永远是那么大，河里的水没有温度，从不休息的车夫。"] = "Тыквы всегда одного размера, вода в реке не имеет температуры, кучер никогда не отдыхает.",
    ["占ID段9030580-9030589_黑荆棘事件簿1_5200227"] = "Занятый сегмент ID 9030580-9030589_Журнал происшествий Чёрный Чертополох 1_5200227",
    ["占位"] = "Инфо",
    ["历史就会在此刻改变！因蒂斯将统一北大陆！"] = "История изменится в этот момент! Интис объединит Северный Континент!",
    ["原来不是霍金斯教士呀……"] = "О, так это не отец Хокинс...",
    ["原来你已经处理完这些“过分的要求”了。"] = "Итак, вы уже обработали эти «чрезмерные запросы».",
    ["原来如此……"] = "Так вот оно как...",
    ["原来是个玩具摊吗？"] = "Так это игрушечный ларек?",
    ["去前面问迎宾。我没空当向导。"] = "Спросите у встречающего спереди. У меня нет времени быть гидом.",
    ["去吧，我的真爱在……呼噜、呼……"] = "Давай, моя настоящая любовь в... храпе, храпе...",
    ["去吧，把这里照亮一些，"] = "Давай, укрась это место немного,",
    ["去喝两杯，跳支舞，别让大家扫兴。等您的眼神和这里的光芒一样了，再来试试。"] = "Иди выпей парочку, потанцуй немного, не подведи всех. Когда твои глаза станут такими же, как свет здесь, приди и попробуй еще раз.",
    ["去湖心亭坐坐，在广阔的天地间也会让人的心情变得开阔。相信我，那儿会让你忘掉一切烦恼。"] = "Иди посиди в павильоне на берегу озера; огромное пространство расширит ваш кругозор. Поверьте, это заставит вас забыть все ваши проблемы.",
    ["去起点线准备吧，咱们马上开始！"] = "Иди к линии старта и готовься, мы скоро начинаем!",
    ["又偷偷学习！说好了今天一起去休息室玩桌游的。"] = "Снова учусь тайно! Мы договорились сегодня пойти в гостиную поиграть в настольные игры.",
    ["又回来了？看来你还没尽兴。"] = "Вернуться снова? Кажется, ты еще не наелся.",
    ["又称“无尽的迷途”。 特殊工艺打造的长方形金箔纸，一端扭转180度后，与另一端相接，形成只有一个平面的环形。"] = "Также известен как «Бесконечный лабиринт». Прямоугольная полоска золотой фольги, изготовленная с помощью специальной техники, один конец которой закручен на 180 градусов и соединен с другим, образуя кольцо только с одной поверхностью.",
    ["又称“盛夏”。一根暗金色的，做成太阳鸟形状的胸针。"] = "Также известен как «Среднее лето». Брошь из темного золота в форме солнечной птицы.",
    ["又脏又破！……唉，找来的佣人总是逃走，有的还会偷家里的珠宝。"] = "Он грязный и сломанный!...Эх, слуги, которых я нанимаю, всегда убегают, а некоторые даже крадут семейные драгоценности.",
    ["又被挡住了！但那些光束机关，似乎是有特定激活顺序的……"] = "Blocked again! But those light beam mechanisms seem to have a specific activation sequence...",
    ["又见面了，德洛塔小姐。"] = "Мы снова встретились, мисс Делота.",
    ["发生什么事了？"] = "Что случилось?",
    ["古堡的初代主人被称为拉姆德男爵，其活跃年代被推断在第四纪末期——也就是大约一千三四百年前。"] = "Первого владельца замка звали барон Ламуд, а время его жизни предположительно относится к концу Четвертой эпохи — то есть примерно тысячу триста или четыреста лет назад.",
    ["古堡里的家族继承了那位执政官的血脉，不知道他们会不会也总是弄丢自己的记忆……"] = "The Family in the old castle inherited the bloodline of that magistrate. I wonder if they, too, are always losing their memories...",
    ["古堡，会动的盔甲，黑风衣的老爷们……听起来，这位先生是目睹过疑似非凡者之间的战斗。"] = "Древний замок, ожившие доспехи, господа в черных плащах... Похоже, этот джентльмен стал свидетелем битвы между предполагаемыми Потусторонними.",
    ["古怪的口味……"] = "Странный вкус...",
    ["另外，您也可以使用蒸汽机组，升级即将上路的火车，这一定能进一步提升您的收益。"] = "Кроме того, вы также можете использовать паровые агрегаты для модернизации поездов, которые вот-вот отправятся в путь, что непременно еще больше увеличит ваш доход.",
    ["只是主人家族的遗传病，要靠新鲜血液维持生命，和放血疗法差不多喵。"] = "Это просто наследственное заболевание семьи Мастера; ей нужна свежая кровь, чтобы поддерживать жизнь, это примерно то же самое, что кровопускание, мяу.",
    ["只是别喝太多，梦境可能会变得太“真实”。 "] = "Только не пей слишком много, сны могут стать слишком «реальными».",
    ["只是比起在这里找，或许这样的爱人闯进你的生活更多要靠缘分。"] = "Но вместо того, чтобы искать здесь, возможно, такой возлюбленный скорее войдет в вашу жизнь по судьбе.",
    ["只是碰巧走过的地方多了点，见过的事怪了点。 "] = "Мне просто довелось исходить чуть больше дорог и повидать чуть больше странностей.",
    ["只有你能救他们，也只有你能做这个决定。"] = "Only you can save them, and only you can make this decision.",
    ["只有我这个老古董，出生在这里，长大在这里，愿意把这一切记录下来，愿意把历史当个宝贝。"] = "Только такой старый антиквариат, как я, родившийся здесь и выросший здесь, готов записывать все это и относиться к истории как к сокровищу.",
    ["只有最漂亮最柔软的睡莲才像我亲爱的奥利维亚。"] = "Только самая красивая и нежная кувшинка похожа на мою дорогую Оливию.",
    ["只有靠着药剂，躺在灵界观测房的地面，我才能进入半梦半醒的状态。"] = "Только полагаясь на лекарство и лежа на полу комнаты наблюдения духовного мира, я могу войти в состояние полусна и полубодрствования.",
    ["只要在晚上虔诚地跪拜祂，就能得到生命的“祝福”，再也不会挨饿了。"] = "Пока вы преклоняете колени и преданно молитесь Ему по ночам, вы можете получить «благословение» жизни и никогда больше не голодать.",
    ["只要您愿意付出几枚苏勒，我就能让它显灵——它能保佑您三个月内发大财！"] = "Если вы готовы заплатить несколько солов, я могу воплотить это в жизнь — это может благословить вас на то, чтобы заработать состояние в течение трех месяцев!",
    ["只要献上一朵睡莲，愿望就会被仙女倾听！大家都这么说！"] = "Если вы предложите кувшинку, фея услышит ваше желание! Все так говорят!",
    ["只需要在杜松子酒中加入一些特殊“秘方”，就能让酒液如星空般闪耀。"] = "Вам нужно всего лишь добавить в джин особые «секретные ингредиенты», чтобы жидкость сияла, как звездное небо.",
    ["叫小白。"] = "Называется Снежок.",
    ["叫我出来做什么？你终于对《机械制造技术基础》感兴趣了吗？"] = "Для чего ты хочешь меня? Вас наконец заинтересовали «Основы технологии механического производства»?",
    ["可、可是，我总是梦到赛斯，他告诉我，斐乐不是好人，让我不要相信他……"] = "Н-но мне всё время снится Сет... Он твердит, что Фил — дурной человек, и просит не верить ему...",
    ["可他是个男人。"] = "Но он мужчина.",
    ["可他是残疾人，每天坐在桥头骂天上的鸟。"] = "Но он инвалид и каждый день сидит на мосту и ругает птиц в небе.",
    ["可以将猎物碎片提交给我，我将提供给你丰厚的报酬。"] = "Вы можете передать мне фрагменты добычи, и я предоставлю вам щедрое вознаграждение.",
    ["可以这样随意进出城堡？"] = "Можно ли просто входить и выходить из замка по своему усмотрению?",
    ["可学派的导师们建议我晋升到序列7“航海家”再外出，这样我就能对洋流风向等等都有把握了，而且有“航海家”的船只从来不会在大海上迷路。"] = "Но наставники школы посоветовали мне перейти к 7-му этапу «Навигатор» перед выходом, чтобы я мог понимать океанские течения, направления ветра и так далее, а корабли с «Навигатором» никогда не терялись в открытом море.",
    ["可惜我不是城里人，不能时常去剧院观摩，但好在有艺术学派，让我能学到一些剧目里的舞步。"] = "Жаль, что я не городской житель и не могу часто ходить в театр... Но к счастью, есть Школа искусств, где я могу разучить движения из театральных постановок.",
    ["可我已经找了好几个地方了……都没有合适的占卜师……"] = "Но я уже обошла столько мест... и нигде нет подходящего предсказателя...",
    ["可是……"] = "Но...",
    ["可是你知道罗塞尔大帝是在何时何地说出这句话的吗？这你就不知道了吧，我来告诉你，那天，罗塞尔走在路上……"] = "Но знаете ли вы, когда и где император Розель сказал это? Ты этого не знаешь, да? Позвольте мне сказать вам, в тот день Розель шла по дороге...",
    ["可是叔叔已经摘了那个南瓜，去菜摊上卖了！"] = "А дядя уже сорвал ту тыкву и понес ее в овощной ларек продавать!",
    ["可是妈妈说，是看分针……分针走过这么长，妈妈就从告解室回来了。"] = "Но Мать сказала: посмотри на минутную стрелку... когда минутная стрелка дойдет так далеко, Мать вернется из исповедальни.",
    ["可是幽灵怎么会有声音呢？"] = "Но как призрак может издавать звук?",
    ["可是这里好像很平静，您说的可怕的战斗，似乎没有影响到镇子上的人们。"] = "Но здесь, кажется, очень мирно, ужасная битва, о которой вы упомянули, похоже, не затронула жителей города.",
    ["可是这里还有这么多信没送呢……"] = "Но здесь еще так много писем, которые не доставлены...",
    ["可每到夜里，屋里就有奇怪的响动，脚步声、叹气声，还有人在楼上走来走去。"] = "Но каждую ночь в доме раздавались странные звуки, шаги, вздохи и люди, гуляющие по лестнице.",
    ["可能是我拿到魔法豌豆后太激动，掉在了地上……"] = "Возможно, я был так взволнован, получив волшебную горошину, что уронил ее на землю...",
    ["可这个人七十岁了。"] = "Но этому человеку семьдесят лет.",
    ["可那卑劣的投机商没告诉我他的货是从哪里来的！结果我又成了嫌疑人，被警察先生盘问了一个下午！"] = "Но этот презренный спекулянт не сказал мне, откуда у него товар! В результате я снова стал подозреваемым, и полиция допрашивала меня целый день!",
    ["叽叽——叽叽叽——"] = "Чириканье-чирик-чирик-",
    ["叽叽！新舞王，新舞王！"] = "Чирик-чирик! Новый король танцев, новый король танцев!",
    ["叽，舞王地盘！舞王地盘！"] = "Чип, территория Танцевального Короля! Территория Танцевального Короля!",
    ["同时，为魔药消化有困难的成员，安排社会实践项目，设计方便扮演的社会身份。"] = "В то же время для участников, испытывающих трудности с перевариванием зелий, мы организуем проекты социальной практики и разрабатываем социальную идентичность, удобную для актерской деятельности.",
    ["同行商店上新时间到，先领券再下单，付款再抽免单，千万不要错过！\n（参与同行组队玩法，获得同行纹章，可兑换各种奖励。）"] = "В Лавке соратников новое поступление! Сначала заберите купон, затем оформите заказ, а после оплаты испытайте удачу и выиграйте заказ бесплатно — не упустите шанс!\n(Участвуйте в совместных командных испытаниях, зарабатывайте знаки соратников и обменивайте их на ценные награды.)",
    ["同行商店新品爆款直降，先抢再看！"] = "На новинки в интернет-магазине действуют большие скидки, успейте приобрести их, прежде чем искать!",
    ["后悔？我绝不后悔！"] = "Сожалеть? Я не жалею!",
    ["后来，镇上的每个孩子都开始讲他们自己的骑士与恶龙的故事。埃德蒙德，雷和露娜……那些故事都是从我这儿听去的。"] = "Позже каждый ребенок в городе начал рассказывать свои истории о рыцарях и драконах. Эдмунд, Рэй и Луна... все эти истории слышал от меня.",
    ["听上去你们挺恩爱的，祝你们幸福！"] = "Похоже, вы двое очень любящие. Желаю тебе счастья!",
    ["听上去你们非常相爱，有故事听吗？"] = "Похоже, вы очень сильно влюблены. Есть ли история, которую можно услышать?",
    ["听上去很独特，我想尝试下。"] = "Это звучит уникально; Я хотел бы попробовать.",
    ["听我说本杰明，把这个护身符拿好，这是我和老托马斯走散前，他托我转交给你的。"] = "Listen to me, Benjamin. Keep this amulet safe. Old Thomas asked me to pass it on to you before we got separated.",
    ["听着……艾玛小姐被困在二楼！"] = "Слушай... Мисс Эмма заперта на втором этаже!",
    ["听着伙计们，今天我们一定能赚够本周的饭钱，同意的举手！"] = "Слушайте, ребята, сегодня мы точно заработаем достаточно на еду на этой неделе. Поднимите руку, если согласны!",
    ["听着，孩子。"] = "Слушай, дитя.",
    ["听见了吗卢比先生？不招人，我就不干了！"] = "Вы это слышали, мистер Руби? Если вы никого не наймете, я увольняюсь!",
    ["听说是受到极端情绪的影响，这位魔女爆发了对曾经爱人极其强烈的情感，导致状态很不稳定。"] = "Я слышал, что на это повлияли сильные эмоции. Эта ведьма вспыхнула чрезвычайно сильными чувствами к своему бывшему возлюбленному, из-за чего ее состояние стало очень нестабильным.",
    ["听说有位伟大的生物学家曾经把小麦和牛杂交，这是一次巨大的物种基因进化！我一直很好奇为什么到处都找不到相关的文献？"] = "Я слышал, как один великий биолог однажды скрестил пшеницу с говяжьим рубцом; это была масштабная генетическая эволюция видов! Мне всегда было интересно, почему я нигде не могу найти соответствующую литературу?",
    ["听说这里埋的都是以前战死的勇士，我的小猫肯定也和他们一样勇敢吧？"] = "Я слышал, что здесь похоронены воины, погибшие в бою. Мой котенок, должно быть, такой же храбрый, как и они, верно?",
    ["听说那架钢琴有灵性，只要坐在那里，什么都不用想，就可以弹出悠扬的旋律。"] = "Я слышал, что фортепиано обладает духовностью; пока ты там сидишь, тебе не нужно ни о чем думать, чтобы сыграть мелодичную мелодию.",
    ["听起来你过得很好？"] = "Похоже, у тебя все хорошо?",
    ["听起来是一份非常劳累的工作啊。"] = "Это звучит как очень утомительная работа.",
    ["听起来是有点……那你打算怎么办？"] = "Это звучит немного... и что ты планируешь делать?",
    ["吼吼！吼吼！"] = "Рев-рев! Рев-рев!",
    ["吼吼，吼吼？<P_Heart>（那么，你准备好了吗？）</>"] = "Рев-рев, рев-рев? <P_Heart>(Итак, вы готовы?)</>",
    ["吼？<P_Heart>（哦？你又来了。）</>"] = "Рев? <P_Heart>(О? Ты снова пришел.)</>",
    ["呃……当然，她和这场戏没关系。"] = "Э-э... Конечно, она не имеет никакого отношения к этой сцене.",
    ["呃……明明是我先问你的……"] = "Э-э... Я был тем, кто спросил тебя первым...",
    ["呃……没……没什么……"] = "Э-э... нет... ничего...",
    ["呃，不好意思，如果你要找陪练，还是去问问索尼娅吧，或者像我一样找个木桩。"] = "Э-э, извини, если хочешь найти спарринг-партнера, то лучше спроси Соню, или найди кола, как я.",
    ["呃，没有，还在尝试……人总要有梦想的，不然和咸鱼有什么区别。"] = "Э-э, нет, все еще пытаюсь... Мечты всегда должны быть у людей, иначе какая разница между ними и соленой рыбкой.",
    ["呃，那没事了……再见，再见。"] = "Э, все в порядке... пока, пока.",
    ["呜呜……"] = "Уууууу...",
    ["呜呜……好吧呜呜……"] = "Ууууу... Ладно, ууууу...",
    ["呜呜……妈妈说等这家店的酒卖光了就准我出门旅行……"] = "Ууууу... Мама сказала, что как только вино в этом магазине будет распродано, она отпустит меня куда-нибудь путешествовать...",
    ["呜呜呜，人呢，人都去哪了？"] = "Ууууууууу, где люди? Куда все пошли?",
    ["呜呜，求求您了，告诉我们吧，呜呜呜呜……"] = "Вааа, пожалуйста, расскажите нам, вааа...",
    ["呜嘎，口气，很大，那就比舞！输的！吃烂香蕉！呜嘎！"] = "Уга, большой, поговорим, потом потанцуем! Неудачник! Ест, гнилой, банан! Уга!",
    ["呜嘎，输了，我，舞步，跟不上，呜呜。"] = "Wuga, I lost. My, dance steps, couldn't keep up, wuwu.",
    ["味道？我什么也没闻到啊？"] = "Запах? Я ничего не почувствовал?",
    ["呵呵……只不过他们现在都变成了封印物。"] = "Хе-хе... просто теперь они все стали запечатанными артефактами.",
    ["呵呵……如果对这款药剂好奇，我建议你直接去休息室找阿曼达女士要一杯朗齐酒。不过，它的味道大概要朗齐酒加好上那么一点……"] = "Хе-хе... если вам интересно это зелье, я предлагаю вам пойти прямо в гостиную и попросить у мисс Аманды стакан вина Рэнси. Однако его вкус, вероятно, немного лучше, чем у вина Ранси...",
    ["呵呵……等你沦落到我这个地步就明白了。"] = "Хех... ты поймешь, когда опустишься до моего уровня.",
    ["呵呵……贵客，您这又是一张“特别”门票。"] = "Хе-хе... Уважаемый гость, у вас есть еще один «особый» билет.",
    ["呵呵，杰克是这老家伙的乖孙子，在廷根的工厂当学徒呢。 "] = "Хех, Джек — хороший внук этого старика, работающего подмастерьем на фабрике Тингена.",
    ["呵呵，这里也有祂的灵性……这感觉，就仿佛是当年的那场神战还没有结束。"] = "Хе-хе, Его духовность тоже здесь... Такое ощущение, будто божественная война того времени еще не закончилась.",
    ["呵呵，雨水是免费的灌溉，阳光是额外的奖赏。算起来还是我赚了。"] = "Хех, дождь — это бесплатный полив, а солнечный свет — дополнительная награда. Учитывая все обстоятельства, я получаю прибыль.",
    ["呵，为什么那群人，会怀念那样一个地方？"] = "Хех, почему эта группа людей пропустила такое место?",
    ["呵，到那时候，一起出海狩猎吧，我准许你作为“烈焰”随侍我。"] = "Ха, когда придёт время, вместе выйдем в море на охоту. Я дозволяю тебе следовать за мной в качестве «Пламени».",
    ["呵，可笑吗？笑吧，我也知道很可笑，一个弱者试图保护强者。"] = "Хех, это смешно? Тогда смейся, я знаю, это смешно: слабак пытается защитить сильного.",
    ["呵，这事情恐怕连小弟自己都不清楚。"] = "Хех, боюсь, даже младший этого сам не знает.",
    ["呵，这女人真是难伺候！庄园里的宴会没见她这么有兴致。"] = "Хм, этой женщине действительно трудно угодить! Во время банкета в поместье она не выглядела такой заинтересованной.",
    ["呼……吓我一跳。"] = "Уф... ты меня напугал.",
    ["命运从不辜负前行者。你的印记或许已经换来了命运相应的馈赠。这次想要领取其中的哪一份呢？"] = "Судьба никогда не разочаровывает тех, кто идет вперед. Возможно, ваша отметка уже принесла вам соответствующий подарок судьбы. На кого из них вы бы хотели претендовать на этот раз?",
    ["命运欺压我年老没有力气，夺走了我的腿，还想夺走我的尊严！"] = "Судьба притесняла меня за старость и слабость, отняла ноги, хотела отнять и достоинство!",
    ["命运的一切都在背后标好了价钱，单看您选择什么代价。"] = "Все в судьбе имеет свою цену, все зависит от того, какую цену вы выберете.",
    ["咱们厂区正好今天组织街头竞速。一圈定胜负，没有赌注，就是比谁先把其他人甩在后视镜里。"] = "Наш заводской район сегодня организует уличную гонку. Один круг определяет победителя; никаких ставок, просто гонка, чтобы увидеть, кто первым оставит остальных в зеркале заднего вида.",
    ["咱们这片领地盛产葡萄和大麦，都是上好的酿酒原料。不如先从最拿手的开始——建一座酿酒坊，您看怎么样？"] = "Наша территория богата виноградом и ячменем – прекрасным сырьем для пивоварения. Почему бы не начать с того, что у нас получается лучше всего — со строительства винодельни, как вы думаете?",
    ["咳……这是为了贴近角色而使用的称呼。"] = "Кхм... это форма обращения, используемая, чтобы сохранить характер.",
    ["咳咳……不过有一说一，香花女士确实很优雅……"] = "Кхм... но, честно говоря, г-жа Сянхуа действительно очень элегантна...",
    ["咳咳……天哪，你想什么呢？我才、才没有想这么诡异的事情呢！"] = "Кашель, кашель... Боже, о чем ты думаешь? Я, я точно не думаю о таких странных вещах!",
    ["咳咳咳咳咳咳咳咳咳——哦不好，我现在就要死了——"] = "Кашель, кашель, кашель, кашель, кашель, кашель — о нет, я сейчас умру —",
    ["咳咳，你刚来塔罗学派吧？"] = "Кхм-кхм, ты ведь только недавно в Клубе Таро?",
    ["咳咳，咳咳……根本没到问答这一步啊，看来资料要补充一点，阿罗德斯大人不会助长投机取巧的行为……"] = "Кхе-кхе... До стадии вопросов и ответов дело даже не дошло. Похоже, данные нуждаются в дополнении; Лорд Арродес не будет поощрять оппортунистическое поведение...",
    ["咳咳，我没说过。"] = "Кхе-кхе, я такого не говорил.",
    ["咳咳，我说……没事的话，离那边的营地远点。"] = "Кхм, я сказал... если ничего нет, держись подальше от того лагеря.",
    ["咳咳，我，我先仔细看看！"] = "Кхм, я, я сначала присмотрюсь!",
    ["咳咳，抱歉，我的未婚妻有点过于活泼。我的腿——额，我的腿在几年前的战争中受了伤。"] = "Кхе-кхе, извини, моя невеста слишком оживленная. Моя нога… ну, моя нога была ранена на войне несколько лет назад.",
    ["咳咳，来客人了？我问问你……老巴克的山羊叫什么？"] = "Кхм-кхм, у нас гость? Позволь спросить тебя... как зовут козу Старого Бака?",
    ["咳咳，说是巡逻员……其实不过是我自己的消遣而已。"] = "Кхм, называть это патрульным... вообще-то, это просто мое времяпрепровождение.",
    ["咳咳，鲁特，我该怎么办？"] = "Кашель, кашель, Рут, что мне делать?",
    ["咳，前方是巴纳比先生的营地，我们在警戒四周，保障营地安全。"] = "Кхм, впереди лагерь мистера Барнаби. Мы охраняем территорию, чтобы обеспечить безопасность лагеря.",
    ["哇——真厉害！"] = "Вау, это потрясающе!",
    ["哇啊！对、对不起，教士先生 ！"] = "Ого! Я, прости, Отец!",
    ["哇！吓我一跳……我是说，很少有人和我搭话，除了这些小鸟们。"] = "Ух ты! Вы меня напугали... То есть со мной мало кто разговаривает, кроме этих птичек.",
    ["哈……有点感觉了。"] = "Ха... Теперь я начинаю это чувствовать.",
    ["哈、哈哈，您什么都知道了……就当咱们扯平了，您看，您也没什么损失……"] = "Ха, хаха, ты всё знаешь... скажем так. Слушай, ты ничего не потерял...",
    ["哈哈哈哈哈，不对，也许有一天，你到我这个年纪，就会理解这个笑话了！"] = "Ха-ха-ха, нет, может быть, однажды, когда ты достигнешь моего возраста, ты поймешь эту шутку!",
    ["哈哈哈哈哈，吓到您了吗？"] = "Ха-ха-ха-ха-ха, я напугал вас?",
    ["哈哈哈，误会了，我们都结婚快十年了，我丈夫还非要拍这婚纱照。"] = "Ха-ха-ха, это недоразумение. Мы женаты уже почти десять лет, а мой муж до сих пор настаивает на том, чтобы сделать эти свадебные фотографии.",
    ["哈哈，他们三个都在跳舞，多热闹啊，我也要跳！"] = "Ха-ха, они все трое танцуют, это так весело, я тоже хочу танцевать!",
    ["哈哈，喜欢这样性格的人，恋爱可是有不少挑战！"] = "Ха-ха, если любить кого-то с таким характером, в любви будет немало испытаний!",
    ["哈哈，好样的！年轻的时候我想当个冒险家，但等啊等，这一生一事无成，就要到头了！"] = "Хаха, хорошо сказано! Когда я был молод, я хотел стать искателем приключений, но я ждал и ждал, и теперь моя жизнь подходит к концу, и мне нечего показать!",
    ["哈哈，您别害怕。我是说身份证明上的索罗。"] = "Хаха, не бойся. Я имею в виду Соло в документе, удостоверяющем личность.",
    ["哈哈，是吗？"] = "Ха-ха, правда?",
    ["哈哈，还是个痴情人，给自己来一杯 “一忘皆空”吧！柑橘和烈酒混合在一起，味道让人放松又让人沉醉。"] = "Ха-ха, все еще тоскующая по любви душа. Подарите себе «Забудьте обо всем»! Цитрусовые и крепкие спиртные напитки смешаны вместе — вкус одновременно расслабляющий и опьяняющий.",
    ["哈瑞！你又不是不知道，执法队总是在事情结束来收尾，我们是要从根源杜绝这种现象。"] = "Гарри! Знаешь, команда правоохранительных органов всегда приходит навести порядок после того, как все закончилось. Нам необходимо искоренить это явление с корнем.",
    ["哈，真是年轻啊！"] = "Ха, какой ты молодой!",
    ["哎呀，真抱歉大侦探，我现在没法帮您占卜，我所有的小道具刚刚全被抢走了。"] = "О боже, мне очень жаль, великий сыщик, я не могу сейчас помочь тебе с гаданием, весь мой реквизит только что украли.",
    ["哎哟！来来来，年轻人，别害羞！我看你在这相亲角前晃了三圈了，说说，想找什么样的对象？ "] = "Ой! Ну-ну, молодой человек, не стесняйтесь! Я уже три раза видел, как ты ходил перед этим сватовским уголком. Скажите, какого партнера вы ищете?",
    ["哎哟，听听这话！玛莎是能干，但我们家爱丽丝可是裁缝铺出来的，她绣的手帕，上面的夜莺像要飞出来似的！"] = "Ой, вы только послушайте! Марта, конечно, толковая, но наша Элис работала в швейной мастерской! На вышитом ею платке соловей будто вот-вот взлетит!",
    ["哎！{{先生|女士}}，我这还有，还有别的诗！"] = "Эй! {{Сэр|Мэм}}, у меня есть еще, еще другие стихи!",
    ["哎，喜欢帅哥怎么了？我只是犯了北大陆女人都会犯的错而已啊！我又没有交往对象，又没有生孩子……"] = "Эй, а что плохого в том, что тебе нравятся красивые парни? Я всего лишь совершила ошибку, которую совершила бы каждая женщина Северного континента! У меня нет отношений, детей у меня нет...",
    ["哟，今天又来提升自己啊？"] = "Эй, ты сегодня снова здесь, чтобы улучшить себя?",
    ["哟，这不是特瑞吗！今天打算买点什么？"] = "Эй, это не Терри? Что вы планируете купить сегодня?",
    ["哥哥，你刚才想说什么？"] = "Брат, что ты собирался сказать сейчас?",
    ["哦……"] = "Ой...",
    ["哦你瞧，那个疯子主角登场了。"] = "Ой, смотрите, появился сумасшедший главный герой.",
    ["哦哦，是臭气满满的芝士蛋糕。"] = "О, так это вонючий чизкейк.",
    ["哦哦，是鱼做的派。"] = "О-о, это рыбный пирог.",
    ["哦对了，可千万别跟小朋友说！这只在大人之间流通！"] = "Ах да, не говорите детям! Это распространяется только среди взрослых!",
    ["哦简，不要幸灾乐祸，要礼貌，听柯莱特讲完。"] = "О, Джейн, не злорадствуй. Будьте вежливы и дайте Коллетт закончить.",
    ["哦！你来了！"] = "Ой! Ты здесь!",
    ["哦，呃，不……你听错了。"] = "Ох, нет... ты ослышался.",
    ["哦，哦，我的意思是——危险的是——营地，现在的营地，你明白吗？"] = "Ох, нет-нет, я к тому... опасность таит именно лагерь, нынешний лагерь, понимаешь?",
    ["哦，您看着眼熟啊。"] = "О, ты выглядишь знакомо.",
    ["哦，您终于来了。"] = "О, ты наконец-то приехал.",
    ["哦，所以继续骗其他人？"] = "О, так продолжаешь обманывать других?",
    ["哦，是的，不瞒您说，我的父亲约翰·乔瑟夫是有名的考古学家，他的研究方向就是霍纳奇斯主峰的古代遗迹。我比不上他。"] = "О, да. Честно говоря, мой отец, Джон Джозеф, известный археолог, и его исследовательская деятельность сосредоточена на древних руинах на главной вершине Горнациса. Я не могу с ним сравниваться.",
    ["哦，朋友，想听听我新写的诗吗？"] = "О, друг, хочешь послушать стихотворение, которое я только что написал?",
    ["哦，没错，你真是太懂我了！这会是个划时代的突破！"] = "О, это правда, вы меня очень понимаете! Это было бы эпохальным прорывом!",
    ["哦，说的是你写的《灵界小淘气》？我最喜欢淘气鬼惹恼城堡女公爵的那段，它……"] = "О, вы имеете в виду «Маленького негодяя из духовного мира», который вы написали? Мне больше всего нравится та часть, где негодяй раздражает герцогиню Замковую, это...",
    ["哦，谢谢你的关心，陌生人。这个孩子在一场考察中受到了一些惊吓，需要一场布道来安抚。"] = "О, спасибо за заботу, незнакомец. Ребенок был напуган во время экспедиции, и ему нужна была проповедь, чтобы успокоить его.",
    ["哦，这位光芒四射的{{先生|女士}}，真荣幸在这里遇见你！"] = "О, этот сияющий {{Mr.|Ms.}}, какая честь встретиться с тобой здесь!",
    ["哦，这是我最喜欢的药剂！它会让人快速入睡，整夜连续不断地做梦。"] = "О, это мое любимое зелье! Это заставляет людей быстро засыпать и видеть непрерывные сны всю ночь напролет.",
    ["哦？你不害怕么？"] = "Ой? Вы не боитесь?",
    ["哦？你也对开车有兴趣么，在这环山公路上向我证明你的实力吧！"] = "Ой? Вас тоже интересует вождение? Докажите мне свое мастерство на этой горной дороге!",
    ["哦？看来你除了面对枪口的冷静，还有一些疯狂……很好，这很格尔曼·斯帕罗。"] = "Ой? Кажется, кроме спокойствия перед оружием, в тебе есть еще и какое-то безумие... Очень хорошо, это очень Герман Воробей.",
    ["哦？那根据对等原则，你准备好回答祂的问题了吗？"] = "Ой? Тогда, согласно принципу взаимности, готовы ли вы ответить на Его вопрос?",
    ["哼……但那小子的好运马上就要到头了。"] = "Хм... но удаче этого мальчишки скоро придет конец.",
    ["哼，以主人的本领，做点新茶敷衍那群老顽固根本不难！真不知变通！"] = "Хм, с мастерством хозяина приготовить новый чай и одурачить этих старых упрямцев — проще простого! Какое упрямство!",
    ["哼，你是不是隔壁派来偷南瓜的！丰收节想赢我，没那么容易！"] = "Хм, тебя что, соседи подослали воровать тыквы?! Победить меня на Празднике Урожая не так-то просто!",
    ["哼，找机会我一定会把场子找回来！ "] = "Хм, я обязательно найду шанс отомстить!",
    ["哼，算你识相，我的南瓜一定是最大最甜的！"] = "Хм, ты соображаешь! Мои тыквы точно самые большие и сладкие!",
    ["唉……也是。那家伙就喜欢往没人的地方钻，说什么“灵感在荒野里”。"] = "Эх... это правда. Этот парень просто любит ходить в места, где никого нет, и говорит что-то вроде: «Вдохновение — в пустыне».",
    ["唉……确实恶化了。"] = "Эх... ситуация действительно ухудшилась.",
    ["唉！你这人怎么不听劝！"] = "Вздох! Почему бы тебе не прислушаться к советам!",
    ["唉！其实我觉得这个习俗取消也可以，但他坚持要这么做。"] = "Эх! По мне, этот обычай можно было бы и отменить, но он упорно стоит на своем.",
    ["唉，什么时候才能送到呢？"] = "Ох, а когда его доставят?",
    ["唉，你真是输不腻啊！"] = "Эх, ты действительно никогда не устанешь проигрывать!",
    ["唉，去吧去吧，孩子，路上小心。"] = "Эх, иди же, дитя, будь осторожен на дороге.",
    ["唉，我想回贝克兰德了。"] = "Эх, я хочу вернуться в Бэкланд.",
    ["唉，托马斯走后，埃莉诺的头发一夜就花白了。"] = "Эх, после ухода Томаса волосы Элеоноры за ночь поседели.",
    ["唉，未婚妻太可爱，也很让人苦恼啊。"] = "Эх, иметь слишком милую невесту тоже довольно хлопотно.",
    ["唉，还不是因为那些爱胡闹的小鬼头！都说了古堡危险，还总爱往那跑。"] = "Увы, это не из-за этих озорных чертиков! Они сказали, что замок опасен, но им все равно нравится туда бегать.",
    ["唉，这可怎么办？直接说也太尴尬了……"] = "Вздох, что мне делать? Неловко говорить об этом прямо...",
    ["唉，那我去找你的真爱来？"] = "Эх, тогда мне стоит пойти найти твою настоящую любовь?",
    ["唔……靠近法阵后头好晕，我似乎想起了什么……"] = "Hmm... My head feels so dizzy after getting close to the magic circle. I think I remember something...",
    ["唔，呜呜。<P_Heart>（我决定了，请让我加入你们。）</>"] = "М-м, у-у-у... <P_Heart>*(Я решилась, пожалуйста, позвольте мне присоединиться к вам.)*</>",
    ["唯一的归宿是安宁……"] = "Единственная цель - покой...",
    ["唯独这一次……我……抱歉。"] = "Только на этот раз... мне... извини.",
    ["商会为您提供了初始的启动资金，您现在就可以开启第一次贸易。"] = "Торговая палата выделила вам начальный капитал: вы уже можете совершить свою первую торговую сделку.",
    ["啊……你是说隔壁南瓜田的那位伦伯先生。"] = "А... ты имеешь в виду мистера Ламбера с тыквенной грядки по соседству.",
    ["啊……梦醒了？你想了解哪个？"] = "Ах... Проснулся ото сна? О каком из них вы хотите узнать?",
    ["啊……这些南瓜看起来的确很好吃。"] = "Ах... Эти тыквы и впрямь выглядят аппетитно.",
    ["啊！"] = "Ах!",
    ["啊！没有佛尔思的小说看，我要坚持不下去了！"] = "Ах! Без чтения романов Форса я больше не могу держаться!",
    ["啊， 是你！多亏了你的帮助。我发现唱歌真的很有趣，现在我已经是唱诵会的领唱了。"] = "Ах, это ты! Благодаря вашей помощи. Я обнаружила, что пение — это действительно интересно, и теперь я солистка певческой группы.",
    ["啊，一不小心说多了，你别嫌我唠叨就好。"] = "Ах, я случайно слишком много наговорил. Надеюсь, ты не против моего ворчания.",
    ["啊，他竟然还在那里？"] = "Ах, он действительно все еще там?",
    ["啊，你有什么事吗？"] = "Ах, тебе что-то нужно?",
    ["啊，别说得那么不体面。"] = "Ах, не выражайтесь так неэлегантно.",
    ["啊，我在想念我的莉诺呢。"] = "Ах, мне не хватает моего Лино.",
    ["啊，最近有人向会长信箱提建议，希望在学派内补充一些装饰……"] = "Ах, кто-то недавно сделал предложение в почтовый ящик президента, надеясь украсить школу...",
    ["啊，有一个我从未在公开场合讲过的，因为太过……诡异。"] = "Ах, есть один, о котором я никогда не говорил публично, потому что он слишком... жуткий.",
    ["啊，有冒险精神的客人。 "] = "Ах, гость с авантюрным духом.",
    ["啊，有勇气的客人。 "] = "Ах, смелый гость.",
    ["啊？"] = "Хм?",
    ["啊？我不想知道这么多……听起来很危险啊。"] = "Хм? Я не хочу знать так много... Это звучит опасно.",
    ["啊？我不是再复述之前阿罗德斯的问题吗……"] = "Ах? Разве я не повторил предыдущий вопрос Арродеса...",
    ["啊？这个想法，也有一定道理。"] = "Ах? В этой идее тоже есть доля правды.",
    ["啊？这是我能听的吗？"] = "Хм? Мне разрешено это слышать?",
    ["啦啦啦啦啦——咳咳！咳咳！"] = "Ла-ла-ла-ла — кашель, кашель! Кхе-кхе!",
    ["喂！你想对我的瓜做什么？"] = "Привет! Что ты делаешь с моей дыней?",
    ["喂，别看不起人，不就是长得矮了点吗？"] = "Эй, не смотри на людей свысока только потому, что я невысокого роста?",
    ["喂，我们小时候去古堡里探险，是谁被吓得尿裤子？毕竟古堡属于一千多年前统治这里的领主，你害怕得不行吧？"] = "Эй, когда мы в детстве гуляли по древнему замку, кто был настолько напуган, что намочил штаны? Ведь замок принадлежал лорду, правившему здесь более тысячи лет назад; ты был в ужасе, не так ли?",
    ["喂，我是要成为拉姆德小镇第一吉他手的，这幸运给你，你要不要啊？"] = "Эй, я собираюсь стать гитаристом номер один в Ламуд-Тауне. Хочешь ты этой удачи или нет?",
    ["喂，汤米，还不去救公主吗？"] = "Эй, Томми, ты еще не собираешься спасти принцессу?",
    ["喏，玛丽，今天送你左脚靴子，配你去年收到的那只右脚的正合适！"] = "Вот, Мэри, сегодня дарю тебе левый сапог — как раз в пару к тому правому, что ты получила в прошлом году!",
    ["喜欢女生啊，我这儿好的小姑娘可不少！喜欢多大年纪的啊？"] = "Тебе нравятся женщины? У меня здесь полно прекрасных барышень! Какой возрастной диапазон вы предпочитаете?",
    ["喜欢男生啊，我这儿好的小伙子可不少！喜欢多大年纪的啊？"] = "Тебе нравятся мужчины? У меня здесь полно прекрасных молодых людей! Какой возрастной диапазон вы предпочитаете?",
    ["喝上一杯，保证你忘记这段爱情里的一切伤痛。"] = "Выпей стаканчик, гарантирую — забудешь всю боль этой любви.",
    ["喝了酒，头真疼。"] = "После питья очень болит голова.",
    ["喝哪气死？"] = "Что выпить и разозлиться?",
    ["喵…喵…喵呜…"] = "Мяу... мяу... мяу-у...",
    ["喵，喵呜"] = "Мяу, мяу",
    ["嗯……也许，也许是我听错了……不对！这正说明它不是一般的幽灵！"] = "Хм... может быть, может я ослышался... Нет! Это просто доказывает, что это не обычное привидение!",
    ["嗯……啊……诶？"] = "Эм... ах... а?",
    ["嗯……嗯。"] = "Мм... мм.",
    ["嗯……您看起来终于找到状态了。"] = "Хм... ты выглядишь так, будто наконец-то нашел свое душевное состояние.",
    ["嗯……我还是等会儿再来吧。"] = "Хм... Мне лучше вернуться позже.",
    ["嗯……是我打扰到你了吗？"] = "Эм... я тебя побеспокоил?",
    ["嗯……有意思。旧日文明一度覆灭，但人类存续后又重建繁荣的社会。秩序是文明稳定之兆？感谢你的回答。"] = "Хм... интересно. Цивилизация Великого Древнего однажды погибла, но после того, как человечество выжило, оно восстановило процветающее общество. Является ли порядок признаком стабильности цивилизации? Спасибо за ваш ответ.",
    ["嗯……有趣。凭借自认为的“正确性”构建秩序，也是一种失序？感谢你的回答。"] = "Хм... Любопытно. Выстраивать порядок на основе собственной «правильности» — это тоже форма беспорядка? Благодарю за ответ.",
    ["嗯……这也是个不错的寄托。"] = "Хм... это тоже хороший эмоциональный якорь.",
    ["嗯……那我提醒你下次注意点？或者买个质量再好些的钓竿？"] = "Гм... может, мне просто напомнить тебе быть осторожнее в следующий раз? Или купить удочку покачественнее?",
    ["嗯。"] = "Мм.",
    ["嗯，其实你自己知道就行了。"] = "Ну, на самом деле, вам просто нужно это знать самому.",
    ["嗯，所以我们要好好待在这里，不要让妈妈担心。"] = "Мм, так что нам следует оставаться здесь как следует и не позволять матери волноваться.",
    ["嗯，这是它的名字。很久很久以前，美丽的村落被恶龙袭击，木马骑士在那场灾难里失去了他最爱的姐姐，于是他决定成为一名骑士，向恶龙复仇。"] = "Хм, это его имя. Давным-давно красивая деревня подверглась нападению дракона. В той катастрофе Рыцарь Деревянного Коня потерял свою любимую сестру, поэтому он решил стать рыцарем и отомстить дракону.",
    ["嗯，这里平和得很，倒是没什么特别的……"] = "Хм, здесь очень спокойно, ничего особенного...",
    ["嗯？什么都没有。不对劲，开启灵视试试。"] = "Хм? Ничего. Что-то не так, попробуем духовное зрение.",
    ["嗯？可是那是鸟巢……"] = "Хм? Но это птичье гнездо...",
    ["嗯？怎么不接着说了？"] = "Хм? Почему ты остановился?",
    ["嗯？抱歉，我将你认错成了客人。没错，需要擦鞋可以来铁十字街找我！又快又好！只要几个便士到一苏勒不等！"] = "Хм? Извините, я принял вас за клиента. Правильно, если тебе нужно почистить обувь, ты можешь прийти на Айрон-Кросс-стрит и найти меня! Быстро и хорошо! Это стоит всего от нескольких пенсов до шиллинга!",
    ["嗯？用这种琐事去打扰主教先生吗？会不会太……"] = "Эм? Стоит ли беспокоить епископа такими пустяками? Не было бы слишком...",
    ["嗯？！"] = "Хм?!",
    ["嘎吱……先别管我。舞台上的时间是被这破剧本篡改过的……嘎吱……"] = "Скрип... Не обращай на меня внимания. Из-за этого сломанного сценария время на сцене искажается... Скрип...",
    ["嘎吱……我怀里这把枪你拿着，会用到的……"] = "Скрип... возьми этот пистолет на руки, он тебе понадобится...",
    ["嘘……"] = "Тсс...",
    ["嘘……别影响到约翰发挥。"] = "Тсс... не отвлекай Джона.",
    ["嘘……小声点！老大可耳朵灵着呢！据说她们教会就是喜欢文化人……"] = "Тсс... потише! У босса острые уши! Говорят, их церковь любит интеллектуалов...",
    ["嘘！嘘……小声点，可以先还给我吗？我和佛尔思老师约定的时间马上就要到了……"] = "Тсс! Тсс... потише, можешь сначала вернуть его мне? Время, которое я договорился с Учителем Форсом, почти истекло...",
    ["嘘！嘘！我们在捉迷藏呢，你千万别把比利引来了。"] = "Тсс! Тсс! Мы играем в прятки, нельзя вести сюда Билли.",
    ["嘘！小声点！主人能听懂我们说话！"] = "Тсс! Держи это в покое! Мастер может нас понять!",
    ["嘘！爸你少说两句……好不容易有顾客！你先把药吃了！"] = "Тсс! Папа, меньше говори... Нелегко найти клиента! Сначала ты прими лекарство!",
    ["嘶……疼！你小心点！别碰坏了箱子！"] = "Ш-ш... больно! Поосторожнее! Не повреди ящик!",
    ["嘻嘻，塞西尔，别再逗我啦！你认真的样子……真让人分不清是玩笑还是真的了。 "] = "Хи-хи, Сесил, хватит меня дразнить! То, как ты выглядишь таким серьезным... действительно, трудно понять, шутка это или правда.",
    ["嘿嘿……是的，没想到叔叔去世了，我、我也没活下来……您会把我销毁吗？"] = "Hehe... Yes, I didn't expect that after my uncle passed away, I, I didn't survive either... Will you destroy me?",
    ["嘿嘿，不知道啊，什么神？"] = "Хе-хе, я не знаю, какой бог?",
    ["嘿嘿，有新猎物上钩了……嗷呜！！！"] = "Хе-хе, новая добыча попалась на крючок... Ау-у-у!!!",
    ["嘿嘿，被你听见啦……"] = "Хе-хе, ты меня услышал...",
    ["嘿小家伙……我不知道你在说什么暗号。"] = "Эй, малыш... я понятия не имею, о каком пароле ты толкуешь.",
    ["嘿！喝！我斩！"] = "Хэй! Ха! Получай!",
    ["嘿！朋友，是来这儿游玩的吧！"] = "Привет! Друг, ты здесь в гостях, не так ли?",
    ["嘿，你来得正好，我在设计金秋湖的印象服装，还差一点灵感。"] = "Эй, ты пришел как раз вовремя. Я создаю импрессионистический наряд для озера «Золотая осень», но мне все еще не хватает вдохновения.",
    ["嘿，准备来试试冲浪吗？今天湖上的浪很不错，我正要过去玩一圈。"] = "Эй, готов попробовать заняться серфингом? Волны на озере сегодня отличные, я как раз собираюсь покататься.",
    ["嘿，这可不能说。你要真想知道，不如去问问买过的人。我想想，你去找全学派最爱睡觉的那位吧，会得到中肯的评价的。"] = "Эй, я не могу сказать. Если вы действительно хотите это знать, почему бы не спросить того, кто это купил? Дай мне подумать, найди в школе того, кто больше всех любит спать; вы получите честную оценку.",
    ["嘿，需要“那种”药剂吗？"] = "Эй, тебе нужно «такое» зелье?",
    ["噢其实我没在钓鱼，在找东西呢。"] = "О, вообще-то я не ловлю рыбу; Я что-то ищу.",
    ["噢！你喜欢的话，到时候就尽管拿去喝。"] = "Ой! Если оно вам нравится, смело берите его и пейте.",
    ["噢！这条河非常神奇，能从里面捞出很多崭新的物品！"] = "Ой! Эта река поистине волшебна; из него можно выудить множество совершенно новых предметов!",
    ["噢，你吓我一跳。"] = "Ой, ты напугал меня.",
    ["噢，嗨，你要来一杯吗？自己拿个杯子就行，酒桶一直是满的。"] = "О, привет, хочешь выпить? Просто возьмите чашку сами; бочка всегда полная.",
    ["噢，对小山羊放尊重点！不然我用拐杖敲烂你的屁股！"] = "О, проявите немного уважения к козлёнку! Или я побью тебя по заднице тростью!",
    ["噢，我亲爱的奥利维亚，我要怎么给你描述她的眼睛……"] = "О, моя дорогая Оливия, как мне описать тебе ее глаза...",
    ["噢，真高兴在这里见到一个活人。您知道金秋湖车站在哪个方向吗?"] = "Ох, как я рада видеть здесь живого человека. Знаете ли вы, в каком направлении находится станция «Озеро Золотая Осень»?",
    ["噢，这么说吧，您会遇到不少人兜售古董之类的，这种……嗯，我就说这么多，您自己有判断就好。"] = "О, скажем так, вы встретите довольно много людей, торгующих антиквариатом и тому подобным. Это... ну, я просто так скажу, вы сами судите.",
    ["噢，那他应该去贝克兰德法庭工作，而不是继承一个出版社。"] = "О, тогда ему следует работать в Баклундском суде, а не наследовать издательство.",
    ["噩梦吗……谢谢，我会小心的。"] = "Кошмары... Спасибо, я буду осторожен.",
    ["回家，回家……唉，要是这样就能回家，我早就回去了。"] = "Иди домой, иди домой... Эх, если бы вернуться домой было так легко, я бы уже давно вернулся.",
    ["回答正确，看来你适应的不错嘛。"] = "Ответ правильный. Кажется, вы хорошо адаптировались.",
    ["回车上？那个老寡妇把她\"卖\"给我，要的就是攀上我这层关系。人要是丢了，我岂不是白花钱？"] = "Вернуться в карету? Эта старая вдова «продала» ее мне именно для того, чтобы через меня подняться по социальной лестнице. Если она пропадет, разве я не зря потратил деньги?",
    ["因为……因为它是恶龙啊！"] = "Потому что... потому что это злой дракон!",
    ["因为他们崇敬又畏惧黑夜，因此人格化了一位神灵来信仰，称这位神灵是黑夜的主宰，天之母！"] = "Потому что они и почитали, и боялись ночи, поэтому олицетворяли божество для поклонения, называя это божество Хозяином Ночи, Матерью Небесной!",
    ["因为淋过雨，所以想为他人撑伞。"] = "Поскольку на меня пролился дождь, я хочу держать зонтик для других.",
    ["因为牛排不会说话！这就是远处那个老太婆忽悠过路人十多年的笑话！"] = "Потому что бифштекс не умеет говорить! Вот этой шуткой вон та старуха уже больше десяти лет морочит голову прохожим!",
    ["因为金秋湖会用丰饶的土地，永远铭记他们。"] = "Потому что озеро Золотая Осень будет использовать свою плодородную землю, чтобы помнить их вечно.",
    ["园丁先生叫什么名字？"] = "Как зовут садовника?",
    ["图书管理员可不是什么轻松的职业，知识背后藏着太多危险的东西。"] = "Библиотекарь — далеко не простая профессия: за знанием кроется слишком много опасностей.",
    ["在夜总会发生了一场美妙的邂逅！"] = "У меня была замечательная встреча в ночном клубе!",
    ["在女神教堂里，不会再有邪恶追赶你，放心吧。"] = "В соборе Богини никакое зло больше не будет преследовать вас, будьте уверены.",
    ["在女神的国度里，细节即是光芒，能驱散迷雾。"] = "В царстве Богини даже мелочи — это свет, способный рассеять туман.",
    ["在您这儿走走，感觉心情都变好了。"] = "Прогуливаясь здесь, я чувствую себя лучше.",
    ["在我最痛苦的时候，我捡到了盔甲之神的纸条！"] = "В самый болезненный для меня момент я нашел записку от Бога Доспехов!",
    ["在我看来很不错。埃文医生比谁都紧张霍克斯的身体。上周夜里霍克斯胸口疼，他连外套都没穿好就赶过来了。"] = "На мой взгляд довольно неплохо. Доктор Эван больше всех нервничал по поводу тела Хоукса. Вчера вечером у Хоукса разболелась грудь, и он пришел сюда, даже не надев пальто.",
    ["在练剑？"] = "Практикуетесь в фехтовании?",
    ["在被逼入绝境时会愤怒地嘶吼。"] = "И злобно рычать, когда их загоняют в отчаянную ситуацию.",
    ["在观众眼中，每个人都是不错的演员呢。"] = "В глазах зрителя каждый является довольно хорошим актером.",
    ["在这个时代，能信任的人越来越少，但正因如此，那些值得托付的关系才更显珍贵。"] = "В эту эпоху становится все меньше и меньше людей, которым можно доверять, но именно из-за этого те отношения, достойные доверия, становятся еще более драгоценными.",
    ["在这些巨兽的遗骸前……我是什么？"] = "Перед останками этих исполинских чудовищ... кто я?",
    ["在这座城市，每一天都有新的机会诞生。"] = "В этом городе каждый день рождаются новые возможности.",
    ["在这片被恶意浸染的土地上，你需要一个锚点来找回自我。"] = "В этой стране, пропитанной злобой, вам нужен якорь, чтобы снова найти себя.",
    ["在金秋湖这种地方随便寄生，说不定哪天就变成满脑袋长满蘑菇的怪物了。"] = "Если паразитировать где попало вроде озера Золотой Осени, того и гляди однажды превратишься в чудище, у которого вся голова грибами заросла.",
    ["地上的血色脚印，不像是人类的。"] = "Кровавые следы на земле не похожи на человеческие.",
    ["地下一层存放着较高等级的封印物，非常危险。"] = "На подвальном уровне хранятся запечатанные артефакты более высокого уровня, которые очень опасны.",
    ["坏了！我忘记还有公主等着我去救了！"] = "О, нет! Я забыл, что принцесса все еще ждет, пока я ее спасу!",
    ["坐吧，你看起来比那些人，更有趣一点……"] = "Садись, ты выглядишь немного интереснее этих людей...",
    ["垃圾啊！"] = "Это мусор!",
    ["埃文医生，案件发生前你在干什么？"] = "Доктор Эван, чем вы занимались до того, как произошел инцидент?",
    ["埃洛伊丝，离开他好吗？他根本不懂你，他只是想要一个听话的机器。"] = "Элоиза, оставь его, ладно? Он вас совсем не понимает; ему просто нужна послушная машина.",
    ["城堡的未来，一片光明啊！"] = "Будущее замка светлое!",
    ["城堡？可是这里……"] = "Замок? Но здесь...",
    ["基拉你一定要平安回来啊……"] = "Кира, ты должна вернуться благополучно...",
    ["塔罗学派“小灵通”，很高兴为您服务。"] = "«Всезнайка» Школы Таро, рад служить вам.",
    ["多么令人震撼啊……但……但我想，也不能总是借助神明的恩眷。"] = "Как это шокирует... но... но я думаю, что нельзя всегда полагаться на милость богов.",
    ["多熬几个通宵就不会失眠了。"] = "Если вы не спите еще несколько ночей, это поможет вам избежать бессонницы.",
    ["夜之国……古老的传说……对夜不敬的人……都会遭到诅咒……"] = "Королевство Ночи... древние легенды... те, кто не уважает ночь... все будут прокляты...",
    ["大不了我们就一个个找过去！"] = "В крайнем случае просто проверим всех по очереди!",
    ["大多数人来这里是为了忘记……"] = "Большинство людей приходят сюда, чтобы забыться...",
    ["大幅提升使用者的力量，激发使用者进行拳击运动的能力。"] = "Значительно увеличивает силу пользователя и стимулирует его способность заниматься боксом.",
    ["大概<P_Yellow>三点十分</>吧，仆人端着茶往卧室走，我还跟他打了招呼，他应该就是<P_Yellow>最后接触男爵</>的人。"] = "Примерно <P_Yellow>в три десять</>. Слуга понес чай в спальню, я еще поздоровался с ним. Похоже, он и был <P_Yellow>последним, кто контактировал с бароном</>.",
    ["大概<P_Yellow>两分钟</>。我看着他<P_Yellow>吃下药</>，呼吸平稳了，才放心离开。他让我别打扰他，说等他好些了再来叫他。"] = "О <P_Yellow>две минуты</>. Я наблюдал, как он <P_Yellow> принимал лекарство </>, и его дыхание стабилизировалось, прежде чем я почувствовал облегчение, когда ушел. Он сказал мне не беспокоить его и сказал, что позвонит мне, когда ему станет лучше.",
    ["大概<P_Yellow>十分钟</>后，我去卧室送茶，那时埃文医生已经在客厅了，还跟我打了声招呼。"] = "Примерно через <P_Yellow>десять минут</> я пошел в спальню, чтобы принести чай. Доктор Эван уже был в гостиной и поприветствовал меня.",
    ["大胆问，不要紧张。"] = "Спрашивайте смело, не нервничайте.",
    ["大自然会说话，只是大多数人忘记了倾听。"] = "Природа говорит, просто большинство людей разучилось слушать.",
    ["天气很恶劣，暴风雪半小时内一定会降临！"] = "Погода ужасная; через полчаса обязательно налетит метель!",
    ["天赋再高，还不是为了做点娱乐的小玩意离家出走？看看她现在做的药剂！"] = "Каким бы высоким ни был талант, не сбегала ли она из дома, чтобы сделать какие-нибудь занимательные безделушки? Посмотрите, какие зелья она сейчас готовит!",
    ["太可怕了，太可怕了……我必须拦住所有人！不能让他们再去送死！"] = "Это слишком ужасно, слишком ужасно... Я должен остановить всех! Нельзя дать им идти на верную гибель!",
    ["太太们，你们这是在……"] = "Дамы, что вы делаете...",
    ["夫人很快生气地离开了，我抬头看过钟，那时是<P_Yellow>三点</>，老爷突然在卧室叫我，说他心脏不舒服。"] = "Вскоре мадам в гневе ушла. Я взглянул на часы: было ровно <P_Yellow>три часа</>. Внезапно хозяин позвал меня из спальни, пожаловавшись на боль в сердце.",
    ["夫人，你一定要参与即将来临的弥撒，并站在前排——以及，我要向你介绍一位警官。"] = "Мадам, вы должны присутствовать на предстоящей мессе и стоять в первом ряду, и я хочу познакомить вас с полицейским.",
    ["夫人，您看起来很着急？"] = "Госпожа, вы кажетесь очень взволнованной?",
    ["夫人，我很理解你的挣扎。慈爱的女神并不禁止一位寡居的女士再一次组建家庭……"] = "Мадам, я понимаю вашу борьбу. Любящая богиня не запрещает овдовевшей даме снова создать семью...",
    ["失落的技术、知识的呓语与精密的造物，理智与疯狂交织于此，穿过这扇门，直面那座斯蒂姆宫中强大的存在。"] = "Утерянные технологии, болтовня знаний и точные творения; Здесь переплетаются разум и безумие. Пройдите через эту дверь и столкнитесь с могущественным существом в этом Паровом Дворце.",
    ["奇怪，这些信封都好旧啊，看起来像被丢在这里很久了。"] = "Странно, эти конверты все такие старые; они выглядят так, будто их оставили здесь надолго.",
    ["奋勇当先的人， 为俱乐部默默奔走的人， 在关键时刻挺身而出的人——\n贡献足够，名字便会出现在这里。 贡献不再，也可能悄然离去。\n光晕公平，一如灰雾之上的目光。"] = "Те, кто смело идет впереди всех; те, кто неустанно трудится на благо клуба; те, кто встает на защиту в решающий миг...\nВнесите достаточный вклад, и ваше имя появится здесь. Если вклад иссякнет, оно может бесследно исчезнуть.\nСияние беспристрастно — словно взор из глубин серого тумана.",
    ["奥利弗先生一次次邀请别人去弹奏，很热情啊……手臂挥舞的幅度很大，嗯，应该是为了缓解他自称钢琴家，却没有被那架钢琴认可的尴尬。"] = "Господин Оливер раз за разом приглашает других сыграть, с таким пылом... Он так широко размахивает руками — видимо, чтобы сгладить неловкость от того, что, называя себя пианистом, он так и не заслужил признания этого пианино.",
    ["奥？你也想加入这场疯狂的抢夺吗？"] = "Ой? Вы тоже хотите присоединиться к этой безумной схватке?",
    ["女士，我有问题需要问你，霍克斯男爵最近有什么奇怪的地方吗？"] = "Мадам, у меня есть к вам вопросы. Барон Хоукс ведет себя странно в последнее время?",
    ["女神啊！这两种食物居然真的有不同的口味？"] = "Богиня милосердная! У этих двух блюд и правда разный вкус?!",
    ["女神啊，去他的坚持！以后没有煎香肠卖的山我都不会来爬的！"] = "Богиня, к черту эту настойчивость! Я никогда больше не полезу в гору, если в продаже нет жареной колбасы!",
    ["女神庇佑……请让我逃离那无边的噩梦……"] = "Богиня защити... пожалуйста, позволь мне избежать этого бесконечного кошмара...",
    ["女神庇佑！没想到我今天又看见了列车的蒸汽出现在这个站点。"] = "Слава Богине! Я не ожидал увидеть сегодня снова на этой станции пар поезда.",
    ["她一定对你很重要吧？"] = "Она наверняка очень важна для тебя?",
    ["她之前挺慷慨的，但和家族断绝关系后就……唉。"] = "Раньше она была весьма щедрой, но после разрыва связей с Семьей она… вздохнула.",
    ["她在喊……她在喊救命！我听见她在喊你的名字！"] = "Она кричит... она зовет на помощь! Я слышал, как она звала тебя по имени!",
    ["她在夜色里诞生，打了两个响指就落成这座小镇。"] = "Она родилась ночью, и двумя щелчками ее пальцев был построен этот маленький городок.",
    ["她在里面留下了“茧”，能够帮她恢复，只要那东西还在，她就是不死的。"] = "She left a 'cocoon' inside, which can help her recover. As long as that thing remains, she is immortal.",
    ["她失踪时大部分笔记都不见了，但我还留着一页，你要看看吗？"] = "Когда она пропала, исчезла и большая часть её записей, но у меня сохранилась одна страница. Хотите взглянуть?",
    ["她将身躯化为石像，伫立在此，永远守护着她造就的丰饶之地。"] = "Она превратила свое тело в каменную статую, стоящую здесь, вечно охраняющую созданную ею плодородную землю.",
    ["她很喜欢我送她的戒指，每天都戴着到处炫耀，劝都劝不住。"] = "Ей очень нравится кольцо, которое я ей подарил. Она носит его повсюду, чтобы похвастаться; Я даже не могу ее остановить.",
    ["她怎么了？"] = "Что с ней случилось?",
    ["她是重振家族荣光的明星！本不是我们可以接近的天才！"] = "Она — путеводная звезда, призванная возродить величие семьи! Гений, к которому нам и близко нельзя подступаться!",
    ["她是镇上最聪明的女孩，就是总爱说些奇怪的话。"] = "Она была самой умной девочкой в ​​городе, просто ей всегда нравилось говорить странные вещи.",
    ["她让我在这里等待，给您一些必要的指引。"] = "Она велела мне подождать здесь, чтобы дать вам нужные указания.",
    ["好……安妮，你跟好本杰明，我来把路打开。"] = "Alright... Annie, stay close to Benjamin. I'll open the path.",
    ["好不容易找到的……怎么偏偏赶上阿尔杰先生回来，哎……"] = "Наконец-то я нашел его... почему это должно было совпасть с возвращением мистера Алджера, вздох...",
    ["好久没见到这么可爱的新人了。"] = "Давненько я не видел такого милого новичка.",
    ["好了好了，你们都消停点。医生是体面人，哪能这么逼问。"] = "Ладно, ладно, вы все успокойтесь. Доктор порядочный человек, не стоит на него так давить.",
    ["好了，你把大伙都当成笨蛋吗？这已经不是什么秘密了。"] = "Alright, do you take everyone for fools? This is no longer a secret.",
    ["好了，开玩笑的，不要那么紧绷着嘛，天塌下来个高的顶着。"] = "Ладно, я шучу, не напрягайся так сильно. Если небо упадет, высокие удержат его.",
    ["好了，当务之急是净化污染。请拿着这个。"] = "Хорошо, главным приоритетом является очищение от Искажения. Пожалуйста, возьмите это.",
    ["好了，我不在乎你在调查什么，这里每个人都有自己的秘密。"] = "Хорошо, меня не волнует, что вы расследуете; здесь у каждого свои секреты.",
    ["好了，我们只能说到这里了，我们还得升起这堆该死的火呢！"] = "Хорошо, мы можем сказать только это; нам еще предстоит зажечь этот чертов огонь!",
    ["好像……大概……对不起，我真得好好思考一下这些问题。"] = "Кажется... возможно... Извините, мне действительно нужно хорошенько подумать над этими вопросами.",
    ["好像在研制某种药剂？这是我听到的药剂配方，很新奇的角度，我最近正在研究。"] = "Кажется, какое-то лекарство разрабатывают? Я слышал об этой формуле зелья. Это очень новый подход, и в настоящее время я его исследую.",
    ["好像没办法沟通啊。"] = "Кажется, договориться никак не выйдет.",
    ["好吧、好吧！我承认！我是在给这些雕像做旧……先埋进土里几天，再挖出来，沾点潮气和泥腥味，贝克兰德的买家就肯出高价…… "] = "Хорошо, хорошо! Я признаю это! Я состариваю эти статуи... закопайте их в землю на несколько дней, затем выкопайте, промокните и испачкайте, и покупатели в Баклунде заплатят высокую цену...",
    ["好吧。如果我有好好保存那些笔记就好了，怪想她的。"] = "Хорошо. Если бы я только вела эти записи должным образом, я так по ней скучаю.",
    ["好吧，我就知道没人会答应，真是一个失败的尝试。"] = "Ну, я знал, что никто не скажет «да», это была такая неудачная попытка.",
    ["好吧，我有一些小宝藏的线索，比如桥下那个宝箱……但不是免费的，懂吧？"] = "Хорошо, у меня есть кое-какие сведения о маленьких сокровищах, например, о сундуке с сокровищами под мостом... но это не бесплатно, понимаешь?",
    ["好啊，我已经迫不及待想骑它了。"] = "Хорошо, мне не терпится покататься на нем.",
    ["好在有“隐者”女士的帮助，庞大而神秘的知识才能如此安全地呈现出来。"] = "К счастью, благодаря мадам Отшельник столь обширные и таинственные знания удалось передать в полной безопасности.",
    ["好坚固的宝箱！看来没法直接撬开了。"] = "Какой прочный сундук с сокровищами! Кажется, его нельзя открыть напрямую.",
    ["好多会移动的平台，不过没关系，我可以帮您控制平台移动！"] = "So many moving platforms, but it doesn't matter, I can help you control their movement!",
    ["好心的过路人，你见过我儿子吗？"] = "Добрый путник, ты не видел моего сына?",
    ["好戏开场！好戏开场！拉姆德小镇富豪霍普为何一夜间死亡？"] = "Время для шоу! Время для шоу! Почему богатая Хоуп Ламуд-Тауна умерла в одночасье?",
    ["好无聊！"] = "Как скучно!",
    ["好晕……我要去……补个妆……"] = "Такое головокружение... Мне пора идти... подправить макияж...",
    ["好的，您的酒马上就来。"] = "Очень хорошо, ваш напиток будет готов.",
    ["好的，感谢你的提醒。"] = "Хорошо, спасибо за напоминание.",
    ["好的，那就紧迫地生活。"] = "Ладно, тогда давайте жить срочно.",
    ["好的，那我先不打扰了。"] = "Хорошо, тогда я больше не буду тебя беспокоить.",
    ["好货？早就被搜刮干净了！现在去，连块完整的砖头都捡不着！"] = "Хорошая вещь? Его давно разграбили! Иди сейчас, и ты даже не сможешь подобрать целый кирпич!",
    ["好，你们先在这里等我消息。"] = "Хорошо, жди здесь моих новостей.",
    ["好，我们进去吧……"] = "Хорошо, заходим...",
    ["如您所见，这片土地虽然充满潜力，却因为长久缺少人管理，一直处于荒废状态。"] = "Как видите, хотя эта земля полна потенциала, она находилась в запущенном состоянии из-за длительного отсутствия управления.",
    ["如果不是他，我简直不敢想象霍克斯会怎么样。"] = "Если бы не он, я даже представить не могу, что случилось бы с Хоуксом.",
    ["如果主人能听家族的话，就不用来这乡下地方了。"] = "Если бы Мастер просто слушал Семью, ей не пришлось бы приезжать в это загородное место.",
    ["如果你不忙的话，能帮我找找亮晶晶的戒指吗？"] = "Если ты не занят, не мог бы ты помочь мне найти блестящее кольцо?",
    ["如果你偶遇一只保险柜式生物，请捎它一程，我会给予报酬的。"] = "Если вам случайно встретится существо, похожее на сейф, подвезите его, и я предоставлю награду.",
    ["如果你单独面对祂紧张的话，我愿意陪你一起去的！"] = "Если вы нервничаете перед встречей с Ним наедине, я готов пойти с вами!",
    ["如果你哪天像他一样，呃，记得去找个“心理医生”。"] = "Если ты когда-нибудь станешь таким, как он, не забудь найти «психиатра».",
    ["如果你找到了相关线索，请一定、一定要告诉我。当然，我会支付丰厚的报酬。"] = "Если вы найдете соответствующие подсказки, пожалуйста, обязательно скажите мне. Конечно, я тебе хорошо заплачу.",
    ["如果你找到了，一定要告诉他们——这个规则一点也不公平……下次要改成只数八十，不，五十！ "] = "Если вы их найдете, вы должны им сказать — это правило совсем несправедливо... в следующий раз нам придется изменить его на счет до восьмидесяти, нет, до пятидесяти!",
    ["如果你看到他，请告诉他我很想他。"] = "Если вы его увидите, пожалуйста, скажите ему, что я очень по нему скучаю.",
    ["如果你知道接下来演什么了，就去你的位置，摆出开演的动作。"] = "Если вы знаете, что будет выполняться дальше, займите свою позицию и примите позу для начала выступления.",
    ["如果再没有进展，我就去“魔匙学会”找阿尔菲女士帮帮忙吧。"] = "Если прогресса не будет, я пойду в «Общество Волшебных Ключей» и попрошу помощи у мисс Алфи.",
    ["如果冒犯了她，她就会半夜溜进你家，往你脑子里塞些恐怖的东西。"] = "Если вы ее обидите, она прокрадется к вам домой посреди ночи и впихнет вам в мозг ужасающие вещи.",
    ["如果去古堡里面走走，也请您务必注意安全。毕竟，那里是一片无人看管的废墟，谁也不能保证意外和明天哪个先到来。"] = "Отправляясь на прогулку по замку, обязательно позаботьтесь о своей безопасности. В конце концов, это заброшенные руины, за которыми никто не отвечает, и никто не может гарантировать, что наступит раньше несчастный случай или завтрашний день.",
    ["如果可以的话，希望你对乔治保密，我想给他一个惊喜。"] = "Если возможно, прошу, сохрани это в тайне от Джорджа. Я хочу устроить ему сюрприз.",
    ["如果在告白前喝下它，你会充满勇气，无往不利！"] = "Если вы выпьете его перед исповедью, вы будете полны мужества, и ничто не встанет у вас на пути!",
    ["如果您是来等待主教先生的，很抱歉，我们可能会占用他接下来的时间。"] = "Если вы здесь и ждете епископа, извините, мы можем отнять у него остаток времени.",
    ["如果您见到他……请告诉他，他的母亲夏琳夫人一直在山脚祈祷，祈祷女神保佑他……"] = "Если вы его увидите... пожалуйста, скажите ему, что его мать, леди Шарлин, молилась у подножия горы, молясь, чтобы Богиня защитила его...",
    ["如果想找个安静点的地方，可以去屏障碎片旁边的灵界观测房。"] = "Если вы хотите найти более тихое место, вы можете пойти в комнату наблюдения Мира Духов рядом с фрагментом Барьера.",
    ["如果成功的话，仅仅需要对应的坐标点，就能实现“传送”了。"] = "В случае успеха понадобятся лишь соответствующие координаты, чтобы совершить телепортацию.",
    ["如果我们身处梦中，或更令人欣慰。没有危险与疯狂，没有流血与牺牲……"] = "Если бы мы были во сне, это принесло бы больше покоя. Ни опасности, ни безумия, ни крови, ни жертв...",
    ["如果我有好好保存其他笔记就好了，怪想她的。"] = "Если бы я только хорошо сохранил остальные записи; Я скучаю по ней.",
    ["如果有善良又能干的人能从林子里帮我抓几只兔子就好了……"] = "Если бы только был добрый и способный человек, который помог бы мне поймать в лесу несколько зайцев...",
    ["如果没什么新的进展，应该很快就能回去了……"] = "Если не будет нового прогресса, я скоро смогу вернуться...",
    ["如果真的有幽灵，这可不是我能处理的事……还是让专业的人来管吧。"] = "Если призраки действительно существуют, я с этим не справлюсь... лучше пусть об этом позаботятся профессионалы.",
    ["如果睡莲仙女会出现的“正午的午夜”指的不是一个具体的时间……"] = "Если «Полдень», когда появляется Фея Водяной Лилии, не относится к конкретному времени…",
    ["如果能够获知详细的操作步骤，那么我有一个大胆的想法……"] = "Если бы я мог изучить подробные этапы работы, у меня появилась бы смелая идея...",
    ["如果能自动生成建筑就好了……"] = "Было бы здорово, если бы здания можно было создавать автоматически...",
    ["如果这个女巫是真的？我一定要把腐烂三天的鱼从她鼻孔里塞进去！"] = "Если эта ведьма реальна, я засуну ей в ноздри гниющую уже три дня рыбу!",
    ["如此阴暗的地下室，还能有什么光呢？"] = "Какой может быть свет в таком темном подвале?",
    ["妈妈怎么还没回来呀？都过去二十分钟了。"] = "Почему мама еще не вернулась? Прошло двадцать минут.",
    ["姐姐送给我的小熊掉到池塘里，再也拿不回来了……"] = "Плюшевый мишка, который подарила мне сестра, упал в пруд, и я не могу его вернуть...",
    ["威廉·黑伍德，这场舞会的主人，却不像一个真正的主人。三十出头的面容本该英气逼人，眉宇间却笼着一层淡淡的疲惫。 "] = "Уильям Хейвуд, ведущий этого бала, не похож на настоящего хозяина. Его лицо, которому чуть больше тридцати, должно было бы быть впечатляющим, однако между бровями висит легкий слой усталости.",
    ["威瑟尔家族第一军团的骑兵队长！用你的长戟去夺取胜利，铸就荣耀！"] = "Капитан кавалерии Первого легиона семьи Вессель! Рази алебардой во имя победы и куй славу!",
    ["威金斯，看在咱们从小一块儿长大的份上……也带带我吧！ "] = "Виггинс, ради того, чтобы мы росли вместе... возьми меня с собой!",
    ["嫁给他！嫁给他！"] = "Выходи за него! Выходи за него!",
    ["嫁给我好吗？我会比他更爱你！以后的每一天我都可以陪着你，我会一直爱着你。"] = "Ты выйдешь за меня? Я буду любить тебя даже больше, чем он! С этого момента я могу быть с тобой каждый день и буду любить тебя вечно.",
    ["学派一楼愚者大厅附近是魔药房、休息室、文献室，远一点的地方是试炼区。"] = "Рядом с Залом Шута на первом этаже школы находятся комната зелий, гостиная и литературный кабинет; дальше находится испытательная площадка.",
    ["学派掌握了几条途径的完整序列，付出足够的代价可以换取对应的配方和材料。"] = "Школа освоила полные последовательности нескольких Путей; заплатив достаточную цену, можно обменять на соответствующие формулы и материалы.",
    ["它书写规则，利用规则，禁锢它的敌人，把他们逼进绝路。"] = "Оно пишет правила, использует правила, сажает в тюрьму своих врагов и загоняет их в тупик.",
    ["它们俯瞰大地的时候……可曾想过自己也会成为桥梁？"] = "Когда они смотрели на землю... думали ли они когда-нибудь, что тоже станут мостами?",
    ["它们在撕咬猎物时会兴奋地嘶吼，"] = "Они взволнованно ревут, когда рвутся на свою добычу,",
    ["它会让人看到平时看不见的东西，建议您小口啜饮。 "] = "Это заставит людей увидеть то, чего они обычно не видят. Я предлагаю вам пить его медленно.",
    ["它可以是任何人的惊喜。最珍贵的不是盒子里的东西，而是在屋顶上诞生的无数个奇妙世界。"] = "Это может стать сюрпризом для любого. Самое ценное не то, что в коробке, а бесчисленные чудесные миры, рожденные на крышах.",
    ["它好像在偷看那群同类……"] = "Кажется, оно украдкой подглядывает за своими сородичами...",
    ["它好像在盯着那只首领。"] = "Кажется, он смотрит на этого лидера.",
    ["它有点跛足，身上可能带着一股酒味。"] = "Он немного прихрамывает, и от него может пахнуть спиртным.",
    ["它能利用学徒的力量，创造一个隐秘的空间，并帮您在这个空间和现实中切换，找到通路。"] = "Он может использовать силу Ученика, чтобы создать скрытое пространство и помочь вам переключаться между этим пространством и реальностью, чтобы найти путь.",
    ["它能让你提神醒脑一整夜，绝对不会在文献室睡着，是考试周前学员们的最爱。"] = "Он поможет вам чувствовать себя отдохнувшим всю ночь, гарантируя, что вы не заснете в литературной комнате; это любимое блюдо среди студентов перед экзаменационной неделей.",
    ["宅子怎么了？"] = "Что не так с домом?",
    ["安妮，跟紧本杰明，我们去救你爷爷，我来把路打开！"] = "Annie, stay close to Benjamin. We are going to save your grandfather, I will open the path!",
    ["安宁……好久没有感受到安宁了……"] = "Покой... Давно я не чувствовал покоя...",
    ["宏大的树木矗立在湖中央，异常美丽的金色树皮下，掩盖着危险的非凡本质。你的理智告诉你：远离它。可另一个声音却时刻蛊惑着你：<P_Heart>触摸它。触摸它。</>"] = "В центре озера стоит великолепное дерево. Под необычайно красивой золотой корой скрывается опасная сущность Потустороннего. Ваш разум подсказывает вам: держитесь от этого подальше. Но вас постоянно завораживает другой голос: <P_Heart> Прикоснитесь к нему. Прикоснитесь к нему. </>",
    ["宝箱是你的吗就开，问过我们猎龙帮了吗？"] = "Сундук с сокровищами вам предстоит открыть? Вы спрашивали нашу банду охотников на драконов?",
    ["宝贝，声音小一点，在女神的教堂里要安静。"] = "Дорогая, потише. В соборе Богини нужно соблюдать тишину.",
    ["实不相瞒，我想在下次唱诵会上赢得大家的惊讶与喝彩。这里很安静，不是吗？"] = "Честно говоря, я хочу заслужить всеобщее удивление и аплодисменты на следующем концерте. Здесь очень тихо, не так ли?",
    ["实在分不出心想这些。请大家让一让，我得去市里补点药。"] = "Мне совсем не до этих мыслей. Пропустите, пожалуйста, мне нужно в город за лекарствами.",
    ["实际上，即使真正的“占卜家”，也只能窥得命运模糊的一角。"] = "На самом деле, даже настоящий «Провидец» может лишь бросить взгляд на размытый угол судьбы.",
    ["家是一个人感到安心和舒适的地方。"] = "Дом – это место, где человек чувствует себя безопасно и комфортно.",
    ["寄出请求调查格兰特叔叔的信件后，我独自来到图书馆调查，却同样被失控的往昔之书杀死，灵性附着在了书上。"] = "After mailing the letter requesting an investigation into Uncle Grant, I went to the Library alone to investigate, but I was killed by the loss of control of the Book of the Past all the same, and my spirituality became attached to the book.",
    ["对……对，回孤儿院。本杰明，你带路，我护着安妮。安妮，我们走吧……"] = "Да... да, вернемся в приют. Бенджамин, иди вперед, я защищу Энни. Энни, пойдем...",
    ["对不起……对不起……路太难走了……还有人受了伤……"] = "Мне жаль... Мне очень жаль... дорога была слишком трудной для движения... и кто-то пострадал...",
    ["对不起…我记得我们的约定……"] = "Прости... Я помню наше обещание...",
    ["对不起茜茜，只能把你单独埋在这……我会常来看你的。"] = "Прости, Сиси, я могу похоронить тебя здесь только одну... Я буду часто к тебе приходить.",
    ["对了，“时空道标”，我就收走了。"] = "Кстати, «Пространственно-временной маяк» я заберу обратно.",
    ["对了，太太，您上次说的膝盖疼，我明天配好新药膏给您送过去。"] = "Кстати, мэм, по поводу боли в колене, о которой вы упомянули в прошлый раз, я приготовлю новую мазь и пришлю ее вам завтра.",
    ["对了，您一路过来，有没有碰见过一个男人？大概这么高，头发有点卷，左边下巴这儿有颗小痣，笑起来有点傻气……"] = "Кстати, по дороге сюда вы случайно не встретили мужчину? Вот такой высокий, со слегка вьющимися волосами, с маленькой родинкой на левом подбородке и несколько глуповатой улыбкой...",
    ["对了，要是您看到那边的流浪汉——请不要害怕。自从他精神失常之后，就天天睡在那废弃车厢里，说些什么古怪的东西。但是他从不伤害别人。"] = "Кстати, если увидите там бомжа — не бойтесь. С тех пор, как он стал психически неуравновешенным, он каждый день спал в этом заброшенном экипаже, говоря всякие странные вещи. Но он никогда никому не причиняет вреда.",
    ["对了，麻烦您去问问他，今年的葡萄酒是否要送去一份——我记得他很爱喝。"] = "Кстати, не могли бы вы спросить его, хочет ли он бутылку вина этого года? Я помню, он любит выпить.",
    ["对于你们学生来说挺危险的。"] = "Это довольно опасно для вас, студенты.",
    ["对于舞台背景的设计，他有更好的想法。"] = "У него были лучшие идеи по дизайну фона сцены.",
    ["对啊，马桶还是给人用的呢！"] = "Да, и туалеты предназначены для людей!",
    ["对对对，但光是今天，你都已经提到他不下十次了。"] = "Да-да, но только сегодня ты упомянул его минимум десять раз.",
    ["对！就是霍纳奇斯山脉！这里的遗迹能追溯到至少一千五百年前。"] = "Да! Это горный хребет Хорнацис! Руины здесь можно проследить как минимум 1500 лет назад.",
    ["对！想让我接着干，得加钱！否则我就罢工！"] = "Верно! Если вы хотите, чтобы я продолжал работать, вам придется платить больше! В противном случае я объявляю забастовку!",
    ["对，今天天气真不错，哈哈……"] = "Да, погода сегодня действительно хорошая, хаха...",
    ["对，就是你！别往前走了！"] = "Да, это ты! Не идите дальше!",
    ["对，我们这是最甜的西红柿！你要尝尝吗？"] = "Да, у нас здесь самые сладкие помидоры! Хотите попробовать?",
    ["对，直击灵魂，直面每个人最私密最不想谈论的话题……"] = "Да, прямо в душу, лицом к лицу с самыми сокровенными темами, о которых никто не желает говорить...",
    ["寻宝队？"] = "Команда охотников за сокровищами?",
    ["导演向灯光师走去，"] = "Режиссер направился к осветителю,",
    ["导演走到了编剧的面前，"] = "Режиссер подошел к сценаристу:",
    ["导演靠近了舞台师，"] = "Режиссер подошел к художнику-постановщику:",
    ["封印物最后出现在一家制铅厂，西迦会和你一起调查，追回丢失的封印物。"] = "Запечатанный объект наконец появился на свинцовом заводе, и Сицзя вместе с вами проведет расследование, чтобы вернуть потерянный запечатанный объект.",
    ["尊敬的{{先生|小姐}}，我今天在这四周逛了一圈，心情从来没有过这样的畅快！这里的一切看起来都越来越好啦。"] = "Уважаемый {{Mr.| Ms.}}, я сегодня гулял здесь и никогда не чувствовал себя таким отдохнувшим! Здесь все выглядит все лучше и лучше.",
    ["尊敬的{{先生|小姐}}，自从您来到这里，我看着这座城堡逐渐焕发出它的生机，真是令人高兴。瞧瞧这黑麦啤酒，闻起来多么芬芳！"] = "Уважаемый {{Mr.|Ms.}}, с тех пор, как вы прибыли, я наблюдал, как этот замок постепенно восстанавливает свою жизнеспособность; это действительно восхитительно. Посмотрите на это ржаное пиво, как оно ароматно пахнет!",
    ["尊敬的非凡者，感谢您来到这里。"] = "Respected Beyonder, thank you for coming here.",
    ["小伙子还挺浪漫嘛……你们是怎么认识的？"] = "А ты романтик, парень... И как же вы познакомились?",
    ["小姑娘，请问你有没有见过一个叫戈多的人？"] = "Маленькая девочка, ты видела человека по имени Годо?",
    ["小家伙，你在房顶上做什么呢？"] = "Малыш, что ты делаешь на крыше?",
    ["小心些，注意安全。"] = "Будьте осторожны и оставайтесь в безопасности.",
    ["小朋友，你怎么一个人在这里哭？"] = "Маленький, почему ты здесь один плачешь?",
    ["小杰克？我好像不认识。"] = "Малыш Джек? Кажется, я его не знаю.",
    ["小溪的源头住着女巫？听起来怪可怕的。"] = "Ведьма живет у истока ручья? Звучит довольно страшно.",
    ["小狗真是可爱……身上怎么挂了一张纸条？"] = "Щенок такой милый... почему на нем висит записка?",
    ["小红帽，还有什么线索？"] = "Красная Шапочка, есть ли еще какие-нибудь подсказки?",
    ["小镇如此美好，他却如此暴躁，这样不好，不好。"] = "Маленький городок такой красивый, а он такой раздражительный; это нехорошо, нехорошо.",
    ["小镇的信仰吗？不管怎么样，祝你愿望成真！"] = "Вера города? В любом случае, желаю, чтобы ваше желание сбылось!",
    ["小镇里的传说，这条小溪源头的沼泽里住着一个女巫。"] = "Городская легенда гласит, что на болотах у истока этого ручья живет ведьма.",
    ["少加一点没什么问题，魔药里还有呢，也没听说有人喝魔药毒死……"] = "Добавить немного не проблема; оно уже в зелье, и я не слышал, чтобы кто-нибудь умер от употребления зелья...",
    ["就像一场永远不会落幕的歌剧，很美妙，对吧？这得感谢学生们给我的灵感。"] = "Словно опера, у которой никогда не опустится занавес... Прекрасно, правда? За это вдохновение я должен благодарить своих учеников.",
    ["就像我和雷吵架后总会和好一样！"] = "Точно так же, как мы с Рэем всегда миримся после ссор!",
    ["就因为他年轻英俊？咱以前抢过那么多小白脸，也没见她手软过。"] = "Только потому, что он молод и красив? Мы раньше ограбили столько симпатичных мальчиков, и я никогда не видел, чтобы она размягчилась.",
    ["就是！你看你这袍子，领口都磨白了！哪个体面姑娘不能帮你打理得妥妥帖帖？"] = "Точно! Посмотрите на свой халат, воротник белый! Какая порядочная девушка не могла бы помочь тебе поддерживать порядок?",
    ["就算想到了……他那么胆小，肯定也不敢找过来，嘻嘻。"] = "Даже если бы он догадался... он такой робкий, что точно не осмелился бы подойти и посмотреть, хи-хи.",
    ["就算摘走一两朵，隔天睡莲也会长出来，这都是仙女的庇佑啊！"] = "Даже если вы соберете одну или две, кувшинки вырастут снова на следующий день. Это всё благословение феи!",
    ["就该多招人！"] = "Вам обязательно стоит нанять больше людей!",
    ["尼古拉，你都多大了，还相信这种东西。"] = "Никола, взрослый ведь человек, а всё ещё веришь в подобные сказки.",
    ["尼尔，你在哪里？"] = "Нил, где ты?",
    ["屋里只有我一个人，所以发出声音的只能是……不干净的东西！"] = "Я один в доме, так что звук, должно быть,... какой-то нечистый!",
    ["崇敬着“梦”的小镇吗……说不定是哪位老熟人的“杰作”？"] = "Город, который чтит «мечты»… возможно, это «шедевр» какого-то старого знакомого?",
    ["崔佛……你还会改装枪支？"] = "Тревор... ты тоже умеешь модифицировать огнестрельное оружие?",
    ["工作永远忙不完！你就是太操心！找个妻子正好照顾你饮食起居！"] = "Work is never finished! You just worry too much! Найти жену было бы идеально, чтобы заботиться о вашей повседневной жизни!",
    ["工作？这不算工作哈哈，我这人比较喜欢聊天，和大家聊的多了，知道的就多了，他们就喜欢叫我“小灵通”。"] = "Работать? Это не считается работой, хаха. Я больше люблю общаться. Чем больше я общаюсь с людьми, тем больше я знаю. Они любят называть меня «Маленький умник».",
    ["巨人语、精灵语、巨龙语、古赫密斯语、赫密斯语、古弗萨克语、鲁恩语……为什么要学这么多种语言，难道我还需要和巨龙沟通吗？"] = "Язык гигантов, Эльфийский, Драконий, Древний Гермес, Гермес, Древний Фейнапоттер, Лоэн... зачем мне учить так много языков? Нужно ли мне общаться с гигантским драконом?",
    ["差不多就这么些了。那么，祝您玩得愉快！"] = "Вот, пожалуй, и все. Что ж, приятного времяпрепровождения!",
    ["布尼尔、贝克、安瑟姆都送来了情诗……今晚和谁约会呢？"] = "Бернье, Бейкер и Ансельм прислали любовные стихи... С кем мне стоит встретиться сегодня вечером?",
    ["布尼尔秃头，安瑟姆油嘴滑舌，还是贝克吧，至少长得帅！"] = "Бёрнье лыс, Ансельм красноречив; Я пойду с Бейкером, он хотя бы красивый!",
    ["希望女神能接受可怜信徒的祈求，能最后给予我一次好运。"] = "Я надеюсь, что Богиня сможет принять молитвы бедного верующего и в последний раз подарить мне удачу.",
    ["希望您能喜欢……"] = "Надеюсь, тебе понравится...",
    ["帮我一个小忙吧，在这里颂念那位的尊名，为那场神战的残留画上句点。"] = "Окажите мне небольшую услугу: повторите здесь Его почетное имя, чтобы положить конец остаткам этой божественной войны.",
    ["帮我收集这里的灵性痕迹碎片，我需要分辨和拼凑出目标真实的行踪。"] = "Помогите мне собрать здесь осколки духовных следов — мне нужно различить их и восстановить истинный маршрут цели.",
    ["干得漂亮！核心污染已被清除，这个空间稳定了。"] = "Красиво сделано! Основная Искажение устранена, и это пространство стабильно.",
    ["平时我们在这些区域活动比较多一些，比较热闹。"] = "Обычно мы чаще бываем в этих районах, здесь довольно оживленно.",
    ["年轻……我年轻时来过这里，还遇到三个人。"] = "Молодой... Я приехал сюда, когда был молодым, и встретил трех человек.",
    ["年轻人，你可不要学那桥上的老头子啊。"] = "Молодой человек, вам не следует походить на того старика на мосту.",
    ["年轻人，你还不错。我就告诉你一个重要信息吧。"] = "Молодой человек, вы неплохи. Позвольте мне сообщить вам важную информацию.",
    ["年轻人，别挡到我的光。"] = "Молодой человек, не загораживайте мне свет.",
    ["年轻人，很遗憾，这里是只有本地老人的酒馆。等你年纪再大些，在古堡落脚了……到那时再来吧！"] = "Young man, it's a pity, but this tavern is only for the local elders. When you're a bit older and have settled down in the ancient castle... come back then!",
    ["年轻人，谢谢你陪我走过这段路。"] = "Молодой человек, спасибо, что сопровождали меня в этом путешествии.",
    ["年轻男性，短发，探险队成员。见过？"] = "Молодой мужчина, короткая стрижка, из исследовательской экспедиции. Видели такого?",
    ["幸好女神没有抛弃我。路过的清洁工伸出了援手，教会的修女又为我介绍了新工作。"] = "К счастью, Богиня не оставила меня. Проходившая мимо уборщица протянула мне руку помощи, а монахиня из церкви познакомила меня с новой работой.",
    ["幻觉里的人说，是由高高的尖顶和巨大的柱子构成……该死，我怎么记得这么清楚！"] = "Люди в галлюцинации говорили, что он состоит из высоких шпилей и огромных колонн... блин, почему я так ясно это помню!",
    ["应当去主动搭讪一位绅士，看上去就阔气的那种。"] = "Я должен взять на себя инициативу и завязать разговор с джентльменом, который выглядит богатым.",
    ["底座刻着一行小字：命运就像导师的脸色——你越想知道，它越不可预测。"] = "На основании выгравирована небольшая строка текста: Судьба подобна выражению инструктора: чем больше вы хотите знать, тем более непредсказуемой она становится.",
    ["度假就是要和大自然亲密接触才行！"] = "Отдых – это приближение к природе!",
    ["开始你的“表演”吧。愿女神庇佑你的推理。"] = "Начинайте свое «представление». Пусть Богиня защитит ваше отчисление.",
    ["弗莱队长就在办公室中等你"] = "Капитан Фрай ждет вас в офисе.",
    ["强大的秩序是无比危险的。它会使你在痛苦中挣扎，却只能怀疑自己：是我做的不对吗？而无法察觉秩序本身的错误。"] = "Непререкаемый порядок невероятно опасен. Он заставит тебя мучиться и винить лишь себя: «Неужели я поступил неправильно?», будучи не в силах осознать порочность самого порядка.",
    ["当你锁定矛盾，就必须以无可辩驳的“证据”，直面你的目标。"] = "Когда вы зацикливаетесь на противоречии, вы должны предъявить своей цели неопровержимые «доказательства».",
    ["当你需要暗号的时候，说“醉汉”准没错！当然了，暗号这种东西，可能不久之后就会改变……但管他呢，到那时再说！"] = "Когда вам нужен пароль, всегда правильно сказать «Пьяница»! Конечно, подобные пароли вскоре могут измениться... но кого это волнует, мы разберемся с этим, когда придет время!",
    ["当我去找他要个说法时，他却当着我的面被马车撞了！"] = "Когда я подошел к нему, чтобы попросить объяснений, его сбила коляска впереди меня!",
    ["当时，我的女儿跟我说，在满月夜里把南瓜埋在后院，就能让生病的孩子好转。我的小儿子咳嗽确实好了，我就……"] = "Тогда моя дочь рассказала мне, что если закопать тыкву на заднем дворе в ночь полнолуния, больному ребенку станет лучше. Кашель моего маленького сына стал лучше, поэтому я...",
    ["当然是偷——买面包啦！我爸爸因为……买一块面包被抓了，要关很久很久。"] = "Конечно, укра... купить хлеба! Моего папу схватили за то, что он... купил буханку хлеба, и теперь его запрут очень-очень надолго.",
    ["当然是寻宝了！"] = "Конечно же, искать сокровища!",
    ["当然是小镇上庆祝丰收，感恩大地的节日。看我家门口满地金黄的南瓜，多么甜美的果实，多么伟大的丰饶之力！"] = "Конечно, в маленьком городке это праздник, посвященный сбору урожая и благодарению земли. Посмотрите, какие золотые тыквы у моего порога, какие сладкие плоды, какая великая сила урожая!",
    ["当然！据说这酿出的酒里，还有仙女对我们的祝福呢！"] = "Конечно! Говорят, что в этом сваренном вине есть и благословение феи для нас!",
    ["当然！这可是塔罗学派建校的基石，我有充分的理由怀疑，“愚者”先生和会长是叔侄关系……"] = "Конечно! Это краеугольный камень основания Клуба Таро. У меня есть достаточно оснований подозревать, что Мистер Шут и Президент — дядя и племянник...",
    ["当然，再去听听他们的叹息声——缅怀那些战争的日子。"] = "Конечно, и еще раз послушать их вздохи — вспомнить те дни войны.",
    ["当然，前提是获得它的认可，你要不要试试？"] = "Конечно, предпосылка состоит в том, чтобы получить его одобрение. Хотите попробовать?",
    ["当然，只是我希望你永远不需要请自己爱的人喝这杯饮品。"] = "Разумеется. Просто надеюсь, тебе никогда не придется угощать этим напитком того, кого любишь.",
    ["当然，如果你对占卜感兴趣的话也可以去那里试试……"] = "Конечно, если вас интересует гадание, вы тоже можете попробовать его там...",
    ["当然，我此生的挚爱，我的生命似乎就是因为她才得以存在。"] = "Конечно, любовь всей моей жизни; мое существование, кажется, благодаря ей.",
    ["当然，有什么事？"] = "Конечно, что это такое?",
    ["当然，生活艰难，就应该盼点好事。"] = "Конечно, жизнь трудна, поэтому следует надеяться на хорошее.",
    ["当然，要我说，谁看到这张名为“私人物品采买清单”，实则是“私人物品愿望清单”的都会感到头疼的。"] = "Конечно. Если вы спросите меня, у любого, кто увидит этот «Список покупок личных вещей», который на самом деле является «Списком желаний личных вещей», возникнет головная боль.",
    ["很多故事里都有类似的勇敢角色。"] = "Во многих историях встречаются похожие храбрые герои.",
    ["很好！你已经学会了叹息之种的使用，下面尝试下进阶挑战！"] = "Очень хороший! Вы научились использовать Семя Вздохов; теперь попробуйте сложную задачу!",
    ["很好！有这样的干劲我们做什么都会成功的！"] = "Отлично! С таким рвением у нас любое дело спориться будет!",
    ["很抱歉，主教阁下现在并不在教堂内，如果您需要，可以向教堂里任何一位牧师寻求帮助。"] = "Извините, епископа сейчас нет в церкви. Если вам что-нибудь понадобится, вы можете обратиться за помощью к любому священнику в церкви.",
    ["得了吧！几百年都过去了，出事还轮得到我们头上吗？不去就别耽误我玩牌。"] = "Ну давай же! Прошли сотни лет, настанет ли наша очередь, чтобы что-то произошло? Если ты не пойдешь, не мешай мне играть в карты.",
    ["徽章。玫瑰的徽章。没有它，你连第一级台阶都碰不到。"] = "Значок. Значок Розы. Без него вы даже не прикоснетесь к первому шагу.",
    ["心上人吗？也对，正是青春浪漫的年纪……"] = "Милая? Правильно, это возраст молодости и романтики...",
    ["忘了妈妈念给你的诗了吗？我们要在安宁和静谧中祈求女神的庇护……嘘……"] = "Ты забыл стихотворение, которое тебе читала мама? Мы должны молиться о защите богини в тишине и покое... Шшш...",
    ["快去指导下一幕戏吧。"] = "Скорее ступай руководить следующей сценой.",
    ["快帮帮我！把我拉出来！"] = "Помоги мне! Вытащи меня!",
    ["快离开吧。"] = "Уходите быстро.",
    ["怎、怎么可能！"] = "Как, как это возможно!",
    ["怎么……回事……昨天还……好好的……"] = "Что... происходит... вчера было... хорошо...",
    ["怎么不能自己出发？"] = "Почему нельзя отправиться в путь самостоятельно?",
    ["怎么了，哥哥？"] = "Что случилось, брат?",
    ["怎么了，顾问{{先生|女士}}？想要放弃追踪？"] = "Что такое, консультант {{господин|госпожа}}? Решили бросить слежку?",
    ["怎么偏心了？"] = "Насколько он был предвзятым?",
    ["怎么办怎么办，如果被叔叔发现，你就完了！"] = "Что мне делать, что мне делать? Если дядя узнает, вам конец!",
    ["怎么办，被，被拒绝了……"] = "Что мне делать, я был, меня отвергли...",
    ["怎么办？当然是硬着头皮办完了！"] = "Что делать? Конечно же, стиснуть зубы и довести дело до конца!",
    ["怎么样，你要报名参赛吗？"] = "Как насчет этого, ты собираешься записаться на конкурс?",
    ["怎么样，还符合您的口味吗？"] = "Как это? Это в вашем вкусе?",
    ["怎么说呢，阿罗德斯大人的提问往往……"] = "Как бы это сказать, вопросы лорда Арродеса ​​часто...",
    ["怎么说，要试试吗？输的人等下宵夜可要请客！"] = "Что скажешь, хочешь попробовать? Проигравшему придется платить за ночные закуски!",
    ["总会有人对霍纳奇斯感到好奇。"] = "Всегда найдутся люди, интересующиеся Хорнацисом.",
    ["恋爱的时候，话不多，但你说过的每一句都能被记住。和这样的人谈大概会有很不错的恋爱体验。"] = "Когда ты влюблен, ты мало говоришь, но все, что ты говоришь, можно запомнить. Вероятно, вы получите большой любовный опыт, если поговорите с таким человеком.",
    ["恐怖如斯……居然能在灵界开辟一方天地，建造这样宏伟的建筑，我越来越崇拜背后的大人物了。"] = "Ужасно... Чтобы иметь возможность открыть мир в Мире Духов и построить такое великолепное сооружение, я все больше и больше восхищаюсь той важной фигурой, которая стоит за ним.",
    ["恢复全部生命"] = "Восстановить все здоровье",
    ["恭喜你做出了真正正确的选择。"] = "Поздравляю, вы сделали поистине верный выбор.",
    ["恭喜各位赢得本次俱乐部宣战。宴席已经备好，请领取属于胜者的奖励。"] = "Congratulations to everyone for winning this Club war. The feast is ready, please claim the rewards belonging to the victors.",
    ["恶龙为什么要来袭击这里呢？"] = "Зачем злой дракон напал на это место?",
    ["恶龙吐出来的明明是火球！"] = "«Злой Дракон» явно извергал огненные шары!",
    ["患者去世对医生来说，意味着误诊的可能性和不必要的麻烦。我只需要为我的职业生涯负责。"] = "Для врача смерть пациента означает возможность постановки неправильного диагноза и ненужных неприятностей. Мне нужно нести ответственность только за свою карьеру.",
    ["您一定就是{{PlayerName}}吧。我收到消息，在这里等候您，并为您提前准备了一份契约。"] = "Вы должны быть {{PlayerName}}. Я получил известие ждать вас здесь и заранее подготовил для вас контракт.",
    ["您一定就是可以净化污染的人吧！我能帮助您！只要您愿意放我离开！"] = "You must be the one who can perform Purification on the corruption! I can help you! As long as you are willing to let me leave!",
    ["您不是俱乐部宣战获胜方，无法领奖。"] = "You are not the winning side of the Club war, so you cannot claim the reward.",
    ["您为什么要拦着火车往里开？"] = "Почему вы не пускаете поезд?",
    ["您也快点离开这里吧，期待我们还有再见的机会。"] = "Тебе тоже следует уйти отсюда поскорее. Я с нетерпением жду нашей встречи снова.",
    ["您做得很好，这份谢礼，请务必收下。"] = "Вы справились очень хорошо. Пожалуйста, обязательно примите этот знак благодарности.",
    ["您刚提到“金秋湖的神秘预言”是什么？"] = "Что такое «Таинственное пророчество об озере Золотой Осени», о котором вы только что упомянули?",
    ["您可以叫我老维克多，与佛尔思女士同属于学徒途径。"] = "Можешь звать меня Старый Виктор. Я принадлежу к «Пути ученика», как и мисс Форс.",
    ["您可以通过合理的买卖策略，在各个站点间进行商贸交易。交易能积累商会票券，最终转换为城堡资产。"] = "Вы можете вести коммерческую торговлю между различными станциями, используя разумные стратегии покупки и продажи. Торговля позволяет накапливать билеты Торговой палаты, которые в конечном итоге будут конвертированы в активы замка.",
    ["您在这儿钓鱼？"] = "Вы здесь рыбачите?",
    ["您好，“倒吊人”先生！"] = "Здравствуйте, господин Повешенный!",
    ["您好，“魔术师”女士！"] = "Здравствуйте, госпожа Волшебница!",
    ["您好，亚伦上士，您一定很了解这里，愿意讲讲吗？"] = "Здравствуйте, сержант Аарон, вы, должно быть, очень хорошо знаете это место, не могли бы вы рассказать мне о нем?",
    ["您好，伦纳德先生！"] = "Здравствуйте, мистер Леонард!",
    ["您好，克莱恩先生！"] = "Здравствуйте, мистер Клейн!",
    ["您好，勤劳的园丁，镇上的花都是您照料的吗？"] = "Здравствуйте, трудолюбивый садовник! Это вы ухаживаете за всеми цветами в городке?",
    ["您好，园丁。总是见到您在这里照料花朵，真是风雨无阻啊。"] = "Привет, садовник. Я всегда вижу тебя здесь, заботящегося о цветах, несмотря на ветер и дождь.",
    ["您好，奥黛丽小姐！"] = "Здравствуйте, мисс Одри!",
    ["您好，尼尔先生！"] = "Здравствуйте, мистер Нил!",
    ["您好，弗兰克先生！"] = "Здравствуйте, мистер Фрэнк!",
    ["您好，弗莱队长！"] = "Здравствуйте, капитан Фрай!",
    ["您好，愿女神庇佑您，有什么事吗？"] = "Здравствуйте, да защитит вас Богиня. Чем могу помочь?",
    ["您好，我是这里的主理人玛里琳，需要我为您推荐菜品吗？"] = "Здравствуйте! Я Мэрилин, управляющая этого заведения. Подсказать вам что-нибудь из блюд?",
    ["您好，我请这位先生一杯酒。"] = "Здравствуйте, я хотел бы купить этому джентльмену выпить.",
    ["您好，戴莉女士！"] = "Здравствуйте, мисс Дейли!",
    ["您好，梅丽莎小姐！"] = "Здравствуйте, мисс Мелисса!",
    ["您好，洛薇雅长老！"] = "Здравствуйте, старейшина Ловия!",
    ["您好，班森先生！"] = "Здравствуйте, мистер Бенсон!",
    ["您好，苏茜女士！"] = "Здравствуйте, мисс Сьюзи!",
    ["您好，薇尔莉特为您服务。"] = "Здравствуйте, Вайолет к вашим услугам.",
    ["您好，要乘坐观光马车吗？"] = "Здравствуйте, не хотите ли прокатиться на экскурсионной карете?",
    ["您好，请问您想来点什么呢？"] = "Здравствуйте, чего бы вам хотелось?",
    ["您好，邓恩队长！"] = "Здравствуйте, капитан Данн!",
    ["您好，陌生的朋友。今天真是浇花的好天气，不是吗？"] = "Здравствуйте, незнакомый друг. Сегодня чудесная погода для полива цветов, не правда ли?",
    ["您已领取过本次俱乐部宣战胜方奖励，或已达到当日领取次数上限。"] = "You have already claimed the reward for the winning side of this Club war, or you have reached the daily claim limit.",
    ["您想坐哪趟车？"] = "В каком вагоне вы бы хотели поехать?",
    ["您想现在开始第一次贸易吗？"] = "Хотели бы вы начать свою первую сделку прямо сейчас?",
    ["您想知道我是怎么当上这行的？这可说来话长。"] = "Хотите знать, как я попал в эту сферу деятельности? Это долгая история.",
    ["您是不是晒昏头了？镇上只有我一个园丁呀。"] = "Вы получили тепловой удар? Я единственный садовник в городе.",
    ["您是戈多？可他不是个年轻人吗……"] = "Ты Годо? Но разве он не был молодым человеком...",
    ["您是指这些南瓜的口味吗？"] = "Вы имеете в виду вкус этих тыкв?",
    ["您是这里的巡逻员？您平时都负责什么呢？"] = "Вы здесь патрульный? Каковы ваши обычные обязанности?",
    ["您猜的没错。只可惜，最后我才是那个“脏污”。"] = "Вы правильно догадались. Жаль только, что в конце концов «грязью» оказался именно я.",
    ["您看到一位少年没有？他刚刚还在这儿和我家小姐说话。"] = "Вы видели маленького мальчика? Он только что разговаривал с моей молодой любовницей.",
    ["您看起来，太清醒了，不太像是属于这里的人呢……"] = "Ты выглядишь... слишком трезвым; ты не похож на того, кому здесь место...",
    ["您真好，要是我也能像您这样能干，也许就不会……总之，非常感谢您！"] = "You are so kind. If I could be as capable as you, perhaps I wouldn't have... Anyway, thank you very much!",
    ["您知道吗，考古发现，霍纳奇斯山脉曾有人类活动的痕迹，明显已形成文明，存在一个古老的国度！"] = "Знаете ли вы, археологические открытия показывают, что в горном хребте Хорнацис были следы деятельности человека, явно сформировавшего цивилизацию, с существовавшим древним царством!",
    ["您知道福斯特和赛肯德这两个名字吗？总觉得他们和您……"] = "Вы знаете имена Фостер и Секонд? Мне кажется, они как-то связаны с вами...",
    ["您知道那家酒馆的暗号吗？就是那边那家，有个老太婆把门的那家——"] = "Ты знаешь пароль от этой таверны? Тот, что там, тот, где старуха охраняет дверь…",
    ["您终于来了，侦探{{先生|女士}}……"] = "Наконец-то вы пришли, детектив {{ Mr. | Ms. } }...",
    ["您能预知天气？"] = "Можете ли вы предсказать погоду?",
    ["您要买点尝尝吗？只要1苏勒，买一个送十个！不，买一个送二十个！"] = "Хотите купить что-нибудь попробовать? Всего 1 суле, при покупке одного получите десять в подарок! Нет, купи один, получи двадцать в подарок!",
    ["您要是哪天碰巧见了，一定告诉他——就说别忘了凯瑟琳娜！他房间窗台上的薄荷草，再不来浇水就该枯啦。"] = "Если вам случится однажды увидеть его, вы должны сказать ему, скажите ему, чтобы он не забыл Кэтрин! Мята на его подоконнике завянет, если он в ближайшее время не придет ее полить.",
    ["您身后的这一位正是象征财富的守护灵，它身披金甲，手持——"] = "Тот, кто позади вас, — дух-хранитель, символизирующий богатство; он облачен в золотые доспехи и держит…",
    ["您还有别的需要吗？"] = "Есть ли у вас другие потребности?",
    ["您还有需要了解的内容吗？"] = "Есть ли что-то еще, что вам нужно знать?",
    ["您这么说……我想起来了！这座图书馆被污染的原因！"] = "Now that you mention it... I remember! The reason this Library was subjected to corruption!",
    ["您需要参加活动吗？"] = "Вам необходимо принять участие в мероприятии?",
    ["想什么呢！学习！二人学习世界！"] = "Что ты думаешь! Изучение! Учебное занятие для двоих!",
    ["想你，玛丽。爱你的，内特。"] = "Думаю о тебе, Мэри. С любовью, Нейт.",
    ["想打开这个宝箱，你得和我玩个游戏。"] = "Чтобы открыть этот сундук с сокровищами, вам придется сыграть со мной в игру.",
    ["想拿工资？先报名“分红炸弹”——赢了分钱，输了算你运气不好。"] = "Хочешь получить плату? Сначала запишись на «Бомбу с кушем»: победишь — разделишь деньги, проиграешь — пеняй на судьбу.",
    ["想要听一曲，来感受这美好的一天吗？"] = "Хотели бы вы послушать мелодию и почувствовать этот чудесный день?",
    ["想要和太阳一般明媚的爱人，这样的要求我可是经常听。"] = "Мечтать о возлюбленном, лучезарном, точно солнце, — уж такие пожелания я слышу сплошь и рядом.",
    ["想要的话，你要自己来拿。"] = "Если ты этого хочешь, ты должен получить это сам.",
    ["想要瞻仰睡莲之美的人，去湖边就好啦！"] = "Желающие полюбоваться красотой кувшинок могут просто отправиться на берег озера!",
    ["感谢你的贡献。我一路追查它到这里，没想到，还是掉进了它的陷阱。还好有你的出现，不然我也要变成被它操控的木偶了。"] = "Спасибо за ваш вклад. Я отслеживал его всю дорогу сюда, но не ожидал, что попадусь в его ловушку. К счастью, ты появился; в противном случае я бы тоже стал марионеткой, управляемой им.",
    ["感谢女神，只是旧伤在阴雨的天气中有些闹腾，至少我活着回来了，还能再见到帕莎。"] = "Слава Богине, просто старая травма дает о себе знать в дождливую погоду. По крайней мере, я вернулся живой и снова вижу Пашу.",
    ["感谢您几位的好意，真的。但最近雨季快到了，老约翰的风湿、丽莎家的双胞胎咳嗽都没好利索，南边镇上还有不少人说要来打疫苗……"] = "Спасибо вам всем за доброту, правда. Но скоро сезон дождей, у старого Джона ревматизм, у близнецов Лизы кашель так и не прошёл до конца, да и в южном городке многие говорили, что придут на вакцинацию...",
    ["感谢您来，期待我们的下次见面。"] = "Спасибо, что пришли, я с нетерпением жду нашей следующей встречи.",
    ["感谢您的聆听，祝您今日愉快。"] = "Спасибо, что выслушали, желаю вам приятного дня.",
    ["感谢您的赞美，{{先生|小姐}}！"] = "Спасибо за комплимент, {{ Mr. | Miss }}!",
    ["愿丰饶的美丽长存，愿圣者的意志与你我同在。"] = "Пусть красота урожая длится вечно, и пусть воля Святого пребудет с нами с вами.",
    ["愿你早日找到那个能与你共同编织命运的人，{{先生|女士}}。"] = "Желаю тебе скорее найти человека, с которым сможешь сплести свою судьбу вместе, {{Mr.|Ms.}}.",
    ["愿命运眷顾你，{{先生|女士}}。我有预感，在这里扔出骰子的话，你将拥有特别的好运馈赠。"] = "Пусть судьба благоволит тебе, {{Mr.|Ms.}}. У меня предчувствие, что если вы бросите кости здесь, вас ждет особенный подарок удачи.",
    ["愿女神庇佑你！"] = "Да хранит тебя Богиня!",
    ["愿女神庇佑你！<P_Heart>（小声）</>作为回报，我偷偷告诉你个秘密……"] = "Да хранит тебя Богиня! <P_Heart>(шепотом)</> В награду я открою тебе секрет...",
    ["愿女神眷顾你，{{先生|女士}}。我是萨默尔太太，誓约见证者。若你找到了那个愿共度一生的人，我可以为你们主持誓约仪式。"] = "Да благословит тебя Богиня, {{Mr.|Ms.}}. Я миссис Сэммер, Свидетель Завета. Если вы нашли человека, с которым хотите провести свою жизнь, я могу провести для вас церемонию завета.",
    ["戈多……谁？"] = "Годо... кто?",
    ["戏演得不错。"] = "Хорошая актерская игра.",
    ["我……"] = "Я...",
    ["我……我不知道啊。"] = "Я... я не знаю.",
    ["我……我们在玩捉迷藏……要数到一百之后，我才能去找他们。可是，他们早就跑得不知道多远了！"] = "Я... мы играли в прятки... Я могу пойти их искать только после того, как досчитаю до ста. Но они давно убежали неизвестно как далеко!",
    ["我……我会认真考虑大家的建议。现在请让我先去工作吧，病人还在等。"] = "Я... Я серьезно рассмотрю предложения каждого. А теперь, пожалуйста, отпустите меня на работу, пациенты еще ждут.",
    ["我……我在这里。听着，我们得离开这儿，回孤儿院。玛莎……玛莎女士可能已经在那里等我们了。"] = "Я... я здесь. Слушай, нам нужно выбраться отсюда и вернуться в приют. Мисс Марта... Мисс Марта, возможно, уже ждет нас там.",
    ["我……我很痛苦，我愧对两个孩子和亡夫……但是，我实在是无法拒绝斐乐的示好。"] = "Мне... мне так больно, я виновата перед обоими детьми и покойным мужем... но я просто не могу отвергнуть ухаживания Фила.",
    ["我……拥有了一座城堡的所有权？<P_Heart>（这就是“正义”小姐说的，“找个地方落脚”？）</>可是……"] = "Я... владею замком? <P_Heart>(Это то, что сказала Мисс «Справедливость»: «Найти место для проживания»?) </> Но...",
    ["我……还不确定。"] = "Я... пока не уверен.",
    ["我、我再待一会儿就回去。"] = "Я, я останусь еще немного, а потом вернусь.",
    ["我、我吗？<P_Yellow>三点</>的时候，我在准备下午茶……因为老爷最近几乎不吃东西，但吩咐茶一定要按时送。"] = "Я, я? <P_Yellow>В три часа</> я готовила полдник... Потому что хозяин в последнее время почти не ел, но распорядился, чтобы чай доставили вовремя.",
    ["我上个月丢的怀表真的在三天后出现在餐桌上！"] = "Карманные часы, которые я потерял в прошлом месяце, через три дня действительно появились на обеденном столе!",
    ["我不是找官方来处理了吗？柯莱特还赔了一大笔钱。"] = "Разве я не нашел официальных властей, которые могли бы справиться с этим? Колле даже заплатил крупную сумму денег.",
    ["我不能让别人也变成这样……求你别进去，千万别进去！"] = "Я не могу допустить, чтобы другие так поступили... пожалуйста, не входите, абсолютно не входите!",
    ["我不问你的，你也别问我的。这样比较……安全。"] = "Я не буду спрашивать о твоем, а ты не спрашивай о моем. Так безопаснее... так.",
    ["我为什么……好像今天才第一次吃出它们的差别？！"] = "Почему... такое ощущение, что сегодня я впервые почувствовал разницу между ними?!",
    ["我主不会强迫人们改信，也不介意信仰是否纯粹，简单来说，他不介意人们在信仰其他神灵的时候信仰他。"] = "Мой Господь не принуждает никого обращаться в Свою веру и не требует абсолютной чистоты помыслов. Проще говоря, Он не против, если люди веруют в Него, одновременно почитая других богов.",
    ["我主居于现实和灵界之上，仁慈洒满了天国和大地，他的座旁共有六位天使侍立……"] = "Мой Господь обитает над реальностью и Миром Духов, милость наполняет небеса и землю, и шесть ангелов стоят рядом с Ним...",
    ["我主拯救了被众神遗弃的失落城邦，带领那片大陆的幸存者走出“神弃之地”，在海岛上重建了家园……"] = "Мой Господь спас затерянный город-государство, покинутый богами, вывел выживших с этого континента из «Заброшенной Земли Богов» и восстановил их дом на острове...",
    ["我主自称“愚者”，在过去，在现在，也在未来，他是支配灵界的伟大主宰，也是执掌好运的黄黑之王，更是每个生灵追求永恒的道标。"] = "Милорд называет себя «Шутом». В прошлом, настоящем и будущем он — великий правитель, господствующий в мире духов, Король Желтого и Черного, несущий удачу, и маяк для каждого живого существа, стремящегося к вечности.",
    ["我也不太清楚……{{尊敬的先生|尊敬的女士}}，如果你愿意的话，就帮我找找具体的地址吧!"] = "Я и сам толком не знаю... {{Уважаемый сэр|Уважаемая мадам}}, если не трудно, помогите мне отыскать точный адрес!",
    ["我也可以来等人。你在等谁？"] = "Я тоже могу быть здесь и ждать кого-нибудь. Кого ты ждешь?",
    ["我也想给老婆置件新大衣，她那件旧的呢子都打了三年补丁了……"] = "Еще я хочу подарить жене новое пальто; ее старая шерстяная одежда уже три года в заплатах...",
    ["我也想试试寻宝，也许您能给我些建议？"] = "Я бы тоже хотел попробовать поискать сокровища. Возможно, вы могли бы дать мне какой-нибудь совет?",
    ["我也撞见了，顺着它们跑来的方向过去看，没抓到野兽，倒是在草丛里捡到了一张情报贩子的名片。"] = "Я тоже столкнулся с этим. Я пошел в том направлении, откуда они пришли, чтобы посмотреть, но не поймал ни одного зверя. Вместо этого я нашел в траве визитную карточку агента разведки.",
    ["我也是！而且，我才入睡没多久。睡着前的外面多安静啊，连马车声都听不到。"] = "Я тоже! И я уже давно не спал. Прежде чем я заснул, на улице было так тихо; Я даже не слышал шума экипажей.",
    ["我也被鲁本枪杀了——因为目击了他的罪行。我们的墓碑是连在一起的。"] = "Меня также застрелил Рубен, потому что я был свидетелем его преступлений. Наши надгробия находятся рядом друг с другом.",
    ["我也许能帮上忙，不如让我试试？"] = "Возможно, я смогу помочь. Почему бы тебе не дать мне попробовать?",
    ["我也这么觉得，也许那些童话传说都是从这个时空传到我们的世界中的。"] = "Я тоже так думаю. Возможно, все эти сказки и легенды были перенесены из этого времени и пространства в наш мир.",
    ["我今天来是为了复诊，所以<P_Yellow>一直在客厅</>等霍克斯男爵。"] = "Сегодня я пришел с повторным визитом, поэтому <P_Yellow> Я ждал барона Хоукса в гостиной </>.",
    ["我今天联系商会的时候，他们表示，如果我们城堡的物产储备合适，可以借用商会的铁轨去做相关贸易。"] = "Когда я сегодня связался с Торговой палатой, они сказали, что, если запасы продукции нашего замка подходят, мы можем одолжить рельсы Палаты для соответствующей торговли.",
    ["我今年二十岁，爱上了一个脾气暴躁的人，我有罪。"] = "Мне двадцать лет, и я полюбила человека с дурным нравом. Я грешна.",
    ["我从一个富人身上“拿”了一条情报。我的天呢，我真的不能再提到这一切。"] = "Я «взял» часть разведки у богатого человека. Боже мой, я правда не могу снова обо всем этом упоминать.",
    ["我从廷根市过来。拉姆德小镇倒是个热闹的地方。"] = "Я приехал из Тингена. Ламуд Таун – довольно оживленное место.",
    ["我从文献库借阅了资料，发现窥秘人途径序列4神秘学家的核心能力是神秘再现。"] = "Я позаимствовал материалы из библиотеки литературы и обнаружил, что основная способность мистериолога из серии 4 «Пути Тайного Прайера» — это мистическое воспроизведение.",
    ["我以为他只是在外面玩得晚了一点！他会回来！"] = "Я думал, он просто опаздывает! Он вернется!",
    ["我们不是说好了？再看一次薰衣草，我们就彻底分开。"] = "Разве мы не согласились? Как только мы увидим лаванду в последний раз, наши пути разойдутся навсегда.",
    ["我们不能放任柯莱特这样下去了……上次他研发的什么药剂，直接在廷根造成了鼠患，那一只只老鼠长得比我的头都大。"] = "Мы не можем позволить Коллетт продолжать в том же духе... Зелье, которое он разработал в прошлый раз, вызвало нашествие крыс прямо в Тингене; эти крысы выросли больше моей головы.",
    ["我们两个也打不过。好了，你能说服柯莱特放弃药剂研发吗？"] = "Мы двое тоже не можем. Хорошо, сможешь убедить Колле отказаться от исследований в области зелий?",
    ["我们两个多么幸运，能看到如今的金秋湖——哪怕是以灵体的方式。噢，这得感谢格温尼女士。"] = "Как нам повезло увидеть озеро Золотой Осени таким, какое оно есть сегодня, даже если оно находится в форме духовных тел. О, мы должны поблагодарить за это мисс Гвенни.",
    ["我们举办活动前会在学派内发布预告，期待你的加入！"] = "Перед каждым мероприятием мы публикуем анонс в школе. Ждем вашего участия!",
    ["我们企图在混沌的世界里建立起秩序，如同行走于空中钢缆。如今人类所作所为，是必要的改变，还是无意义的自我约束？"] = "Мы пытаемся установить порядок в хаотичном мире, словно ходим по стальному тросу в воздухе. Является ли то, что сейчас делает человечество, необходимым изменением или бессмысленным самоограничением?",
    ["我们会在这里等你的好消息。"] = "Мы будем ждать здесь ваших хороших новостей.",
    ["我们会定期举办历史文化讲座，进行时代常识科普。"] = "Мы регулярно проводим лекции по истории и культуре, чтобы просвещать людей в реалиях нашей эпохи.",
    ["我们先进行第一次的小测验。码头工人布拉迪失踪了，这是现场遗留的证物，记得仔细查看。"] = "Для начала проведем небольшую проверку. Пропал докер Брейди, а это — оставленные на месте улики. Осмотрите их повнимательнее.",
    ["我们十分心动，答应了一同旅行。"] = "Мы очень соблазнились и согласились поехать вместе.",
    ["我们四兄弟，大哥精神状况不好，二哥身体不好，父亲从不苛待他们。而小弟芬尼安，是父亲与其他女人的私生子，父亲却对外谎称是贫民窟收养的孩子。"] = "Нас четыре брата. У старшего плохое психическое здоровье, у второго слабое физическое здоровье, и наш отец никогда с ними плохо не обращался. Но младший, Финниан, является внебрачным ребенком, которого отец имел от другой женщины, однако отец солгал общественности, утверждая, что он был ребенком, усыновленным из трущоб.",
    ["我们在为今晚的谷仓舞会做准备！"] = "Сегодня вечером мы готовимся к амбарным танцам!",
    ["我们就要等待戈多。"] = "Мы должны дождаться Годо.",
    ["我们已经抓捕了嫌疑人，是他的同事班克，现在，你可以直接去质询他。"] = "Мы уже поймали подозреваемого, его коллегу Банка. Теперь вы можете пойти прямо на его допрос.",
    ["我们曾经非常亲近……她每天都会来找我聊天，就像现在这样……"] = "Мы были очень близки... она каждый день приходила ко мне поговорить, вот так...",
    ["我们正在创造奇迹！艺术学派里，肯定还没有人在雪山上做过演出。"] = "Мы творим чудо! Наверняка никто в Школе искусств еще никогда не выступал на Снежной горе.",
    ["我们特地给他买了一副，他特别喜欢，从来不离手。"] = "Мы специально купили для него пару, и она ему так понравилась, что он никогда ее не оставлял.",
    ["我们的小弟弟，虽然不太懂规则，但很爱玩扑克牌。"] = "Наш младший брат. Хотя он не совсем понимает правила, он любит играть в покер.",
    ["我们的战友……唉，他们是永远的英雄。"] = "Наши товарищи... ох, они навсегда герои.",
    ["我们的游览路线自北向南覆盖了诸如河与海教堂、大学城和铁十字街等关键交通节点，为您省下脚力的同时还能带您领略廷根市内百般风情。"] = "Наш маршрут тура охватывает ключевые транспортные узлы с севера на юг, такие как Церковь Реки и Моря, Университетский район и улицу Айрон-Кросс, что избавляет вас от работы и позволяет насладиться различными прелестями города Тинген.",
    ["我们的钱不够，没法将你带回家，只能来教堂为您祷告……对不起……"] = "У нас нет денег, чтобы привезти тебя домой, поэтому мы можем только прийти в церковь и помолиться за тебя... Прости...",
    ["我们约着玩斗邪恶，输家喝酒。结果两个人合起伙来出老千，把我灌醉，逼着我签下不合理的契约！"] = "Мы договорились сыграть в «Борьбу со злом», где проигравший будет пить. В результате они объединились, чтобы обмануть меня, напоили и заставили подписать необоснованный контракт!",
    ["我们考古队的营地得从这条道往左拐。"] = "Лагерю нашей археологической группы необходимо свернуть с этой тропы налево.",
    ["我们艺术团就要做挑战不可能的第一人！你要不要也加入我们？"] = "Наша арт-группа первой бросит вызов невозможному! Хотите присоединиться к нам?",
    ["我们营地里有个该死的小偷！"] = "В нашем лагере чертов вор!",
    ["我们要回去吗？"] = "Должны ли мы вернуться?",
    ["我们这座小镇位于廷根西北，是周边乡村唯一的商贸集散地。你看这些建筑风格，几乎没有受到蒸汽时代的侵染，还保持着更早的样貌。"] = "Наш город расположен к северо-западу от Тингена и является единственным торговым центром для окрестных деревень. Посмотрите на эти архитектурные стили; их почти не коснулась эпоха Steam, и они до сих пор сохраняют свой прежний вид.",
    ["我们这里是考古队的营地，成员大多是历史系的师生。"] = "Это лагерь археологической команды. Большинство членов – преподаватели и студенты исторического факультета.",
    ["我们都心疼她，但又能说什么呢？她高兴就好。"] = "Нам всем ее безумно жаль, но что тут скажешь? Лишь бы она была счастлива.",
    ["我们面对的存在，其真相往往隐藏在层层谎言与灵性误导之下。因此，在某些……“特殊”的案件中，圣堂认可了一种更为“戏剧化”的取证程序。"] = "Истина, стоящая за существованием, с которым мы сталкиваемся, часто скрыта под слоями лжи и духовного заблуждения. Поэтому в некоторых... «особых» случаях Собор признает более «драматическую» процедуру сбора доказательств.",
    ["我会在这个站点时刻准备为您发车，或进行火车的维修保养工作。"] = "На этой станции я всегда буду готов отправить для вас поезда или выполнить работы по техническому обслуживанию поездов.",
    ["我会常来看小熊的，你要离水远一点哦！"] = "Я буду часто приходить посмотреть на плюшевого мишку, держись подальше от воды!",
    ["我会注意的。"] = "Я буду иметь это в виду.",
    ["我会留意的。"] = "Я буду следить за этим.",
    ["我似乎不是往昔之书，而是一个“人”……"] = "I don't seem to be a book of the past, but a \"person\"...",
    ["我似乎发现我多了些什么能力……难道，就像那座拔地而起的小镇……许个愿试试。"] = "Кажется, я обнаружил, что у меня появились некоторые способности... Может быть, как тот город, который поднялся из-под земли... Давай я попробую загадать желание.",
    ["我侄女玛莎下周就到镇上来，那姑娘又壮实又勤快，一顿饭能吃掉两条黑面包！你一定要见见！"] = "Моя племянница Марта приезжает в город на следующей неделе. Эта девушка сильная и старательная; она может съесть две буханки черного хлеба за один прием! Вы должны встретиться с ней!",
    ["我保证给你全廷根最公道的价格。"] = "Я гарантирую вам самую справедливую цену во всем Тингене.",
    ["我做梦都想成为她那样的人，她是我的偶像和榜样。"] = "Я мечтаю стать кем-то вроде нее; она мой кумир и образец для подражания.",
    ["我决定不理彼得了，他竟然说我的穿搭奇怪，我明明模仿的是会长，而她可是全学派时尚风潮的引领者！"] = "Я решил игнорировать Питера. Он вообще сказал, что у меня странный наряд, хотя я явно подражал президенту, а она – лидер модного направления всей школы!",
    ["我去探望躺在床上的他……可他醒来时却忘记了我是谁……这一定是盔甲之神的诅咒……"] = "Я пришла навестить его в постели... но очнувшись, он даже не вспомнил, кто я... Это наверняка проклятие Бога Доспехов...",
    ["我发现了主教贪图信徒的钱财，那是无可容忍的脏污。"] = "Я обнаружил, что епископ жаждет денег верующих; это была невыносимая грязь.",
    ["我只想永远和我的木桩朋友待着。"] = "Я просто хочу навсегда остаться со своим деревянным другом-пустышкой.",
    ["我只是图克莱拉的金镑，你放心，我绝对不会背弃我们的小家！"] = "Я всего лишь золотой фунт Тукелелы. Не волнуйтесь, я никогда не оставлю нашу маленькую семью!",
    ["我只是在正常诊疗。作为一名医生，观察病人是职责所在。"] = "Я просто проводил обычную диагностику. Моя обязанность как врача – наблюдать за пациентом.",
    ["我只是多喝了一点酒，我对她没有感情的！"] = "Я просто выпил слишком много; У меня нет к ней чувств!",
    ["我只是想去见我的弗洛拉和小艾米，但是连湖都在拒绝我。"] = "Я просто хотел увидеть свою Флору и маленькую Эми, но даже озеро меня отвергает.",
    ["我只是翻译了你的菜单而已啊！"] = "Я всего лишь перевел ваше меню!",
    ["我只负责管理霍克斯男爵的身体状况，至于他的家庭关系和那些争执……夫人会比我更了解。"] = "Я отвечаю только за здоровье барона Хоукса. Что до его семейных отношений и ссор... госпожа знает об этом куда больше моего.",
    ["我叫爱丽丝给医生做件新衬衫！"] = "Я попрошу Элис сшить доктору новую рубашку!",
    ["我叫福斯特，很高兴认识您。"] = "Меня зовут Фостер, приятно познакомиться.",
    ["我叫赛肯德。祝您拥有美好的一天！"] = "Меня зовут Второй. Хорошего дня!",
    ["我可不关心那些。你看这里，有《睡莲仙女异闻录》连载。"] = "Меня не волнуют эти вещи. Посмотрите, есть сериал «Хроники волшебных кувшинок».",
    ["我可以帮您留意。需要我带个话吗？"] = "Я могу приглядеть для вас. Нужно что-нибудь передать?",
    ["我可以替您去联系当地商会，这样，您之后在城堡产出的更多物产，就有合适的销售渠道了。"] = "Я могу обратиться за вами в местную торговую палату, чтобы у большего количества продукции, производимой в замке, были подходящие каналы сбыта.",
    ["我可能这辈子也见不到他啦，但他们总不能把小狗也关起来吧？"] = "Быть может, мне больше никогда в жизни не суждено его увидеть, но щенка-то они взаперти держать не станут, правда?",
    ["我向他们讨要食物。那些人说，食物是祂的恩赐。"] = "Я попросил у них еды. Эти люди сказали, что еда – это Его дар.",
    ["我听到脚步声了，请别管我，让我睡吧……"] = "Я услышал шаги, пожалуйста, не обращайте на меня внимания, дайте мне поспать...",
    ["我听见它的呓语，让我打开它，证明文学、证明戏剧和感性的伟大。"] = "Я слышал его шепот, говорящий мне открыть его, чтобы доказать величие литературы, драмы и чувственности.",
    ["我听说几年前，有一群特别的人来过？"] = "Я слышал, что несколько лет назад сюда приехала группа особенных людей?",
    ["我告诉他，这酒馆是咱们一砖一瓦垒起来的，是你亲手打的柜台，我亲手刷的墙。"] = "Я ему рассказал, что эту таверну мы построили по кирпичику, ты построил прилавок своими руками, а стены я покрасил сам.",
    ["我和我的同伴一直有这方面的争论，他是蒸汽的信徒，认为数字是一切的真理。"] = "Мы с моим спутником всегда спорили по этому поводу; он верит в Steam и считает, что цифры — это правда всего.",
    ["我和木马骑士呆在一起。这里很安静。"] = "Я остаюсь с Рыцарем Деревянной Лошади. Здесь очень тихо.",
    ["我和里德尔是小有名气的艺术学派创作者，总有一天我们会变得大有名气！"] = "Мы с Риддлом довольно известные создатели Художественной школы, и однажды мы станем очень знаменитыми!",
    ["我哥，哥哥。"] = "Мой брат, брат.",
    ["我在和比利玩捉迷藏呢！他肯定想不到，我能在他数一百下的时间里跑这么远。"] = "Я играю в прятки с Билли! Он определенно не догадался, что я смогу пробежать так далеко за время, необходимое ему, чтобы сосчитать до ста.",
    ["我在找格兰杰，我的爱人。她今天要被求婚了，我想去阻止这一切的发生……"] = "Я ищу Грейнджер, мою возлюбленную. Сегодня ей собираются сделать предложение, и я хочу это предотвратить...",
    ["我在捉迷藏呢！霍金斯教士最讨厌我们在教堂玩闹，所以这里既是最危险的地方， 也是最安全的地方。"] = "Я играю в прятки! Отец Хокинс ненавидит, когда мы играем в церкви, так что это самое опасное и в то же время самое безопасное место.",
    ["我在改造这只怀表！听说下个月贝克兰德又有比赛……"] = "Я модифицирую эти карманные часы! Я слышал, что в следующем месяце в Баклунде пройдут еще одни соревнования...",
    ["我在等人，倒是你，不像是这家的人，你来做什么？"] = "Я жду кого-то. Что касается тебя, то ты не похож на представителя этой семьи. Что ты здесь делаешь?",
    ["我在艺术学派参与过好多次演出，肯定跳得比他们都好。"] = "Я участвовал во многих спектаклях Школы искусств и уверен, что танцую лучше всех.",
    ["我在贝克兰德、廷根都认识不少这样的绅士、夫人……"] = "Я знаю немало таких господ и дам в Баклунде и Тингене...",
    ["我在这荒郊野外花了二十年，找到些破铜烂铁又有什么意义呢。"] = "Я провел двадцать лет в этой пустыне; какой смысл искать металлолом?",
    ["我在这里生活了这么久，却一点也不厌倦。"] = "Я живу здесь так долго, но никогда не устаю от этого.",
    ["我在这里等他。"] = "Я подожду его здесь.",
    ["我在骑士们剑尖所指的方向都埋了宝藏，也许它们到现在都没被发现。"] = "Я закопал сокровища в том направлении, куда указывали мечи рыцарей. Возможно, они не найдены и по сей день.",
    ["我坐了三小时的马车，可不是为了看这些野花。"] = "Я просидел в карете три часа не для того, чтобы посмотреть на эти полевые цветы.",
    ["我多用蜡纸包几层，保证一点味都透不出去，总行了吧？ "] = "Я заверну его еще в несколько слоев вощеной бумаги, гарантирую, что запах не вытечет, ничего страшного, правда?",
    ["我女儿在学校里听来的，她说同学家的女佣亲眼见过。"] = "Моя дочь услышала это в школе. Она сказала, что горничная в доме ее одноклассника видела это собственными глазами.",
    ["我好不容易给他们留下了见面的空档，可是这孩子听见声音就忽地不见了。到现在，我也不知道那男孩长什么样。"] = "Мне наконец удалось оставить им время для встречи, но как только мальчик услышал звук, он внезапно исчез. Я до сих пор не знаю, как выглядит этот мальчик.",
    ["我家小姐最近喜欢上了一个男孩，可是这两个孩子总是躲着我们所有人。"] = "Моей молодой хозяйке недавно понравился мальчик, но эти двое детей всегда прячутся от всех нас.",
    ["我家里的老人从城堡里淘出过真货……带暗纹的银餐具，金子做的怀表，这都是祖传的宝贝！"] = "Старики моей семьи когда-то откопали в замке настоящие сокровища... серебряная посуда с темными узорами, золотые карманные часы - все это родовые реликвии!",
    ["我对这则预言并不感兴趣。再见了，朋友。"] = "Меня не интересует это пророчество. До свидания, друг.",
    ["我将为您奉上独特的变奏，您永远不知道下一个音符是什么。 "] = "Я предложу вам уникальную вариацию; вы никогда не узнаете, какой будет следующая нота.",
    ["我就不一样，每当我想让自己冷静的时候，我就会给自己讲个笑话。"] = "Я другой. Всякий раз, когда я хочу успокоиться, я рассказываю себе анекдот.",
    ["我就看上这个南瓜！又大又黄，肯定好吃！"] = "Я положил глаз на эту тыкву! Он большой и желтый, должно быть очень вкусный!",
    ["我就顺手腌了两条。反正我也吃不完，喂猫可惜了。 "] = "Я попутно засолил парочку. Всё равно сам столько не съем, а кошкам отдавать жалко. ",
    ["我已经努力了两年，还是没有成功通过文法学校的考试，马上、马上是我最后一次机会。"] = "Я усердно работал два года, но мне так и не удалось сдать экзамен в гимназию. Скоро, скоро у меня будет последний шанс.",
    ["我已经很久没……奥罗拉……她忘记我了吗？"] = "Давно я... Аврора... она меня забыла?",
    ["我已经撑不住了，白天做工晚上学习的日子快要毁掉我了。"] = "Я больше не могу этого терпеть; дни работы днем ​​и учебы ночью вот-вот уничтожат меня.",
    ["我已经救了他无数次，尽到了医生的职责。"] = "Я спасал его бесчисленное количество раз и выполнял свои обязанности врача.",
    ["我巴不得几个月见不着他……那才叫清净呢！"] = "Я бы предпочел не видеть его несколько месяцев... вот что называется тишиной и покоем!",
    ["我帮你们问问吧。"] = "Позвольте мне спросить за вас.",
    ["我帮你去找，你快回家吃饭吧。"] = "Я помогу тебе найти его. Ты идешь домой и ужинаешь.",
    ["我帮你捡上来吧。"] = "Давай я помогу тебе поднять.",
    ["我常常感觉自己像一个木偶，一切的结局都是被安排好的。"] = "Я часто чувствую себя марионеткой, у которой все заранее предрешено.",
    ["我平时没机会和老爷说话。关于老爷的事情……您还是去问夫人和约翰先生吧。"] = "Обычно у меня нет возможности поговорить с Мастером. Что касается дел Мастера... вам следует спросить мадам и мистера Джона.",
    ["我很抱歉听到这个故事。"] = "Мне очень жаль слышать эту историю.",
    ["我得先找个地方藏起来……要是偷偷喝药通宵学习的事被发现就糟了。"] = "Сначала мне нужно найти место, где можно спрятаться... Было бы ужасно, если бы выяснилось, что я всю ночь тайно пил зелье, чтобы учиться.",
    ["我怀疑你在骂人……"] = "Я подозреваю, что вы меня оскорбляете...",
    ["我怀疑是代表当事人去工厂检查时，受到了一些惊吓。真是惭愧，一位律师居然如此怯弱。"] = "Подозреваю, что я испугался, осматривая фабрику по поручению клиента. Для адвоката действительно стыдно быть таким робким.",
    ["我怎么会在这里……"] = "Как я здесь оказался...",
    ["我怎么会想杀他？不、不对……"] = "Как я мог хотеть его убить? Нет, это неправильно...",
    ["我恐怕要先找到图书馆的馆长格兰特先生，才能净化这个空间，离开这里。"] = "I am afraid I must find Mr. Grant, the curator of the Library, before I can perform a Purification of this space and leave here.",
    ["我想了解码头的事情。"] = "Я хочу знать о доке.",
    ["我想到了！我要继续去画设计稿了，谢谢你！"] = "Я понял! Собираюсь продолжить работу над эскизом дизайна, спасибо!",
    ["我想听听有关镇子和古堡的来历。"] = "Я хотел бы услышать о происхождении города и замка.",
    ["我想带着我的房子飞上天！年轻人，你觉得我能做到吗？"] = "Я хочу взять свой дом и полететь в небо! Молодой человек, как вы думаете, я смогу это сделать?",
    ["我想您对这个提议一定很感兴趣。不过，这需要一些准备时间，等城堡达到<Highlight>2级</>，一切就绪的时候，您随时可以来找我。"] = "Полагаю, это предложение вас заинтересует. Впрочем, потребуется время на подготовку. Когда замок достигнет <Highlight>2-го уровня</> и все будет готово, вы сможете прийти ко мне в любое время.",
    ["我想我知道该画些什么了，你愿意与我一起吗？"] = "Кажется, я знаю, что теперь рисовать. Хотите присоединиться ко мне?",
    ["我想知道这片美丽花园的主人叫什么名字。"] = "Я хотел бы знать имя владельца этого прекрасного сада.",
    ["我想要钓的未必是鱼。"] = "То, что я хочу поймать, может быть не рыбой.",
    ["我想起来了！他现在已经搬家啦，你可以去村口的稻草房子里找他。"] = "Теперь я вспомнил! Он уехал; ты можешь найти его в соломенном доме на въезде в деревню.",
    ["我想，我是愿意的……"] = "Думаю... я согласна...",
    ["我所做的，无非是把这些传说与砖石的年代勉强拼接，而真相……恐怕早已沉没在历史的长河里了。"] = "Все, что я сделал, это едва сложил воедино эти легенды с возрастом кирпичей и камней, а правда... Боюсь, она уже давно утонула в длинной реке истории.",
    ["我打算做一个经典招牌，当当当当！“想你的风还是吹到了塔罗学派”，怎么样？"] = "Планирую сделать классический знак, да-да-да-да! «Ветер, который скучает по тебе, все еще дует в Клуб Таро», как насчет этого?",
    ["我打算把这些葡萄做成酒，只需要把它们放进木桶，再等待发酵……这一定是小镇上最好喝的葡萄酒！"] = "Я планирую превратить этот виноград в вино; Мне просто нужно положить их в бочку и подождать, пока они забродят... Это наверняка будет самое вкусное вино в городе!",
    ["我扮演的是勇者，勇者要每天勤奋练习，收集木棍，成为合格的勇者，才能……"] = "Я действую как герой. Герой должен усердно тренироваться каждый день, собирать деревянные палочки и стать квалифицированным героем, только тогда я смогу...",
    ["我找遍了集市、花园、还有河边……哪里都没有……"] = "Я обыскал рынок, сад и берег реки... их нигде нет...",
    ["我承认……是我动的手，谋害了老爷。"] = "Признаюсь... это сделал я, убивший мастера.",
    ["我拒绝回答这个问题。"] = "Я отказываюсь отвечать на этот вопрос.",
    ["我推荐你在花海里多走走，不一会儿就能遇见呢。"] = "Советую вам больше гулять по морю цветов; возможно, вы скоро столкнетесь с ними.",
    ["我敢说它一定会震撼你！"] = "Смею заверить, это вас потрясёт!",
    ["我明天带照片来诊所！"] = "Завтра принесу фото в клинику!",
    ["我明明在树上刻了箭头……但我怎么还被困在森林迷宫中……"] = "Я явно вырезал на деревьях стрелы... Но почему я до сих пор в ловушке лесного лабиринта...",
    ["我明白了！他们其实是最好的朋友！"] = "Я понимаю! Они на самом деле лучшие друзья!",
    ["我明白，茉莉安……明天，我们去石像旁看看那些勇敢的人们吧。"] = "Я понимаю, Мориан... Завтра пойдем к статуям и посмотрим на этих храбрых людей.",
    ["我昨晚看见队长装好枪就走了出去，据说，开膛手也是昨晚被击毙的……"] = "Вчера вечером я видел, как капитан заряжал свое ружье и отправлялся в путь. Говорят, что Потрошителя тоже застрелили прошлой ночью...",
    ["我是一位四处贸易的行商。我听说不同城堡之间的行情有所差异，正准备来看看这儿的情况。"] = "Я странствующий торговец. Я слышал, что рыночные условия в разных замках различаются, поэтому готовлюсь увидеть ситуацию здесь.",
    ["我是一朵蘑菇。"] = "Я гриб.",
    ["我是个退伍军士，身上老毛病不少，只能回家养病。可偏偏闲不下来，不如给自己安排点事做。"] = "Я сержант в отставке, у меня немало старых недугов, поэтому я могу вернуться домой только для того, чтобы поправиться. Но я не могу оставаться без дела, так что мне стоит заняться чем-нибудь.",
    ["我是公主啊！我的勇者们说好会打败恶龙，拯救我们的国家！结果，结果……"] = "Я принцесса! Мои герои пообещали, что победят «Злой Дракон» и спасут наше королевство! Но, но...",
    ["我是在酒馆听铁匠说的，他说这比向女神祈祷还灵验……哦不，女神啊，我没那个意思！"] = "Я услышал это в таверне от кузнеца: он уверял, что это помогает лучше молитвы Богине... О нет, помилуй Богиня, я вовсе не это имел в виду!",
    ["我是说他的结局吧。"] = "Я имел в виду его финал.",
    ["我曾经也觉得这里有些阴森，有些寒冷。"] = "Раньше мне казалось, что это место немного жуткое и холодное.",
    ["我替他们向你表示感谢。"] = "Выражаю вам благодарность от их имени.",
    ["我最喜欢小阿卡纳的宝剑骑士，"] = "Мой любимый — Рыцарь Меча Младших Арканов.",
    ["我最好的朋友也总这样告诉我。"] = "Мой лучший друг тоже всегда мне это говорил.",
    ["我最近一直被各种各样的噩梦缠绕，有的是面目扭曲的工人，有的是凶恶狂暴的机器……"] = "В последнее время меня преследуют всевозможные кошмары, некоторые из которых — рабочие с искаженными лицами, а некоторые — злобные и жестокие машины…",
    ["我有一个困扰许久的问题，希望借助占卜的力量。但最好要快。我的助手一来就跑走，不知道要出什么事。"] = "У меня есть проблема, которая беспокоит меня уже долгое время, и я надеюсь воспользоваться силой гадания. Но лучше поторопиться. Мой помощник убежал, как только они приехали, я не знаю, что произойдет.",
    ["我有一个大胆的想法。"] = "У меня есть смелая идея.",
    ["我有一段时间没能睡好觉了，一闭眼就是旋律诡异的声音在耳边回荡……"] = "Я уже некоторое время не могу нормально спать. Как только я закрываю глаза, в моих ушах раздаются странные мелодии...",
    ["我有些想家了……朋友和亲人都离我那么遥远，我再难回到故乡，却也无法融入这里。"] = "Я немного тоскую по дому... Мои друзья и семья так далеко. Мне тяжело возвращаться в родной город, но интегрироваться здесь я не могу.",
    ["我有关于我女儿的急事需要占卜！"] = "У меня срочное дело относительно моей дочери, требующее гадания!",
    ["我有时会怀疑，眼前的光景是否只是一场绚烂而易逝的梦？"] = "Иногда я задаюсь вопросом, не является ли сцена перед моими глазами всего лишь блестящим и мимолетным сном?",
    ["我未婚夫让出版社的审核文员加上的。"] = "Мой жених попросил рецензента издательства добавить их.",
    ["我每天卖啤酒，没见过什么戈多。"] = "Пиво продаю каждый день, Годо не видел.",
    ["我每天吃煎蛋，没见过什么戈多。"] = "Я ем яичницу каждый день, никакого Годо не видел.",
    ["我每天唱歌，没见过什么戈多。"] = "Я пою каждый день и знать не знаю никакого Годо.",
    ["我每天都来这里等待，但是已经很久没有看见他了。"] = "Я прихожу сюда каждый день, чтобы дождаться, но давно его не видела.",
    ["我永远怀念那个美妙的午夜——我与香花女士发生的一切。"] = "Я всегда буду скучать по той чудесной полуночи – по всему, что произошло между мной и госпожой Сянхуа.",
    ["我没有进去，真的没有！我完全不知道发生了什么……"] = "Я не заходил, правда! Я понятия не имею, что произошло...",
    ["我没看见，他当时往树林里跑，很快就没影了。"] = "Я не видел. Он бросился в лес и тут же скрылся из виду.",
    ["我没醉……真的没醉……只是晕……你帮我看着它……我的宝贝……"] = "Я не пьян... правда не пьян... просто кружится голова... помоги мне посмотреть... мое сокровище...",
    ["我照顾了他这么多年。他的每一次发烧、每一次心悸、每一次从噩梦里惊醒……我都在。"] = "Я заботился о нем столько лет. Каждый жар, каждое сердцебиение, каждый раз, когда он просыпался от кошмара... Я был там.",
    ["我父亲死了。"] = "Мой отец мертв.",
    ["我猜马丁在外面，要是你看到他，帮我转告一句：如果想要晋升，就要直面恐惧。"] = "Думаю, Мартин снаружи. Если вы увидите его, помогите мне передать сообщение: если вы хотите двигаться вперед, вы должны встретиться лицом к лицу со своим страхом.",
    ["我现在就是……参与了那些人的冒犯……受到了惩罚……"] = "Я теперь... участвую в преступлениях этих людей... и наказан...",
    ["我的丈夫基拉，去教堂后的池塘边摘睡莲了，这是我们镇子上的习俗。"] = "Мой муж Кира пошел к пруду за церковью собирать кувшинки. В нашем городе это обычай.",
    ["我的丈夫霍克斯男爵离奇死亡，我认为这件事情另有内情，所以才请您过来。"] = "Мой муж, барон Хоукс, умер загадочным образом. Я считаю, что в этом вопросе есть нечто большее, поэтому я пригласил вас сюда.",
    ["我的吉他被松鼠啃烂了，没法练习。"] = "Мою гитару съела белка, поэтому я не могу заниматься.",
    ["我的夫人只有你！只会是你！"] = "Моя жена – это только ты! Это всегда будешь только ты!",
    ["我的家在廷根。想回贝克兰德是因为上次去那边参加学术会议的时候……"] = "Мой дом в Тингене. Я хочу вернуться в Бэкланд, потому что в прошлый раз я ездил туда на научную конференцию...",
    ["我的指南针和我的脑袋，就像在跳弗朗明戈一样，旋转不停。"] = "Мой компас и голова кружились, как будто они танцевали фламенко.",
    ["我的父亲和母亲在很遥远的地方，那些无人陪伴的日子里，我开始幻想小骑士和恶龙的故事，讲给镇上的孩子们听……"] = "Мои отец и мать находятся в очень далеком месте. В те дни, проведенные без компании, я начал воображать историю о маленьком рыцаре и злом драконе и рассказал ее городским детям...",
    ["我的画是空白的。我还在等，等风把那片云吹到合适的位置，等一只蝴蝶停在一朵花上。"] = "Моя картина пуста. Я все еще жду, жду, пока ветер перенесет это облако в нужное положение, жду, когда бабочка приземлится на цветок.",
    ["我的确恨那件东西，恨我丈夫看我的眼神越来越像看一个陌生人！"] = "Я ненавижу эту штуку и ненавижу то, что глаза моего мужа все больше и больше выглядят так, будто он смотрит на незнакомца!",
    ["我的药剂研发陷入了瓶颈……"] = "Мои исследования зелий зашли в тупик...",
    ["我看你还不如咸鱼，咸鱼还能吃！你除了能给我增加工作量还能干些什么！"] = "Я думаю, ты хуже соленой рыбы, соленую рыбу еще можно есть! Что еще можно сделать, кроме увеличения моей нагрузки!",
    ["我看到员工手册上写了哀嚎黑市的案件追踪，我可以参与吗？"] = "Я видел отслеживание дел на Стонущем черном рынке в справочнике для сотрудников; могу ли я участвовать?",
    ["我看到您已经收成了一些美酒！真是完美的商品——它们一定能有一个同样完美的成交价。"] = "Я вижу, ты уже собрал немного хорошего вина! Поистине совершенный товар — за него должна быть такая же идеальная цена.",
    ["我看看配料……"] = "Давайте я проверю состав...",
    ["我看见了……那盔甲，古老的、沾满泥的盔甲，自己动了起来，里面是空的，却是活的！"] = "Я видел... эти доспехи, старинные, измазанные грязью доспехи, двигались сами по себе. Внутри было пусто, но они были живыми!",
    ["我真是……蠢透了！"] = "Я правда... такой глупый!",
    ["我真是个胆小鬼，现在她要被人抢走了……"] = "Я такой трус, а теперь ее похитят...",
    ["我真的听见他说话了！那个声音就是从他房间里传出来的！侦探{{先生|女士}}，您相信我啊！"] = "Я действительно слышал, как он говорил! Этот голос доносился из его комнаты! Детектив {{Mr.|Ms.}}, вы должны мне поверить!",
    ["我真的等不下去了！"] = "Я действительно не могу больше ждать!",
    ["我真诚地许下心愿，请睡莲庇佑。"] = "Я искренне загадываю свое желание и прошу кувшинку благословить меня.",
    ["我睡觉的时候，感觉有东西压在我身上，不论我怎么挣扎，都没办法坐起来！"] = "Когда я сплю, мне кажется, будто что-то давит на меня. Сколько бы я ни бился, я не могу даже приподняться!",
    ["我知道他们说的是对的，但“暴怒之民”扮演起来真的很难……"] = "Я знаю, что они правы, но Действовать как «Варвар» действительно трудно...",
    ["我知道你不是警察，但我信得过你。这张通行证可以让你直接进去。"] = "Я знаю, что ты не полицейский, но я тебе доверяю. Этот пропуск позволит вам войти напрямую.",
    ["我知道你在等谁，他不会来的！"] = "Я знаю, кого ты ждешь, он не придет!",
    ["我知道格兰特先生在哪里！我还能够短暂使用历史投影，请您不用客气，尽管好好使用我！"] = "I know where Mr. Grant is! I can also briefly use a historical projection, so please don't be polite—feel free to make good use of me!",
    ["我知道的就这些了，我和管家会在外面等您，以免打扰您的调查。"] = "Это все, что я знаю. Мы с дворецким подождем снаружи, чтобы не мешать вашему расследованию.",
    ["我知道这很难，但是……我们必须快点做出决定。"] = "Я знаю, это тяжело, но... нам нужно быстрее принять решение.",
    ["我知道！艾米的秘密基地在客运站！黛西说古堡里有个好地方，我可不敢跟去，太远了……"] = "Я знаю! Секретная база Эми находится на Пассажирской станции! Дейзи сказала, что в старинном замке есть хорошее место, но я не осмелилась пойти за ним, это слишком далеко...",
    ["我研究的是死的历史，他们……他们和杰克经历的，是活过来的历史。这部分的真相，恐怕永远埋在城堡的地基下了。"] = "Я изучаю мертвую историю, но они... то, что они с Джеком пережили, - это история, которая ожила. Правда об этой части, вероятно, навсегда будет погребена под фундаментом замка.",
    ["我确定……我熟悉老爷的声音，那音色就是他的，我服侍老爷好几年了，不会记错的……"] = "Я уверен... Мне знаком голос Мастера. Тон был его. Я служу Хозяину несколько лет, не запомню этого неправильно...",
    ["我确认过了，你中的那一枪，不是普通的铅弹。"] = "Я подтвердил это; пуля, которую ты взял, не была обычной свинцовой пулей.",
    ["我离开时，他还坐在桌边喝茶。一边喝，一边盯着门口，应该是在等埃文医生，他患有心脏病，那时正好是他的复诊时间。"] = "Когда я ушел, он все еще сидел за столом и пил чай. Выпивая, он смотрел на дверь, вероятно, ожидая доктора Эвана. Он страдал от болезни сердца, и пришло время его повторного визита.",
    ["我答应带他们旅行，想着行程安排，兴奋地多走了两步，不小心离开了。"] = "Я пообещал взять их в путешествие, но, размышляя о маршруте, на радостях прошел лишние пару шагов и случайно ушел.",
    ["我能为你提供三种帮助。"] = "Я могу предложить тебе три вида помощи.",
    ["我能听见！"] = "Я слышу тебя!",
    ["我能感觉到你就在这儿……就在我身边。所以我们哪儿也不去，这店永远是咱们的。"] = "Я чувствую тебя прямо здесь... рядом со мной. Так что мы никуда не денемся, этот магазин всегда будет нашим.",
    ["我能感觉到你的状态。如果你愿意，我可以给你一点帮助。"] = "Я чувствую твое состояние. Если вы готовы, я могу вам немного помочь.",
    ["我被一个疯子戏剧家盯上了！崔佛说会有人来帮我。"] = "На меня напал сумасшедший драматург! Тревор сказал, что кто-нибудь придет мне на помощь.",
    ["我被诅咒了！没法从地上起来，只有真爱之吻才能解除！"] = "Я проклят! Нет возможности подняться с земли, только поцелуй настоящей любви сможет поднять ее!",
    ["我被鲁本枪杀……子弹贯穿心脏。这太具体了，像是已经发生过一样。"] = "В меня стрелял Рубен... пуля пронзила мне сердце. Это слишком конкретно, как будто это уже произошло.",
    ["我要佛尔思的签名……签名！签名！"] = "Я хочу автограф Форса... автограф! Автограф!",
    ["我要写一本军事巨著！论证因蒂斯应该趁鲁恩和弗萨克开战，轻取霍纳奇斯攻入鲁恩！"] = "Я напишу военный шедевр! Утверждая, что Интис должен воспользоваться войной между Лоэном и Фейсаком, чтобы легко захватить Хорнациса и вторгнуться в Лоэн!",
    ["我要朗诵第二段了：冰湖！你像一面白色的镜！干干净净！"] = "Я прочитаю вторую строфу: Ледяное озеро! Ты как белое зеркало! Чистый и чистый!",
    ["我要看佛尔思的新作！我要看佛尔思的新作……我要佛尔思的签名！"] = "Я хочу прочесть новую книгу Форс! Хочу новую книгу Форс... И хочу автограф Форс!",
    ["我觉得数学太理性了。但文字，文字不一样。它记录人的爱恨，生死，一切的故事……"] = "Я считаю, что математика слишком рациональна. Но слова, слова разные. Они записывают любовь и ненависть людей, жизнь и смерть, все истории...",
    ["我让那个骗走我工厂、伤害我家人的混蛋永远沉入了间海……一切，都结束了。"] = "Я заставил этого ублюдка, который обманул мою фабрику и причинил вред моей семье, навсегда погрузиться в Мидсишир... Все кончено.",
    ["我记得“共感手铐”要这样这样才能安全解开……"] = "Я помню, что «Наручники Эмпатии» нужно надевать так и эдак, чтобы их можно было безопасно разблокировать...",
    ["我试过去教堂祈祷，可一闭上眼，就能看见那可怕的战斗。那绝对不是人类之间的战斗……绝对不是！"] = "Я пытался молиться в церкви, но как только закрыл глаза, увидел ту страшную битву. Это определенно не была битва между людьми… определенно нет!",
    ["我调整了药物的剂量，只要剂量出错，他的心脏随时都会停下。也是我，锁住房门，伪造成反锁的密室。"] = "Я скорректировал дозировку лекарства; если дозировка была неправильной, его сердце могло остановиться в любой момент. Это я также запер дверь, создав тайну запертой комнаты.",
    ["我负责环村河流的清理工作，但河里每天都有新的生活垃圾堆积，我每天干到半夜，但河流永远也干净不了。"] = "Я отвечаю за очистку реки вокруг деревни, но каждый день в ней скапливается новый бытовой мусор. Я работаю до полуночи каждый день, а река так и не становится чище.",
    ["我跟这帮畜生耗太久了，早被盯上了。不能在此地久留，等你狙击完事后，我在远处接应。"] = "Я слишком долго боролся с этими животными и уже стал объектом нападения. Я не могу оставаться здесь долго; после того, как ты закончишь стрелять, я прикрою тебя на расстоянии.",
    ["我身上太臭了，一股尸体和苔藓的味道。"] = "От меня ужасно воняет трупами и мхом.",
    ["我还听说，昨晚队长去的路上，遇到了几个黑帮混混，是来接应杀手的呢！"] = "Я также слышал, что вчера вечером по дороге туда капитан встретил нескольких гангстеров, которые были там, чтобы встретиться с убийцей!",
    ["我还得把它还给佛尔思女士。"] = "Мне все еще придется вернуть его мисс Форс.",
    ["我还想再多陪陪戴维。"] = "Я все еще хочу сопровождать Дэвида еще немного.",
    ["我还闻到了佛手柑和……迷迭香？"] = "Еще я почувствовал запах бергамота и... розмарина?",
    ["我这趟旅程的目的，就是为了解开这个谜题。"] = "Цель моего путешествия – разгадать эту тайну.",
    ["我这身家，全靠从古堡里挖的宝贝，一个小雕像就抵得上我爹的磨坊！"] = "Мое богатство полностью зависит от сокровищ, которые я выкапываю из замка; одна маленькая статуэтка стоит мельницы моего отца!",
    ["我这里最不缺的就是故事。让我想想。"] = "Чего мне здесь не хватает, так это историй. Дай мне подумать.",
    ["我马上就要到了！我没有疯！"] = "Я почти у цели! Я не сумасшедший!",
    ["我，我在练，练习，要去，去面试。"] = "Я практикуюсь, тренируюсь, собираюсь пойти на собеседование.",
    ["我，我想先把，把话能顺，顺利地说，说完。"] = "Я, я хочу сначала уметь говорить, говорить гладко.",
    ["我，我杀了他。我是谁？我是阿瑟……他是谁？他是霍普……我杀了谁？谁杀了我？"] = "Я, я убил его. Кто я? Я Артур... Кто он? Он — Надежда... Кого я убил? Кто меня убил?",
    ["我，黑夜信徒，风暴信徒，大地信徒，吟游诗人、小镇画师、旅馆主理人、黄金右脸……在此祈祷。"] = "Я, верующий Ночи, верующий Шторма, верующий Земли, Бард, городской художник, управляющий отелем, Золотая Правая Щека... молюсь здесь.",
    ["或许吧。因为那时候，我也很难控制住自己的手。"] = "Возможно. Потому что тогда мне тоже было трудно контролировать свои руки.",
    ["或许有一天，你会成为除我之外最像他的人。"] = "Возможно, однажды ты станешь человеком, который больше всех похож на него... кроме меня.",
    ["或许缺少开膛手也缺一位雪中送炭的贵人。"] = "Возможно, у Потрошителя тоже не хватает благородного человека, который в снежную погоду принес бы древесный уголь.",
    ["战前礼仪？不懂，但是鼓掌总归是没错的。"] = "Предбоевой этикет? Я не понимаю, но аплодировать никогда не бывает неправильно.",
    ["戴着它，我就得替她守着这里，替她喝那些不想喝的酒……"] = "Носить его означает, что я должен охранять это место ради нее, пить те напитки, которые я не хочу пить ради нее...",
    ["戴维，我忘记了，你是什么时候爱上阿斯兰的……"] = "Дэвид, я забыл, когда ты влюбился в Аслана...",
    ["所以……你是在卖假古董骗人？"] = "Итак... вы продаете поддельный антиквариат мошенникам?",
    ["所以……这个教派到底崇拜什么？满月还是日出？"] = "Итак... чему поклоняется этот культ? Полнолуние или восход солнца?",
    ["所以佛尔思女士托我交给您这个。"] = "Итак, мисс Форс доверила мне передать вам это.",
    ["所以只有一个法子——砰！远程，一枪毙命。不给他们反应的空档。"] = "Так что выход только один — Бац! Дальний бой, один выстрел на поражение. Не давайте им возможности отреагировать.",
    ["所以它喷火是在照明？乌云是它难过的样子？"] = "Значит, он дышал огнем, чтобы обеспечить свет? А темные тучи были грустными?",
    ["所以我去了厨房，让仆人准备好下午茶点心。大概<P_Yellow>三点二十分</>，我想问问老爷是否还记得复诊预约，但怎么敲门都没人应。"] = "Поэтому я пошел на кухню и попросил слуг приготовить закуски к послеобеденному чаю. Примерно в <P_Yellow> 15:20 </> я хотел спросить, помнит ли мастер о своем следующем приеме, но как я ни стучал, ответа не последовало.",
    ["所以由什么组成？"] = "Так из чего же он состоит?",
    ["所有人？"] = "Каждый?",
    ["手持宝剑、跨坐白马，"] = "Держа меч и сидя на белом коне,",
    ["手指伸进环孔，手腕会浮现循环符号，并被读取当前记忆中印象最深的情景，灵魂陷入这一段情景的无限循环中。触碰受害者手腕符号的人，会以旁观者身份进入循环空间。"] = "Когда палец вставляется в кольцо, на запястье появляется символ цикла и читается самая глубокая сцена в текущем воспоминании, захватывая душу в бесконечный цикл этой сцены. Те, кто прикасается к символу на запястье жертвы, входят в пространство петли в качестве свидетелей.",
    ["才不是，他们肯定把我给忘了！我要回家告状！"] = "Это не так, они, наверное, забыли обо мне! Я пойду домой жаловаться!",
    ["才能什么？"] = "Только тогда ты сможешь что?",
    ["打不过，但……"] = "Мне с ними не сладить, но...",
    ["打开「市场」界面，您可找到高价物产并大量生产。拥有足够物产后，即可拜访他人城堡并出售。"] = "Откройте интерфейс «Рынок», где вы сможете найти дорогостоящие товары и производить их в больших количествах. Как только у вас будет достаточно товаров, вы сможете посещать замки других людей и продавать их.",
    ["打扫，整理一下……其实学派里需要学员们干的工作很少啦，很多时候都是我自己找点活干。"] = "Уборка, уборка... на самом деле в школе у ​​учеников очень мало работы. Большую часть времени я просто нахожу работу для себя.",
    ["打扰一下，请问你了解乔的“那些”药剂都有什么效果？"] = "Извините, могу я спросить, какой эффект имеют «эти» зелья Джо?",
    ["打扰了，为什么在灵界观测房休息呢？"] = "Простите, почему вы отдыхаете в наблюдательной комнате Мира Духов?",
    ["打扰了，请问你们知道茶会的主人在哪吗？"] = "Простите, вы не знаете, где ведущий чаепития?",
    ["打探到那名超凡者的能力了吗？"] = "Вы узнали о способностях этого Потустороннего?",
    ["托马斯爱说笑话，埃莉诺就在柜台后面笑，手里的杯子都端不稳……啧啧，那个时候，多好啊。"] = "Томас любил рассказывать анекдоты, Элеонора смеялась за стойкой, не в силах даже твердо держать чашку... Тск-цк, это были хорошие времена.",
    ["托马斯爷爷……他、他快撑不住了！但是，但是艾玛也……"] = "Grandpa Thomas... he, he can't hold on much longer! But, but Emma is also...",
    ["找到之后，务必小心。那里……让人忘记自己是谁。"] = "Как только найдете его, будьте осторожны. Это место... заставляет людей забывать, кто они.",
    ["把我们的东西偷走，埋在野外！"] = "Крадут наши вещи и закапывают их на природе!",
    ["抑或是拥抱自己，享受一段静谧的时光。"] = "Или, возможно, обнимите себя и насладитесь моментом тишины.",
    ["抱、抱歉……我，我只是太紧张、太难过了。"] = "П-извини... Я, я слишком нервничаю, слишком грустно.",
    ["抱歉非凡者，您暂无可领取的福利"] = "Простите, Потусторонний, в данный момент для вас нет доступных наград.",
    ["抱歉，今天没有。"] = "Извините, не сегодня.",
    ["抱歉，先生，我只是有些感兴趣您在看些什么。"] = "Извините, сэр, меня просто немного заинтересовало то, на что вы смотрели.",
    ["抱歉，没有印象。"] = "Извините, у меня нет о нем никакого впечатления.",
    ["拉姆德小镇最好的纪念品！{{先生|女士}}，这里是给您的家人和朋友挑礼物的不二之选！"] = "Лучшие сувениры в Ламуд Тауне! {{ Mr. | Ms. }}, это лучший выбор для выбора подарков родным и близким!",
    ["招人干什么？让他加钱！"] = "Зачем нанимать кого-либо? Заставьте его платить больше!",
    ["拿回去。"] = "Возьми это обратно.",
    ["拿回去，我不要你的钱。"] = "Возьми это обратно, мне не нужны твои деньги.",
    ["据说为了这次演讲，议院治安队甚至派出了一名超凡能力者，我需要你先去大闹一番，打探清楚这名超凡者的能力。"] = "Говорят, что для этой речи служба безопасности городского совета даже направила Потустороннего. Мне нужно, чтобы ты сначала пошел и устроил сцену, чтобы узнать способности этого Потустороннего.",
    ["据说他还有个变态的爱好，每次行凶后都会给人的肠子带走。"] = "Говорят, что у него есть и извращенное хобби: каждый раз, когда он совершает преступление, он отбирает у людей кишки.",
    ["据说有人违反规定，偷偷下去过，再也没上来。"] = "Говорят, кто-то нарушил запрет, тайком спустился туда и больше никогда не вернулся.",
    ["据说鲁恩国国王心有百姓，"] = "Говорят, что король Лоэна держит людей в своем сердце,",
    ["据说，只有<P_Yellow>被邀请之人</>才能看见入口。但我不知道具体是哪扇门，得靠你自己找。"] = "Говорят, лишь <P_Yellow>приглашенные</> способны увидеть вход. Но какая именно это дверь, мне неведомо — придется искать самому.",
    ["接下来有很长的路要走，如果你需要时间，我们可以再做些准备。"] = "There is a long road ahead; if you need time, we can make some more preparations.",
    ["接下来，您就可以在这里进行各种酒类的产出了。黑麦啤酒是廷根人民餐桌上常见的饮料，我们不妨从这里开始试试。"] = "Теперь вы можете наладить здесь производство различных видов выпивки. Ржаное пиво — привычный напиток на столах жителей Тингена, с него нам и стоит начать.",
    ["接取【叹息之种】任务，将收集到的猩红遗物提交给我，你将获得对等的奖赏。"] = "Примите квест [Семя вздохов], отдайте мне собранные вами алые реликвии, и вы получите соразмерную награду.",
    ["推进这个精彩绝伦的凶杀计划吧。"] = "Продвиньте вперед этот великолепный план убийства.",
    ["掷骰子到20点！大成功！"] = "Бросьте кубик до 20! Критический успех!",
    ["摩根先生，在制作怀表吗？"] = "Мистер Морган, вы делаете карманные часы?",
    ["操，小看那帮狗了。议院治安队的手伸得跟章鱼似的。"] = "Блин, я недооценил этих собак. У службы безопасности Совета щупальца повсюду.",
    ["收下这把手枪，“体验”一下还是个小小非凡者时的祂，呵呵……"] = "Возьмите этот пистолет и «испытайте» Его, когда Он был еще крошечным Потусторонним, хе-хе...",
    ["攻击+80%，星云咏叹附加<P_Heart>冰冻</>标记"] = "Атака +80%, Небула Ария добавляет метку <P_Heart>Freeze</>.",
    ["攻击-300%，技能附加一层<P_Yellow>灼烧</>（灼烧根据学徒最大生命值造成伤害）"] = "Атака -300%, навыки добавляют один уровень <P_Yellow>Burn</> (Ожог наносит урон в зависимости от максимального здоровья Ученика)",
    ["攻击提高10%"] = "Атака повышена на 10%",
    ["攻击提高35%"] = "Атака увеличена на 35%",
    ["攻击提高80%"] = "Атака повышена на 80%",
    ["攻击提高固定值20000"] = "Атака увеличена на фиксированное значение 20000.",
    ["攻击提高固定值2500"] = "Атака увеличена на фиксированное значение 2500.",
    ["攻击提高固定值8000"] = "Атака увеличена на фиксированное значение 8000.",
    ["放和喝能一样吗！你真是害死喵了！还没多少零食吃！"] = "Спускать кровь – то же самое, что пить ее! Ты действительно убил меня, мяу! И закусок не так много!",
    ["故事？没什么故事。工作需要的东西而已。"] = "История? Никакой истории. Просто то, что нужно для работы.",
    ["教会遗失了一件封印物，据调查它可能流入了黑市。"] = "Церковь потеряла запечатанный артефакт, и расследование предполагает, что он мог попасть на черный рынок.",
    ["文化人的事情，怎么能叫“偷”呢？我只是“拿”而已。"] = "Как можно называть воровством то, что делает культурный человек? Я просто «брал» их.",
    ["文献室向学派的每位成员开放。整个文献室一共分两层，一楼存放了各种文艺社科书籍，二楼则收藏了非凡能力相关的书籍。"] = "Литературный кабинет открыт для всех учащихся школы. Он разделен на два этажа: на первом этаже размещена различная литература и книги по общественным наукам, а на втором этаже — книги, связанные со способностями Потустороннего.",
    ["文献室欢迎每个向往知识的人。"] = "Библиотека приветствует всех, кто жаждет знаний.",
    ["斐谢尔是谁？"] = "Кто такой Фешер?",
    ["斯普拉特！我怎么没想到，简直太棒了！我又有了新的思路！"] = "Спратт! Почему я об этом не подумал? Это великолепно! У меня есть новая идея!",
    ["斯普林那家伙脾气古怪，但他对我朋友好歹算是爱护，就由他去吧。"] = "Спринг немного эксцентричен, но он, по крайней мере, заботится о моем друге, так что пусть будет так.",
    ["新婚快乐，但你看起来不太高兴？"] = "Счастливой свадьбы, но выглядишь не очень счастливым?",
    ["新来的？"] = "Впервые здесь?",
    ["新来的？那你真是来巧了。"] = "Впервые здесь? Вы пришли в идеальное время.",
    ["新的猎手，你已踏入猎龙之城。"] = "Новый охотник, ты ступил в Город Охоты на Драконов.",
    ["旅人，此处风雪封存之物，非蛮力所能取——若欲开启，需先通过骑士的试炼。"] = "Путешественник, то, что запечатано здесь ветром и снегом, невозможно взять грубой силой — если ты хочешь открыть это, ты должен сначала пройти испытание Рыцаря.",
    ["旅行指南展开后变成了一扇大门。"] = "Путеводитель разворачивается и превращается в дверь.",
    ["无人管理的建筑还是太危险了。"] = "Неуправляемое здание по-прежнему слишком опасно.",
    ["无论何时，若你需要帮助，我都在这里。女神会眷顾每一份真挚的约定。"] = "Неважно когда, если вам понадобится помощь, я здесь. Богиня будет благосклонно относиться к каждому искреннему обещанию.",
    ["无论你有没有名字，我想我都会记住你的，可爱的毛毛草。"] = "Есть у тебя имя или нет, думаю, я запомню тебя, милая пушистая травка.",
    ["日安，我是胖哈利，一个普通的商人。"] = "Добрый день, я Толстый Гарри, обычный бизнесмен.",
    ["早知道你想问这个，我就不……唉……"] = "Если бы я знал, что ты хочешь это спросить, я бы не... вздох...",
    ["时间紧迫，快拿着它！想象它像伞一样被撑开……"] = "Time is tight, take this quickly! Imagine it opening up like an umbrella...",
    ["明天……明天会来信的。"] = "Завтра... завтра будет письмо.",
    ["明天就是我的婚礼了，艾米莉亚，我美丽的女巫肯定又要生气——"] = "Завтра день моей свадьбы, Эмилия, моя прекрасная ведьма наверняка снова рассердится…",
    ["明明是你哭着喊着叫妈妈！"] = "Это явно ты плакала и звала маму!",
    ["明智，看来这案子已经超出你的范围了。"] = "Разумно, похоже, это дело уже выходит за рамки твоих возможностей.",
    ["星云咏叹附加<P_Red>流血</>"] = "Ария Небулы дополнительно<P_Red>Кровотечение</>",
    ["昨天刚扔了玫瑰花进来，今天没有花，明天再给你带！"] = "Я только вчера бросил розу; сегодня нет цветов, завтра принесу тебе!",
    ["昨天在山上看到的人，一定是幻觉吧？"] = "Человек, которого я видел вчера на горе, должно быть, был галлюцинацией, верно?",
    ["昨天我去踩了点，枪架好了，改装货，带瞄准镜。"] = "Вчера разведал локацию, винтовка настроена, модифицированная деталь с прицелом.",
    ["昨天捞到了一捧玫瑰花，今天能捞出什么呢？"] = "Вчера я выловил букет роз; что я могу выловить сегодня?",
    ["昨天被雷劈了三个，然后社会性死亡了一二三四……数不过来了。"] = "Вчера три человека ударила молния, а потом наступила социальная смерть для одного, двух, троих, четырех... Я потерял счет.",
    ["昨晚好几道聚光灯“唰”地打过来，把晚上照得跟白天一样。紧接着，我听到“砰”的一声巨大枪响！"] = "Вчера вечером вспыхнуло несколько прожекторов, освещая ночь, как день. Сразу после этого я услышал громкий выстрел!",
    ["昨晚我睡到半夜，被窗外亮得刺眼的光照醒，还以为天亮了……"] = "Прошлой ночью я спал посреди ночи, когда меня разбудил слепящий свет за окном. Я думал, что уже рассвет...",
    ["是……是……抱歉先生……我们会抓紧时间……"] = "Да... Да... Извините, сэр... Мы поторопимся...",
    ["是、是、老爷。要不…要不咱们回马车上等夫人？"] = "Д-да, сэр. Как насчет... как насчет того, чтобы вернуться в карету и дождаться даму?",
    ["是、是吗……我会考虑的！谢谢您的建议，也愿女神庇佑您！"] = "Это так... Я подумаю! Спасибо за совет, и пусть Богиня хранит и вас!",
    ["是一个小孩……原来只是被窗口挡住了。"] = "Это ребенок... так что его просто заблокировали окном.",
    ["是个喜欢给人开膛破肚的变态。"] = "Извращенец, который любит потрошить людей.",
    ["是乌云！你根本没好好听故事！"] = "Это были темные облака! Вы вообще не внимательно слушали историю!",
    ["是你喜欢的姑娘吗？"] = "Она девушка, которая тебе нравится?",
    ["是吗，我还以为是副队长呢！他还发过誓，要亲手击毙那个残忍的杀手。"] = "Это так? Я думал, это вице-капитан! Он даже поклялся, что лично застрелит этого жестокого убийцу.",
    ["是否要开启鲁恩风尚打卡？"] = "Хотите начать следить за модой Лоэн?",
    ["是否选择失去生命值50%，获得一个金色密卷。"] = "Вы решили потерять 50% своего здоровья, чтобы получить Золотой Свиток?",
    ["是啊。我以为手刃仇人之后会痛快，但现在只觉得心里很空，好像留在这世界最后的理由也没有了。"] = "Ага. Я думал, что почувствую облегчение после убийства врага, но теперь я чувствую себя пустым внутри, как будто исчезла последняя причина оставаться в этом мире.",
    ["是啊。男人、女人、老人、小孩……"] = "Да. Мужчины, женщины, старики, дети...",
    ["是啊是啊，真讨厌，我要一个人孤立他们两个！"] = "Да-да, как же бесят! Я одна объявлю им двоим бойкот!",
    ["是啊！可我的上司，这位卢比先生完全没有为我请个帮手的意思。"] = "Да уж! Но мой начальник, мистер Руби, вовсе не собирается нанимать мне помощника.",
    ["是啊，为什么……为什么我会这么做?"] = "Да, почему... почему я это сделал?",
    ["是啊，多亏了教会的牺牲，才能控制住它的负面效果。"] = "Да, именно благодаря жертве Церкви ее негативные последствия удалось контролировать.",
    ["是啊，这里可不安全，快回家去吧。"] = "Да, здесь небезопасно, иди скорее домой.",
    ["是因为太紧张才来这里练习？"] = "Ты пришел тренироваться, потому что слишком нервничаешь?",
    ["是很危险，我们冒着危险来，就是为了毕业……呃，冒险……"] = "Это опасно, но мы рисковали, приехав сюда только на выпускной... эээ, приключение...",
    ["是想家了吗？"] = "Тоскуешь по дому?",
    ["是我家有几百年历史的宅子，那地方太破了，我打算卖点钱补贴家用。"] = "Это дом моей семьи с сотнями лет истории. Это место слишком ветхое, я планирую продать его за какие-то деньги, чтобы прокормить семью.",
    ["是我杀了他，我杀了他！我杀了父亲！"] = "Это я его убил, я его убил! Я убил отца!",
    ["是我过于冒昧，但是我想问，是否十镑会有十镑的注视，五镑会有五镑的……"] = "Это слишком самонадеянно с моей стороны, но я хотел бы спросить: десять фунтов принесут десять фунтов взгляда, а пять фунтов принесут пять фунтов...",
    ["是格兰特先生！他、他怎么……"] = "It's Mr. Grant! How, how did he...",
    ["是的……他每周都会在夜晚帮我备好食物和鲜花，但却从来不见我，不说一句话。"] = "Да... Каждую неделю по ночам он готовит для меня еду и цветы, но никогда меня не видит и не говорит ни слова.",
    ["是的……有什么问题吗？斐乐……斐乐将我从悲伤中拯救出来，我很感激他……"] = "Да... есть ли проблема? Фела... Фела спас меня от грусти, и я ему очень благодарна...",
    ["是的。你是……"] = "Да. Ты...",
    ["是的！我们马上就要在女神的注视下步入婚姻了！"] = "Да! Мы собираемся вступить в брак под пристальным взглядом Богини!",
    ["是的，佛尔思女士预见了此处的污染有扩散风险，委托我在这里监视。"] = "Да, госпожа Форс предвидела, что Искажение здесь имеет риск распространения, и поручила мне следить за ней здесь.",
    ["是的，几年前的一段时间，古堡变得很奇怪，去过的人都觉得隐隐约约不对劲。就在那段时间，一群穿黑色风衣的人来到这里，径直往古堡里去了。"] = "Да, несколько лет назад на какое-то время замок стал очень странным, и каждый, кто туда заходил, чувствовал, что что-то не так. В это время сюда пришла группа людей в черных плащах и направилась прямо в замок.",
    ["是的，如果你有空的话，可以找他一起玩。"] = "Да, если вы свободны, вы можете найти его и поиграть вместе.",
    ["是的，我得找到一朵适合我妻子的睡莲，才能娶她回家呢。"] = "Да, мне нужно найти кувшинку, подходящую для моей жены, прежде чем я смогу жениться на ней и привезти ее домой.",
    ["是的，我找一位商人买了些兔子和小鸟，但他的供应链出了问题。"] = "Да, я купил кроликов и птиц у торговца, но в его цепочке поставок возникли проблемы.",
    ["是的，我是往昔之书，这座图书馆被邪神污染，我已经被困很久了。"] = "Yes, I am the Book of the Past. This Library has been corrupted by an Evil God, and I have been trapped here for a long time.",
    ["是科考队要的食物和仪器。别问了，这不是我们该知道的。"] = "Это продукты и инструменты для команды научной экспедиции. Не спрашивай; это не то, что нам следует знать.",
    ["是罗塞尔！是伟大的罗塞尔大帝！你知道吗？罗塞尔发明了蒸汽机，是他带领世界前进……"] = "Это Рассел! Это великий император Рассел! Вы знали? Рассел изобрел паровой двигатель и повёл мир вперёд...",
    ["是这样吗？可是……哥哥，我觉得妈妈好难过。"] = "Это так? Но... Брат, я думаю, что Мать очень грустит.",
    ["是霍纳奇斯！你们知道吗，最最有趣的是，遗迹内没有发现这个国家的墓葬！这是为什么呢？"] = "Это Хорнасис! Знаете, что самое интересное? Никаких захоронений из этой страны в руинах обнаружено не было! Почему это?",
    ["显然某台聚光灯过于晃眼了。"] = "Видимо, определенный прожектор был слишком ослепляющим.",
    ["晚上好，我是“特殊案件咨询办公室”的顾问，这里的情况可能需要“特别视角”的评估。"] = "Добрый вечер, я консультант в Отделе консультирования особых случаев, где для оценки ситуаций может потребоваться «особый взгляд».",
    ["普普通通的心情或许是生活少了些趣味，去湖边的小船上坐坐吧！船上的风和飘落的花瓣一定会让你惊喜的。"] = "Возможно, ваше обычное настроение связано с тем, что в жизни мало веселья; посиди на маленькой лодке на берегу озера! Ветер на лодке и падающие лепестки наверняка вас удивят.",
    ["暂无"] = "Никто",
    ["更妙的是，哪怕被冲进下水道，它也会伴着水流一路高歌，带给所有享用它的人极致的歌唱体验。"] = "Еще лучше то, что даже если его смыть в канализацию, он продолжит петь вместе с водой, даря незабываемые впечатления от пения каждому, кто его потребляет.",
    ["更离谱的是，有人说，连续三次投中，就能够回家……"] = "Еще более возмутительно то, что некоторые говорят, что если поразить цель три раза подряд, то можно идти домой...",
    ["曾在这里生存的家伙留下了大量壁画，从壁画上看，他们的外形几乎与我们一模一样，可以当作人类看待！"] = "Ребята, жившие здесь, оставили после себя большое количество фресок. Судя по фрескам, их внешний вид был почти идентичен нашему; их можно считать людьми!",
    ["曾经我也是个逃避训练的战士，直到……"] = "Раньше я был Воином, который избегал тренировок, пока...",
    ["曾经的我服务于永恒烈阳教会，那时人还年轻，误以为太阳的荣光能照亮一切黑暗。"] = "Когда-то я служил Церкви Вечного Пылающего Солнца; Я был тогда молод и ошибочно полагал, что слава солнца может осветить всю тьму.",
    ["最后……"] = "В конце концов...",
    ["最后一章被撕掉了，据说是为了防止学生尝试召唤“友善的灵界朋友”。"] = "Последняя глава была вырвана якобы для того, чтобы студенты не пытались призвать «дружественных друзей из Мира Духов».",
    ["最后，记住，一定要让该死的金狼脑袋开花！"] = "И напоследок помни: обязательно размозжи голову этому чертову Золотому Волку!",
    ["最近……她应该都在灵界观测房，外面对她而言太吵了。"] = "Недавно... она должна была быть в комнате наблюдения Мира Духов; снаружи для нее слишком шумно.",
    ["最近塔罗牌很流行呢。"] = "Карты Таро в последнее время очень популярны.",
    ["最近小镇发生了什么新鲜事吗？"] = "Случилось ли что-нибудь новое в маленьком городке за последнее время?",
    ["最近镇上那些年轻人，还有外乡来的探险队，像发疯似的往古堡跑。"] = "В последнее время городская молодежь и экспедиционные команды из других городов спешили к замку как сумасшедшие.",
    ["最近魔药房里来了个小东西，挺能折腾的……不过它看待药剂的角度，还是有趣的。"] = "Недавно в Комнате Зелий появилось кое-что, весьма неприятное... но его взгляд на зелья по-прежнему интересен.",
    ["最重要的是，等一个愿意停下来看画的人。"] = "Самое главное – дождаться того, кто захочет остановиться и посмотреть на картину.",
    ["有。他自从购买一件古董后，就越来越不正常了，不和人交流，一直待在卧室。"] = "Да. С тех пор, как он купил антиквариат, он становился все более ненормальным, не общался с людьми и все время оставался в спальне.",
    ["有一个问题困扰我很久了……"] = "Один вопрос не дает мне покоя уже давно...",
    ["有一次，猎场马匹受惊失控，还是约翰冲上去救了霍克斯！霍克斯没有受伤，约翰却被撞断了几根肋骨，卧床很久才恢复……"] = "Однажды лошади на охоте испугались и вышли из-под контроля, и именно Джон бросился спасать Хоукса! Хоукс не пострадал, но Джон сломал несколько ребер и долгое время был прикован к постели, прежде чем прийти в себя...",
    ["有个少女，看起来像被什么怪物追着，也没看路，就直接冲向了主干道。"] = "Там была молодая девушка, которая выглядела так, будто ее преследовал какой-то монстр. Она даже не посмотрела, куда идет, и бросилась прямо на главную дорогу.",
    ["有事？"] = "Что-то случилось?",
    ["有些负面效果非常严重的神奇物品，学派会将其封印起来，防止它们造成灾难性的后果。"] = "Некоторые мистические предметы с очень серьезными негативными последствиями школа запечатывает, чтобы они не вызвали катастрофических последствий.",
    ["有人混淆了死亡时间，引发公爵的精神异常，扭曲了医生的意志，让忠诚的管家成为本案的凶手，故意让每个人都变得可疑。"] = "Кто-то перепутал время смерти, спровоцировал психическое отклонение барона, исказил завещание доктора, сделал в данном случае убийцей верного дворецкого и намеренно вызвал у всех подозрения.",
    ["有什么事吗？"] = "Есть ли что-то, что вам нужно?",
    ["有什么事？没事的话别来打扰我，成为合格学员的第一步是学着自己使用熔炉。"] = "Что стряслось? Если ничего важного, не отвлекай меня: первый шаг к тому, чтобы стать толковым учеником, — научиться самому управляться с горном.",
    ["有什么发现吗？"] = "Есть открытия?",
    ["有什么能够帮助您？"] = "Могу ли я чем-нибудь вам помочь?",
    ["有从南大陆来的符咒石，据说能带来好运。"] = "Есть камни-обереги с Южного континента, которые, как говорят, приносят удачу.",
    ["有任何疑问，我都乐意替您解答。"] = "Я рад ответить на любые ваши вопросы.",
    ["有多古老？"] = "Сколько лет?",
    ["有太多刚学会几种占卜方法就宣称要窥视真相、改变命运的人。"] = "Слишком много людей утверждают, что могут докопаться до истины и изменить судьбу, всего лишь освоив несколько методов гадания.",
    ["有太多非凡者因为缺乏扮演的机会而消化缓慢，更有甚者陷入混乱，我们成立“魔钥学会”就是为了解决这一问题。"] = "Слишком много Потусторонних, у которых пищеварение замедлено из-за отсутствия возможностей действовать, и что еще хуже, некоторые впадают в хаос. Чтобы решить эту проблему, мы создали «Общество ключей к зельям».",
    ["有家人的地方也是家，就是有亲人、朋友在的地方。"] = "Место с семьей – это тоже дом, а значит место, где находятся родственники и друзья.",
    ["有家的感觉真好……可以每天安安稳稳睡大觉。"] = "Как же хорошо, когда есть дом... можно каждый день спокойно высыпаться.",
    ["有小偷？我们这有什么值得小偷光顾的吗？"] = "Там вор? Есть ли что-нибудь из нашего, что стоит украсть?",
    ["有意思，你刚才是想绕过我吗？可惜，你已经被我“记住”了。"] = "Интересно, ты только что пытался обойти меня? Как жаль, я вас уже «запомнил».",
    ["有所付出，就有所得到。 "] = "Что отдашь, то и вернётся. ",
    ["有时他会注视着欢笑的人群面露恍惚，发出一声悠长的喟叹……"] = "Иногда он ошеломленно смотрел на смеющуюся толпу, глубоко вздыхая...",
    ["有时候我真想扔了它，假装自己只是个普通女人，找个能陪我喝到倒下的人……"] = "Иногда мне очень хочется выбросить его, притвориться, что я обычная женщина, и найти того, кто сможет пить со мной, пока мы оба не упадём в обморок...",
    ["有汉克斯先生捎来的信件吗？"] = "Есть ли письма от мистера Хэнкса?",
    ["有没有什么草药能体现让人沉静下来？"] = "Есть ли какие-нибудь травы, которые могут успокоить человека?",
    ["有的说家族触犯了隐秘的禁忌，有的说他们消失于一夜之间。我能确定的是，自他们之后，古堡便失去了长久的主人，在时光中逐渐变成你现在看到的、被神秘和恐惧环绕的样子。"] = "Одни говорят, что семья нарушила тайное табу, другие — что они исчезли за одну ночь. В чём я точно уверен, так это в том, что после них старый замок лишился постоянных хозяев и с течением времени превратился в то, что вы видите сейчас — место, окутанное тайнами и ужасом.",
    ["有西群岛的海螺，放在耳边能听到风的声音。"] = "Есть раковины с Западного архипелага; если приложить их к уху, можно услышать шум ветра.",
    ["有这好事？"] = "Есть ли такая хорошая вещь?",
    ["有，我自己。"] = "Да, я сам.",
    ["朋友，仰望星空派和海洋之甜风，你更推荐哪个？"] = "Друг, что ты порекомендуешь больше между пирогом «Звездочет» и «сладким бризом океана»?",
    ["朋友，超凡物种逐渐在这个世界中消亡，是时候团结起来，保护这些濒危的生物了。"] = "Друг, в этом мире постепенно вымирают необыкновенные виды; пришло время объединиться и защитить этих находящихся под угрозой исчезновения существ.",
    ["期待与你的下次相遇。"] = "С нетерпением жду нашей следующей встречи.",
    ["期待你的改进建议，年轻人，这也是为人类的未来做出贡献！"] = "С нетерпением жду ваших предложений по улучшению, молодой человек. Это тоже вклад в будущее человечества!",
    ["木乃伊粉末？"] = "Мумий порошок?",
    ["木桩怎么变得这么矮了？几乎和坐地上一样。"] = "Почему деревянный кол стал таким коротким? Это почти как сидеть на земле.",
    ["木马骑士在这里与恶龙大战了七天七夜。他的枪尖折断了，他的眼睛看不见了，他在恶龙喷出的黑雾里迷失了方向。"] = "Рыцарь Деревянного Коня сражался здесь с драконом семь дней и семь ночей. Наконечник его копья сломался, глаза ослепли, и он заблудился в черном тумане, извергаемом драконом.",
    ["未婚夫送的戒指不小心掉进去了，我想拿鱼钩弄上来……女神啊他知道的话肯定会很生气！"] = "Кольцо, которое подарил мне мой жених, случайно упало, и я хотела вернуть его рыболовным крючком... О Богиня, если он узнает, он обязательно очень рассердится!",
    ["本地的猎人而已，请离开吧，这里实在没什么好看的。"] = "Просто местный охотник, пожалуйста, уходите; здесь действительно нечего смотреть.",
    ["本杰明哥哥……我害怕……我想回家……"] = "Брат Вениамин... Мне страшно... Я хочу домой...",
    ["本杰明！你……你刚才去哪了？外面……到处都是枪声，还有火。托马斯爷爷的房子也着火了！"] = "Бенджамин! Ты... куда ты только что был? Снаружи... повсюду была стрельба и огонь. Дом старого Томаса тоже горит!",
    ["本杰明！谢天谢地！"] = "Бенджамин! Слава богу!",
    ["本杰明，你的护盾，能同时罩住两边吗？"] = "Бенджамин, может ли твой Щит прикрывать обе стороны одновременно?",
    ["本杰明，孩子们……幸好你们都还活着。"] = "Бенджамин, дети... слава богу, вы все еще живы.",
    ["本盛典与联赛同轨，每季四轮八周。每轮的第一周会进行一场比赛，每轮的第二周则会进行两场比赛，每场比赛都会提前两天开启搭配，并在比赛开始前给会长与外交官调整出战顺序的机会。"] = "This grand ceremony runs concurrently with the league, consisting of four rounds over eight weeks per season. The first week of each round features one match, while the second week features two matches. Matching for each match opens two days in advance, giving the Club President and Diplomat an opportunity to adjust the battle order before the match begins.",
    ["本身相当沉重，外形如同巨锤，表面幽蓝深邃，缠绕着银白的电光，握柄疑似生灵的腿骨。"] = "Он довольно тяжелый, по форме напоминает гигантский молот, с темно-синей поверхностью, увитой серебристо-белыми молниями, а рукоятка, предположительно, представляет собой кость ноги живого существа.",
    ["来不及了！不要打扰我学习！"] = "Нет времени! Не мешайте мне учиться!",
    ["来吧，让我们继续！"] = "Давай, продолжим!",
    ["来都来了，今天体验一下二人世界？不告诉肯和萨拉他们。"] = "Раз уж пришли, может, побудем сегодня вдвоём? Только Кену и Саре ни слова.",
    ["杰克是谁？"] = "Кто такой Джек?",
    ["杰克那小子最喜欢吃腌鱼了。他在廷根的工厂当学徒，肯定连口荤腥都沾不上……"] = "Этот ребенок Джек больше всего любит маринованную рыбу. Работая подмастерьем на фабрике Тингена, он наверняка даже не может почувствовать вкус мяса...",
    ["杰瑞米不是我弟弟了……呜呜……"] = "Джереми больше не мой брат... у-у-у...",
    ["杰瑞米肯定是被怨灵附体了，我在故事书上看过的！"] = "Джереми, должно быть, был одержим мстительным духом; Я читал об этом в сборниках рассказов!",
    ["杰里米先生在喝闷酒，看起来喝醉了，但是眼神却很清明啊……他的视线，一直在偷偷看向帕尼斯女士……"] = "Мистер Джереми пьет свою печаль, выглядит пьяным, но глаза его очень ясные... Его взгляд тайно смотрел на мисс Парнис...",
    ["某日雨雪大寒，国王令人给孤寡穷患大批赠与木炭。"] = "Однажды, когда шел снег и было холодно, король приказал раздать большое количество древесного угля сиротам и беднякам.",
    ["柜台、保险箱、别人的口袋……谁知道它今天又准备在哪。"] = "Счетчики, сейфы, чужие карманы... кто знает, где бы это было сегодня.",
    ["查理那个家伙肯定躲在教堂的草丛，黛西好像往古堡的方向跑了。拜托你啦！"] = "Чарли, должно быть, прячется в церковных кустах, а Дейзи, похоже, побежала к замку. Я рассчитываю на тебя!",
    ["根据幻象投影存活排名、击杀数、存活时间计算积分。排名前列的玩家可获得「乱斗 冠军」等称号，而数据突出的棋子还有「罗氏速递」「二五仔之光」等称号奖励。"] = "Очки рассчитываются на основе рейтинга выживаемости, количества убийств и времени выживания фантомных проекций. Игроки с самым высоким рейтингом могут получить такие титулы, как «Чемпион потасовки», а пешки с выдающимися данными также могут получить титульные награды, такие как «Экспресс Ро» или «Свет предателя».",
    ["根据我能找到的最早的、混杂在教会档案里的世俗记录——咳咳，不要问我为什么要查阅这样人人都知道的资料——严谨！这是研究员最重要的素养！"] = "Согласно самым ранним светским записям, которые я смог найти, смешанным с церковными архивами — хм, не спрашивайте меня, зачем мне искать такие общеизвестные сведения — строгость! Это самое важное качество для исследователя!",
    ["根本没人见过这家店的老板，没人知道她或者他是什么时候加的酒！"] = "Хозяина этого заведения никто в глаза не видел, и никто не знает, когда она или он подливает выпивку!",
    ["格兰特先生并非坠楼而死，他是被人杀害的。"] = "Mr. Grant did not die from falling; he was murdered.",
    ["格兰特先生用仪式魔法沟通邪神，将我召唤了出来，但他没有足够的力量驾驭我……"] = "Mr. Grant used Ritual Magic to communicate with an Evil God and Summoned me, but he did not have enough power to control me...",
    ["案件发生前你在干什么？"] = "Чем вы занимались до происшествия?",
    ["楼下那两个傻瓜，不知道在这里要保持安静吗？"] = "Эти два дурака внизу, разве они не знают, что здесь нужно молчать?",
    ["欢迎你，{{先生|女士}}。我是萨默尔太太，很高兴你能来。"] = "Добро пожаловать, {{мистер|мисс}}. Я миссис Сэммер, я очень рада, что вы смогли прийти.",
    ["欢迎回到您的领地！我看到了您在商业上的深刻潜力，也许在不久的将来，鲁恩将诞生一位新的铁路大亨。"] = "Добро пожаловать обратно на вашу территорию! Я вижу ваш огромный потенциал в бизнесе; возможно, в ближайшем будущем в Лоэне родится новый железнодорожный магнат.",
    ["欢迎您回到俱乐部！"] = "Добро пожаловать обратно в Клуб!",
    ["欢迎您，尊敬的{{先生|小姐}}。我们随时准备装载物产发车，或者您是想保养一下车厢和引擎？"] = "Добро пожаловать, уважаемый {{господин|госпожа}}. Мы готовы погрузить товары и отправиться в любой момент, или вы желаете провести техобслуживание вагона и двигателя?",
    ["欢迎来到俱乐部乱斗场。"] = "Добро пожаловать на клубную арену потасовок.",
    ["欢迎来到塔罗学派！崭新的水手。"] = "Добро пожаловать в Клуб Таро, новоиспечённый Моряк!",
    ["欢迎落座。善良的客人，能麻烦您稍微挪一下吗？您差点压坏我的书页了。"] = "Добро пожаловать на свое место. Добрый гость, не могли бы вы немного подвинуться? Ты чуть не раздавил мои страницы.",
    ["止步。上面的空气不是给普通人呼吸的。"] = "Останавливаться. Воздух наверху не предназначен для дыхания обычных людей.",
    ["正如你看到的那样，我现在是个海盗……佛尔思女士的作品《大冒险家》中的大海盗——“烈焰”，赏金……"] = "Как видите, я теперь пират... Великий пират из произведения госпожи Форс \"Великий авантюрист\" - \"Дурак\", награда...",
    ["正是！啊——伟大的存在！我感受到了它的呼吸！"] = "Точно! Ах, великолепное существование! Я чувствую его дыхание!",
    ["此地向西逃，是死胡同，向东是热闹的集市。"] = "Это место — тупик на западе и оживленный рынок на востоке.",
    ["死之前我必须告诉你，其实我那个大哥，是我母亲初恋的遗腹子……他其实不疯，他是装的！"] = "Прежде чем я умру, я должен вам сказать, что на самом деле мой старший брат — посмертный ребенок первой любви моей матери… На самом деле он не сумасшедший, он притворяется!",
    ["死去的人？！"] = "Мертвец?!",
    ["每一个诺言都拥有效力，每一笔交换都基于信任。"] = "Каждое обещание имеет силу, и каждый обмен основан на доверии.",
    ["每周一会刷新物产收购价格，请注意及时检查，生产高价值物产。"] = "Закупочная цена продукции обновляется каждый понедельник. Пожалуйста, не забывайте вовремя приходить и производить дорогостоящие товары.",
    ["每周二、周四中午12:00开放报名，晚间19:00~20:30乱斗正式开启。场次安排以上一届参与人数而定（首届以俱乐部人数）。"] = "Регистрация открывается каждый вторник и четверг в 12:00, а официальное начало потасовки — с 19:00 до 20:30 вечера. Расписание определяется количеством участников предыдущей сессии (первая сессия формируется по количеству членов клуба).",
    ["每周六、周日晚间19:30~21:00，该增益强化为【闪耀的结社之辉】：基于魅力、直觉的检定投骰结果+3;参与教团玩法后，获得战斗属性增益。"] = "Каждую субботу и воскресенье с 19:30 до 21:00 этот положительный эффект усиливается до [Сияющая слава общества]: +3 к броскам кубиков на основе Харизмы и Интуиции; после участия в культовом игровом процессе вы получаете бонусы к боевым атрибутам.",
    ["每场乱斗共有32个幻象投影参与，时长5分钟。击杀、存活皆可赚取积分。4分30秒时若未分胜负，将结算最终排名积分。 "] = "В каждой драке участвуют 32 фантомные проекции и она длится 5 минут. Вы можете зарабатывать очки, убивая и выживая. Если по истечении 4 минут 30 секунд не будет победителя, будут подсчитаны окончательные рейтинговые очки.",
    ["每天从早到晚，店里挤满了人，笑声能从这头传到那头。 "] = "Каждый день с утра до вечера магазин был полон людей, и смех был слышен от одного конца до другого.",
    ["每天跳上车筐，就已经耗尽我全部的力气了。"] = "Каждый день запрыгивать в корзину — на это уходят все мои силы.",
    ["每次攻击增加5%攻击力"] = "Каждая атака увеличивает атаку на 5%.",
    ["比利，还好你没事！你知道——"] = "Billy, thank goodness you're alright! You know—",
    ["比如弗兰克精品蘑菇研究小组，巨龙和巨人研究小组……兴趣自由，选择自由！"] = "Например, исследовательская группа Фрэнка по грибам, исследовательская группа по драконам и гигантам... свобода интересов, свобода выбора!",
    ["毕竟我是个已经死去的人。"] = "В конце концов, я ведь уже мертв.",
    ["水很浅，为什么不下去捡呢？"] = "Вода совсем неглубокая, почему бы не спуститься и не достать?",
    ["求求你，自己跳下去，我就解脱了。"] = "Пожалуйста, спрыгни сам, и я буду освобожден.",
    ["求求您了，千万别说出去……我分您一成，不，两成利润？要是传出去，我就全完了！ "] = "Я вас прошу, пожалуйста, никому не говорите... Я вам дам десять процентов, нет, двадцать процентов прибыли? Если это выйдет наружу, мне конец!",
    ["汪汪汪！"] = "Гав-гав-гав!",
    ["汪汪！汪！"] = "Гав! Гав!",
    ["没、没什么！我们在讨论……讨论天气！"] = "Н-ничего! Мы обсуждали... обсуждали погоду!",
    ["没事的，我已经祈祷兔子之神宽恕我的罪过了！"] = "Ничего, я уже помолился Богу Кроликов, чтобы он простил мои грехи!",
    ["没事，我胆子比较大，我去看看。"] = "Ничего, я достаточно смелый, пойду посмотрю.",
    ["没人能让我提起兴趣了。"] = "Никто больше не сможет меня заинтересовать.",
    ["没什么好隐瞒的，我刚刚完成了一场复仇。"] = "Скрывать тут нечего, я только что свершил месть.",
    ["没关系的朋友，微小的善意也可以改变世界，希望在未来的活动中与你相遇。"] = "Все в порядке, друг; Маленькие добрые дела также могут изменить мир. Я надеюсь встретиться с вами в будущих мероприятиях.",
    ["没关系，你还有时间考虑。"] = "Ничего, у тебя еще есть время подумать.",
    ["没关系，无论什么时候，我都愿意为你介绍我主，伟大的“愚者”先生。"] = "Неважно, я готов представить вас моему Лорду, великому Мистеруу, в любое время.",
    ["没关系，这也是我的工作。"] = "Все в порядке, это тоже моя работа.",
    ["没关系，顾问{{先生|女士}}，接下来就交给我们。"] = "Все в порядке, консультант {{Mr.|Ms.}}, остальное оставьте нам.",
    ["没时间了，快看外面！"] = "There's no time left, look outside quickly!",
    ["没有佛尔思的小说看，我就要活不下去了……"] = "Я не смогу без чтения романов Форса...",
    ["没有机械结构，没有能源供应，净化之泉的水能持续流动，这就是神秘学吗……"] = "Ни механической конструкции, ни энергоснабжения, однако вода в Фонтане Очищения течет непрерывно; это и есть мистика...",
    ["没有的事！我和马修吵架之后没多久就散了，您看，我现在一个人老老实实地卖纪念品，也是……是正当的生意嘛！"] = "Нисколько! Я расстался с Мэтью вскоре после того, как мы поссорились. Слушайте, я, честно говоря, теперь сам торгую сувенирами, это... это законный бизнес!",
    ["没有！这家伙能躲过我们的巡逻，丢的东西越来越多了！！"] = "Никто! Этот парень может уклоняться от наших патрулей, и при этом пропадает все больше и больше вещей!!",
    ["没有，他，他在湖边写诗，很，很好的诗！"] = "Нет, он, он пишет стихи на берегу озера, очень, очень хорошие стихи!",
    ["没有，没有家人……你还是离我远点吧，他们说不幸是会传染的，是最难解决的瘟疫。"] = "Нет, никакой семьи... Тебе лучше держаться от меня подальше. Говорят, несчастье заразительно, это самая трудная чума, которую можно вылечить.",
    ["没用的家伙！看谁会信你！"] = "Бесполезный парень! Посмотрим, кто тебе поверит!",
    ["没见过的面孔，你不是本地人吧？要不要尝尝我做的睡莲啤酒？"] = "Лицо, которое я раньше не видел. Ты не местный, не так ли? Хотите попробовать пиво из водяных лилий, которое я приготовил?",
    ["没车的话，厂子里还有辆老车可以借你使使。可别给磕坏咯。"] = "Если у вас нет машины, на заводе есть старая, которую вы можете одолжить. Только не разрушай его.",
    ["没错……这是我与香花女士之间的珍贵的信物。"] = "Правильно... это драгоценный знак между мной и госпожой Сянхуа.",
    ["没错。它看上去像瓜果，但吃起来却有鳟鱼和牛奶混合的味道。"] = "Точно. Они похожи на дыни, но по вкусу напоминают смесь форели и молока.",
    ["没错。愿意进去吗？或者等你想好了再来找我。"] = "Это верно. Хотите войти? Или вернись ко мне, когда примешь решение.",
    ["没错！她是贝克兰德夜总会里最不同的舞女，她的舞姿优美，歌声也动人！"] = "Это верно! Она самая уникальная танцовщица ночного клуба Бэкланд; ее танцевальные движения изящны, а ее певческий голос трогателен!",
    ["没错！来吧，翻开我，阅读我，我可以在一定时间内记录您的行为！"] = "That's right! Come on, open me up and read me. I can record your actions for a certain period of time!",
    ["没错，霍纳奇斯！你们知道吗，最最有趣的是，遗迹内没有发现这个国家的墓葬！这是为什么呢？"] = "Точно, Хорнацис! Знаете, что самое интересное? Никаких захоронений из этой страны в руинах обнаружено не было! Почему это?",
    ["没问题！"] = "Без проблем!",
    ["沼泽女巫这种鬼话也有人信？斐谢尔那家伙就会编故事。"] = "Кто-нибудь на самом деле верит в ерунду о Болотной Ведьме? Этот парень Фешер просто любит сочинять истории.",
    ["波特总喜欢躲起来唱歌。"] = "Портер всегда любит прятаться и петь.",
    ["注意事项是，<P_Yellow>保持好距离不要拉断灵性形成的连线</>，还有……"] = "Главное предостережение: <P_Yellow>держи дистанцию и не разорви связь из духовности</>, а еще...",
    ["注意，这不是社交场合谈论天气的敷衍——"] = "Обратите внимание: это не поверхностный светский разговор о погоде.",
    ["派克医生这么讲究的人，就该配个秀气的姑娘，多雅致！"] = "Такой утонченный человек, как доктор Паркер, должен быть с нежной девушкой, как элегантно!",
    ["派克医生，你可算从诊所出来了！今天必须给我个准话！"] = "Доктор Бейкер, вы наконец-то вышли из клиники! Сегодня вы обязаны дать мне точный ответ!",
    ["海洋之甜风，听起来很浪漫。"] = "Sweet Breeze of the Ocean звучит очень романтично.",
    ["深眠花？"] = "Цветок глубокого сна?",
    ["清脆的声音，嗯……好听就是好瓜！"] = "Четкий звук, хм... если звучит хорошо, то это хорошая дыня!",
    ["漂亮的裙子、新鲜的花朵、好用的擀面杖……带给妈妈，妈妈很喜欢。"] = "Красивые платья, живые цветы, полезные скалки... Я приношу их маме, и они очень нравятся маме.",
    ["演出的主角是位美丽的小姐，温柔的小姐。"] = "Главная героиня спектакля – прекрасная дама, нежная дама.",
    ["火车……火车不要再往里开了！不要再放人进来了！停下！"] = "Поезд... не пускайте поезд дальше! Не впускайте никого больше! Останавливаться!",
    ["灯光下，镜片折射出异样的光泽——那不是普通玻璃，而是一种特殊水晶磨制而成，内部似乎有极细微的灵性流转。"] = "Под светом ламп линзы преломили необычный блеск — это было не простое стекло, а шлифованный особый хрусталь, внутри которого словно струилась тончайшая духовность.",
    ["灵异事件？是发生什么事了吗？"] = "Паранормальное событие? Что-то случилось?",
    ["灵数？魔镜？塔罗牌还是星盘占卜？"] = "Нумерология? Волшебное зеркало? Карты Таро или астрологическое гадание?",
    ["热闹？哈！都是些老面孔，没劲透了。我就爱听你们这些走路带风的人讲故事……"] = "Живой? Ха! Все те же старые лица, это так скучно. Мне просто нравится слушать истории таких людей, как вы, которые всегда в движении...",
    ["然后就再找不到镇子了，整整过去三十年，才终于回来……"] = "Потом я снова не смог найти город. Прошло целых тридцать лет, прежде чем я наконец вернулся...",
    ["然后，我的日程表就越来越满了！"] = "Потом мой график становился все насыщеннее и насыщеннее!",
    ["煮沸……加入纯牛奶150毫升……搅拌……"] = "Вскипятить... добавить 150мл цельного молока... перемешать...",
    ["爱情属于勇敢者，我相信你会成功的！"] = "Любовь принадлежит храбрым; Я верю, что у тебя все получится!",
    ["父亲？我呸，他从来没把我当亲儿子看过！看他只培养老三埃德加的样子就知道了！"] = "Отец? Пффф, он никогда не относился ко мне как к собственному сыну! Посмотрите, как он ухаживал только за третьим, Эдгаром, и вы поймете!",
    ["爷爷！爷爷在下面！本杰明哥哥！救爷爷！求求你……救救爷爷好不好？"] = "Дедушка! Дедушка внизу! Брат Бенджамин! Спасите дедушку! Пожалуйста... пожалуйста, спаси дедушку, ладно?",
    ["爷爷！谢谢你，本杰明哥哥！"] = "Дедушка! Спасибо, Брат Вениамин!",
    ["爸爸离开了，但我们的生活还得接着过下去。"] = "Папы больше нет, но наша жизнь должна продолжаться.",
    ["爸爸说它不能和家里人葬在一起……我只能把它带到这来。"] = "Папа сказал, что его нельзя хоронить вместе с семьей... Я могу только принести его сюда.",
    ["爸爸！那里亮闪闪的，是女神在看我们吗？"] = "Папочка! Там светится, Богиня наблюдает за нами?",
    ["牧师先生，请原谅，不是我对女神的敬意有所……额……只是……少捐十镑，女神是否会减少对我的注视？"] = "Пастор, пожалуйста, простите меня, дело не в том, что я уважаю Богиню... э-э... просто... если я пожертвую на десять фунтов меньше, Богиня перестанет смотреть на меня?",
    ["牧师说，你已经回到了女神的怀抱。希望您能在那里安眠……"] = "Священник сказал, что ты вернулся в объятия Богини. Надеюсь, ты сможешь найти там сон...",
    ["特别舒服，维尔芙和丽丝她们每天都会拿着好吃的来看我，和以前一样。"] = "Это особенно удобно. Верф и Лис приходят ко мне каждый день с вкусной едой, как и раньше.",
    ["犯人经常半夜惨叫，狱警巡逻时会莫名迷路，走着走着就回到原点。更邪门的是，有个被关了一年的家伙，前天晚上突然在牢房里哭喊“一分钟又到了”……问他什么意思，他只抱着头，头疼欲裂。"] = "Заключенные часто кричат по ночам как резаные, а тюремщики на обходе почему-то блуждают кругами и выходят туда, откуда начали. И что еще страшнее: один парень, что сидит здесь уже год, позавчера ночью вдруг зарыдал в камере: «Минута снова истекла!»... Когда его спросили, что это значит, он лишь схватился за голову, корчась от дикой боли.",
    ["狗屎，我连夜背的台词都没有用上！"] = "Блин, строчки, которые я учил всю ночь, даже не прижились!",
    ["狼鱼……呃，突然想起今天已经有人约我吃饭了，狼鱼这种味道重的食物还是留到下次再吃吧……"] = "Рыба-волк... эм, я вдруг вспомнил, что кто-то уже пригласил меня сегодня на ужин. Такую сильно пахнущую еду, как рыба-волк, я оставлю на следующий раз...",
    ["猎人。"] = "Охотник.",
    ["玛尔塔婶婶带我们排练了艺术学派的时下最热门的舞蹈，听说这只舞连挑剔的贝克兰德人都非常追捧呢。"] = "Тетя Марта взяла нас на репетицию самого популярного танца Школы искусств. Я слышал, что даже привередливые жители Баклунда очень любят этот танец.",
    ["现在她总说托马斯还在，就在她旁边坐着。有时还给空座位倒酒，说托马斯爱喝这口……"] = "Теперь она всегда говорит, что Томас все еще здесь, сидит рядом с ней. Иногда она даже наливает напиток на пустое место, говоря, что Томас любит эту штуку...",
    ["现在她走了，我还精心维护着花丛，等着她有一天能回来。"] = "Теперь, когда ее больше нет, я все еще тщательно ухаживаю за цветами, ожидая того дня, когда она может вернуться.",
    ["现在好了，听说好几个都在古堡撞见了不干净的东西！"] = "Слушайте, я слышал, что некоторые из них столкнулись с чем-то нечистым в замке!",
    ["现在的年轻人啊……哎，真是缺乏进取精神啊，你要是能有罗塞尔一半的努力……"] = "Молодые люди в наши дни... ох, им действительно не хватает предприимчивости. Если бы ты мог воспользоваться хотя бы половиной усилий Розеллы...",
    ["现在的开膛手又是扮演怎样的角色？一切到底是怎么一回事……"] = "Какую роль сейчас играет Потрошитель? О чем все на самом деле...",
    ["现在的我是索罗·卡特。"] = "Теперь я Соло Картер.",
    ["现在镇上的人怎么看待那座古堡？"] = "Как теперь жители города относятся к замку?",
    ["现在，我就要带着他的那份好奇继续努力鼓捣了！"] = "Теперь я собираюсь продолжить работу над его долей любопытства!",
    ["琼委托我的，她灵性较强，被搞得失眠，躲灵界观测房去了。"] = "Джоан доверила это мне; у нее сильная духовность, и ее довела до бессонницы, поэтому она спряталась в комнате наблюдения Мира Духов.",
    ["甚至还编了个碰到溪水就会被住在源头沼泽里的女巫诅咒的故事！哈！"] = "Даже придумали легенду, что если прикоснуться к воде ручья, то будешь проклят ведьмой, живущей в болоте у истока! Ха!",
    ["甜品推荐“海洋之甜风”。我们没有用狼鱼罐头，而是坚持自制狼鱼肉泥，将之与牛乳、芝士、砂糖混合，烘烤成糕点……"] = "На десерт рекомендую «Сладкий океанский бриз». Мы принципиально не используем консервированную зубатку, а готовим домашнее филе зубатки, смешивая его с молоком, сыром и сахаром, и выпекаем изысканное пирожное...",
    ["生命值提高"] = "Здоровье увеличено",
    ["生活总是这样，有分歧，有和解，不是吗？"] = "Жизнь всегда такая — бывают разногласия и примирения, не так ли?",
    ["用于占卜的设备，因长期承受学生们“这次考试范围是什么”的提问而精神崩溃，现在只会用雾气拼出“去复习第四章”或“建议转专业”。"] = "Устройство, используемое для гадания. Поскольку он долгое время терпел вопросы студентов типа «Каков объем этого экзамена?», у него случился психический срыв, и теперь он использует туман только для того, чтобы произнести «Пересмотрите главу 4» или «Предложите сменить специальность».",
    ["用你的眼睛，你的灵性直觉，乃至任何……嗯……“会说话的证物”，去捕捉一切不合逻辑的细节。"] = "Используйте зрение, духовную интуицию и даже любые... хм... «говорящие улики», чтобы подметить малейшие нестыковки и алогизмы.",
    ["用大炮！轰击山体引发雪崩！埋葬一切敌人！"] = "С пушками! Бомбардируйте гору, чтобы вызвать лавину! Похороните всех врагов!",
    ["用气球飞天吗？感觉不太可能。"] = "Летаете на воздушных шарах? Это кажется маловероятным.",
    ["男爵在看那个角落。那里有什么？"] = "Барон смотрит в тот угол. Что там такое?",
    ["疯子！都是疯子！我劝你离他们远点，不然迟早你也会被变成蘑菇。"] = "Сумасшедший! Они все сумасшедшие! Советую вам держаться от них подальше, иначе рано или поздно вы тоже превратитесь в гриб.",
    ["的确，没人比您这样的人更了解这座古堡了。"] = "Действительно, никто не знает этот замок лучше, чем кто-то вроде тебя.",
    ["盔甲之神？"] = "Бог доспехов?",
    ["直击灵魂！"] = "Удар прямо в душу!",
    ["直到今天，把气球拴在屋顶，我又感受到了久违的快乐，至于究竟能不能飞，已经不重要了啊。"] = "До сегодняшнего дня, привязывая воздушные шары к крыше, я ощущал давно утраченную радость. Что касается того, сможет ли он вообще летать, это уже не важно.",
    ["直到有一天！那个该死的猎人比尔特，他发现我能够感受到环境里的不安和危险。"] = "Пока однажды! Этот проклятый Охотник, Билт, обнаружил, что я чувствую беспокойство и опасность в окружающей среде.",
    ["直到有一天，我开始对“价值”特别敏感。"] = "Пока однажды я не стал особенно чувствительным к «ценности».",
    ["直走那边是另外的营地，老师让我们注意别走到私人的营地里了。"] = "Прямо по курсу другой лагерь. Учитель предупредил, чтобы мы случайно не забрели в частные лагеря.",
    ["相信您一定能让这片土地重新焕发生机，我已经准备好为它惊叹了！"] = "Я верю, что вы обязательно сможете вернуть эту землю к жизни; Я уже готов удивиться этому!",
    ["相信我，你迟早还会来问的。"] = "Поверьте, рано или поздно вы придете спрашивать.",
    ["相信我，搬来这里前我是家乡镇子里最有名的占卜师。"] = "Поверьте, до переезда сюда я был самым известным мастером гаданий в своем родном городе.",
    ["相信我，这是女神给予的预兆，你需要黑夜的安抚和教会的帮助。"] = "Поверьте, это знак Богини; вам нужно ночное утешение и помощь Церкви.",
    ["看到旁边的这个木雕小骑士吗？你能在镇子上的许多房顶上找到它们。"] = "Вы видите рядом со мной маленького деревянного рыцаря, который вырезает? Их можно найти на многих крышах города.",
    ["看啊{{先生|女士}}，多漂亮的雪山，有兴趣来一次刺激的雪山悬崖飙车吗？"] = "Посмотри, {{sir|madam}}, какая красивая заснеженная гора. Хотите поучаствовать в захватывающей гонке по заснеженной горе?",
    ["看在跟您聊得来的份上，愿意跟我走一趟看看？您是识货的人，我一眼就看得出来！"] = "Раз уж мы так славно поладили, не согласитесь ли пройтись со мной и взглянуть? Вы человек знающий толк, я сразу это вижу!",
    ["看守也是一种守护，是一件有意义的事。"] = "Сторожить — это тоже форма защиты, в этом есть свой смысл.",
    ["看来必须先调查一下格兰特先生的死因了。"] = "It seems I must first investigate the cause of Mr. Grant's death.",
    ["看来我已经狼狈到引起了一位好心人的注意，唉，都是那该死的噩梦。"] = "Кажется, я настолько растрепалась, что привлекла внимание доброго человека. Эх, это все тот чертов кошмар.",
    ["看来是一盏路灯照亮了这位美丽的小姐，也照亮了这场悲剧的凶杀。"] = "Кажется, уличный фонарь осветил эту прекрасную девушку, а также осветил это трагическое убийство.",
    ["看法？过去是敬畏，绕着走。现在是贪婪，想着去里面扒拉点“古董”换酒钱！"] = "Вид? Раньше это было благоговение, и они ходили вокруг него. Теперь это жадность — думать о том, чтобы выкопать внутри какой-нибудь «антиквариат», чтобы обменять его на деньги на выпивку!",
    ["看着我，让我教你如何将黑暗驱散。"] = "Посмотри на меня, позволь мне научить тебя, как рассеять тьму.",
    ["看着自己的名字在墓碑上……说实话，我有点发毛。"] = "Видеть свое имя на надгробии... честно говоря, у меня мурашки по коже.",
    ["看起来它不太喜欢被打扰。"] = "Похоже, он не любит, когда его беспокоят.",
    ["看这里，我们的世界由四块大陆和五片海洋一起构成。而我所涉足过的地方，只有那么一点点，我很想走出去，成为一个像格尔曼·斯帕罗一样伟大的冒险家。"] = "Посмотрите, наш мир состоит из четырех континентов и пяти океанов. А мест, куда я ступил, лишь немного. Я очень хочу выйти наружу и стать великим искателем приключений, как Герман Воробей.",
    ["看，多么棒的一片集市！有商人已经驻扎在这里了。"] = "Посмотрите, какой чудесный рынок! Торговцы уже открыли здесь свои магазины.",
    ["看，这么多年过去，尤德拉之树依旧在庇佑这里。"] = "Смотри, спустя столько лет Древо Йодры все еще защищает это место.",
    ["真不来一局？好吧……什么时候想乱斗了，记得来找我！"] = "Неужели не придешь на обход? Ладно... когда тебе захочется подраться, не забудь прийти и найти меня!",
    ["真希望有机会能见到这样的“大人物”，或许我应该在车站再等等。"] = "Я очень надеюсь, что у меня будет шанс встретить такую ​​«большую шишку». Возможно, мне стоит еще немного подождать на вокзале.",
    ["真是一个悲伤的故事。"] = "Какая грустная история.",
    ["真是一座漂亮的酒舍。"] = "Какой красивый винный дом.",
    ["真是个节省的好孩子啊！"] = "Какой запасливый и хороший ребенок!",
    ["真是令人难过，但这就是艺术不是吗？"] = "Это действительно грустно, но это искусство, не так ли?",
    ["真是想念我壁炉旁的猫窝啊，还有我的小鱼玩具。"] = "Мне очень не хватает моей кошачьей лежанки у камина и маленькой игрушечной рыбки.",
    ["真是有个性的名字，希望味道也能给我带来惊喜！"] = "Какое уникальное имя, надеюсь, вкус меня тоже удивит!",
    ["真正的神迹！没想到如此高层次的事物就这样摆在最显眼的地方。"] = "Настоящее чудо! Я не ожидал, что столь высокоуровневая вещь будет размещена на самом видном месте.",
    ["真痴情啊！"] = "Как искренне предан!",
    ["真的、真的还要触碰它吗？你的理智即将崩溃，这对非凡者来说太过危险。"] = "Правда, нужно ли это трогать? Ваше здравомыслие вот-вот рухнет; это слишком опасно для Потустороннего.",
    ["真的吗！？太好了！"] = "Действительно!? Замечательно!",
    ["真的吗？那不是你瞎编的神吗？兔子之神真能管偷吃？！"] = "Действительно? Разве это не бог, которого ты выдумал? Сможет ли Бог Кроликов справиться с воровством еды?!",
    ["真的吗？那故事里，他们为什么肚子都圆滚滚的？"] = "Правда? А почему тогда в историях у них у всех круглые раздутые животы?",
    ["真的确定还要触碰它吗？你的理智将下降到较为危险的范围。"] = "Ты действительно уверен, что хочешь прикоснуться к нему? Ваше здравомыслие упадет до относительно опасного уровня.",
    ["真的确定还要触碰它吗？你的理智正在摇摇欲坠，不如及时收手。"] = "Ты действительно уверен, что хочешь прикоснуться к нему? Ваше здравомыслие колеблется; лучше остановиться сейчас.",
    ["真的要放在这里吗？会不会有点奇怪？"] = "Нам действительно нужно разместить это здесь? Не будет ли это немного странно?",
    ["真的？这么神奇的事情，你怎么也不教教我？"] = "Правда? Такая удивительная вещь, почему же ты меня не научишь?",
    ["真的？！您是一位真正的勇士。"] = "Действительно?! Ты настоящий воин.",
    ["真高兴见到你！我听说金秋湖发生了一些怪事，一株黄金树苗一夜之间生根发芽，成长大树。"] = "Так рада тебя видеть! Я слышал, что на озере Золотой Осени произошли какие-то странные вещи; Саженец Золотого Дерева за ночь пустил корни и пророс, превратившись в большое дерево.",
    ["睡在鸟巢里的小猫啊，很特别的猫呢。"] = "Котенок, спящий в птичьем гнезде... право, удивительный котик.",
    ["睡莲……沉睡了……保护睡莲……"] = "Кувшинка... уснула... защитите кувшинку...",
    ["睡莲啤酒？是用莲花酿的吗？"] = "Водяное пиво? Его варят с цветами лотоса?",
    ["睡莲对我们来说是很神圣的，怎么能卖呢？"] = "Кувшинки для нас священны, как мы можем их продавать?",
    ["睡莲？……噢！你是旅客吧？"] = "Водяные лилии?...Ой! Ты путешественник, да?",
    ["瞧这货的工艺，真正的复古，真正的贵族审美！"] = "Посмотрите на мастерство этого изделия — настоящее ретро, ​​настоящая аристократическая эстетика!",
    ["知道的越多，越危险。"] = "Чем больше знаешь, тем опаснее.",
    ["石板也好多！翻开我，使用投影，您一定可以通过！"] = "There are so many stone slabs too! Open me up and use the projection; you will definitely be able to pass!",
    ["砍完木头后，我们会在太阳落山时，用树脂在树干上画眼睛的符号。"] = "После того как мы закончим рубить дрова, на стволах рисуем смолой символы глаз при заходе солнца.",
    ["确实很累，作为战斗力不强的途径，本来很少有学员邀请我一起出任务的……"] = "Я действительно очень устал. Поскольку Путь не силен в бою, немногие ученики приглашают меня пойти с ними на квесты...",
    ["碎片拼凑出了犯人的行踪，现在出发吗？"] = "По фрагментам удалось установить местонахождение преступника. Мы уходим сейчас?",
    ["社会性死亡？"] = "Социальная смерть?",
    ["祝您放松身心，自由自在……"] = "Желаю тебе расслабления и свободы...",
    ["神奇物品通常是非凡特性和其他事物结合而成的产物，数量稀少，很多都有明显的缺陷和负面效果。"] = "Магические предметы обычно являются результатом сочетания необычных свойств и других вещей. Их мало, и многие из них имеют очевидные недостатки и негативные последствия.",
    ["神秘的影像，只留下了一句话，不具有沟通的能力。"] = "Загадочное изображение оставило только одно предложение и не имеет возможности общаться.",
    ["神秘老爷爷，奇异空间，接下来应该是系统来发布任务了吧……<P_Heart>（陷入自言自语）</> "] = "Таинственный старик, странное пространство, рядом должна быть система, выдающая квест... <P_Heart> (начинает бормотать про себя) </>",
    ["福斯特？赛肯德？像是汽车的品牌名字，呵呵。"] = "Взращивать? Второй? Они звучат как названия автомобильных марок, ха-ха.",
    ["离开隐藏关。"] = "Покиньте скрытый уровень.",
    ["私人的营地？营地也有归属于私人的吗？"] = "Частные лагеря? Могут ли лагеря находиться в частной собственности?",
    ["科林导师似乎是所有导师中最特殊的一位。"] = "Инструктор Колин кажется самым особенным среди всех инструкторов.",
    ["科考队定下什么时间，你们就得什么时候送来！"] = "В какое время научная экспедиция скажет, в такое и доставите!",
    ["秘偶大师非凡特性形成的书状封印物，具有活化的特性，有意识地操控活人成为它的观众和演员。"] = "Запечатанный артефакт в форме книги, созданный на основе характеристик Потустороннего Мастера Марионеток. Он обладает свойством анимации и сознательно манипулирует живыми людьми, чтобы стать его зрителями и актерами.",
    ["移动速度提高"] = "Скорость передвижения повышена",
    ["稍等，我在用我的灵魂感知它的模样……"] = "Подождите, я использую свою душу, чтобы воспринять его внешний вид...",
    ["究竟是谁杀了我，而我又杀了谁？"] = "Кто конкретно меня убил и кого я убил?",
    ["穿黑风衣的老爷们？"] = "Господа в черных плащах?",
    ["站在我面前的骑士，向我证明你有资格担任威瑟尔家族第一军团的骑兵队长之职。"] = "Рыцарь, стоящий передо мной, докажи мне, что ты достоин служить капитаном кавалерии Первого легиона семьи Вессель.",
    ["童叟无欺，说说你的恋爱烦恼吧？"] = "Никакого обмана здесь нет. Скажи мне, какие у тебя романтические проблемы?",
    ["第一杯，只是润喉。"] = "Первый стакан – просто чтобы смочить горло.",
    ["第一，“搜集”。"] = "Сначала «Сбор».",
    ["第一，乞丐，也是有尊严的。"] = "Во-первых, у нищих тоже есть достоинство.",
    ["第二，“质询”。"] = "Второе: «Допрос».",
    ["第二，每月两天，本乞丐休息！"] = "Во-вторых, два дня в месяц этот нищий не на службе!",
    ["第四枚金币。贫民的聚集处，这里是他们最后待的地方。"] = "Четвертая золотая монета. Место сбора бедняков; это последнее место, где они останавливались.",
    ["等他回来我狠狠收拾他！"] = "Я дам ему хороший урок, когда он вернется!",
    ["等你知道自己真正想要什么的时候……也许我们可以再聊。"] = "Как только ты поймешь, чего на самом деле хочешь... возможно, мы сможем поговорить еще раз.",
    ["等埃尔夫的腿好一些，我们就举行婚礼！"] = "Как только нога Альфа поправится, мы проведем свадьбу!",
    ["等婆婆帮你留意留意，温柔内敛的人可不好找啊……"] = "Пусть бабушка присмотрит за тобой. Нежных и замкнутых людей трудно найти...",
    ["等您再进一步，把城堡升到3级，我们还能建造自己的工坊，这些丰富的物产能装载上火车，被用于铁路行商中。"] = "Как только вы продвинетесь дальше и улучшите замок до уровня 3, мы сможем построить собственную мастерскую. Эти богатые ресурсы можно погрузить в поезда и использовать для железнодорожной торговли.",
    ["等我的心上……呃，没什么，怎么随便打听别人的事！"] = "Жду любимую... эээ, ничего, зачем ты лезешь в чужие дела!",
    ["等着吧！要是被我抓到，你就完了！"] = "Просто подожди! Если я тебя поймаю, тебе конец!",
    ["等着，下一次参加聚会，我帮你好好找找。"] = "Подождите. В следующий раз, когда я приду на собрание, я помогу вам внимательно осмотреться.",
    ["等等，{{先生|女士}}。"] = "Подожди, {{sir|madam}}.",
    ["等等，你放了什么？"] = "Подожди, а что ты вставил?",
    ["等等，夫人，你是说，你的丈夫赛斯死于一场急病，然后你很快认识了那位斐乐先生，是吗？"] = "Подождите, мадам, вы имеете в виду, что ваш муж Сет умер от внезапной болезни, а вскоре после этого вы встретили этого мистера Фила, верно?",
    ["等老爷回来，看见宅子被打理成这样，非解雇我不可。"] = "Когда хозяин вернется и увидит, что дом так устроен, он меня обязательно уволит.",
    ["答得不错，蒙对的？算了，我不在乎。不过……"] = "Not a bad answer. Did you guess it right? Forget it, I don't care. However...",
    ["签名也很重要！这是粉丝的精神寄托！"] = "Автографы тоже важны! Это духовная поддержка болельщиков!",
    ["简单来说，就是能够通过一些神秘学知识创造魔法，而这些神秘学知识知道的人越少，效果越好。"] = "Проще говоря, это способность творить магию посредством каких-то оккультных знаний, и чем меньше людей знают эти оккультные знания, тем лучше эффект.",
    ["算了，请你离开。山里危险，不要乱逛。"] = "Неважно, пожалуйста, уходите. Горы опасны, не бродите вокруг.",
    ["算了，还是一会儿问问贝茜吧……她今天有点沉默，谁惹她生气了？"] = "Забудь об этом, я спрошу у Бесси через некоторое время... Она сегодня немного Молчалива, кто ее разозлил?",
    ["算啦，我一会就回去找他，再帮他找找其他人。"] = "Забудь об этом, я вернусь, чтобы найти его через некоторое время и помочь ему найти других.",
    ["管他是谁掉的。不过我刚才在林子深处追踪足迹时，看见那个穿长风衣的开膛手就在空地那儿，正焦急地原地转圈，好像在等待某人。可能与这有关呢。"] = "Какая разница, кто его обронил? Но когда я только что выслеживал следы в чаще леса, то приметил на поляне Потрошителя в длинном плаще: он тревожно кружил на месте, будто ждал кого-то. Возможно, это как-то связано.",
    ["箱子里面有什么？"] = "Что внутри ящика?",
    ["精彩绝伦的演出，我为对你的轻视抱以歉意，下一次我会优先找你，伙计。"] = "Великолепное выступление! Прошу прощения за своё пренебрежение. В следующий раз я обращусь к тебе в первую очередь, приятель.",
    ["精神紧张，仇视见到的每个人，还总觉得有人在偷听他说话。"] = "Нервный, враждебно относился ко всем, кого видел, и всегда чувствовал, что кто-то подслушивает его разговоры.",
    ["累？你听错了，我是说，这腰带有点勒。能够摸到那么精密又完美的机械是我的幸运。"] = "Усталый? Вы ослышались неправильно. Я сказал, что этот ремень немного туговат. Мне повезло иметь возможность прикоснуться к такому точному и совершенному механизму.",
    ["纤细的双手，天鹅的脖颈。"] = "Тонкие руки, лебединая шея.",
    ["约翰先生，所有线索，最后都指向了你。"] = "Мистер Джон, в конечном счете все улики указывают на вас.",
    ["约翰尼说要来这里寻找某种“材料”，之后就没了音讯……"] = "Джонни говорил, что собирается сюда в поисках какого-то «материала», и с тех пор от него ни весточки...",
    ["约翰是这只狗？你们在干什么呢？"] = "Джон, это собака? Что ты делаешь?",
    ["纸条上详细介绍了向我主祈祷需要的东西，这一定是主给我的启示！"] = "В записке подробно описывалось, что необходимо молиться моему Господу; должно быть, это откровение, которое дал мне Господь!",
    ["终于到二楼了！对面就是我被仪式召唤出来的地方！"] = "Finally reached the second floor! Right across is where I was Summoned by the ritual!",
    ["经过协会内部各个成员的努力，目前神奇生物保护协会已经初具规模了。"] = "Благодаря усилиям различных членов ассоциации, Ассоциация защиты магических существ теперь приняла первоначальную форму.",
    ["经过漫长的实验和摸索，人们完善了魔药体系，形成了稳定的序列链条，序列数字越低，魔药品阶越高。"] = "После долгих экспериментов и исследований люди усовершенствовали систему зелий и сформировали стабильную цепочку последовательностей. Чем меньше порядковый номер, тем выше уровень зелья.",
    ["给我振作起来本杰明！"] = "А ну соберись, Бенджамин!",
    ["继续找吧。"] = "Продолжайте поиски.",
    ["罗塞尔大帝曾说过“富贵险中求”，这恰恰说明我马上就要发财了！"] = "Император Розель однажды сказал: «Богатство ищут среди опасности», и это доказывает, что я вот-вот разбогатею!",
    ["美味烤羊腿？"] = "Вкусная жареная баранья нога?",
    ["老乔治一天见不到就念得紧，嘴上却硬得像块石头！ "] = "Старый Джордж скучает по нему, если не видит его хотя бы день, но рот у него твердый, как камень!",
    ["老乔治，这真不行！腌鱼的味道这么大，客人全被熏跑了。"] = "Старый Джордж, так не пойдет! Запах маринованной рыбы такой сильный, что всех клиентов разгонят.",
    ["老人家，您干嘛一直走来走去？"] = "Старик, почему ты продолжаешь ходить туда-сюда?",
    ["老先生，这里风雪很大，您怎么一个人在这儿？"] = "Старый джентльмен, здесь очень сильный ветер и снег, почему ты здесь один?",
    ["老哥，你这班岗站了挺久吧？这一晚林子里有什么动静吗？"] = "Брат, ты уже довольно долго стоишь на страже, не так ли? Было ли какое-нибудь движение в лесу сегодня вечером?",
    ["老巴克的山羊比他胡子还黑！下一个！"] = "Козел Старого Бака чернее его бороды! Следующий!",
    ["老布莱克教士就不一样了，有时候还会给我们分蛋糕。但要是比利来教堂捉我，他肯定也会笑呵呵地把我供出来……"] = "Старый отец Блейк другой; иногда он даже делится с нами тортом. Но если бы Билли пришел в церковь, чтобы поймать меня, он бы обязательно рассмеялся и выдал меня...",
    ["老师不是说过了桥直走吗？"] = "Разве учитель не говорил идти прямо после моста?",
    ["老早没人管了，这是废墟，{{先生|女士}}！没有治安官，没有警察。只有我这样的向导保证你的安全——我是从小在这儿长大的，里里外外不知道转过多少回了。"] = "Это место уже давно никого не заботит; это руина, {{Mr.|Ms.}}! Нет ни судей, ни полиции. Только такой гид, как я, может обеспечить вашу безопасность — я вырос здесь и прошел через каждый угол больше раз, чем могу сосчитать.",
    ["老汤姆，看在咱们二十年交情的份上，就帮我这一回！ "] = "Старый Том, ради нашей двадцатилетней дружбы, помоги мне хоть раз!",
    ["老爷……老爷当时就倒在书桌旁，茶撒了一地。我冲过去，碰了碰他的手——"] = "Мастер... Мастер в это время лежал у стола, а чай был рассыпан по полу. Я подбежал и коснулся его руки…",
    ["老爷卧室的<P_Yellow>门锁着</>。我敲了很久，里面一直没人回应。过了几秒，老爷突然开口说……"] = "Дверь <P_Yellow> в хозяйскую спальню </> была заперта. Я долго стучал, но изнутри не было никакой реакции. Через несколько секунд мастер вдруг сказал...",
    ["老爷和夫人从来没过想责备小姐和那男孩，只是希望我来把把关……如果您见到他，请帮忙转达这份心意吧。谢谢您。"] = "Хозяин и хозяйка никогда не собирались винить девушку и мальчика; они просто хотели, чтобы я что-то проверил... Если вы его увидите, пожалуйста, помогите передать это чувство. Спасибо.",
    ["考察什么？"] = "Исследование чего?",
    ["考验？"] = "Тест?",
    ["而且……上面的游戏比下面危险得多。你现在这样，上去了也活不过第一夜。"] = "Кроме того... игры наверху гораздо опаснее тех, что внизу. В таком виде, как сейчас, ты не переживешь первую ночь, даже если поднимешься наверх.",
    ["而且他有了新名字，你可以叫他“毛毛草”"] = "И у него новое имя; вы можете называть его «Нечеткая трава».",
    ["而且我有了自己的新名字，我不再是一只让人记不住的小猫了！"] = "И у меня есть новое имя; Я больше не котенок, которого люди не могут запомнить!",
    ["而他不在的话，你会怎么选呢……"] = "И если бы его здесь не было, как бы вы выбрали...",
    ["而最后一步，也是关键所在——"] = "И последний шаг тоже ключевой -",
    ["而这里，都是会长创造的魔法，像桃花源，杰克与豌豆……"] = "А здесь всё волшебство создаёт президент, как «Весна цветения персика», «Джек и бобовый стебель»...",
    ["而那座古堡，是这里最为出名的地标，可以说拉姆德小镇的名字，正来源于拉姆德古堡。"] = "И этот древний замок – самая известная достопримечательность здесь. Можно сказать, что название города Ламуд происходит от замка Ламуд.",
    ["肉桂粉8克……纯水100毫升……"] = "8 граммов порошка корицы... 100 миллилитров чистой воды...",
    ["胡说什么，那就是个混小子，一回来就吵吵闹闹，把屋子翻个底朝天。 "] = "Ерунда, это просто паршивец, он, как только вернется, поднимает шум, переворачивает дом вверх дном.",
    ["能在战斗里发出让敌人惊恐混乱的声音，就像雷神降临到地面，正不间断地怒吼，它每一击都带有强烈的毁灭性，可怕的闪电永不缺席。"] = "В бою он может издавать звук, который приводит врагов в ужас и хаос, как будто Бог Грома спустился на землю и непрерывно ревёт. Каждый удар несет в себе огромную разрушительную силу, и ужасающая молния никогда не отсутствует.",
    ["能对敌人造成极大的难以遏制的精神伤害，除此之外，只是加强了对各类武器的掌握。"] = "Оно может нанести огромный, неконтролируемый психический ущерб врагам. В остальном это только усиливает мастерство обращения с различным оружием.",
    ["能提升威严和体质，得到“扭曲”目标语言、行动和意图的能力，可以通过象征意义上的“贿赂”，让目标产生强烈的好感，使锁定的目标或周围一定区域出现“混乱”。"] = "Он может улучшить достоинство и телосложение, давая возможность «искажать» язык, действия и намерения цели. Посредством символического «подкупа» можно заставить цель развить сильную доброжелательность и вызвать «хаос» в заблокированной цели или в прилегающей территории.",
    ["能理解…… "] = "Я могу понять...",
    ["能麻烦你帮我尝尝，这两样蔬菜吃起来有什么不同吗？"] = "Не мог бы ты попробовать эти два овоща и сказать, чем они отличаются на вкус?",
    ["自从三个月零五天零七个小时前，在廷根剧院看过《吉赛尔》舞剧的演出后，我就无法自拔！"] = "С тех пор как три месяца, пять дней и семь часов назад я увидел спектакль «Жизель» в театре Тинген, я не мог перестать думать об этом!",
    ["自从我的小鸟在艺术学派看过这段舞蹈后，就非常兴奋。大概是因为这些动作很像鸭子走路，让同属禽类的它倍感亲切。"] = "С тех пор как моя птичка увидела этот танец в Школе искусств, она ужасно взволнована. Должно быть, эти движения так напоминают утиную походку, что пернатое создание почувствовало небывалое родство.",
    ["臭丫头，再啰嗦别怪我不客气！"] = "Дрянная девчонка, если не замолчишь, я за себя не отвечаю!",
    ["至于蘑菇，呕……那是邪恶的化身！早晚有一天，我要把所有蘑菇都毁掉！"] = "Что касается грибов, ух... это олицетворение зла! Рано или поздно я уничтожу все грибы!",
    ["至于这和黑夜女神有什么关系……我父亲和我还需要继续考古。"] = "Что касается того, какое отношение это имеет к Богине Вечной Ночи... нам с отцом все еще нужно продолжить археологию.",
    ["至少一千五百年！"] = "Минимум 1500 лет!",
    ["艾玛，对不起……我们、我们会回来救你的，一定！"] = "Emma, I'm sorry... We, we will come back to save you, we promise!",
    ["艾玛，我们来了！撑住！"] = "Эмма, мы идем! Подожди!",
    ["芬芬，你还记得爸爸吗？以前这个时候，他会一边抱怨你掉毛，一边还是让你趴在腿上。"] = "Фенфен, ты еще помнишь папу? Тогда, в это время, он жаловался, что у тебя выпадают волосы, но все равно позволял тебе лежать у него на коленях.",
    ["花漂走了，爸爸一定能收到我们的祝福！"] = "Цветок улетел, папа обязательно получит наше благословение!",
    ["若尝过她唇间的酒，谁还愿意清醒着回归！"] = "Если бы кто-нибудь попробовал вино из ее уст, кто бы еще захотел вернуться трезвым!",
    ["荣幸至极！世上每一位辛劳的园丁听到您这话，疲惫都会一扫而空。"] = "Это абсолютная честь! Услышав это, у каждого трудолюбивого садовника в мире пропала бы усталость.",
    ["莫莉，其实，有件事……"] = "Молли, вообще-то, есть что-то...",
    ["莫莉，我们还是再考虑考虑吧……"] = "Молли, давай еще раз подумаем...",
    ["菲尔，你这小兔崽子！！！"] = "Фил, ты маленький негодяй!!!",
    ["萝卜！芹菜！防风草！买得多，送得也多！"] = "Редис! Сельдерей! Пастернак! Покупайте больше, получайте больше бесплатно!",
    ["萨尔德，也就是我的名字。如果您喜欢，不妨常来逛逛。"] = "Сард, это мое имя. Если хотите, можете заходить почаще.",
    ["蘑菇？"] = "Гриб?",
    ["虫子……远离虫子……"] = "Ошибки... держитесь подальше от ошибок...",
    ["虫子！虫子！不要靠近我！"] = "Баги! Баги! Не подходи ко мне!",
    ["虽然可惜，但若你们都已想清楚，我会尊重你们的决定。有些人，只能陪着走一段人生的旅程。愿女神仍眷顾你们各自的前路。"] = "Хотя жаль, но если вы оба все обдумали, я буду уважать ваше решение. Некоторые люди могут сопровождать вас лишь часть жизненного пути. Пусть Богиня по-прежнему благоприятствует вашим дальнейшим путям.",
    ["虽然工厂主给了补偿，但家里要用钱的地方太多了。"] = "Хоть хозяин фабрики и выплатил компенсацию, в семье слишком много расходов.",
    ["虽然我真的很好奇下面有什么，但还是活着比较重要。"] = "Мне, конечно, до смерти любопытно, что там внизу, но собственная жизнь все-таки дороже.",
    ["虽然挣的苏勒变多了，但是总有种被当缉毒犬的感觉……"] = "Хотя я зарабатываю больше золотых суле, мне всегда кажется, что со мной обращаются как с собакой, вынюхивающей наркотики...",
    ["虽然看到你第一眼，我就知道崔佛那混蛋不是诚心的。"] = "Хотя в тот момент, когда я тебя увидел, я понял, что этот ублюдок Тревор не искренен.",
    ["虽然需要忍受一些难以克制的冲动，但生活安稳，家庭和睦。"] = "Хотя мне приходится терпеть некоторые неконтролируемые порывы, жизнь стабильна и семья гармонична.",
    ["西迦。是队长让你来的吗？"] = "Сика. Тебя капитан прислал?",
    ["西里尔，再给我点时间……好了，不要辜负金秋湖的景色，让我们暂时遗忘贝克兰德的一切。"] = "Кирилл, дай мне еще время... Ладно, не пропадай пейзажи озера Золотой Осени; давайте на время забудем все о Баклунде.",
    ["要不要看看我的货物？或者听听故事？"] = "Хотите увидеть мой товар? Или послушать историю?",
    ["要出发去哪里呢，{{先生|女士}}？"] = "Куда мы направляемся, мистер {{ Ms. |}}?",
    ["要开启名流之殿吗？"] = "Хотите открыть Зал Славы?",
    ["要我说，这纯属胡编，不过是斐谢尔那家伙想独占鱼贩的生意罢了！"] = "По мне, так это чистой воды выдумка! Просто Фишер хочет загрести всю торговлю рыбой под себя!",
    ["要是我的灵感高一些，就能用<P_Yellow>窥秘之眼</>看到残留的魔法痕迹了。"] = "Если бы мое Вдохновение было выше, я мог бы использовать <P_Yellow>Eyes of Mystery Prying</>, чтобы увидеть остаточные магические следы.",
    ["要是把比利急哭了，他下次就不跟我玩了……"] = "Если Билли расстроится и заплачет, в следующий раз он не будет со мной играть...",
    ["要是能尝尝他的酒就好了。哦不，我是说，我的南瓜比他的酒好多了，如果他想要的话，我当然可以慷慨地和他交换！"] = "Если бы я только мог попробовать его вино. О нет, я имею в виду, что мои тыквы намного лучше, чем его вино. Если он захочет их, я, конечно, могу щедро с ним обменять!",
    ["要是被我发现了什么宝贝，那我可就发财了！"] = "Если я найду какое-нибудь сокровище, я стану богатым!",
    ["要结婚了？恭喜你。"] = "Жениться? Поздравляю.",
    ["要给我摘一朵最漂亮最柔软的睡莲，真是个笨蛋！"] = "Он хочет сорвать для меня самую красивую и нежную кувшинку. Какой дурак!",
    ["要转一圈吗，{{先生|女士}}？"] = "Хотите совершить экскурсию, {{Mr.|Ms.}}?",
    ["要重置符号吗？"] = "Сбросить символы?",
    ["观察是一件很有趣的事，你觉得呢？"] = "Наблюдение — интересная вещь, вам не кажется?",
    ["规则很简单：拿起桌上的训练手枪，在六十秒内尽可能击中更多目标。"] = "The rules are simple: pick up the training pistol on the table and hit as many targets as possible within sixty seconds.",
    ["解读出来，能让人一步成神……哈哈，我开玩笑的。"] = "Расшифровав его, можно за один шаг сделать человека богом... хаха, я шучу.",
    ["誓约不易，解契更需慎重。这是你们共同编织的约定，真的要就此撕毁吗？再想想吧，{{先生|女士}}。"] = "Завет нелегко заключить, и его нарушение требует еще большей осторожности. Это обещание, которое вы сплели вместе; ты действительно хочешь его разорвать? Подумай об этом еще раз, {{Mr.|Ms.}}.",
    ["讨论这些有意义么……"] = "Есть ли смысл это обсуждать...",
    ["讨论？讨论被瑞克忽悠的倒霉新人……"] = "Обсуждаем? Обсуждаем неудачливого новичка, которого одурачил Рик...",
    ["让我们开始这场风尚决斗吧"] = "Давайте начнем эту дуэль моды.",
    ["让我假装品一品酒。"] = "Сделаю вид, будто дегустирую вино.",
    ["让我看看……《如何与灵界生物和平共处——从入门到放弃》？"] = "Дай-ка посмотреть... «Как мирно сосуществовать с существами духовного мира — от новичка до сдавшегося»?",
    ["让柯莱特研发出药剂可不是什么好事，你，你们忘了上次长出鳃和鱼尾的小白鼠了吗？"] = "Позволять Колетт варить зелья — к добру не приведет! Вы что, уже забыли ту белую мышь, у которой в прошлый раз выросли жабры и рыбий хвост?!",
    ["记住，在这项程序中，你的武器并非只有左轮与符咒，更是敏锐的观察、严密的逻辑与无畏的勇气。"] = "Помните, в этой процедуре вашим оружием станут не только револьверы и брелоки, но и острая наблюдательность, строгая логика и бесстрашная смелость.",
    ["试炼到此为止！你已经向我证明了你拥有足够的实力。"] = "Суд заканчивается здесь! Ты уже доказал мне, что обладаешь достаточной силой.",
    ["诗集新增的标点，如同给维纳斯接上了手臂。见鬼，这到底是谁的主意？"] = "Пунктуация, добавленная в сборник стихов, подобна прикреплению рук к Венере. Черт возьми, чья это была идея?",
    ["该封印物信息暂时不可查看。"] = "Сведения об этом Запечатанном Артефакте пока недоступны.",
    ["该死……托马斯爷爷，对不起。"] = "Черт побери... Дедушка Томас, прости.",
    ["该死的，他要是不死，有人可是要睡不着觉了。"] = "Черт возьми, если он не умрет, кто-то не сможет спать по ночам.",
    ["该死的，该死的，为了这条丝巾，我被当成变态，让警察先生狠狠地盘问了十分钟！"] = "Черт возьми, черт возьми. За этот шелковый шарф со мной обращались как с извращенцем и жестоко допрашивали в полиции в течение десяти минут!",
    ["该死的，这种闹鬼的祖宅，怎么可能卖得出去？"] = "Черт возьми, как можно было продать такой проклятый родовой дом?",
    ["该死，两边都是狙击手……"] = "Блин, снайперы есть с обеих сторон...",
    ["该死，没想到他们这么快就追来了，嘶，我中了一枪，顶不住了。这回看你的了。"] = "Черт возьми, я не ожидал, что они так быстро догонят. Хисс, меня подстрелили, я не могу держаться. Теперь дело за вами.",
    ["说不定他们在努力寻找公主的下落。"] = "Возможно, они усердно работают, чтобы найти принцессу.",
    ["说不定真的可以呢？"] = "Может быть, это действительно возможно?",
    ["说些什么呢？"] = "Что мне сказать?",
    ["说什么来着，这孩子心里装着全镇人的健康呢……这事儿急不得。"] = "Да что я сказал, у этого ребенка в сердце здоровье всего города... С этим делом нельзя торопиться.",
    ["说是奖励，其实是锁链。"] = "Она называет это наградой, но на самом деле это цепочка.",
    ["说来也巧，我深夜换班走了一半，发现地图和武器忘了带，赶紧原路折返。结果回去拿东西时，正好看见开膛手居然还在原地，正和另一个人在那儿低声交谈呢。"] = "Так случилось, что посреди ночи я был на полпути смены, когда понял, что забыл свою карту и оружие, поэтому поспешил обратно тем же путем, которым пришел. Когда я вернулся за своими вещами, я увидел, что Потрошитель все еще был на том же месте и что-то шептал кому-то другому.",
    ["说梦话吗……"] = "Разговариваю во сне, да...",
    ["说的这么厉害，这饮料真的有用？"] = "Это звучит впечатляюще. Действительно ли этот напиток работает?",
    ["说真的，我要回去了，这根本不是一位度假的绅士应该爬的山。"] = "Серьезно, я возвращаюсь. Это не та гора, на которую должен подняться джентльмен в отпуске.",
    ["说着“让我来考考你，霍纳奇斯山脉的古代遗迹由什么组成”……"] = "Говоря: «Позвольте мне проверить вас, из чего состоят древние руины горного хребта Хорнацис»…",
    ["说说你今天心情如何，我来为你推荐！"] = "Скажи мне, как ты себя чувствуешь сегодня, и я дам тебе рекомендацию!",
    ["说说看？"] = "Давайте послушаем?",
    ["说起来你到底为什么要偷吃田里的南瓜啊！"] = "Кстати говоря, с какой стати ты украл и съел тыкву в поле!",
    ["说这么玄乎，它真的这么有用？"] = "Звучит так таинственно... Неужели эта штука и правда настолько полезна?",
    ["诶？这报纸上的日期怎么是三十多年前的？……现在还在看吗？"] = "Э? Почему дата в этой газете датирована более тридцати лет назад?...Вы все еще читаете это сейчас?",
    ["请不要随意靠近，容易陷入混乱。"] = "Пожалуйста, не приближайтесь без нужды: легко поддаться хаосу.",
    ["请你冷静……"] = "Пожалуйста, успокойся...",
    ["请恕我失礼——我以为这座城堡，不会再有人来了。"] = "Простите, пожалуйста, за грубость — я думал, в этот замок больше никто не придет.",
    ["请您先试用一下它的能力，等完全掌握了它的用法再出发。"] = "Сначала испытайте его способности и отправляйтесь в путь лишь тогда, когда полностью освоите их.",
    ["请您小心点，不要踩到我给盔甲之神布置的祭坛。"] = "Пожалуйста, будьте осторожны, не наступайте на алтарь, который я установил для Бога Доспехов.",
    ["请按需借阅，按时归还。"] = "Пожалуйста, одалживайте по мере необходимости и возвращайте вовремя.",
    ["请支持我们吧！作为回报，我们愿意为你和伴侣的誓约仪式提供舞蹈表演。"] = "Пожалуйста, поддержите нас! Взамен мы готовы предоставить танцевальное представление для церемонии завета вас и вашего партнера.",
    ["请止步，{{先生|女士}}！前方区域封锁，警方办案，无关人员请勿靠近。"] = "Пожалуйста, остановись, {{Mr.|Ms.}}! Территория впереди оцеплена; Полиция ведет дело, посторонних лиц просьба не приближаться.",
    ["请沉醉在曲中吧……"] = "Упивайтесь этой мелодией...",
    ["请等一下，我需要一点时间回忆“烈焰”现在的赏金是多少……"] = "Пожалуйста, подождите немного, мне нужно немного времени, чтобы вспомнить, какова текущая награда «Пламя»…",
    ["请给我来一份今天的日报。"] = "Пожалуйста, дайте мне сегодняшнюю ежедневную газету.",
    ["请谨记：魔药的名称是扮演的钥匙。"] = "Пожалуйста, помните: название зелья является ключом к действию.",
    ["请跟我们来，侦探{{先生|女士}}，卧室就在那边……拜托了，请您务必查出真相。"] = "Пожалуйста, пойдем с нами, детектив {{Мистер|Мисс.}}, спальня вон там... Пожалуйста, пожалуйста, выясните правду.",
    ["请选择到达的站点。"] = "Пожалуйста, выберите станцию ​​назначения.",
    ["请问你需要帮助吗？"] = "Вам нужна помощь?",
    ["请问发生了什么？"] = "Могу я спросить, что случилось?",
    ["请问您认识一个叫戈多的人吗？"] = "Могу я спросить, знаете ли вы человека по имени Годо?",
    ["谁七老八十还要让你拍，都不好看了！"] = "Кто же станет фотографироваться под старость лет? Мы ведь уже не будем такими красивыми!",
    ["谁不知道霍纳奇斯山脉上的遗迹！"] = "Кто не знает о руинах на горном хребте Хорнацис!",
    ["谁杀了谁？"] = "Кто кого убил?",
    ["谁知道呢，好奇心太足有时候不是个好习惯。"] = "Кто знает, слишком большое любопытство иногда не является хорошей привычкой.",
    ["调这款酒需要特别的专注力， 喝它的人也需要。"] = "Смешивание этого напитка требует особой концентрации, и она нужна и человеку, его пьющему.",
    ["谢谢。"] = "Спасибо.",
    ["谢谢你女士。"] = "Спасибо вам, мадам.",
    ["谢谢你！这很贴心。"] = "Спасибо! Это очень продуманно.",
    ["谢谢你，{{先生|女士}}。这只是我的故事，也许别的骑士会经历更精彩的冒险。"] = "Спасибо, {{мистер|мисс}}. Это всего лишь моя история; возможно, других рыцарей ждут еще более великолепные приключения.",
    ["谢谢你，好心人！我想我很快就会过去。"] = "Спасибо, добрый человек! Думаю, я скоро буду там.",
    ["谢谢你，还是那么贴心，这是什么饮料？"] = "Спасибо, вы как всегда внимательны. Что это за напиток?",
    ["谢谢您的祝福，愿女神庇佑您！"] = "Спасибо за ваше благословение, пусть Богиня хранит вас!",
    ["谢谢惠顾，欢迎再来！"] = "Спасибо за ваше покровительство, приходите еще!",
    ["豆角有一股青草的香味，嚼着很有韧劲；而竹笋水分更足，吃起来脆嫩鲜甜。"] = "Зеленая фасоль имеет травянистый аромат и жевательная, а побеги бамбука более сочные, хрустящие, нежные и сладкие на вкус.",
    ["贝克兰德啊，这里藏着太多秘密，太多谎言，太多自以为藏得很好的东西。"] = "Бэкланд, оно скрывает слишком много тайн, слишком много лжи и слишком много вещей, которые, по мнению людей, хорошо спрятаны.",
    ["贝琳达，你听我说啊！是她勾引我的！"] = "Белинда, послушай меня! Она соблазнила меня!",
    ["负面效果是会让使用者一点点累积暴躁的情绪，这个只要定期发泄，就不存在问题，不过，它还有一个负面效果，那就是持有它的人，在无光的环境下，被黑暗深处恐怖怪物袭击的概率是百分之百！"] = "Негативный эффект заключается в том, что это заставит пользователя постепенно накапливать раздражительные эмоции. Это не проблема, если вентиляция осуществляется регулярно, но она имеет еще один отрицательный эффект: человек, держащий его, со 100% вероятностью подвергнется нападению ужасающих монстров в глубине тьмы, находясь в темноте!",
    ["负面效果是会让携带者心理逐渐阴暗，总是希望走捷径，用阴谋，靠不光彩的手段做事。此外，佩戴超过3分钟后，使用者自身也会陷入混乱的状态。"] = "Негативный эффект заключается в том, что психология носителя постепенно становится темной, он всегда надеется срезать путь, использовать заговоры и полагаться на бесчестные средства для достижения целей. Кроме того, после ношения его более 3 минут пользователь сам впадет в состояние хаоса.",
    ["负面效果是使用者将对自身实际力量产生误判，且在短期内对周围环境的感知能力将降低，容易丢失物品。"] = "Негативным эффектом является то, что пользователь будет неправильно оценивать свою реальную силу, и его восприятие окружающей среды в краткосрочной перспективе ухудшится, что позволит легко потерять предметы.",
    ["负面效果是使用者进入循环空间后，每一次循环，手上会随机出现一个机关谜题，需要在限定时间内解开，否则会被吞噬、转化为一个全新的机关谜题。"] = "Негативный эффект заключается в том, что после того, как пользователь входит в пространство цикла, с каждым циклом у него в руке случайным образом появляется механическая головоломка. Ее необходимо решить за ограниченное время, иначе они будут сожраны и превращены в совершенно новую механическую головоломку.",
    ["负面效果是只要佩戴着它，你就永远无法感受到凉爽，始终处于可怕的炎热里。"] = "Негативный эффект в том, что пока вы его носите, вы никогда не сможете чувствовать прохладу, постоянно находясь в жуткой жаре.",
    ["负面效果是时刻头痛，恨不得撞墙。"] = "Отрицательный эффект — постоянная головная боль, от которой хочется лезть на стену.",
    ["财富从不属于谨慎的人。"] = "Богатство никогда не принадлежит осторожным.",
    ["赏景？坐在自家花园里来一份下午茶不比在这里漫无目的走路要好？"] = "Любоваться пейзажем? Разве чашечка послеполуденного чая в собственном саду не лучше, чем эти бесцельные блуждания?",
    ["赞美女神。这次我将踏上正确的道路。"] = "Слава Богине. На этот раз я вступлю на правильный путь.",
    ["赞美睡莲……"] = "Славься, кувшинка...",
    ["走吧。在种子生根之前，打碎那面该死的镜子。"] = "Пойдем. Прежде чем семена укоренятся, разбейте это проклятое зеркало.",
    ["走错路了？前面怎么是悬崖？"] = "Свернул не туда? Почему впереди обрыв?",
    ["赶紧的，找人！！"] = "Спешите найти ее!!",
    ["跑腿？这是学徒高贵的开门技能！"] = "Курьерские поручения? Это благородный навык «Отпирание» Ученика!",
    ["跟着我的节奏，不要思考……只要……感受。"] = "Следуй моему ритму, не думай... просто... чувствуй.",
    ["路见不平就挺身而出。"] = "Шагать вперед всякий раз, когда есть несправедливость.",
    ["身居高位而博爱开明，赞美我主！"] = "Занимая высокое положение, будучи доброжелательным и просвещенным, хвала моему Господу!",
    ["身披羽毛的恶棍！长了翅膀的老鼠！我以女神的名义发誓，我要把你们整个家族驱逐！"] = "Пернатые мерзавцы! Крылатые крысы! Клянусь именем Богини, я изгоню весь ваш род!",
    ["车头有撞击的凹痕，但人完整带回来了，干得很有效率，顾问{{先生|女士}}。"] = "На передней части кареты осталась вмятина от удара, но человека доставили целым и невредимым. Очень эффективная работа, консультант {{Mr.| Ms.}}.",
    ["轻取？这山怎么轻取？"] = "Легко поймать? Как легко захватить эту гору?",
    ["达克耶派的，伟大的达克耶！"] = "Школа Дэйкай, великий Дэйкай!",
    ["达克耶？"] = "Дакай?",
    ["达到20、30和45分，会分别解锁一档奖励。分数足够时，可以一次获得多个宝箱。"] = "Reaching 20, 30, and 45 points will unlock a tier of rewards respectively. When you have enough points, you can obtain multiple treasure chests at once.",
    ["过了好久，一个都没来！"] = "Прошло столько времени, а ни один не пришел!",
    ["过了桥靠左走。"] = "Перейдите мост и держитесь левой стороны.",
    ["过去？很遗憾，没什么能和您逗趣的故事。"] = "Прошлое? Извините, нет истории, которая могла бы вас развлечь.",
    ["运气爆棚？"] = "Переполняющая удача?",
    ["还不是那些商业顾问告诉巴纳比队长，霍纳奇斯有古代文明留下的宝藏。"] = "Это потому, что эти бизнес-консультанты сказали капитану Барнаби, что у Хорнациса есть сокровища, оставленные древними цивилизациями.",
    ["还好吧？可能是恶作剧？"] = "Ты в порядке? Может это шутка?",
    ["还好这本书不是赃物。也多亏丝巾那件事已经解释清楚，警察先生才放我出来……"] = "К счастью, эта книга не оказалась краденой. Да и то недоразумение с шелковым шарфом удалось прояснить, так что господин констебль отпустил меня...",
    ["还差一步……我就能找到。"] = "Еще один шаг... и я найду его.",
    ["还带着我们一起出来吃苦，是好事吗？你清醒点吧伙计。"] = "И она вывела нас страдать вместе. Это хорошо? Просыпайся, приятель.",
    ["还想尝尝别的特调吗？"] = "Хотите попробовать другие авторские напитки?",
    ["还把我喝醉的事报告给巴纳比队长！"] = "Они даже сообщили, что я напился капитану Барнаби!",
    ["还是下次再问吧。"] = "Лучше спрошу в следующий раз.",
    ["还是等店家回来再说吧。"] = "Я подожду, пока вернется продавец.",
    ["还是算了，我不太喜欢喝酒。"] = "Забудь об этом, я не очень люблю пить.",
    ["还有……别盯着任何人看太久。在这里，被注视的感觉并不好受。"] = "И еще... не смотри ни на кого слишком долго. Чужие взгляды здесь мало кому по душе.",
    ["还有一件事，给老子记住——"] = "И еще одно: ты меня послушай…",
    ["还有什么需要的吗？"] = "Есть ли что-нибудь еще, что вам нужно?",
    ["还有别的想知道的吗？历代镇子管理员的资料？小镇周边交通地图？我这儿都有！"] = "Есть ли что-нибудь еще, что вы хотите знать? Информация о прошлых городских администраторах? Карты дорожного движения по городу? У меня все это есть здесь!",
    ["还有这本亲签典藏小说《大冒险家》……这本书，我可是从二道贩子手里买的！"] = "А этот коллекционный роман с автографом «Великий авантюрист»… Эту книгу я купил у спекулянта!",
    ["还有这本笔记，据说是某个古老笔记的翻版，里面记录了一些消息。"] = "И ещё эта тетрадь: говорят, это копия неких древних записей, содержащая важные сведения.",
    ["还没到工作的点，恕不接待！再见！"] = "Ещё не рабочее время, я отказываюсь вас обслуживать! До свидания!",
    ["还要了解哪些方面？"] = "Что еще вам нужно знать?",
    ["这“证据”可以是一份文件，一件封印物，或者……一句来自鹦鹉的证词。关键在于，要让谎言在逻辑的重压下自行崩溃。"] = "Этим «доказательством» может быть документ, Запечатанный Артефакт или... показания попугая. Главное – позволить лжи рухнуть под тяжестью логики.",
    ["这……下次、下次一定！我还有事得先走了！"] = "Э-э... в следующий, в следующий раз обязательно! У меня дела, так что я побегу!",
    ["这……这不方便说啊，你从那边上二楼，会有人给你答案的。"] = "Это... неудобно говорить. Если вы подниметесь оттуда на второй этаж, кто-то даст вам ответ.",
    ["这一切都离不开具体的生活，身份，还有人。"] = "Все это неотделимо от конкретной жизни, личности и людей.",
    ["这一定是很有意义的信物吧。"] = "Это должно быть очень значимый знак.",
    ["这一片的位置，都有人。请你去别处，谢谢。"] = "Эта территория оккупирована. Пожалуйста, сходите куда-нибудь еще, спасибо.",
    ["这不仅仅是对罪犯的指控，更是一种灵性层面的“宣判”，能有效震慑其背后的隐秘力量，迫使真相显形。"] = "Это не просто обвинение в адрес преступника, а «приговор» на духовном уровне, который может эффективно сдерживать скрытые силы, стоящие за ним, и заставить правду проявиться.",
    ["这不能怪我，一直以来我准备的角色都是格尔曼·斯帕罗，可到招新会前夜，迪文娜学姐才通知我之前准备的布料只够给兔子做衣服了。"] = "Меня нельзя винить в этом. Я всегда готовился к роли Германа Воробья, но только накануне вечером, накануне набора, Старшая Дивина сообщила мне, что подготовленной мной ткани хватит только на пошив одежды для кролика.",
    ["这个光线和角度，一定能给克塞娜拍出最漂亮的结婚照！"] = "При таком освещении и ракурсе я обязательно смогу сделать для Зены самую красивую свадебную фотографию!",
    ["这个嘛……咳咳，实话跟你说吧，老约翰。 "] = "Что касается этого... *кхе-кхе*, по правде говоря, Старый Джон.",
    ["这个嘛……她只喜欢乖小孩，比如会好好吃掉胡萝卜的那种！"] = "Ну... ей нравятся только хорошие дети, такие, которые правильно едят морковку!",
    ["这个宝箱似乎有一个复杂的锁具。"] = "Кажется, у этого сундука с сокровищами сложный замок.",
    ["这个封印物必须由序列7以上的非凡者使用才能抵抗住产生的幻觉啊。"] = "Этот Запечатанный Артефакт должен использоваться Потусторонним из Последовательности 7 или выше, чтобы противостоять вызываемым им галлюцинациям.",
    ["这个小镇都要没什么人吃鱼了！全怪那个该死的沼泽女巫！"] = "В этом маленьком городке уже почти никто не ест рыбу! Во всем виновата эта чертова Болотная Ведьма!",
    ["这个年纪，人思想成熟，也有些经济能力了，好选择！"] = "В этом возрасте люди становятся зрелыми и обладают некоторой финансовой стабильностью. Хороший выбор!",
    ["这个怀表，您也可以叫它——“时空道标”。"] = "Эти карманные часы вы также можете назвать «Маяк пространства-времени».",
    ["这个手感……好像是木头？这边的是……海绵？"] = "Эта текстура... похожа на дерево? А эта сторона... губка?",
    ["这个方向的尽头就是警局总部……她是故意的。"] = "Конец этого направления – полицейское управление... Она сделала это специально.",
    ["这个木头就喜欢到外面去画画。说好南瓜收获前回来……算了，不提了！"] = "Этот болван просто обожает выходить на улицу и рисовать. Он обещал вернуться до сбора тыквы... Забудь об этом, не будем об этом!",
    ["这个水池被沼泽女巫诅咒了，碰到水的人会连做噩梦好几天！"] = "Этот пруд был проклят Болотной Ведьмой; любому, кто прикоснется к воде, будут сниться кошмары несколько дней!",
    ["这个灵恐怕十分强大，普通的感知已经无法维持！"] = "Этот дух, должно быть, невероятно силен — обычного восприятия уже недостаточно!",
    ["这么多面包也没人看着？"] = "Столько хлеба и никто не смотрит?",
    ["这也不是什么有罪的事情吧。"] = "В этом ведь нет никакого преступления, верно?",
    ["这也是我的系列创作，“注视爱人”，大概会一直拍到我们七老八十。"] = "Это также часть моей серии «Взгляд на любовника». Я, вероятно, буду продолжать принимать их, пока мы не состаримся и не поседеем.",
    ["这也能忘？！"] = "Ты вообще можешь это забыть?!",
    ["这些东西都有个共同点，你知道是什么吗？没人真的见过它们！"] = "У всех этих вещей есть одна общая черта, знаете ли вы, что это такое? На самом деле их никто никогда не видел!",
    ["这些家伙……是把我当许愿机了吗！"] = "Эти ребята... они думают, что я машина, исполняющая желания!",
    ["这些村民好像在聊最近的怪事……"] = "Эти жители деревни, похоже, рассказывают о недавних странных происшествиях...",
    ["这些葡萄看上去好极了！"] = "Этот виноград выглядит великолепно!",
    ["这些都是我的称号，好吗？好的。"] = "Это все мои титулы, ясно? Хорошо.",
    ["这会是一段令人振奋的旋律。"] = "Это будет поднимающая настроение мелодия.",
    ["这位{{先生|女士}}，能占用一下您的时间吗？我想给您讲一讲我主，“愚者”先生。"] = "Этот {{Mr.|Ms.}}, могу я отнять у вас минутку? Я хотел бы рассказать вам о моем господине, господине «Шуте».",
    ["这位{{先生|女士}}，请问您认识戈多吗？"] = "Это {{ Mr. | Ms. }}, могу ли я спросить, знаешь ли ты Годо?",
    ["这位先生，你是收发员吗？"] = "Сэр, вы диспетчер?",
    ["这位同学，遇到什么问题了吗？"] = "Студент, у вас возникли какие-то трудности?",
    ["这位女士就交给我吧，会有专业人士来帮助她处理失控的。你做的很好。"] = "Оставьте эту даму мне: сейчас прибудут специалисты, чтобы помочь ей справиться с Потерей Контроля. Вы отлично сработали.",
    ["这位客人，您也想与我共舞一曲吗？"] = "Гость, не хочешь ли ты потанцевать со мной?",
    ["这位客人，请您不要质疑我作为通灵者的能力！只是我需要更多的……呃……苏勒，才能继续沟通！"] = "Уважаемый гость, прошу вас не сомневаться в моих способностях Медиума! Просто мне нужно больше... э-э... соли, чтобы продолжить спиритический сеанс!",
    ["这位客人，这里是私密区域。"] = "Этот гость, это частная зона.",
    ["这位是商会委派的专职列车员。他带来了“区域经销协议”，具体的经营规则，将由他为您介绍。"] = "Это штатный кондуктор, назначаемый Торгово-промышленной палатой. Он принес «Соглашение о региональной дистрибуции», и он познакомит вас с конкретными правилами работы.",
    ["这则预言是什么意思？"] = "Что означает это пророчество?",
    ["这到底是事实还是传说！写得太精彩了！要是能单独出书就好了。"] = "Это факт или легенда! Это так гениально написано! Было бы здорово, если бы она была издана отдельной книгой.",
    ["这卷心菜，紧实得像个守财奴的钱包，谁都别想掰开一片叶子！"] = "Эта капуста тесна, как кошелек скряги; никто не снимет с него ни одного листочка!",
    ["这变化当然是个好事，我能轻易感应哪个物品比较贵重。"] = "Это изменение, безусловно, было хорошо; Я легко мог почувствовать, какие предметы были более ценными.",
    ["这只狒狒为什么这么兴奋？"] = "Почему этот бабуин так взволнован?",
    ["这只狒狒怎么看着愁眉苦脸的？"] = "Почему этот павиан выглядит таким несчастным?",
    ["这只猪的嘴里咬着……珍珠项链？"] = "Эта свинья кусает... жемчужное ожерелье?",
    ["这地儿也不安全，先冲出去，别废话。"] = "Это место тоже небезопасно, давайте сначала нападем, больше никаких разговоров.",
    ["这地方我待了三年，哪个角落的花几点开、什么光线最适合拍摄，我比蜜蜂还清楚！ "] = "Я нахожусь в этом месте уже три года. Я знаю, какие цветы в какое время цветут в каждом уголке и какое освещение лучше всего подходит для фотографии, лучше, чем у пчел!",
    ["这地方真是美，简直美得不真实！"] = "Это место действительно красивое, настолько красивое, что кажется нереальным!",
    ["这城堡荒废了几百年，真有什么古董，能轮到他？"] = "Этот замок заброшен уже сотни лет. Будь там настоящий антиквариат, разве он достался бы ему?",
    ["这家店是埃莉诺和托马斯一起开起来的，都几十年了。 "] = "Этот магазин открыли Элеонора и Томас вместе, прошло уже несколько десятилетий.",
    ["这就是你介绍的饭票！主人是个吃人血肉的怪物！"] = "Это талон на питание, который вы представили! Хозяин — монстр, питающийся человеческой плотью и кровью!",
    ["这就是矛盾所在！壁画里显示这个国度的人民有关于死亡的风俗，却完全不涉及下葬的部分，就好像这里的居民不需要安葬，也不会死亡！"] = "Вот в чем противоречие! Фрески показывают, что у жителей этого королевства были обычаи относительно смерти, но они вообще не предполагают погребения, как будто жителей здесь не нужно хоронить и они не умрут!",
    ["这座小镇真是美极了，你不觉得吗？"] = "Этот маленький городок действительно прекрасен, вам не кажется?",
    ["这才有了现在的我，{{先生|女士}}。"] = "Так я стал тем, кем являюсь сегодня, {{Mr.|Ms.}}.",
    ["这把枪我已经改装过了，能对那帮复制体造成真实伤害。"] = "Я уже модифицировал это ружье; он может нанести реальный ущерб этим репликам.",
    ["这是一段令人振奋的旋律。"] = "Это поднимающая настроение мелодия.",
    ["这是个怀旧的选择。橙皮和肉桂的香气会让您放松下来。"] = "Это ностальгический выбор. Аромат апельсиновой цедры и корицы поможет вам расслабиться.",
    ["这是为了让森林之主记得我们取走的份额，庇佑我们丰收常在。"] = "Это сделано для того, чтобы Хозяин Леса помнил о той доле, которую мы взяли, и благословил нас постоянным урожаем.",
    ["这是什么流派的诗？"] = "Что это за поэтическая школа?",
    ["这是什么营地？ "] = "Что это за лагерь?",
    ["这是什么？神神秘秘的。"] = "Что это? Такой загадочный.",
    ["这是佛尔思女士托我给您的，它能帮助您打开前进的通路。"] = "Вот что мне доверила передать вам мисс Форс; это может помочь вам открыть путь вперед.",
    ["这是可以说的吗？老天，能不能来个人让他们闭嘴？"] = "Можно ли это сказать? Боже, может ли кто-нибудь заставить их замолчать?",
    ["这是唯一的机会。去吧，把他的线，一根根斩断。"] = "Это единственный шанс. Иди, перерезай его линии, одну за другой.",
    ["这是崔佛警官让我交给你的封印物“共感手铐”，他说用这个就可以暂时压制住她的失控进程。"] = "Офицер Тревор просил передать вам этот Запечатанный Артефакт — «Наручники сопереживания». Он сказал, что с их помощью можно временно сдержать процесс Потери Контроля.",
    ["这是我们仅有的找到睡莲仙女的线索，说什么都不能放弃！"] = "Это наш единственный ключ к поиску Феи Водяной Лилии; мы не можем сдаться, несмотря ни на что!",
    ["这是我们的许愿池呀，你不知道吗？"] = "Это наш пул желаний, ты не знал?",
    ["这是我带过的最差一届乐团！"] = "Это худший оркестр из всех, которыми я руководил!",
    ["这是我的感谢，希望你未来一切顺利。"] = "Это моя благодарность, надеюсь, что в будущем у вас все будет хорошо.",
    ["这是灵异事件。那些东西被埋起来，还配上墓碑……像是某种预兆。"] = "Это паранормальное явление. Эти вещи были закопаны да ещё и снабжены надгробиями... прямо как дурное предзнаменование.",
    ["这是给孩子们留下的惊喜？"] = "Это сюрприз для детей?",
    ["这是，这是奶茶！你不是要教我配催眠药剂的吗？"] = "Это, это чай с молоком! Разве ты не собираешься научить меня готовить зелье гипноза?",
    ["这杯酒里带着古老的气息，至于是什么……抱歉，我只能保密。"] = "В этом вине чувствуется древнее дыхание, а вот какое именно... прошу прощения, но это тайна.",
    ["这杯饮品有一股浓郁的薰衣草香气，自己品尝时，它只是一杯爽口的茶。但如果请你爱的人喝下，那个人就会永远无药可救的爱着你。"] = "У этого напитка насыщенный аромат лаванды. Для тебя это просто освежающий чай. Но если напоить им того, кого любишь, этот человек полюбит тебя до безумия и навсегда.",
    ["这样只顾睡觉不干活，万一被领导发现怎么办！"] = "Если ты просто спишь и не работаешь, что ты будешь делать, если твой начальник узнает!",
    ["这样吗？那正好，他们一定猜不到我们有火枪这种东西，正好方便我们行动。"] = "Это так? Отлично. Они точно не догадаются, что у нас есть что-то вроде мушкета, который облегчит нашу работу.",
    ["这样的曲子适合独自思考，帮助梳理纷乱的思绪。 "] = "Такое произведение подойдет для самостоятельного размышления, помогая разобраться в хаотичных мыслях.",
    ["这次……大概两个月了吧？"] = "На этот раз... около двух месяцев, я полагаю?",
    ["这次是斧子，墓碑上是你的名字……"] = "На этот раз это топор, и твое имя на надгробии...",
    ["这次考古回去，我的博士论文就有着落了。等我通过副教授面试……就能给你更好的生活。"] = "После этой археологической поездки моя докторская диссертация будет защищена. Как только я пройду собеседование на доцента... я смогу дать тебе лучшую жизнь.",
    ["这款饮品只要让背叛你的对象喝下，他就会追悔莫及，回来向你道歉。"] = "Если вы позволите человеку, который вас предал, выпить это, он пожалеет об этом и вернется, чтобы извиниться перед вами.",
    ["这段记忆......是谁放进来的？"] = "Эта память... кто ее вложил?",
    ["这片冰湖原本是我选择的长眠之地，在我看到盛夏时的它时……可它现在冻住了。"] = "Это ледяное озеро изначально было местом отдыха, которое я выбрал, когда увидел его в середине лета... но сейчас оно замерзло.",
    ["这确实是片丰饶的土地，也许用南瓜作为设计主题……"] = "Это и впрямь благодатная земля, может, взять тыкву за основу темы дизайна...",
    ["这种事情……是应该记得很清楚吗？奇怪，那我怎么会不记得……"] = "Это такие вещи... которые следует ясно помнить? Странно, тогда почему я не помню...",
    ["这种传统的手艺活，怎么能叫骗呢？那些阔老爷们要的不就是刚挖出来的那种感觉吗？"] = "Как такое традиционное мастерство можно назвать мошенничеством? Разве не этого хотят эти богатые джентльмены — что его только что выкопали?",
    ["这种宁静的，只需要思考下一顿吃什么的生活，在来到塔罗学派之前，我连想都不敢想。"] = "Такую мирную жизнь, где нужно думать только о том, что съесть на следующий прием пищи, я даже представить себе не смела до прихода в Клуб Таро.",
    ["这群人再不努力，我们乐团就要和镇子里的老年乐团沦为一个档次了！"] = "Если эти бездельники не начнут стараться, наш оркестр скатится до уровня городского ансамбля стариков!",
    ["这耗尽了她的力量，不得不陷入沉睡，但直到现在，她也在暗处守护着我们。"] = "Это истощило ее силы, заставив ее погрузиться в глубокий сон, но даже сейчас она продолжает охранять нас от теней.",
    ["这花好看，那花也好看，这虫子可爱，那虫子也可爱！要不再去摘点葡萄吧……"] = "Этот цветок красивый, тот цветок тоже красивый, этот жук милый, этот жук тоже милый! Может, мне лучше пойти собрать виноград...",
    ["这规矩你早懂的。"] = "Вы уже знали это правило.",
    ["这说明，童话里的都是真的，不是骗人的，它们真实发生过。所以，这个世界……"] = "Это показывает, что в сказках все правда, а не ложь; они действительно произошли. Поэтому этот мир...",
    ["这里卖些什么？"] = "Что вы здесь продаете?",
    ["这里四下无人，还是凶杀事故的多发地，上过不少次老实人报呢。"] = "Здесь ни души вокруг, к тому же это место частых убийств — про него не раз писали в газете «Честный человек».",
    ["这里存放着塔罗学派中大部分神奇物品，由学派内部的“看守者”轮值。"] = "Здесь хранится большинство мистических предметов Клуба Таро, которые чередуются «Хранителями» внутри школы.",
    ["这里已经不剩什么难题了呢，快去迎接你的……"] = "Сложных задач здесь не осталось, поспешите встретить своего...",
    ["这里恰好有火车站点，我立刻为您联系商会，或许可以借用铁轨进行一些行商贸易！请您稍微等待一些日子。"] = "Здесь как раз расположена железнодорожная станция. Я немедленно свяжусь для вас с торговой палатой: возможно, нам удастся использовать пути для коммерческих перевозок! Пожалуйста, подождите несколько дней.",
    ["这里是哪里？我们登顶了吗？"] = "Где это? Достигли ли мы вершины?",
    ["这里是巴纳比队长组织的寻宝队。"] = "Это команда по поиску сокровищ, организованная капитаном Барнаби.",
    ["这里曾被规划为一片小小的城堡，可惜在许多遗憾后，它并没能最终落成。"] = "Когда-то это место планировалось как небольшой замок, но, к сожалению, после многих сожалений, он так и не был достроен.",
    ["这里水流很急，能钓到鱼吗？"] = "Течение здесь очень сильное. Сможете ли вы поймать любую рыбу?",
    ["这里没有人吗？"] = "Здесь никого нет?",
    ["这里的一切不会真的夺走你的生命，但它们制造的恐惧是真实的。"] = "Все здесь не отнимет у вас жизни, но ужас, который они создают, реален.",
    ["这里的招牌菜是？"] = "Какое здесь фирменное блюдо?",
    ["这里究竟发生过什么……"] = "Что же здесь произошло...",
    ["这里能够在一定程度上抑制灵感，在外面我总会听不见别人听不见的声音，陷入恍惚的状态，在这里就不会，很舒服，很宁静。"] = "Здесь это может в определенной степени подавить мое Вдохновение. Снаружи я всегда слышу голоса, которые не могут услышать другие, впадая в транс. Здесь этого не происходит; это очень удобно и спокойно.",
    ["这里至少安静些，没有那些轰鸣声。"] = "По крайней мере здесь тише, без этих ревущих звуков.",
    ["这里还可以继续打磨……"] = "Тут еще можно отполировать...",
    ["这里风景优美，镇上也很温馨，最重要的是拉姆德古堡——来的人一定不会错过。"] = "Здесь прекрасные пейзажи, городок очень уютный, а главное — старинный замок Ламуд: приезжие ни за что его не пропустят.",
    ["这镇子一年到头没几件新鲜事，我偶尔转转，帮帮初到此处的旅客。"] = "В этом городе круглый год практически не происходит ничего нового. Я иногда гуляю и помогаю путешественникам, которые впервые побывали в этом месте.",
    ["这难道不是赛斯在女神的神国谴责我吗？他和斐乐根本不认识啊！"] = "Разве это не Сет осуждает меня в Царстве Божьем? Он и Фела даже не знают друг друга!",
    ["这鬼地方！泥巴溅到我靴子上了，你知道吗？这双可是贝克兰德最好的皮匠手工定制的！ "] = "Это богом забытое место! Грязь забрызгала мои ботинки, ты это знаешь? Их сделал на заказ лучший сапожник Баклунда!",
    ["这，这是怎么回事？"] = "Это, что происходит?",
    ["这，这样不好吧……<P_Heart>（害羞）</>"] = "Э-это было бы нехорошо... <P_Heart>(застенчиво)</>",
    ["进去之后，好好欣赏台上那些卖力的“木偶”吧。"] = "После того, как вы войдете, насладитесь этими трудолюбивыми «марионетками» на сцене.",
    ["进去吧。但请记住，在里面，醉是礼貌，醒是冒犯。别打破规矩。"] = "Заходите. Но помните: быть пьяным — это вежливо, а трезвым — оскорбление. Не нарушайте правила.",
    ["进来吧，年轻人，要下雨了。"] = "Заходи, юноша, скоро пойдет дождь.",
    ["连他去世的时候也一样，我们那时候才二十多岁，他说：“卡尔啊，其实你的那些奇思妙想都不会成功的。但我最喜欢你乱鼓捣的样子！”"] = "Даже перед самой смертью он не изменился. Нам тогда едва перевалило за двадцать, и он сказал: «Карл, по правде говоря, твои сумасбродные затеи обречены на провал. Но больше всего на свете я люблю наблюдать, как ты что-то мастеришь!»",
    ["连同我们的份，赢下这场赌局……"] = "Выиграйте эту игру и для нас тоже...",
    ["迟到整整两个小时！你们这些乡巴佬懂不懂什么叫守时？"] = "Опоздать на целых два часа! Вы, деревенщина, вообще понимаете, что такое пунктуальность?!",
    ["迪西馅饼？豌豆炖羊羔肉？……要不还是红焖达格亚牛小排？"] = "Дикси пирог? Тушеная баранина с горошком? …Как насчет тушеных коротких ребрышек из говядины дагоя?",
    ["迷途的旅人啊，快铭记她眼眸中的玫瑰——"] = "Заблудившийся путник, скорей вспомни розу в ее глазах —",
    ["退后，别找抽。"] = "Отойди, не ищи побоев.",
    ["适合那些想暂时忘却明天，抑或是寻找过去的人。"] = "Подходит для тех, кто хочет на время забыть завтрашний день или ищет прошлое.",
    ["通过对时空扭曲与微观粒子运动的量子力学分析……"] = "С помощью квантовомеханического анализа искажений пространства-времени и движения микроскопических частиц...",
    ["那……"] = "Тогда...",
    ["那上面都是些看不懂的鬼画符，我却差点因此死在下水道里。"] = "Он был полон призрачных символов, которые я не мог понять, но из-за этого чуть не умер в канализации.",
    ["那个古董贩子跟你聊了什么，又是去看真品古董那套说辞？"] = "О чем с тобой болтал тот антиквар? Это был тот самый старый лозунг «приходите посмотреть на настоящий антиквариат»?",
    ["那个时候，托马斯酿的麦芽酒香得能把隔壁镇子的酒鬼都勾过来。埃莉诺烤的派也是一绝，皮酥得咬一口能掉渣。 "] = "Тогда эль, сваренный Томасом, пах так хорошо, что мог заманить сюда пьяниц из соседнего города. Пироги Элеоноры тоже были шедевром; корка была настолько шелушащейся, что могла рассыпаться от одного укуса.",
    ["那个疯狂的戏剧家给我寄了张烧焦的戏票，约我在这个路口看演出。"] = "Этот сумасшедший драматург прислал мне сгоревший билет в театр и предложил посмотреть спектакль на этом перекрестке.",
    ["那个穿大衣的商人，开口就是三百金镑，说要把这里改成时髦的咖啡馆。 "] = "Этот торговец в пальто сразу предложил триста золотых фунтов, заявив, что хочет превратить это место в модное кафе.",
    ["那么大一个南瓜，我只是饿了，在底部挖了个孔，把南瓜软软的瓤掏光了而已啊……"] = "Тыква была такая большая, что я просто проголодался, поэтому выкопал в дне ямку и вычерпал мягкую мякоть...",
    ["那也有可能是你根本就看错了，我反正才不会相信世界上有鬼魂。"] = "Также возможно, что вы просто ошиблись. В любом случае, я не поверю, что на свете существуют призраки.",
    ["那买束花带走吧！"] = "Тогда купи букет с собой!",
    ["那些年轻的孩子总想着去外面的世界，外面到底有什么好的！"] = "Эти маленькие дети всегда думают о выходе во внешний мир. Что такого хорошего снаружи!",
    ["那件非凡物品让男爵察觉了异常，他发现自己被观察，发现某种东西藏在这座宅邸里。但也正因为它，吸引来了某种特殊的存在，导致了男爵的死。"] = "Этот предмет Потустороннего сообщил Барону об аномалии; он обнаружил, что за ним наблюдают, и обнаружил, что в этом особняке что-то спрятано. Но именно из-за этого оно привлекло некое особое существование, приведшее к смерти барона.",
    ["那你不应该练习面试的问题吗？"] = "Тогда не следует ли вам попрактиковаться в вопросах на собеседовании?",
    ["那你为什么在祭坛边跳舞？"] = "Тогда почему ты танцуешь у алтаря?",
    ["那你们找到什么了？"] = "Так что же вы нашли?",
    ["那你又为什么会出现在这里？嗯？"] = "Тогда почему ты здесь? Хм?",
    ["那你喜欢什么样性格的呢？"] = "Тогда какая личность тебе нравится?",
    ["那你就是要解决爱情难题的特制饮品喽~ 保证解决你的所有恋爱问题！"] = "Значит, ты тот особенный напиток, который решает любовные проблемы~ Я гарантирую, что он решит все твои романтические проблемы!",
    ["那你就问对人了！这里是不错的旅游小镇，附近的城市——尤其是廷根市，有很多人愿意趁着周末过来走一趟呢。"] = "Тогда вы обратились по адресу! Это прекрасный туристический городок: многие жители окрестных городов — особенно Тингена — с удовольствием приезжают сюда на выходные.",
    ["那你算是挑对了，这是今天早上我刚从我家地里摘的南瓜！我帮你切开打包！"] = "Вы выбрали правильный вариант; Я только сегодня утром собрал это со своего поля! Позвольте мне разрезать его и упаковать для вас!",
    ["那你练的这个是谁告诉你的？"] = "Тогда кто сказал вам практиковать это?",
    ["那你说该怎么办吧。"] = "Тогда ты скажешь мне, что нам следует делать.",
    ["那你需要一杯 “梦想成真”。这款饮品入口时有蜂蜜般甜蜜柔软的味道，片刻之后烈酒基底则会慢慢上涌，让你心跳加速。"] = "Тогда вам нужен бокал «Dream Come True». Этот напиток имеет медовый сладкий и мягкий вкус при входе, а через мгновение основа крепкого напитка будет медленно подниматься, заставляя ваше сердце биться чаще.",
    ["那危机感有什么用？"] = "И какая тогда польза от предчувствия опасности?",
    ["那又怎样？我做的可是这个镇上最清闲的工作。"] = "Ну и что? У меня самая неторопливая работа в этом городе.",
    ["那可不只是矛盾！"] = "Это не просто конфликт!",
    ["那可不是随随便便就能操控的，刚入塔罗学派的学生我都不推荐，毕竟那需要控制好冰霜和火焰的力量。"] = "Это не то, что вы можете контролировать случайно. Я не рекомендую это студентам, которые только что присоединились к Клубу Таро; в конце концов, для этого нужно контролировать силу мороза и огня.",
    ["那可是托人从贝克兰德最有名的钓具店买回来的！"] = "Её же специально заказывали в самом знаменитом рыболовном магазине Бэкланда!",
    ["那名超凡者是律师途径序列X，能力是XXX，演讲区域已经被禁止使用超凡能力。"] = "Этот Потусторонний — это последовательность X пути Юриста со способностью XXX; в области речи запрещено использовать силы Потустороннего.",
    ["那后来呢？你换班的时候他还在吗？"] = "А потом? Он все еще был там, когда вы меняли смену?",
    ["那咆哮的海，是众神斟满的酒杯！"] = "Это ревущее море — бокал вина, наполненный богами!",
    ["那她去了哪里？有没有告诉你什么时候回来？"] = "Тогда куда она пошла? Она сказала тебе, когда вернется?",
    ["那孩子胆子小，却很诚实，连偷懒被发现都会脸红一整天。"] = "Этот ребенок робок, но очень честен; он даже краснеет весь день, если его поймают на безделье.",
    ["那它可能是来找东西的！就像我上次找不到玩具熊那样着急。"] = "Тогда, может, оно что-то искало! Прямо как я, когда никак не могла найти своего плюшевого мишку.",
    ["那家店的暗号是“醉汉”！"] = "Пароль от этого магазина — «Пьяница»!",
    ["那就是一个圆形了，哪里是正午呢？"] = "Это был бы круг; где полдень?",
    ["那就难办了，你带路，我们去布置仪式的地方！"] = "That makes things difficult. You lead the way; we're going to the place where the ritual is being set up!",
    ["那当然，我总结了一本《阿罗德斯问答攻略大全》，这可是一次次试出来的。资料证明，阿罗德斯大人不会太过为难学员的。"] = "Конечно, я составил «Полное руководство по вопросам и ответам Арродеса», которое проверял снова и снова. Данные доказывают, что лорд Арродес не будет слишком усложнять жизнь студентам.",
    ["那必须是这儿专门的拍照花墙！趁着阳光，拍出来别提会有多好看了！"] = "Это определенно здешняя цветочная стена для фотографий! Пока светит солнце, снимки получатся просто загляденье!",
    ["那我们得……抓紧时间了。晚了，就什么都没了……"] = "Тогда нам нужно... поторопиться. Если мы опоздаем, ничего не останется...",
    ["那我要怎么样才能见到她呢？她肯定很厉害吧！"] = "Тогда как я могу ее увидеть? Она, должно быть, очень сильна!",
    ["那时候整个贝克兰德的古董市场，没人不认识“鹰眼”艾伯特。"] = "Тогда на всем антикварном рынке Баклунда не было человека, который не знал Альберта «Орлиного Глаза».",
    ["那时候边境天旱，很多小村子都在闹饥荒。可这个村子里的所有人，肚子都鼓着。 "] = "В то время на границе была засуха, и многие небольшие деревни страдали от голода. Но у всех в этой деревне был выпуклый живот.",
    ["那是为了验证水下呼吸效果……算了，先不说那个。"] = "Это было сделано для проверки эффекта подводного дыхания... Забудьте об этом, давайте не будем об этом.",
    ["那月下的骏马，踏着永夜疾驰如雷！"] = "Тот конь под луной мчится сквозь вечную ночь подобно грому!",
    ["那现在……"] = "Тогда сейчас...",
    ["那真的太遗憾了！"] = "Это действительно жаль!",
    ["那箱子里装的东西……要是摔坏了，我们全家都赔不起……"] = "То, что в этом ящике... если разобьётся, всей моей семье вовек не расплатиться...",
    ["那老头子死了也不做点好事！我就该多给他灌几口毒药！"] = "Этот старик даже после смерти не сделал ни одного доброго дела! Мне следовало скормить ему еще несколько доз яда!",
    ["那边的那位骑士倒是死得其所。至少有人记得他。"] = "Тот рыцарь там умер, как и должен был. Хоть кто-то его помнит.",
    ["那里以前只是座破城堡，不是现在这样……不是的……全变了。别进去，像那穿黑风衣的老爷们一样，不知道经历了什么！"] = "Раньше там был просто полуразрушенный замок, совсем не такой, как сейчас... Нет... Всё изменилось. Не ходите туда! Прямо как те господа в чёрных плащах — кто знает, через что им пришлось пройти!",
    ["那骑士是不是该帮它找东西，而不是打架……"] = "Тогда разве рыцарь не должен помочь ему найти то, что он ищет, вместо того, чтобы сражаться...",
    ["那，我没有家。"] = "Тогда у меня нет дома.",
    ["那，那你……"] = "Э, тогда ты...",
    ["邦尼在里面埋了“花种”，会让你的灵性遭受污染。"] = "Bonnie has buried \"flower seeds\" inside, which will cause your spirituality to suffer corruption.",
    ["邦尼是那里的主人，没人见过她真面目。莉莉是她的副手，管着里里外外。"] = "Бонни там хозяин; никто никогда не видел ее настоящего лица. Лили — ее заместитель, управляющий всем внутри и снаружи.",
    ["邦尼没骗我们——金狼真正的力量来自那些狂信徒的<P_Yellow>红线</>。"] = "Бонни не лгала нам: истинная сила Золотого Волка исходит от красных нитей <P_Yellow> </> этих фанатиков.",
    ["邦尼的“原始镜面”，她的力量源头。"] = "«Примитивное зеркало» Бонни, источник ее силы.",
    ["邦德每次打架前都要送朵花给对手。"] = "Бонд дарит противнику цветок перед каждым боем.",
    ["部分更高保密等级的资料，则需要进行额外的申请与测试。毕竟，知识就是力量，强大的力量不是每个人都能承受的。"] = "Некоторые материалы с более высоким уровнем допуска требуют дополнительного применения и испытаний. Ведь Знание – Сила, и не каждый сможет выдержать мощную силу.",
    ["部分神奇物品具有“活着”的特性，会引诱周围的人，试图逃脱，请千万小心。"] = "Некоторые мистические предметы обладают характеристикой «живости», что привлекает вокруг себя людей, пытающихся сбежать; пожалуйста, будьте очень осторожны.",
    ["都怪那个沼泽女巫的传说，现在大家都说我的鱼被污染了！"] = "Всему виной легенда о Болотной Ведьме; теперь все говорят, что моя рыба заражена!",
    ["都是为了研究霍纳奇斯遗迹的秘密。"] = "Все это для исследования тайн руин Хорнациса.",
    ["都是自家种的蔬菜，沿着我身后的路直走，就是我家的菜地！"] = "Все эти овощи выращены в домашних условиях. Просто идите прямо по тропинке позади меня, и это мой огород!",
    ["都是面具，看了也认不出来，不如不看。"] = "Это все маски; вы бы их не узнали, даже если бы посмотрели, так что лучше не делать этого.",
    ["都说了这是高贵的……好吧，没错，我是在利用序列能力完成一些委托。"] = "Я уже сказал, что это благородно... Хорошо, хорошо, да, я использую способности Последовательности для выполнения некоторых поручений.",
    ["配？酒就是酒，没有什么配不配的。"] = "Сопряжение? Вино — это просто вино, не бывает сочетания или несочетания.",
    ["酒喝到自己嘴里，才知道是什么味道。别人的描述，都是多余的。"] = "Вы узнаете, какое на вкус вино, только когда оно окажется у вас во рту. Чужие описания просто излишни.",
    ["酒馆小广场也值得一逛，不仅仅是那一圈的食物都十分美味，还有乐队表演呢！顺带一提，如果有机会，你可以去角落里那家店看看。他们家可真是……"] = "Также стоит посетить таверну-сквер: там не только вкусная еда, но и выступления музыкальных групп! Кстати, если у вас будет возможность, вы можете заглянуть в тот магазин в углу. Их место действительно...",
    ["醉汉。"] = "Пьяница.",
    ["重在参与……我准备问问阿罗德斯大人，希望“愚者”先生庇佑。"] = "Участие – вот что важно… Я готов обратиться к лорду Арродесу, надеясь на защиту Мистераа.",
    ["重新介绍一下，我叫刘易斯，我研究了大量有关这里的历史的资料。你可以叫我历史研究员……呃，民间的，不是官方的。"] = "Позвольте мне представиться, меня зовут Льюис. Я изучил большое количество исторических данных об этом месте. Можете называть меня историческим исследователем... эээ, гражданским, а не официальным.",
    ["野兽干的？总之这把猎枪，你拿着。最近发生了太多古怪的事情。"] = "Сделано зверем? В любом случае, возьмите это охотничье ружье. Слишком много странных вещей произошло за последнее время.",
    ["野史！根据论文研究，目前只能证明“愚者”先生和罗塞尔大帝的盟友关系，由此推出乡土情怀在建校历程中的重大作用……"] = "Неофициальная история! Согласно исследовательским работам, в настоящее время можно доказать только то, что Мистер Шут и император Розель заключили союз, и из этого мы можем сделать вывод о значительной роли местных настроений в процессе основания...",
    ["金狼那狗东西，身边围了两圈人——外面是年轻打手，里面是他那帮死忠信徒，贴得跟吸血蛭一样。你敢靠上去？还没摸到边就被按地上了。"] = "Вокруг этого пса Золотого Волка два круга людей: молодые головорезы снаружи и его стойкие последователи внутри, прилипшие к нему, как кровососущие пиявки. Осмелишься подойти поближе? Вас пригвоздит к земле еще до того, как вы коснетесь края.",
    ["金盆洗手之后她整个人都不对劲了……以前多威风的海盗啊。"] = "С тех пор, как она умыла руки от пиратства, она уже не была собой... раньше она была такой впечатляющей пираткой.",
    ["金秋湖村庄中还流传过一则神秘预言——“<P_Yellow>当圣者的叹息声响起时，金色幼苗在此地苏醒，万物将迎接荒芜。</>”"] = "Таинственное пророчество также распространилось в деревне у озера Золотой Осени: «<P_Yellow>Когда раздастся вздох Святого, здесь проснется золотой росток, и все будет приветствовать запустение.</>».",
    ["金秋湖的宝藏，据说是第四纪的东西。"] = "Говорят, что сокровища озера Золотой Осени принадлежат Четвертой Эпохе.",
    ["金色……丰饶之树的颜色确实能作为主色调。"] = "Золото... цвет Древа Изобилия действительно можно использовать в качестве основного тона.",
    ["金黄饱满的南瓜，甜到你掉牙！"] = "Золотистые, пухлые тыквы, настолько сладкие, что у вас выпадут зубы!",
    ["银色子弹就一颗，就一颗！别给老子浪费！"] = "Есть только одна серебряная пуля, всего одна! Не тратьте его ради меня!",
    ["镇子上也有两个小广场，据说以前也是古堡的领地。现在，大家喜欢在那些地方组织些活动，有时候很热闹呢。"] = "В городе также есть две небольшие площади, которые, как говорят, в прошлом были частью территории замка. Сейчас все любят устраивать в этих местах мероприятия, и иногда это очень оживленно.",
    ["镇子里总是下雨！这有把伞也送你！"] = "В городе всегда дождь! Вот и тебе зонтик!",
    ["门从里面<P_Yellow>反锁着</>，我实在担心，就叫仆人一起撞开了门。"] = "Дверь была <P_Yellow>заперта изнутри</>. Я так разволновался, что велел слугам выломать дверь.",
    ["问什么？难道要我像个傻子一样对着空报亭喊话吗？"] = "Спросить что? Хочешь, чтобы я как дурак кричал в пустом газетном киоске?",
    ["队长？<P_Heart>（摇摇头）</>是罗珊给了我新人礼包，让我在廷根到处走走，熟悉环境。"] = "Капитан? <P_Heart> (качает головой) </> Именно Розанна дала мне пакет для новичка и позволила прогуляться по Тингену, чтобы познакомиться с окружающей средой.",
    ["阿尔伯特站在大厅边缘，身体微颤，摘下眼镜擦拭眼角。"] = "Альберт стоял на краю зала, его тело слегка дрожало, он снял очки, чтобы вытереть уголки глаз.",
    ["附近刚刚有……有野兽出没，我们刚刚将他……将它捕杀！你快离开！"] = "Рядом был... зверь, мы просто... его выследили! Тебе следует уйти быстро!",
    ["陌生人咪。"] = "Незнакомец, мяу.",
    ["陌生人喵。"] = "Незнакомец мяу.",
    ["除了精酿酒舍以外，您还可以尝试建造不同种类的工坊，用以满足不同订单的需求。"] = "Помимо крафтовой пивоварни, вы также можете попробовать построить различные типы мастерских для удовлетворения потребностей различных заказов.",
    ["除了魔药配置外，魔药房还是一个药剂讨论与交流的平台，感兴趣的话你可以和这里的学员交流交流，说不定会有所收获。"] = "Помимо приготовления зелий, Комната зелий также является платформой для обсуждения и обмена зельями. Если вам интересно, вы можете пообщаться со студентами здесь; вы можете что-то получить.",
    ["陪我喝点酒吧，让我试试，你到底有没有真的沉沦。"] = "Выпей со мной, дай мне посмотреть, действительно ли ты увлекся этим.",
    ["随便看，这里什么都有点。"] = "Смотрите, выбирайте, тут всего понемногу.",
    ["难得的假期，为什么不去廷根呢？这里有什么好？"] = "Редкий отпуск, почему бы не поехать в Тинген? Что такого хорошего в этом месте?",
    ["难怪你现在这么气派！我就说嘛，你这身新马甲，料子肯定不一般。 "] = "Неудивительно, что ты сейчас такой модный! Я знал, что материал твоего нового жилета определенно необыкновенный.",
    ["难道是方位？如果把整个小镇看作一个表盘。"] = "Может дело в ориентации? Если посмотреть на весь город как на циферблат.",
    ["集体幻觉真可怕……连不存在的知识都进入了大脑……"] = "Коллективные галлюцинации ужасают... в мозг проникают даже знания, которых не существует...",
    ["雪山茶树新叶12片……"] = "12 новых листьев чайного дерева Снежная Гора...",
    ["雾气？我没看到雾气啊。"] = "Туман? Я не видел тумана.",
    ["雾蒙蒙的，像是……准备好忘记点什么了。"] = "Пасмурно, как будто... ты готов что-то забыть.",
    ["需要净化的污染核心在地窖里的祭坛上。"] = "Ядро загрязнения, которое необходимо очистить, находится на алтаре в погребе.",
    ["霍克斯男爵的病情越来越严重，恐怕时候不长了。我不久前如实告知他的情况，却被他怀疑我在监视他，这显然是一种被害妄想。"] = "Состояние барона Хоукса становится все хуже и хуже; Боюсь, у него осталось мало времени. Недавно я рассказал ему правду о его ситуации, но он заподозрил меня в слежке за ним. Это явно форма мании преследования.",
    ["霍普先生是廷根企业家，每年都会来我们拉姆德小镇度假，为我们小镇的经济做出极大贡献。"] = "Мистер Хоуп был предпринимателем из Тингена, который каждый год приезжал в наш город Ламуд на каникулы, внося большой вклад в экономику нашего города.",
    ["霍普叔叔去世得太突然了，你那三个兄弟都是硬茬……就算你请我站在你这边也……"] = "Дядя Хоуп скончался так внезапно, а трое твоих братьев — те еще крепкие орешки... Даже если ты просишь меня встать на твою сторону, я...",
    ["霍纳奇斯？"] = "Хорнацис?",
    ["霍纳奇狮？"] = "Хорнацис?",
